BEGIN;

-- 1. SOLANA Spa 임시 슬러그(sunset-place-9) 시맨틱 슬러그 전환 (충돌 방어 포함)
UPDATE public.businesses
SET slug = 'solana-spa-sunset-town-phu-quoc',
    updated_at = NOW()
WHERE slug = 'sunset-place-9'
  AND NOT EXISTS (SELECT 1 FROM public.businesses WHERE slug = 'solana-spa-sunset-town-phu-quoc');

UPDATE public.businesses SET category = 'hotels', subcategory = 'boutique_hotel', address = 'Shophouse Ven-06, Sun Premier Village, khu đô thị/08 Primavera, Đặc, khu, Phú Quốc, An Giang 92000, Vietnam', description_ko = '선셋타운 베니스 해안가 숍하우스(Ven-06)에 자리한 오션뷰 부티크 호텔입니다. 객실 발코니에서 푸꾸옥 서해안 일몰과 야간 불꽃놀이를 정면으로 감상할 수 있으며 해변 산책로와 카페 거리까지 도보 이동이 매우 편리합니다.', description_en = 'Occupying a prime seafront shophouse at Ven-06 Venice Street, NOSKA Hotel is a stylish boutique stay facing Sunset Town’s coastline. Guests can watch golden sunsets and nightly fireworks right from ocean-view balconies while enjoying doorstep access to seaside cafes and Kiss Bridge.', description_vi = 'Nằm tại dãy shophouse mặt biển đường Venice (Ven-06), NOSKA Hotel là khách sạn boutique sở hữu tầm nhìn hướng biển đắt giá tại Thị trấn Hoàng Hôn. Từ ban công phòng nghỉ, du khách có thể ngắm trọn hoàng hôn và pháo hoa rực rỡ mỗi tối cũng như tản bộ ra Cầu Hôn chỉ trong vài phút.', description_zh = 'NOSKA Hotel 位于日落小镇威尼斯街海滨排屋（Ven-06），是一家视野开阔的海景精品酒店。宾客可在海景阳台上正面欣赏富国岛西海岸落日与每晚海上烟花秀，下楼即可轻松漫步海滨咖啡街并前往亲吻桥。', description_ja = 'サンセットタウンのヴェニス通り海沿い（Ven-06）に佇むオーシャンビュー・ブティックホテルです。客室のバルコニーから西海岸の夕陽と夜の花火ショーを正面に望め、海辺の遊歩道やカフェ街へも徒歩すぐの好立地です。', description_ru = 'Стильный бутик-отель NOSKA Hotel занимает здание на первой береговой линии улицы Венеция (Ven-06) в Сансет-Тауне. С балконов видовых номеров открывается прямой обзор на морской закат и вечерний фейерверк, а прибрежные кафе и Мост Поцелуев находятся в паре минут ходьбы.', description_hi = 'सनसेट टाउन की वेनिस स्ट्रीट के समुद्र तटीय शॉपहाउस (Ven-06) में स्थित नोस्का होटल एक आकर्षक ओशन-व्यू बुटीक ठहराव है। मेहमान अपनी बालकनी से सूर्यास्त और रात्रि आतिशबाज़ी का सीधा आनंद ले सकते हैं, और पास के कैफ़े व किस ब्रिज तक पैदल पहुँच सकते हैं।', public_name = '노스카 호텔 선셋타운 (NOSKA Hotel)', tags = ARRAY['boutique_hotel', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'noska-hotel';
UPDATE public.businesses SET category = 'hotels', subcategory = 'boutique_hotel', address = '44-46 Đ. Amalfi, Sunset Town, Phú Quốc, An Giang 92500, Vietnam', description_ko = '선셋타운 아말피 거리(44-46 Amalfi)에 위치한 일본식 오모테나시 환대와 웰니스 스파가 결합된 4성급 부티크 호텔입니다. 정갈하고 쾌적한 객실과 구내 마사지 테라피 시설을 함께 갖추어 휴식 중심의 커플·가족 여행객에게 인기가 높습니다.', description_en = 'Situated at 44–46 Amalfi Street in Sunset Town, Sakurakyo Hotel & Spa pairs attentive Japanese-inspired hospitality with a full-service wellness spa. Guests enjoy spotless modern rooms, restorative massage treatments on site, and convenient walking access to the cable car plaza and waterfront.', description_vi = 'Tọa lạc tại số 44–46 đường Amalfi, Sakurakyo Hotel & Spa kết hợp phong cách phục vụ tận tâm kiểu Nhật cùng trung tâm spa trị liệu chuyên nghiệp ngay trong khuôn viên. Phòng nghỉ hiện đại, tinh tươm cùng vị trí gần ga cáp treo và bờ biển rất phù hợp cho kỳ nghỉ thư giãn.', description_zh = 'Sakurakyo Hotel & Spa 位于日落小镇阿马尔菲街 44–46 号，将日式细致待客之道与专业水疗中心融为一体。酒店拥有整洁雅致的现代客房与馆内按摩护理设施，步行前往跨海缆车广场与海滨大道均十分便捷。', description_ja = 'サンセットタウンのアマルフィ通り（44-46番地）に位置し、日本流の細やかなおもてなしと本格スパを融合させた4つ星ブティックホテルです。清潔感あふれる客室と館内リラクゼーション施設を備え、ケーブルカー広場や海辺への移動にも便利です。', description_ru = 'Четырёхзвёздочный бутик-отель Sakurakyo Hotel & Spa расположен на улице Амальфи, 44–46, в Сансет-Тауне и сочетает японское гостеприимство с полноценным спа-центром. Гостей ждут безупречно чистые номера, расслабляющий массаж прямо в отеле и близость к площади канатной дороги.', description_hi = 'सनसेट टाउन में 44–46 अमाल्फ़ी स्ट्रीट पर स्थित सकुराक्यो होटल एंड स्पा जापानी शैली के आतिथ्य और इन-हाउस वेलनेस स्पा का सुंदर संगम है। यहाँ स्वच्छ आधुनिक कमरे, आरामदायक मसाज थेरेपी और केबल कार प्लाज़ा तक आसान पैदल पहुँच मिलती है।', public_name = '사쿠라쿄 호텔 & 스파 푸꾸옥 (Sakurakyo Hotel & Spa Phu Quoc)', tags = ARRAY['boutique_hotel', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'sakurakyo-hotel-spa-phu-quoc';
UPDATE public.businesses SET category = 'hotels', subcategory = 'boutique_hotel', address = '9-17 Đường Venice, Sunset Town, Phú Quốc, An Giang 92500, Vietnam', description_ko = '베니스 거리 해안 라인(9-17 Venice)에 자리해 키스 브릿지와 서해안 바다를 정면으로 마주하는 4성급 부티크 호텔입니다. 지중해풍 아치 발코니 객실과 정갈한 조식 라운지를 갖추었으며, 야간 공연장과 야시장까지 해안 산책로로 곧장 연결됩니다.', description_en = 'Set along the prime coastal row at 9–17 Venice Street, Venice Hotel Phu Quoc is a 4-star boutique property overlooking Kiss Bridge and the open sea. Mediterranean arched-balcony rooms, daily breakfast service, and direct promenade access to evening shows make it a standout Sunset Town base.', description_vi = 'Nằm trên trục ven biển đắc địa số 9–17 đường Venice, Venice Hotel Phu Quoc là khách sạn boutique 4 sao hướng thẳng ra Cầu Hôn và mặt biển phía tây. Thiết kế ban công vòm Địa Trung Hải, bữa sáng chu đáo cùng lối đi bộ thẳng ra khu biểu diễn đêm mang lại kỳ nghỉ trọn vẹn.', description_zh = 'Venice Hotel Phu Quoc 坐落于威尼斯街 9–17 号海滨一线，是一家正对亲吻桥与辽阔海面的四星级精品酒店。酒店设有地中海拱廊阳台客房与舒适早餐厅，沿门前海滨步道即可直达夜间演艺剧场与夜市。', description_ja = 'ヴェニス通り9〜17番地の海岸ラインに位置し、キスブリッジと大海原を正面に望む4つ星ブティックホテルです。地中海風のアーチ型バルコニー付き客室と朝食ラウンジを備え、夜のショー会場やナイトマーケットへ遊歩道伝いに歩いて行けます。', description_ru = 'Четырёхзвёздочный бутик-отель Venice Hotel Phu Quoc расположен на первой линии улицы Венеция (9–17) прямо напротив Моста Поцелуев. Отель предлагает номера с арочными балконами в средиземноморском стиле, завтраки и прямой выход на променад к вечерним шоу.', description_hi = '9–17 वेनिस स्ट्रीट की प्रमुख तटीय पंक्ति में स्थित वेनिस होटल फ़ू क्वोक एक 4-स्टार बुटीक प्रॉपर्टी है, जहाँ से किस ब्रिज और खुले समुद्र का दृश्य दिखता है। भूमध्यसागरीय बालकनी वाले कमरे, नाश्ते की सुविधा और रात्रि शो तक सीधी पहुँच इसे खास बनाती है।', public_name = '베니스 호텔 푸꾸옥 (Venice Hotel Phu Quoc)', tags = ARRAY['boutique_hotel', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'venice-hotel-phu-quoc';
UPDATE public.businesses SET category = 'hotels', subcategory = 'boutique_hotel', address = '312-332 Đường Sorrento, Sunset Town, Phú Quốc, An Giang 92500, Vietnam', description_ko = '소렌토 거리(312-332 Sorrento) 해안 인접 구역에 위치한 이탈리아 감성의 부티크 호텔입니다. 고풍스러운 로마풍 인테리어 객실과 전용 스파, 루프탑 테라스를 운영하며 키스 오브 더 씨 공연장과 케이블카 역까지 도보 수 분 내에 닿습니다.', description_en = 'Located at 312–332 Sorrento Street near the southern waterfront, Roma Hotel Phu Quoc captures classic Italian boutique charm with warm architectural details. Guests can unwind at the on-site spa and rooftop terrace while staying just a short walk from the Kiss of the Sea theater and cable car terminal.', description_vi = 'Tọa lạc tại số 312–332 đường Sorrento gần bờ biển phía nam, Roma Hotel Phu Quoc mang nét quyến rũ cổ điển kiểu Ý với không gian nghỉ dưỡng ấm cúng. Khách sạn có spa thư giãn, sân thượng thoáng đãng và chỉ cách sân khấu Nụ Hôn Của Biển Cả cùng ga cáp treo vài phút đi bộ.', description_zh = 'Roma Hotel Phu Quoc 位于索伦托街 312–332 号近海街区，散发浓郁的意式古典精品酒店风情。馆内配备水疗护理空间与屋顶露台，步行数分钟即可抵达海之吻演艺剧场及香岛跨海缆车站。', description_ja = 'ソレント通り（312-332番地）の海辺近くに位置する、クラシカルなイタリア調ブティックホテルです。落ち着いた客室に加え館内スパやルーフトップテラスを備え、キス・オブ・ザ・シー会場やケーブルカー駅へ徒歩数分で移動できます。', description_ru = 'Бутик-отель Roma Hotel Phu Quoc расположен на улице Сорренто (312–332) недалеко от южной набережной и оформлен в классическом итальянском стиле. К услугам гостей собственный спа-салон, терраса на крыше и близость к театру шоу «Поцелуй моря» и станции канатной дороги.', description_hi = 'दक्षिणी समुद्र तट के पास 312–332 सोरेंटो स्ट्रीट पर स्थित रोमा होटल फ़ू क्वोक इतालवी बुटीक स्थापत्य का आकर्षण प्रस्तुत करता है। यहाँ ऑन-साइट स्पा और रूफ़टॉप टेरेस की सुविधा है, तथा किस ऑफ़ द सी थिएटर और केबल कार स्टेशन पैदल दूरी पर हैं।', public_name = '로마 호텔 푸꾸옥 (Roma Hotel Phu Quoc)', tags = ARRAY['boutique_hotel', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'roma-hotel-phu-quoc';
UPDATE public.businesses SET category = 'hotels', subcategory = 'boutique_hotel', address = 'Ven07 Sunset Town, Phú Quốc, An Giang, Vietnam', description_ko = '베니스 거리 중심부(Ven 07)에 위치한 감각적인 디저트 카페 결합형 부티크 호텔입니다. 1층 아티산 커피 & 페이스트리 라운지와 지중해풍 객실, 루프탑 인피니티 풀을 함께 갖추어 휴양과 감성 사진 촬영을 동시에 즐기기 좋습니다.', description_en = 'Set at Ven 07 on vibrant Venice Street, The Juliet Boutique Hotel & Coffee pairs sunlit Mediterranean guestrooms with a ground-floor specialty coffee and pastry lounge. Guests also enjoy a scenic rooftop infinity pool within easy walking distance of Kiss Bridge and VuiFest Bazaar.', description_vi = 'Nằm tại căn Ven 07 trên trục đường Venice nhộn nhịp, The Juliet Boutique Hotel & Coffee kết hợp phòng nghỉ Địa Trung Hải ngập nắng cùng không gian cà phê và bánh ngọt ở tầng trệt. Hồ bơi vô cực trên sân thượng và vị trí gần Cầu Hôn giúp nơi đây rất được lòng du khách trẻ.', description_zh = 'The Juliet 精品酒店及咖啡馆位于热闹的威尼斯街 Ven 07 号，将阳光充足的地中海风客房与一楼精品咖啡甜点酒廊巧妙结合。顶楼更设有视野优美的无边泳池，步行前往亲吻桥与夜市均十分便捷。', description_ja = '活気あるヴェニス通り（Ven 07）に位置する、カフェ併設の洗練されたブティックホテルです。1階のスペシャルティコーヒー＆ペイストリーラウンジと地中海風の明るい客室、屋上インフィニティプールを備え、キスブリッジへも徒歩圏内です。', description_ru = 'Бутик-отель The Juliet на улице Венеция (Ven 07) объединяет светлые номера в средиземноморском стиле и уютную кофейню с выпечкой на первом этаже. На крыше обустроен видовой панорамный бассейн, а до Моста Поцелуев и ночного рынка легко дойти пешком.', description_hi = 'जीवंत वेनिस स्ट्रीट के Ven 07 में स्थित द जूलियट बुटीक होटल एंड कॉफ़ी में भूमध्यसागरीय कमरों के साथ ग्राउंड-फ़्लोर पर स्पेशलिटी कॉफ़ी व पेस्ट्री लाउंज है। मेहमान रूफ़टॉप इन्फिनिटी पूल का आनंद ले सकते हैं और किस ब्रिज तक पैदल जा सकते हैं।', public_name = '더 줄리엣 부티크 호텔 & 커피 Ven 07 (The Juliet A Boutique Hotel & Coffee - Venice 07)', tags = ARRAY['boutique_hotel', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'the-juliet-a-boutique-hotel-coffee-ven-07';
UPDATE public.businesses SET category = 'dining', subcategory = 'korean', address = 'Khu Sun Premier Village Primavera, FB2-04, Phú Quốc, An Giang, Vietnam', description_ko = '선셋타운 프리마베라 해변 구역(FB2-04)에 위치한 한식 바비큐 & 요리 전문점입니다. 불향 가득한 제육볶음과 삼겹살·양념갈비 구이, 바삭한 한국식 치킨, 김치찌개를 한국어 소통이 가능한 쾌적한 매장에서 편안하게 즐길 수 있습니다.', description_en = 'Set in the Primavera seaside zone (FB2-04) of Sunset Town, BBQ House for You serves classic Korean grilled meats and comfort dishes with Korean-speaking staff support. Favorites include smoky stir-fried spicy pork, marinated galbi ribs, crispy Korean fried chicken, and kimchi stew.', description_vi = 'Tọa lạc tại phân khu ven biển Primavera (FB2-04) thuộc Thị trấn Hoàng Hôn, BBQ House for You phục vụ các món nướng và ẩm thực Hàn Quốc quen thuộc trong không gian rộng rãi, thân thiện. Món đinh tại quán gồm thịt heo xào cay dậy mùi lửa, sườn tẩm gia vị nướng, gà rán Hàn Quốc giòn rụm và canh kim chi.', description_zh = '韩国馆（BBQ House for You）位于日落小镇 Primavera 海滨街区（FB2-04），是一家提供正宗韩式烤肉与家常热菜的舒适餐厅。招牌美味涵盖锅气十足的辣炒猪肉、烤五花肉、秘制腌牛排骨、酥脆韩式炸鸡与泡菜锅，用餐沟通十分顺畅。', description_ja = 'サンセットタウンのプリマヴェーラ海辺エリア（FB2-04）に位置する韓国焼肉＆韓国家庭料理レストランです。香ばしい豚肉のピリ辛炒め（チェユクポックム）やサムギョプサル、味付けカルビ、韓国フライドチキン、キムチチゲを快適な店内で安心して味わえます。', description_ru = 'Корейский ресторан BBQ House for You расположен в приморском секторе Primavera (FB2-04) в Сансет-Тауне и предлагает классическое корейское барбекю и горячие блюда. В числе хитов — острая свинина с дымком, маринованные рёбрышки кальби, хрустящая корейская курочка и суп кимчи-ччигэ.', description_hi = 'सनसेट टाउन के प्रीमावेरा तटीय क्षेत्र (FB2-04) में स्थित बीबीक्यू हाउस फ़ॉर यू क्लासिक कोरियन ग्रिल्ड मीट और घरेलू व्यंजन परोसता है। यहाँ के पसंदीदा व्यंजनों में स्मोकी स्पाइसी पोर्क स्टिर-फ़्राई, मैरिनेटेड गाल्बी रिब्स, क्रिस्पी कोरियन फ़्राइड चिकन और किमची स्टू शामिल हैं।', public_name = '한국관 BBQ House for You', tags = ARRAY['korean', 'Sunset Town', '한국관', 'BBQ House']::text[], updated_at = NOW() WHERE slug = 'bbq-house-for-you';
UPDATE public.businesses SET category = 'hotels', subcategory = 'boutique_hotel', address = '201 Sorrento, Sunset Town, Phú Quốc, An Giang 92000, Vietnam', description_ko = '소렌토 거리 201번지 코너에 자리한 유러피안 감성의 3성급 부티크 호텔입니다. 조식과 식사를 제공하는 구내 레스토랑을 운영하며, 혼똔섬 케이블카 광장과 키스 오브 더 씨 공연장, 해변 식당가까지 도보 이동이 편리합니다.', description_en = 'Positioned at 201 Sorrento Street, Times Corner Sorrento Boutique Hotel offers comfortable 3-star European-inspired accommodations with an on-site dining room. Its corner location places travelers within a short stroll of the Hon Thom Cable Car plaza, evening show venues, and seaside dining.', description_vi = 'Nằm ngay góc phố số 201 đường Sorrento, Times Corner Sorrento Boutique Hotel mang phong cách châu Âu thanh lịch với nhà hàng phục vụ ăn uống ngay tại chỗ. Từ khách sạn, du khách dễ dàng đi bộ ra quảng trường ga cáp treo Hòn Thơm, sân khấu biểu diễn đêm và dãy nhà hàng ven biển.', description_zh = 'Times Corner Sorrento 精品酒店坐落于索伦托街 201 号街角，提供舒适的欧式风情三星级客房与馆内餐饮服务。从酒店出发，步行片刻即可抵达香岛跨海缆车广场、夜间演出场地及海滨餐厅街。', description_ja = 'ソレント通り201番地の角地に佇むヨーロピアン調の3つ星ブティックホテルです。朝食や食事を楽しめる館内レストランを併設し、ホントム島ケーブルカー広場や夜のショー会場、海辺の飲食店街へ徒歩で快適にアクセスできます。', description_ru = 'Трёхзвёздочный бутик-отель Times Corner Sorrento занимает угловое здание на улице Сорренто, 201, и предлагает уютные номера в европейском стиле с собственным рестораном. Площадь канатной дороги Хон-Тхом, вечерние шоу и прибрежные кафе находятся в нескольких минутах ходьбы.', description_hi = '201 सोरेंटो स्ट्रीट के कोने पर स्थित टाइम्स कॉर्नर सोरेंटो बुटीक होटल ऑन-साइट रेस्तरां के साथ आरामदायक 3-स्टार यूरोपीय शैली के कमरे प्रदान करता है। यहाँ से होन थोम केबल कार प्लाज़ा, शाम के शो और समुद्री रेस्तरां पैदल दूरी पर हैं।', public_name = '타임즈 코너 소렌토 부티크 호텔 (Times Corner Sorrento Boutique Hotel)', tags = ARRAY['boutique_hotel', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'times-corner-sorrento-boutique-hotel';
UPDATE public.businesses SET category = 'hotels', subcategory = 'boutique_hotel', address = 'Khu đô thị Sun Grand City Hillside Residence- Phân khu The Center, Phú Quốc, An Giang, Vietnam', description_ko = '선셋타운 더 센터(The Center) 구역 케이블카 역 광장 인근에 자리한 클래식 유러피안 외관의 호텔입니다. 넓고 정돈된 객실과 엘리베이터 등 편의 설비를 갖추고 있어 혼똔섬 워터파크 방문객과 가족 단위 여행자의 거점 숙소로 실용적입니다.', description_en = 'Set in The Center district just steps from the Hon Thom Cable Car plaza, ROYAL HOTEL PHU QUOC stands out with its classic European facade and spacious guestrooms. Its central hillside-to-harbor access makes it a practical base for families heading to Sun World Hon Thom and evening shows.', description_vi = 'Tọa lạc tại phân khu The Center sát quảng trường nhà ga cáp treo Hòn Thơm, ROYAL HOTEL PHU QUOC gây ấn tượng với kiến trúc châu Âu cổ điển và hệ thống phòng nghỉ rộng rãi. Vị trí trung tâm giúp các gia đình di chuyển cực kỳ thuận tiện đi đảo Hòn Thơm lẫn xem show buổi tối.', description_zh = 'ROYAL HOTEL PHU QUOC 位于日落小镇 The Center 核心街区，紧邻香岛跨海缆车站广场，以典雅的欧式建筑立面与宽敞整洁的客房著称。优越的中心位置非常适合计划前往香岛水世界及观看夜间演出的家庭旅客。', description_ja = 'サンセットタウン「ザ・センター」地区のケーブルカー広場すぐそばに位置する、クラシカルな欧風外観のホテルです。ゆとりある清潔な客室を備え、ホントム島のウォーターパークや夜のショーを楽しむ家族旅行の拠点として重宝します。', description_ru = 'Отель ROYAL HOTEL PHU QUOC с классическим европейским фасадом расположен в квартале The Center в нескольких шагах от площади канатной дороги Хон-Тхом. Просторные номера и удобная локация делают его практичным выбором для семейных поездок в парк Sun World и на вечерние шоу.', description_hi = 'होन थोम केबल कार प्लाज़ा से कुछ ही कदम दूर द सेंटर डिस्ट्रिक्ट में स्थित रॉयल होटल फ़ू क्वोक अपने क्लासिक यूरोपीय बाहरी डिज़ाइन और विशाल कमरों के लिए जाना जाता है। सन वर्ल्ड वाटर पार्क और रात्रि शो जाने वाले परिवारों के लिए यह एक सुविधाजनक ठहराव है।', public_name = '로얄 호텔 푸꾸옥 1 (ROYAL HOTEL PHU QUOC)', tags = ARRAY['boutique_hotel', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'royal-hotel-phu-quoc';
UPDATE public.businesses SET category = 'hotels', subcategory = 'boutique_hotel', address = 'Số 330, Khu Sun Premier Village Primavera, 332 Đường Sorrento 3, Phú Quốc, An Giang 92500, Vietnam', description_ko = '선셋타운 소렌토 3거리(330-332 Sorrento 3)에 위치한 모던하고 실속 있는 부티크 호텔입니다. 합리적인 숙박 요금에 깔끔한 침구와 에어컨·전용 욕실을 완비하고 있으며 해안 산책로와 케이블카 탑승장까지 걸어서 이동하기 좋습니다.', description_en = 'Located at 330–332 Sorrento 3 Street in Sun Premier Village Primavera, FELLA HOTEL delivers clean, contemporary boutique rooms at traveler-friendly rates. Guests are within an easy walk of the southern coastal promenade, seafood restaurants, and the Hon Thom Cable Car station.', description_vi = 'Nằm tại số 330–332 đường Sorrento 3 thuộc khu Primavera, FELLA HOTEL mang đến không gian phòng nghỉ boutique hiện đại, sạch sẽ với mức giá tiết kiệm. Du khách chỉ mất vài phút đi bộ để ra lối dạo biển, các quán hải sản và nhà ga cáp treo Hòn Thơm.', description_zh = 'FELLA HOTEL 坐落于日落小镇索伦托三街 330–332 号，以亲民价格提供现代整洁的精品客房与舒适卫浴设施。从酒店步行即可轻松前往南侧海滨长廊、海鲜餐厅街以及香岛跨海缆车站。', description_ja = 'ソレント3通り（330-332番地）に位置する、モダンでコストパフォーマンスに優れたブティックホテルです。清潔な寝具と快適な設備を手頃な料金で提供しており、海辺の遊歩道やシーフードレストラン、ケーブルカー駅まで徒歩で移動できます。', description_ru = 'Современный бутик-отель FELLA HOTEL на улице Сорренто-3 (330–332) предлагает аккуратные светлые номера по доступной цене. В пешей доступности находятся южная морская набережная, рыбные рестораны и терминал канатной дороги Хон-Тхом.', description_hi = '330–332 सोरेंटो 3 स्ट्रीट पर स्थित फ़ेला होटल किफ़ायती दरों पर साफ़-सुथरे और आधुनिक बुटीक कमरे उपलब्ध कराता है। यहाँ से दक्षिणी तटीय सैरगाह, सीफ़ूड रेस्तरां और होन थोम केबल कार स्टेशन पैदल दूरी पर हैं।', public_name = '펠라 호텔 선셋타운 (FELLA HOTEL)', tags = ARRAY['boutique_hotel', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'fella-hotel';
UPDATE public.businesses SET category = 'hotels', subcategory = 'boutique_hotel', address = '50 Đ. Amalfi, Phú Quốc, An Giang, Vietnam', description_ko = '아말피 해안도로 50번지에 자리해 바다 전망과 중심가 이동성을 모두 갖춘 4성급 부티크 호텔입니다. 씨뷰 객실에서 푸꾸옥 서해안 노을과 야간 불꽃놀이를 감상할 수 있으며 주변 한식당·카페·환전소 및 케이블카 역 접근성이 뛰어납니다.', description_en = 'Set at 50 Amalfi Street along Sunset Town’s lively coastal corridor, Times Corner Amalfi Hotel offers refined 4-star rooms including sea-view balconies for sunset and fireworks viewing. Cafes, Korean and local restaurants, currency exchange booths, and the cable car terminal are all nearby.', description_vi = 'Tọa lạc tại số 50 đường Amalfi sôi động, Times Corner Amalfi Hotel là khách sạn 4 sao sở hữu các hạng phòng hướng biển ngắm trọn hoàng hôn và pháo hoa. Xung quanh khách sạn tập trung đầy đủ quán cà phê, nhà hàng, quầy đổi tiền và ga cáp treo Hòn Thơm.', description_zh = 'Times Corner Amalfi 酒店位于日落小镇热闹的阿马尔菲街 50 号，是一家兼具海景视野与便利交通的四星级精品酒店。入住海景房即可欣赏西海岸晚霞与夜间烟花，周边环绕咖啡馆、餐厅、换汇点及跨海缆车站。', description_ja = 'サンセットタウンのアマルフィ通り50番地に位置し、海景と利便性を兼ね備えた4つ星ブティックホテルです。シービュー客室からは夕陽や夜の花火を望め、周辺のカフェやレストラン、両替所、ケーブルカー駅へも歩いてすぐです。', description_ru = 'Четырёхзвёздочный отель Times Corner Amalfi расположен на оживлённой улице Амальфи, 50, и располагает видовыми номерами с панорамой заката и вечерних салютов. Рядом сосредоточены кафе, рестораны, пункты обмена валюты и станция канатной дороги.', description_hi = '50 अमाल्फ़ी स्ट्रीट के जीवंत तटीय गलियारे पर स्थित टाइम्स कॉर्नर अमाल्फ़ी होटल सी-व्यू बालकनी कमरों वाला 4-स्टार होटल है, जहाँ से सूर्यास्त और आतिशबाज़ी दिखती है। पास ही कैफ़े, रेस्तरां, मनी एक्सचेंज और केबल कार टर्मिनल मौजूद हैं।', public_name = '타임즈 코너 아말피 호텔 (Times Corner Amalfi Hotel)', tags = ARRAY['boutique_hotel', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'times-corner-amalfi-hotel';
UPDATE public.businesses SET category = 'hotels', subcategory = 'residence', address = 'the Hill, Hillside Residence, Đường Burano, Sunset town, Phú Quốc, An Giang 920000, Vietnam', description_ko = '부라노 거리 선 그랜드 시티 힐사이드(The Hill) 고층 단지에 자리한 가족 맞춤형 레지던스 아파트먼트입니다. 다인원이 머물기 좋은 2~3베드룸 거실·간이 주방 구조와 파노라마 오션뷰, 단지 내 루프탑 수영장 및 피트니스 이용 편의를 제공합니다.', description_en = 'Located in The Hill tower of Sun Grand City Hillside Residence along Burano Street, Rosie Hillside Apartment specializes in spacious multi-bedroom units for families and groups. Apartments feature living areas, kitchenettes, panoramic sea views, and access to rooftop pool facilities.', description_vi = 'Nằm tại phân khu The Hill thuộc tổ hợp cao tầng Sun Grand City Hillside trên đường Burano, Rosie Hillside Apartment cung cấp các căn hộ 2–3 phòng ngủ rộng rãi cho gia đình và nhóm bạn. Căn hộ có phòng khách, bếp nhỏ, tầm nhìn biển toàn cảnh cùng tiện ích hồ bơi sân thượng.', description_zh = 'Rosie Hillside 海景公寓坐落于布拉诺街 Sun Grand City Hillside 高层住宅区（The Hill），主打适合家庭及多人同行的两至三卧套房。公寓配备宽敞客厅、简易厨房与全景海景视野，并可使用园区屋顶泳池等配套设施。', description_ja = 'ブラーノ通りのサン・グランド・シティ・ヒルサイド（The Hill棟）に位置する、家族やグループ向けのレジデンス・アパートメントです。リビングや簡易キッチンを備えた2〜3ベッドルーム仕様で、高層階からの海景や屋上プールを楽しめます。', description_ru = 'Апартаменты Rosie Hillside расположены в высотном корпусе The Hill комплекса Sun Grand City Hillside на улице Бурано и отлично подходят для семей и компаний. Просторные квартиры с 2–3 спальнями оснащены гостиной, мини-кухней и панорамным видом на море.', description_hi = 'बुरानो स्ट्रीट के सन ग्रैंड सिटी हिलसाइड रेज़िडेंस (द हिल टॉवर) में स्थित रोज़ी हिलसाइड अपार्टमेंट परिवारों और समूहों के लिए 2–3 बेडरूम यूनिट प्रदान करता है। इनमें लिविंग रूम, किचनेट, विस्तृत समुद्री दृश्य और रूफ़टॉप पूल की सुविधा शामिल है।', public_name = '로지 힐사이드 시뷰 아파트먼트 (Rosie Hillside Phu Quoc apartment)', tags = ARRAY['residence', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'rosie-hillside-phu-quoc-apartment';
UPDATE public.businesses SET category = 'hotels', subcategory = 'boutique_hotel', address = '302 - 304 đường Sorrento, Phú Quốc, An Giang, Vietnam', description_ko = '소렌토 거리 해안 인접 구역(302-304 Sorrento)에 위치한 감각적인 4성급 부티크 호텔입니다. 키스 오브 더 씨 공연장과 해변 산책로 바로 앞에 자리해 오션뷰 객실 발코니에서 서해안 석양과 야간 불꽃놀이를 여유롭게 감상할 수 있습니다.', description_en = 'Steps from the Kiss of the Sea theater at 302–304 Sorrento Street, CASEPiA is a stylish 4-star boutique hotel along Sunset Town’s southern coast. Ocean-view balconies frame glowing sunsets and nightly fireworks, while the Hon Thom Cable Car station is just a few minutes away on foot.', description_vi = 'Nằm tại số 302–304 đường Sorrento ngay sát sân khấu Nụ Hôn Của Biển Cả và đường dạo biển, CASEPiA là khách sạn boutique 4 sao đầy phong cách. Ban công phòng hướng biển đón trọn hoàng hôn cùng pháo hoa rực rỡ, đồng thời rất gần nhà ga cáp treo Hòn Thơm.', description_zh = 'CASEPiA 四星级精品酒店位于索伦托街 302–304 号，紧邻海之吻演艺剧场与海滨步道。海景客房阳台可将富国岛西海岸落日与璀璨海上烟花尽收眼底，步行前往香岛缆车站亦仅需数分钟。', description_ja = 'ソレント通り302〜304番地、キス・オブ・ザ・シー会場と海辺の遊歩道すぐそばに佇む洗練された4つ星ブティックホテルです。オーシャンビュー客室のバルコニーから夕陽と夜の花火を堪能でき、ケーブルカー駅へも徒歩数分です。', description_ru = 'Стильный 4-звёздочный бутик-отель CASEPiA расположен на улице Сорренто, 302–304, в нескольких шагах от театра «Поцелуй моря» и набережной. С балконов номеров с видом на океан открывается прекрасный обзор на закат и вечерний салют рядом с канатной дорогой.', description_hi = '302–304 सोरेंटो स्ट्रीट पर किस ऑफ़ द सी थिएटर से चंद कदम दूर स्थित कैसेपिया एक स्टाइलिश 4-स्टार बुटीक होटल है। ओशन-व्यू बालकनी से सूर्यास्त और रात्रि आतिशबाज़ी का शानदार दृश्य दिखता है, और केबल कार स्टेशन पैदल दूरी पर है।', public_name = '카세피아 호텔 푸꾸옥 (CASEPiA)', tags = ARRAY['boutique_hotel', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'casepia';
UPDATE public.businesses SET category = 'hotels', subcategory = 'boutique_hotel', address = 'Sun Grand City Hillside Residence, A32-A34 Đ. Amalfi, Phú Quốc, An Giang 92500, Vietnam', description_ko = '혼똔섬 케이블카 탑승장 맞은편 아말피 거리(A32-A34 Amalfi)에 위치한 프렌치 클래식 무드의 3성급 부티크 호텔입니다. 우아한 외관과 정돈된 객실, 친절한 프런트 응대를 갖추었으며 광장·해변·식당가 도보 이동이 매우 수월합니다.', description_en = 'Situated at A32–A34 Amalfi Street right across from the Hon Thom Cable Car terminal, Le Bonheur Hotel brings French-inspired boutique charm to central Sunset Town. Travelers appreciate its elegant facade, well-appointed rooms, and effortless walkability to coastal plazas and dining.', description_vi = 'Nằm tại căn A32–A34 đường Amalfi ngay đối diện nhà ga cáp treo Hòn Thơm, Le Bonheur Hotel mang vẻ đẹp boutique cổ điển kiểu Pháp giữa lòng Thị trấn Hoàng Hôn. Phòng nghỉ chỉn chu, nhân viên thân thiện cùng vị trí đi bộ thuận lợi tới quảng trường biển là điểm cộng lớn.', description_zh = 'Le Bonheur Hotel 坐落于阿马尔菲街 A32–A34 号，正对香岛跨海缆车航站楼，散发典雅的法式精品酒店魅力。酒店外观精致、客房整洁舒适，步行前往海滨广场与餐饮街区极为便利。', description_ja = 'ホントム島ケーブルカー乗り場の向かい、アマルフィ通り（A32-A34）に位置するフレンチ調の3つ星ブティックホテルです。上品な外観と整った客室、丁寧なフロント対応が魅力で、海辺の広場やレストラン街へ気軽に歩いて行けます。', description_ru = 'Французский 3-звёздочный бутик-отель Le Bonheur расположен на улице Амальфи (A32–A34) прямо напротив терминала канатной дороги Хон-Тхом. Гости ценят элегантную архитектуру, уютные номера и пешую доступность главных площадей и ресторанов.', description_hi = 'होन थोम केबल कार टर्मिनल के ठीक सामने A32–A34 अमाल्फ़ी स्ट्रीट पर स्थित ले बोन्हेर होटल फ़्रेंच बुटीक आकर्षण प्रस्तुत करता है। इसका सुंदर स्थापत्य, सुसज्जित कमरे और तटीय प्लाज़ा व रेस्तरां तक आसान पैदल पहुँच यात्रियों को खूब भाती है।', public_name = '르 보뇌르 호텔 (Le Bonheur Hotel)', tags = ARRAY['boutique_hotel', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'le-bonheur-hotel';
UPDATE public.businesses SET category = 'hotels', subcategory = 'residence', address = 'Sunset, Town, Ward, Phú Quốc, An Giang 925000, Vietnam', description_ko = '불꽃놀이 정면 뷰 고층 레지던스.', description_en = 'Luna Sol Sunset & Firework Signature is a residence apartment located in Sunset Town, Phu Quoc.', description_vi = 'Luna Sol Sunset & Firework Signature là căn hộ lưu trú nằm tại Thị trấn Hoàng Hôn, Phú Quốc.', description_zh = 'Luna Sol Hillside Apartment 是位于富国岛日落小镇的高层公寓式住宿，可正面观看烟花表演。', description_ja = 'Luna Sol Hillside Apartmentはフーコックのサンセットタウンにある高層レジデンスで、花火を正面に望む眺望を備えています。', description_ru = 'Luna Sol Hillside Apartment — апартаменты в высотном здании в Сансет-Тауне на Фукуоке с прямым видом на фейерверки.', description_hi = 'Luna Sol Hillside Apartment फु क्वॉक के सनसेट टाउन में स्थित एक बहुमंजिला रेज़िडेंस अपार्टमेंट है, जहाँ से आतिशबाजी का सीधा दृश्य दिखाई देता है।', public_name = '루나 솔 선셋 & 파이어웍스 시그니처 (Luna Sol Sunset & Firework Signature)', tags = ARRAY['residence', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'luna-sol-sunset-firework-signature';
UPDATE public.businesses SET category = 'hotels', subcategory = 'boutique_hotel', address = 'Khu Dân Cư Sunset Town, Tổ 10, Khu Phố 6, Phú Quốc, An Giang 92513, Vietnam', description_ko = '선셋타운 중심 주거·상업 지구에 자리해 1층 스페셜티 커피 라운지와 상층부 지중해풍 객실을 함께 운영하는 부티크 호텔입니다. 아침마다 향긋한 에스프레소와 음료를 즐기며 시계탑 광장, 키스 브릿지, 야시장까지 여유롭게 걸어 다닐 수 있습니다.', description_en = 'Combining a welcoming ground-floor specialty coffeehouse with Mediterranean-toned guestrooms upstairs, De Stefano Hotel Coffee offers a relaxed boutique stay in Sunset Town. Start the morning with freshly brewed Vietnamese or Italian coffee before strolling to the Clock Tower and Kiss Bridge.', description_vi = 'De Stefano Hotel Coffee kết hợp hài hòa giữa quán cà phê ấm cúng ở tầng trệt và các phòng nghỉ mang sắc màu Địa Trung Hải phía trên tại Thị trấn Hoàng Hôn. Du khách có thể khởi đầu ngày mới với ly cà phê thơm lừng trước khi tản bộ ra Tháp Đồng Hồ và Cầu Hôn.', description_zh = 'De Stefano 咖啡精品酒店位于日落小镇中心街区，一楼经营精品咖啡馆，楼上设有温馨的地中海色调客房。住客清晨即可品尝现萃越式或意式咖啡，随后轻松步行前往钟楼广场、亲吻桥与海滨夜市。', description_ja = 'サンセットタウン中心部に位置し、1階のスペシャルティカフェと上階の地中海調客室を併設したブティックホテルです。朝は淹れたてのベトナムコーヒーやエスプレッソを味わい、時計塔広場やキスブリッジへゆっくり散策を楽しめます。', description_ru = 'Уютный бутик-отель De Stefano Hotel Coffee в Сансет-Тауне объединяет кофейню на первом этаже и светлые номера в средиземноморских тонах наверху. Утро здесь приятно начать со свежесваренного кофе, а затем отправиться пешком к Часовой башне и Мосту Поцелуев.', description_hi = 'सनसेट टाउन में स्थित डी स्टेफ़ानो होटल कॉफ़ी ग्राउंड-फ़्लोर स्पेशलिटी कैफ़े और ऊपर भूमध्यसागरीय शैली के आरामदायक कमरों का संगम है। मेहमान सुबह ताज़ा वियतनामी या इतालवी कॉफ़ी का आनंद लेकर क्लॉक टॉवर और किस ब्रिज की ओर टहल सकते हैं।', public_name = '드 스테파노 커피 앤 호텔 (De Stefano Hotel Coffee)', tags = ARRAY['boutique_hotel', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'de-stefano-hotel-coffee';
UPDATE public.businesses SET category = 'beaches', subcategory = 'cafe', address = 'Khu vực Nhà Hàng Zone 2 Địa Trung Hải, FB2-03, Khu Đô Thị Gateway, Phường, Phú Quốc, An Giang, Vietnam', description_ko = '키스 브릿지 매표소 바로 앞 해변가(FB2-03)에 자리한 푸꾸옥 대표 오션프론트 스타벅스 비치 하우스입니다. 지중해풍 아치형 테라스와 탁 트인 실내 좌석에서 서해안 노을을 바라보며 시그니처 에스프레소·리프레셔 음료와 푸꾸옥 한정 시티 머그·텀블러 굿즈를 만날 수 있습니다.', description_en = 'Set right on the beachfront beside the Kiss Bridge entrance (FB2-03), Starbucks Beach House Sun Primavera is Sunset Town’s signature oceanfront coffeehouse. Relax on breezy Mediterranean terraces over espresso classics, tropical Refreshers, and collectible Phu Quoc city mugs and tumblers.', description_vi = 'Tọa lạc ngay sát bãi biển cạnh lối vào Cầu Hôn (căn FB2-03), Starbucks Beach House Sun Primavera là điểm hẹn cà phê hướng biển biểu tượng của Thị trấn Hoàng Hôn. Không gian hiên vòm Địa Trung Hải thoáng đãng rất lý tưởng để thưởng thức espresso, thức uống giải nhiệt và sưu tầm ly giữ nhiệt phiên bản Phú Quốc.', description_zh = '星巴克海滨店（Starbucks Beach House Sun Primavera）坐落于亲吻桥入口旁的海滩一线（FB2-03），是日落小镇最具代表性的海景咖啡馆。宾客可在地中海拱廊露台与通透室内座位一边欣赏西海岸落日，一边品尝经典浓缩咖啡、清爽果摇饮品并选购富国岛限定城市杯周边。', description_ja = 'キスブリッジ入場口すぐ横のビーチフロント（FB2-03）に位置する、サンセットタウン象徴のオーシャンフロント・スターバックスです。地中海風の開放的なテラス席から西海岸の夕陽を眺めつつ、定番エスプレッソやリフレッシャー、フーコック限定のシティマグやタンブラーを楽しめます。', description_ru = 'Флагманская пляжная кофейня Starbucks Beach House Sun Primavera расположена на самом берегу моря рядом со входом на Мост Поцелуев (FB2-03). На просторной террасе с видом на закат подают фирменный эспрессо, прохладительные напитки Refreshers и продают коллекционные кружки и тамблеры Фукуока.', description_hi = 'किस ब्रिज प्रवेश द्वार के ठीक बगल समुद्र तट (FB2-03) पर स्थित स्टारबक्स बीच हाउस सन प्रीमावेरा सनसेट टाउन का प्रमुख ओशनफ़्रंट कैफ़े है। हवादार भूमध्यसागरीय टेरेस से सूर्यास्त देखते हुए क्लासिक एस्प्रेसो, रिफ्रेशर्स और फ़ू क्वोक के विशेष सिटी मग व टम्बलर का आनंद लें।', public_name = '스타벅스 비치 하우스 선셋타운 (Starbucks Beach House Sun Primavera)', price_level = '$$', tags = ARRAY['cafe', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'starbucks-beach-house-sun-primavera';
UPDATE public.businesses SET category = 'hotels', subcategory = 'residence', address = 'The Hillside, Thị Trấn Hoàng Hôn, B28 Đường MILAN, Phú Quốc, An Giang 92500, Vietnam', description_ko = '바다 및 불꽃놀이 전망 객실 지정 가능.', description_en = 'Elyday Apartment Hillside Phu Quoc - Sea & Firework view is a residence apartment located in Sunset Town, Phu Quoc.', description_vi = 'Elyday Apartment Hillside Phu Quoc - Sea & Firework view là căn hộ lưu trú nằm tại Thị trấn Hoàng Hôn, Phú Quốc.', description_zh = 'Elyday Apartment Hillside是位于富国岛日落小镇的公寓式住宿，可选择享有海景与烟花景观的房间。', description_ja = 'Elyday Apartment Hillsideはフーコックのサンセットタウンにあるレジデンスアパートメントで、海や花火の景色を楽しめる客室を選択できます。', description_ru = 'Elyday Apartment Hillside — апартаменты в Сансет-Тауне на Фукуоке, где можно выбрать номер с видом на море и фейерверки.', description_hi = 'Elyday Apartment Hillside फु क्वॉक के सनसेट टाउन में स्थित एक रेज़िडेंस अपार्टमेंट है, जहाँ समुद्र और आतिशबाजी के नज़ारे वाले कमरों का चयन किया जा सकता है।', public_name = '엘리데이 아파트먼트 힐사이드 푸꾸옥 (Elyday Apartment Hillside Phu Quoc - Sea & Firework view)', tags = ARRAY['residence', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'elyday-apartment-hillside-phu-quoc-sea-firework-view';
UPDATE public.businesses SET category = 'hotels', subcategory = 'boutique_hotel', address = 'A118 Đ. Amalfi, sunset town, Phú Quốc, An Giang 92513, Vietnam', description_ko = '아말피 해안 거리(A118 Amalfi)에 자리한 산뜻한 지중해 블루 톤 콘셉트의 3성급 부티크 호텔입니다. 깔끔하게 관리된 객실과 합리적인 숙박비를 갖추고 있으며, 해변 산책로와 아말피 맛집·편의점 라인까지 도보 접근성이 우수합니다.', description_en = 'Located at A118 Amalfi Street, Blue Hotel Sunset Town Phu Quoc features refreshing Mediterranean blue-and-white accents and tidy 3-star guestrooms. Its convenient Amalfi strip setting puts seaside sunset viewpoints, casual restaurants, and 24-hour minimarts within easy walking reach.', description_vi = 'Tọa lạc tại căn A118 đường Amalfi, Blue Hotel Sunset Town Phu Quoc nổi bật với gam màu xanh trắng Địa Trung Hải tươi mát và phòng nghỉ 3 sao gọn gàng. Vị trí ngay trục phố chính giúp du khách đi bộ nhanh chóng ra bờ biển ngắm hoàng hôn, nhà hàng và siêu thị tiện lợi.', description_zh = 'Blue Hotel 位于日落小镇阿马尔菲街 A118 号，采用清爽的地中海蓝白设计风格，提供整洁舒适的三星级客房。酒店紧邻海滨日落观景点、阿马尔菲餐饮街及 24 小时便利店，步行出行十分省心。', description_ja = 'アマルフィ通り（A118）に位置する、地中海らしいブルー＆ホワイトの色調が爽やかな3つ星ブティックホテルです。清潔に整えられた客室を手頃な料金で利用でき、海辺の夕陽スポットや飲食店、コンビニへ徒歩ですぐアクセスできます。', description_ru = 'Трёхзвёздочный бутик-отель Blue Hotel на улице Амальфи (A118) оформлен в освежающих бело-голубых средиземноморских тонах. Удобное расположение позволяет за пару минут дойти до смотровых площадок у моря, ресторанов и круглосуточных минимаркетов.', description_hi = 'A118 अमाल्फ़ी स्ट्रीट पर स्थित ब्लू होटल सनसेट टाउन फ़ू क्वोक भूमध्यसागरीय नीले-सफ़ेद रंगों और साफ़-सुथरे 3-स्टार कमरों से सुसज्जित है। यहाँ से समुद्री सूर्यास्त पॉइंट, रेस्तरां और 24 घंटे खुले मिनीमार्ट पैदल दूरी पर हैं।', public_name = 'Blue Hotel Sunset Town Phu Quoc', tags = ARRAY['boutique_hotel', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'blue-hotel-sunset-town-phu-quoc';
