UPDATE public.businesses SET category = 'hotels', subcategory = 'boutique_hotel', address = 'Đặc Khu Phú Quôc, 126 Amalfi Địa, Phú Quốc, An Giang 97000, Vietnam', description_ko = '선셋타운 지중해풍 부티크 호텔.', description_en = 'ROSY HOTEL Phu Quoc Sunset town is a boutique hotel located in Sunset Town, Phu Quoc.', description_vi = 'ROSY HOTEL Phu Quoc Sunset town là khách sạn boutique nằm tại Thị trấn Hoàng Hôn, Phú Quốc.', description_zh = 'ROSY HOTEL Phu Quoc Sunset town是一家位于富国岛日落小镇的地中海风格精品酒店。', description_ja = 'ROSY HOTEL Phu Quoc Sunset townはフーコックのサンセットタウンにある地中海風のブティックホテルです。', description_ru = 'ROSY HOTEL Phu Quoc Sunset town — это бутик-отель в средиземноморском стиле в Сансет-Тауне на Фукуоке.', description_hi = 'ROSY HOTEL Phu Quoc Sunset town फु क्वॉक के सनसेट टाउन में स्थित भूमध्यसागरीय शैली का एक बुटीक होटल है।', public_name = 'ROSY HOTEL Phu Quoc Sunset town', tags = ARRAY['boutique_hotel', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'rosy-hotel-phu-quoc-sunset-town';
UPDATE public.businesses SET category = 'hotels', subcategory = 'boutique_hotel', address = '22J4+MC3, Phú Quốc, An Giang, Vietnam', description_ko = '선셋타운 밀란 거리에 자리한 실속형 3성급 부티크 호텔로, 1층 카페 라운지와 루프탑 야외 수영장을 함께 운영합니다. 번잡한 해안가보다 한결 차분한 분위기에서 머물면서 드래곤 계단과 아말피 해변 거리까지 도보로 편리하게 오갈 수 있습니다.', description_en = 'Situated along Milan Street in Sunset Town, Milan Hotel is a value-friendly 3-star boutique property equipped with a rooftop plunge pool and ground-floor coffee space. Guests enjoy a quieter neighborhood atmosphere while remaining an easy walk via Dragon Stairs down to Amalfi Street and the sea.', description_vi = 'Nằm trên trục đường Milan yên tĩnh của Thị trấn Hoàng Hôn, Milan Hotel là khách sạn boutique 3 sao giá tốt có hồ bơi sân thượng và quán cà phê tầng trệt. Từ đây, du khách dễ dàng dạo bước qua Thang Rồng để xuống phố biển Amalfi và khu quảng trường.', description_zh = 'Milan Hotel 坐落于日落小镇米兰街，是一家配备屋顶露天泳池与一楼咖啡休闲区的高性价比三星级精品酒店。街区环境安静宜人，沿着网红龙梯步行即可快速下行至阿马尔菲海滨街区。', description_ja = 'サンセットタウンのミラン通りに位置し、屋上プールと1階カフェスペースを備えたコスパ良好な3つ星ブティックホテルです。落ち着いた環境で滞在しながら、ドラゴン階段を通ってアマルフィ通りや海辺へ徒歩で気軽に移動できます。', description_ru = 'Уютный 3-звёздочный отель Milan Hotel на улице Милан в Сансет-Тауне располагает бассейном на крыше и кофейней на первом этаже. Спокойное расположение сочетается с быстрой пешей прогулкой по Драконьей лестнице к улице Амальфи и морю.', description_hi = 'सनसेट टाउन की मिलान स्ट्रीट पर स्थित मिलान होटल रूफ़टॉप पूल और ग्राउंड-फ़्लोर कॉफ़ी स्पेस वाला किफ़ायती 3-स्टार बुटीक होटल है। शांत माहौल में रहते हुए मेहमान ड्रैगन स्टेयर्स के रास्ते अमाल्फ़ी स्ट्रीट और समुद्र तट तक आसानी से पैदल जा सकते हैं।', public_name = 'Milan Hotel', tags = ARRAY['boutique_hotel', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'milan-hotel';
UPDATE public.businesses SET category = 'hotels', subcategory = 'boutique_hotel', address = '22M5+QPW, Phú Quốc, An Giang, Vietnam', description_ko = '선셋타운 지중해풍 부티크 호텔.', description_en = 'TH Luxury Hotel is a boutique hotel located in Sunset Town, Phu Quoc.', description_vi = 'TH Luxury Hotel là khách sạn boutique nằm tại Thị trấn Hoàng Hôn, Phú Quốc.', description_zh = 'TH Luxury Hotel是一家位于富国岛日落小镇的地中海风格精品酒店。', description_ja = 'TH Luxury Hotelはフーコックのサンセットタウンにある地中海風のブティックホテルです。', description_ru = 'TH Luxury Hotel — это бутик-отель в средиземноморском стиле в Сансет-Тауне на Фукуоке.', description_hi = 'TH Luxury Hotel फु क्वॉक के सनसेट टाउन में स्थित भूमध्यसागरीय शैली का एक बुटीक होटल है।', public_name = 'TH Luxury Hotel', tags = ARRAY['boutique_hotel', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'th-luxury-hotel';
UPDATE public.businesses SET category = 'hotels', subcategory = 'residence', address = 'Burano, Phú Quốc, An Giang 92513, Vietnam', description_ko = '부라노 거리 선 그랜드 시티 힐사이드 고층 타워에 위치한 모던 레지던스 아파트먼트입니다. 주방 조리 도구와 세탁 설비를 갖춘 깔끔한 객실 발코니에서 서해안 석양과 해상 불꽃쇼를 조망할 수 있어 장기 체류나 가족 여행에 적합합니다.', description_en = 'Perched in the high-rise towers of Sun Grand City Hillside on Burano Street, Sunset Home Apartment offers modern self-catering units with kitchenettes and laundry facilities. Elevated balconies overlook Phu Quoc’s western coastline and nightly fireworks, ideal for families and longer stays.', description_vi = 'Nằm trên tòa tháp cao tầng Sun Grand City Hillside đường Burano, Sunset Home Apartment mang đến các căn hộ dịch vụ hiện đại có đầy đủ bếp nhỏ và máy giặt. Ban công tầng cao đón trọn khung cảnh hoàng hôn biển và pháo hoa đêm, rất lý tưởng cho gia đình hoặc kỳ nghỉ dài ngày.', description_zh = 'Sunset Home 公寓位于布拉诺街 Sun Grand City Hillside 高层塔楼，提供配备简易厨房与洗衣设备的现代自助式公寓。高层阳台可远眺富国岛西海岸落日与夜间海上烟花，非常适合家庭出游及中长期旅居。', description_ja = 'ブラーノ通りのサン・グランド・シティ・ヒルサイド高層タワーに入るモダンなレジデンス・アパートメントです。簡易キッチンや洗濯設備を備えた客室バルコニーから西海岸の夕陽と花火を見渡せ、家族旅行や連泊滞在に適しています。', description_ru = 'Современные апартаменты Sunset Home в высотных башнях Sun Grand City Hillside на улице Бурано оснащены мини-кухней и стиральной машиной. С высоких балконов открывается панорама западного побережья Фукуока и вечерних фейерверков, что удобно для семей и длительного отдыха.', description_hi = 'बुरानो स्ट्रीट के सन ग्रैंड सिटी हिलसाइड हाई-राइज़ टॉवर में स्थित सनसेट होम अपार्टमेंट किचनेट और लॉन्ड्री सुविधाओं वाले आधुनिक अपार्टमेंट प्रदान करता है। ऊँची बालकनी से पश्चिमी तट का सूर्यास्त और रात्रि आतिशबाज़ी दिखती है, जो परिवारों व लंबे ठहराव के लिए उपयुक्त है।', public_name = 'Sunset Home - Apartment Phu Quoc', tags = ARRAY['residence', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'sunset-home-apartment-phu-quoc';
UPDATE public.businesses SET category = 'hotels', subcategory = 'boutique_hotel', address = 'Ama71, Sunset Town, Phú Quốc, An Giang 91000, Vietnam', description_ko = '선셋타운 아말피 거리(Ama 71) 중심에 자리한 더 줄리엣의 아말피 지점 부티크 호텔 & 카페입니다. 산뜻한 유러피안 객실과 감각적인 1층 커피 바를 갖추었으며, 키스 브릿지·부이페스트 야시장·아말피 맛집 거리까지 도보 이동이 편리합니다.', description_en = 'Located at Ama 71 on bustling Amalfi Street, The Juliet Boutique Hotel & Coffee – Ama 71 blends bright European-inspired rooms with a cozy ground-floor cafe bar. Guests enjoy central walkability to Kiss Bridge, VuiFest Night Market, and Amalfi’s popular dining strip.', description_vi = 'Tọa lạc tại căn Ama 71 trên phố Amalfi sầm uất, The Juliet Boutique Hotel & Coffee chi nhánh Amalfi kết hợp phòng nghỉ phong cách châu Âu tươi sáng với quầy cà phê tầng trệt. Du khách chỉ cần đi bộ vài phút là tới Cầu Hôn, chợ đêm VuiFest và chuỗi nhà hàng nổi tiếng.', description_zh = 'The Juliet 精品酒店及咖啡馆（Ama 71 店）坐落于热闹的阿马尔菲街 Ama 71 号，结合明亮的欧式风格客房与温馨的一楼咖啡吧。从酒店出发，步行即可轻松抵达亲吻桥、VuiFest 夜市及周边人气餐厅。', description_ja = '賑やかなアマルフィ通り（Ama 71）に位置する「ザ・ジュリエット」のアマルフィ店ブティックホテル＆カフェです。明るいヨーロピアン調客室と1階カフェバーを備え、キスブリッジやVuiFestナイトマーケット、飲食店街へ徒歩で快適に出かけられます。', description_ru = 'Филиал бутик-отеля и кофейни The Juliet на оживлённой улице Амальфи (Ama 71) сочетает светлые номера в европейском стиле с уютным кафе-баром внизу. Мост Поцелуев, ночной рынок VuiFest и популярные рестораны находятся в пешей доступности.', description_hi = 'अमाल्फ़ी स्ट्रीट के Ama 71 पर स्थित द जूलियट बुटीक होटल एंड कॉफ़ी उजले यूरोपीय शैली के कमरों और ग्राउंड-फ़्लोर कैफ़े बार का सुंदर मेल है। यहाँ से किस ब्रिज, वुईफ़ेस्ट नाइट मार्केट और प्रमुख रेस्तरां पैदल दूरी पर हैं।', public_name = 'The Juliet A Boutique Hotel & Coffee - Ama 71', tags = ARRAY['boutique_hotel', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'the-juliet-a-boutique-hotel-coffee-ama-71';
