UPDATE public.businesses SET category = 'hotels', subcategory = 'boutique_hotel', address = '23 Positano Street, Sunset Town, An Thới, Phú Quốc, Kiên Giang, Vietnam', description_ko = '포지타노 거리 중심 구역에 자리한 지중해풍 3성급 부티크 호텔입니다. 채광 좋은 깔끔한 객실과 친절한 프런트 컨시어지 서비스를 제공하며, 남보 키친 등 주변 로컬 맛집과 시계탑 광장, 해변 산책로까지 도보로 손쉽게 닿습니다.', description_en = 'Set along colorful Positano Street in Sunset Town, Cybele Sunset Hotel Phu Quoc offers bright 3-star Mediterranean-style rooms and friendly front-desk assistance. Guests are steps away from neighborhood Vietnamese dining, the Clock Tower plaza, and scenic coastal walkways.', description_vi = 'Nằm trên con phố Positano rực rỡ sắc màu của Thị trấn Hoàng Hôn, Cybele Sunset Hotel Phú Quốc mang đến phòng nghỉ 3 sao thoáng sáng cùng lễ tân nhiệt tình. Khách lưu trú chỉ mất ít phút đi bộ để tới các quán ăn Việt, Tháp Đồng Hồ và đường dạo biển.', description_zh = 'Cybele Sunset Hotel 位于日落小镇色彩明快的波西塔诺街，提供采光良好的地中海风三星级客房与热情的前台礼宾服务。周边紧邻地道越南餐厅，步行片刻即可到达钟楼广场与海滨步道。', description_ja = 'カラフルな街並みが続くポジターノ通りに位置する、地中海風の3つ星ブティックホテルです。日当たりの良い清潔な客室と親切なフロント対応が魅力で、周辺のベトナム料理店や時計塔広場、海辺の遊歩道へ徒歩ですぐ出られます。', description_ru = 'Трёхзвёздочный отель Cybele Sunset Hotel расположен на живописной улице Позитано в Сансет-Тауне и предлагает светлые номера с внимательным обслуживанием. В нескольких шагах находятся вьетнамские рестораны, площадь с Часовой башней и морской променад.', description_hi = 'सनसेट टाउन की रंगीन पॉज़िटानो स्ट्रीट पर स्थित सिबेले सनसेट होटल उजले 3-स्टार भूमध्यसागरीय कमरे और विनम्र फ्रंट-डेस्क सेवा प्रदान करता है। पास ही स्थानीय वियतनामी रेस्तरां, क्लॉक टॉवर प्लाज़ा और तटीय सैरगाह स्थित हैं।', public_name = 'Cybele Sunset Hotel Phú Quốc', tags = ARRAY['boutique_hotel', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'cybele-sunset-hotel-phu-quoc';
UPDATE public.businesses SET category = 'hotels', subcategory = 'boutique_hotel', address = 'Sunset town, S209 Sorento 2, Phú Quốc, An Giang 92513, Vietnam', description_ko = '선셋타운 지중해풍 부티크 호텔.', description_en = 'Khách sạn Bella Sunset Town Phú Quốc is a boutique hotel located in Sunset Town, Phu Quoc.', description_vi = 'Khách sạn Bella Sunset Town Phú Quốc là khách sạn boutique nằm tại Thị trấn Hoàng Hôn, Phú Quốc.', description_zh = 'Khách sạn Bella Sunset Town Phú Quốc是一家位于富国岛日落小镇的地中海风格精品酒店。', description_ja = 'Khách sạn Bella Sunset Town Phú Quốcはフーコックのサンセットタウンにある地中海風のブティックホテルです。', description_ru = 'Khách sạn Bella Sunset Town Phú Quốc — это бутик-отель в средиземноморском стиле в Сансет-Тауне на Фукуоке.', description_hi = 'Khách sạn Bella Sunset Town Phú Quốc फु क्वॉक के सनसेट टाउन में स्थित भूमध्यसागरीय शैली का एक बुटीक होटल है।', public_name = 'Khách sạn Bella Sunset Town Phú Quốc', tags = ARRAY['boutique_hotel', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'khach-san-bella-sunset-town-phu-quoc';
UPDATE public.businesses SET category = 'hotels', subcategory = 'residence', address = 'Thị trấn Hoàng Hôn - Sunset Town, Phú Quốc, An Giang 92500, Vietnam', description_ko = 'Sun Grand City Hillside 고층 아파트먼트, 오션/불꽃놀이 뷰.', description_en = 'The Maris Apartment Hillside Phu Quoc - Sunset Town is a residence apartment located in Sunset Town, Phu Quoc.', description_vi = 'The Maris Apartment Hillside Phu Quoc - Sunset Town là căn hộ lưu trú nằm tại Thị trấn Hoàng Hôn, Phú Quốc.', description_zh = 'The Maris Apartment Hillside Phu Quoc - Sunset Town是位于Sun Grand City Hillside的高层公寓式住宿，享有海景与烟花表演景观。', description_ja = 'The Maris Apartment Hillside Phu Quoc - Sunset TownはSun Grand City Hillsideの高層レジデンスアパートメントで、オーシャンビューと花火の眺望が楽しめます。', description_ru = 'The Maris Apartment Hillside Phu Quoc - Sunset Town — это высотные апартаменты в комплексе Sun Grand City Hillside с видом на море и фейерверки.', description_hi = 'The Maris Apartment Hillside Phu Quoc - Sunset Town फू क्वोक के सनसेट टाउन में Sun Grand City Hillside की ऊँची इमारत में स्थित अपार्टमेंट आवास है, जहाँ से समुद्र और आतिशबाज़ी का नज़ारा देखा जा सकता है।', public_name = 'The Maris Apartment Hillside Phu Quoc - Sunset Town', tags = ARRAY['residence', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'the-maris-apartment-hillside-phu-quoc-sunset-town';
UPDATE public.businesses SET category = 'hotels', subcategory = 'boutique_hotel', address = 'Shophouse Ven105, Khu Sun Premier Village Primavera, Đường Venice/tổ 10 khu phố 6, phường, Phú Quốc, An Giang, Vietnam', description_ko = '베니스 거리 숍하우스(Ven 105)에 위치한 모던 지중해 감성의 부티크 호텔입니다. 부이페스트 야시장과 베니스 해안 산책로 인근에 자리해 저녁 시간대 맛집 탐방과 일몰·불꽃쇼 관람 후 도보로 안전하고 빠르게 복귀할 수 있습니다.', description_en = 'Occupying shophouse Ven 105 on Venice Street in Sun Premier Village Primavera, Rova 105 Hotel provides crisp boutique rooms in a walkable coastal setting. Its proximity to VuiFest Bazaar and the Venice promenade makes evening dining, sunset strolls, and post-fireworks returns effortless.', description_vi = 'Tọa lạc tại căn shophouse Ven 105 đường Venice, Rova 105 Hotel sở hữu hệ thống phòng boutique gọn gàng, hiện đại gần bờ biển. Nhờ nằm gần chợ đêm VuiFest và lối dạo bộ ven biển, du khách rất thuận tiện đi ăn tối, ngắm hoàng hôn và trở về sau màn pháo hoa.', description_zh = 'Rova 105 Hotel 位于威尼斯街 Ven 105 号排屋，提供干净现代的地中海风格精品客房。酒店毗邻 VuiFest 海滨夜市与威尼斯海滨大道，傍晚赏日落、逛夜市或看完烟花秀后步行回房十分便捷。', description_ja = 'ヴェニス通りのショップハウス（Ven 105）に位置する、モダンな地中海調ブティックホテルです。VuiFestナイトマーケットや海辺の遊歩道に近く、夕陽鑑賞や夜のグルメ、花火ショーの後も徒歩でスムーズにホテルへ戻れます。', description_ru = 'Бутик-отель Rova 105 Hotel занимает здание Ven 105 на улице Венеция и предлагает аккуратные современные номера рядом с побережьем. Близость к ночному рынку VuiFest и променаду делает вечерние прогулки и возвращение после фейерверков максимально удобными.', description_hi = 'वेनिस स्ट्रीट के शॉपहाउस Ven 105 में स्थित रोवा 105 होटल पैदल घूमने योग्य तटीय क्षेत्र में साफ़ और आधुनिक बुटीक कमरे प्रदान करता है। वुईफ़ेस्ट नाइट मार्केट और वेनिस प्रोमेनाड के करीब होने से शाम का भोजन व आतिशबाज़ी देखना बेहद आसान रहता है।', public_name = 'Rova 105 Hotel', tags = ARRAY['boutique_hotel', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'rova-105-hotel';
UPDATE public.businesses SET category = 'hotels', subcategory = 'boutique_hotel', address = 'H30101 Sun Grand City Hillside, Phú Quốc, An Giang, Vietnam', description_ko = '선 그랜드 시티 힐사이드 구역(H3-01)에 자리한 포지타노 감성의 아늑한 부티크 숙소입니다. 언덕 위 시티·오션 전망과 조용한 휴식 환경을 갖추었으며, 혼똔섬 케이블카 탑승장과 아말피 거리까지 도보로 편리하게 연결됩니다.', description_en = 'Tucked into the Sun Grand City Hillside quarter (H30101), Sole Casa Phu Quoc channels warm Positano-inspired interiors in a peaceful hillside setting. Guests enjoy restful rooms with elevated town views alongside quick walking access to Amalfi Street and the Hon Thom Cable Car station.', description_vi = 'Nằm tại khu Sun Grand City Hillside (H30101), Sole Casa Phu Quoc mang nét ấm cúng cảm hứng Positano giữa không gian đồi thoáng đãng, yên bình. Từ chỗ nghỉ, du khách vẫn dễ dàng đi bộ xuống phố Amalfi và nhà ga cáp treo Hòn Thơm chỉ trong ít phút.', description_zh = 'Sole Casa Phu Quoc 坐落于 Sun Grand City Hillside 街区（H30101），将温暖的波西塔诺意式装饰融入宁静的山坡环境中。客房安静舒适且拥有高处街景视野，步行前往阿马尔菲街与香岛缆车站亦十分方便。', description_ja = 'サン・グランド・シティ・ヒルサイド地区（H30101）に佇む、ポジターノ風の温かみあるインテリアが魅力のブティック宿です。落ち着いた高台の環境でくつろぎながら、アマルフィ通りやホントム島ケーブルカー駅へ徒歩で移動できます。', description_ru = 'Уютный бутик-отель Sole Casa Phu Quoc в квартале Sun Grand City Hillside (H30101) оформлен в тёплом стиле итальянского Позитано. Спокойная атмосфера на возвышенности удачно сочетается с быстрой прогулкой до улицы Амальфи и канатной дороги.', description_hi = 'सन ग्रैंड सिटी हिलसाइड क्षेत्र (H30101) में स्थित सोले कासा फ़ू क्वोक शांत पहाड़ी परिवेश में पॉज़िटानो शैली की गर्मजोशी भरी सजावट प्रस्तुत करता है। यहाँ से अमाल्फ़ी स्ट्रीट और होन थोम केबल कार स्टेशन तक पैदल पहुँचना बेहद आसान है।', public_name = 'Sole Casa Phu Quoc', tags = ARRAY['boutique_hotel', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'sole-casa-phu-quoc';
UPDATE public.businesses SET category = 'hotels', subcategory = 'residence', address = 'Sun Grand City Hillside Residence, Đường TAORMINA, Phú Quốc, An Giang, Vietnam', description_ko = 'Sun Grand City Hillside 고층 아파트먼트, 오션/불꽃놀이 뷰.', description_en = 'Oscar Seaview Apartment is a residence apartment located in Sunset Town, Phu Quoc.', description_vi = 'Oscar Seaview Apartment là căn hộ lưu trú nằm tại Thị trấn Hoàng Hôn, Phú Quốc.', description_zh = 'Oscar Seaview Apartment是位于Sun Grand City Hillside的高层公寓式住宿，享有海景与烟花表演景观。', description_ja = 'Oscar Seaview ApartmentはSun Grand City Hillsideの高層レジデンスアパートメントで、オーシャンビューと花火の眺望が楽しめます。', description_ru = 'Oscar Seaview Apartment — это высотные апартаменты в комплексе Sun Grand City Hillside с видом на море и фейерверки.', description_hi = 'Oscar Seaview Apartment फू क्वोक के सनसेट टाउन में Sun Grand City Hillside की ऊँची इमारत में स्थित अपार्टमेंट आवास है, जहाँ से समुद्र और आतिशबाज़ी का नज़ारा देखा जा सकता है।', public_name = 'Oscar Seaview Apartment', tags = ARRAY['residence', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'oscar-seaview-apartment';
UPDATE public.businesses SET category = 'hotels', subcategory = 'boutique_hotel', address = 'Sunset Town (Địa Trung Hải, 27 Đ.Positano, Phú Quốc, An Giang 92513, Vietnam', description_ko = '선셋타운 지중해풍 부티크 호텔.', description_en = 'The Nice Hotel Phu Quoc - Fireworks & Ocean view is a boutique hotel located in Sunset Town, Phu Quoc.', description_vi = 'The Nice Hotel Phu Quoc - Fireworks & Ocean view là khách sạn boutique nằm tại Thị trấn Hoàng Hôn, Phú Quốc.', description_zh = 'The Nice Hotel Phu Quoc - Fireworks & Ocean view是一家位于富国岛日落小镇的地中海风格精品酒店。', description_ja = 'The Nice Hotel Phu Quoc - Fireworks & Ocean viewはフーコックのサンセットタウンにある地中海風のブティックホテルです。', description_ru = 'The Nice Hotel Phu Quoc - Fireworks & Ocean view — это бутик-отель в средиземноморском стиле в Сансет-Тауне на Фукуоке.', description_hi = 'The Nice Hotel Phu Quoc - Fireworks & Ocean view फु क्वॉक के सनसेट टाउन में स्थित भूमध्यसागरीय शैली का एक बुटीक होटल है।', public_name = 'The Nice Hotel Phu Quoc - Fireworks & Ocean view', tags = ARRAY['boutique_hotel', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'the-nice-hotel-phu-quoc-fireworks-ocean-view';
UPDATE public.businesses SET category = 'hotels', subcategory = 'boutique_hotel', address = 'đường Sorrento 2, Phú Quốc, An Giang 92513, Vietnam', description_ko = '선셋타운 지중해풍 부티크 호텔.', description_en = 'Sunset sorento Phu Quoc (Nắng Biển hotel) is a boutique hotel located in Sunset Town, Phu Quoc.', description_vi = 'Sunset sorento Phu Quoc (Nắng Biển hotel) là khách sạn boutique nằm tại Thị trấn Hoàng Hôn, Phú Quốc.', description_zh = 'Nắng Biển hotel 是一家位于富国岛日落小镇的地中海风格精品酒店。', description_ja = 'Nắng Biển hotelはフーコック島のサンセットタウンにある地中海風のブティックホテルです。', description_ru = 'Nắng Biển hotel — бутик-отель в средиземноморском стиле в Сансет-Тауне на Фукуоке.', description_hi = 'Nắng Biển hotel फू क्वोक के सनसेट टाउन में स्थित भूमध्यसागरीय शैली का एक बुटीक होटल है।', public_name = 'Sunset sorento Phu Quoc (Nắng Biển hotel)', tags = ARRAY['boutique_hotel', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'sunset-sorento-phu-quoc-nang-bien-hotel';
UPDATE public.businesses SET category = 'hotels', subcategory = 'boutique_hotel', address = 'VEN 18, Sunset Town, Phú Quốc, An Giang 71000, Vietnam', description_ko = '베니스 거리 중심부(Ven 18) 해안 인접 블록에 자리한 밝고 쾌적한 3성급 부티크 호텔입니다. 스타벅스 비치 하우스, 키스 브릿지 매표소, 해변 레스토랑 라인이 모두 도보 수 분 거리에 있어 선셋타운 도보 여행에 최적화된 입지를 자랑합니다.', description_en = 'Centrally situated at Ven 18 Venice Street near the waterfront, Sunny Hotel Phu Quoc welcomes travelers with bright 3-star rooms and attentive local hosts. Starbucks Beach House, the Kiss Bridge entrance, and beachfront restaurants are all within a few minutes’ walk.', description_vi = 'Nằm ngay trung tâm đường Venice (căn Ven 18) gần bờ biển, Sunny Hotel Phu Quoc ghi điểm với phòng nghỉ 3 sao sáng sủa và đội ngũ nhân viên thân thiện. Du khách chỉ mất vài phút đi bộ để tới Starbucks Beach House, cổng Cầu Hôn và dãy nhà hàng ven biển.', description_zh = 'Sunny Hotel Phu Quoc 位于威尼斯街 Ven 18 号近海中心街区，以明亮整洁的三星级客房与热情细致的管家服务受到好评。从酒店步行数分钟即可抵达星巴克海滨店、亲吻桥入口及一众海景餐厅。', description_ja = 'ヴェニス通り中心部（Ven 18）の海辺近くに位置する、明るく清潔な3つ星ブティックホテルです。スターバックス・ビーチハウスやキスブリッジ入場口、海沿いのレストラン街までいずれも徒歩数分と、街歩きに絶好のロケーションです。', description_ru = 'Светлый 3-звёздочный бутик-отель Sunny Hotel Phu Quoc расположен в центре улицы Венеция (Ven 18) рядом с побережьем и славится радушным персоналом. Пляжный Starbucks, вход на Мост Поцелуев и прибрежные рестораны находятся всего в нескольких минутах ходьбы.', description_hi = 'समुद्र तट के पास Ven 18 वेनिस स्ट्रीट पर स्थित सनी होटल फ़ू क्वोक उजले 3-स्टार कमरों और सहयोगी स्टाफ़ के साथ यात्रियों का स्वागत करता है। स्टारबक्स बीच हाउस, किस ब्रिज प्रवेश द्वार और तटीय रेस्तरां यहाँ से कुछ ही मिनट की पैदल दूरी पर हैं।', public_name = 'Sunny Hotel Phu Quoc- Ven 18 Sunset Town', tags = ARRAY['boutique_hotel', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'sunny-hotel-phu-quoc-ven-18-sunset-town';
UPDATE public.businesses SET category = 'hotels', subcategory = 'boutique_hotel', address = '73 Positano, Thị Trấn Hoàng Hôn, Phú Quốc, An Giang 92513, Vietnam', description_ko = '선셋타운 지중해풍 부티크 호텔.', description_en = 'Sunset House Phu Quoc - Buggy Services is a boutique hotel located in Sunset Town, Phu Quoc.', description_vi = 'Sunset House Phu Quoc - Buggy Services là khách sạn boutique nằm tại Thị trấn Hoàng Hôn, Phú Quốc.', description_zh = 'Sunset House Phu Quoc - Buggy Services是位于富国岛日落小镇的地中海风格住宿。', description_ja = 'Sunset House Phu Quoc - Buggy Servicesはフーコックのサンセットタウンにある地中海風の宿泊施設です。', description_ru = 'Sunset House Phu Quoc - Buggy Services — это объект размещения в средиземноморском стиле в Сансет-Тауне на Фукуоке.', description_hi = 'Sunset House Phu Quoc - Buggy Services फु क्वॉक के सनसेट टाउन में स्थित भूमध्यसागरीय शैली का आवास है।', public_name = 'Sunset House Phu Quoc - Buggy Sevices', tags = ARRAY['boutique_hotel', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'sunset-house-phu-quoc-buggy-services';
UPDATE public.businesses SET category = 'hotels', subcategory = 'residence', address = 'The Sea, Hillside Residence, Sunset Town, Phú Quốc, An Giang 92500, Vietnam', description_ko = 'Sun Grand City Hillside 고층 아파트먼트, 오션/불꽃놀이 뷰.', description_en = 'Pearl Vista Luxury Service Apartments - Seaview & Fireworks is a residence apartment located in Sunset Town, Phu Quoc.', description_vi = 'Pearl Vista Luxury Service Apartments - Seaview & Fireworks là căn hộ lưu trú nằm tại Thị trấn Hoàng Hôn, Phú Quốc.', description_zh = 'Pearl Vista Luxury Service Apartments - Seaview & Fireworks是位于Sun Grand City Hillside的高层公寓式住宿，享有海景与烟花表演景观。', description_ja = 'Pearl Vista Luxury Service Apartments - Seaview & FireworksはSun Grand City Hillsideの高層レジデンスアパートメントで、オーシャンビューと花火の眺望が楽しめます。', description_ru = 'Pearl Vista Luxury Service Apartments - Seaview & Fireworks — это высотные апартаменты в комплексе Sun Grand City Hillside с видом на море и фейерверки.', description_hi = 'Pearl Vista Luxury Service Apartments - Seaview & Fireworks फू क्वोक के सनसेट टाउन में Sun Grand City Hillside की ऊँची इमारत में स्थित अपार्टमेंट आवास है, जहाँ से समुद्र और आतिशबाज़ी का नज़ारा देखा जा सकता है।', public_name = 'Pearl Vista Luxury Service Apartments - Seaview & Fireworks', tags = ARRAY['residence', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'pearl-vista-luxury-service-apartments-seaview-fireworks';
UPDATE public.businesses SET category = 'hotels', subcategory = 'residence', address = 'Căn hộ Hillside, Sunset Town Khu căn hộ Sun Grand City Hillside Residence, khu phố 6, Phú Quốc, An Giang 92500, Vietnam', description_ko = '선 그랜드 시티 힐사이드 레지던스 고층에 위치한 오션 & 파이어워크 뷰 아파트먼트입니다. 넓은 통창과 전용 발코니를 통해 서해안 노을과 키스 브릿지, 매일 밤 펼쳐지는 해상 불꽃놀이를 한눈에 내려다볼 수 있으며 취사·세탁 편의도 완비되어 있습니다.', description_en = 'Set on high floors of Sun Grand City Hillside Residence, Eirlys Home Apartment delivers sweeping ocean, Kiss Bridge, and nightly fireworks views from private balconies. Well-equipped kitchenettes, washing machines, and shared pool access make it a comfortable home-style stay in Sunset Town.', description_vi = 'Tọa lạc trên các tầng cao của Sun Grand City Hillside Residence, Eirlys Home Apartment sở hữu ban công thoáng rộng bao quát đại dương, Cầu Hôn và màn pháo hoa hàng đêm. Căn hộ trang bị sẵn bếp nhỏ, máy giặt cùng tiện ích hồ bơi chung rất tiện nghi.', description_zh = 'Eirlys Home 海景烟花公寓位于 Sun Grand City Hillside 高层住宅楼，私人阳台与落地窗可俯瞰辽阔大海、亲吻桥及每晚绚丽的海上烟花秀。房内配备简易厨房与洗衣机，并可共享园区泳池设施，兼具居家舒适与度假视野。', description_ja = 'サン・グランド・シティ・ヒルサイド高層階に位置し、専用バルコニーから海とキスブリッジ、夜の花火ショーを一望できるアパートメントです。簡易キッチンや洗濯機を備えた自宅のようにくつろげる空間で、共用プール施設も利用できます。', description_ru = 'Видовые апартаменты Eirlys Home на высоких этажах комплекса Sun Grand City Hillside предлагают панорамный обзор с балкона на океан, Мост Поцелуев и вечерние фейерверки. Квартиры оснащены мини-кухней и стиральной машиной для комфортного проживания.', description_hi = 'सन ग्रैंड सिटी हिलसाइड रेज़िडेंस की ऊँची मंज़िलों पर स्थित एरलिस होम अपार्टमेंट की निजी बालकनी से समुद्र, किस ब्रिज और रात्रि आतिशबाज़ी का विहंगम दृश्य दिखता है। किचनेट, वॉशिंग मशीन और पूल की सुविधा इसे घर जैसा आरामदायक ठहराव बनाती है।', public_name = 'Eirlys Home Apartment Phu Quoc - Firework & Ocean View', tags = ARRAY['residence', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'eirlys-home-apartment-phu-quoc-firework-ocean-view';
UPDATE public.businesses SET category = 'hotels', subcategory = 'residence', address = 'Sunset, M107-M109, Đường MILAN Town, P, Phú Quốc, An Giang, Vietnam', description_ko = '밀란 거리 중심부(M107-M109 Milan)에 위치한 모던 호텔 & 아파트먼트 복합 숙소입니다. 깔끔한 스튜디오형 객실부터 가족용 스위트까지 다양한 구성을 갖추었으며 드래곤 계단을 통해 아말피 해안가와 시계탑 광장으로 빠르게 이동할 수 있습니다.', description_en = 'Located at M107–M109 Milan Street, SOLÉA Hotels & Apartments offers contemporary hotel rooms and spacious apartment-style suites in central Sunset Town. Guests enjoy quiet modern interiors with easy access down to Amalfi Street, the Clock Tower plaza, and seaside attractions.', description_vi = 'Nằm tại số M107–M109 đường Milan, SOLÉA Hotels & Apartments cung cấp đa dạng hạng phòng khách sạn hiện đại lẫn căn hộ suite rộng rãi cho gia đình. Không gian lưu trú yên tĩnh, thanh lịch và kết nối thuận tiện xuống phố Amalfi cùng quảng trường Tháp Đồng Hồ.', description_zh = 'SOLÉA 酒店及公寓坐落于日落小镇米兰街 M107–M109 号，提供从精致客房到宽敞家庭套房的多样化现代住宿选择。室内安静整洁，步行即可便捷前往阿马尔菲街、钟楼广场及海滨景点。', description_ja = 'サンセットタウンのミラン通り（M107-M109）に位置する、モダンなホテル＆アパートメント複合宿泊施設です。機能的な客室から広々としたスイートまで揃い、アマルフィ通りや時計塔広場、海辺の観光スポットへスムーズに移動できます。', description_ru = 'Современный комплекс SOLÉA Hotels & Apartments на улице Милан (M107–M109) предлагает как стандартные гостиничные номера, так и просторные семейные апартаменты. Спокойная обстановка сочетается с удобным выходом к улице Амальфи, Часовой башне и набережной.', description_hi = 'M107–M109 मिलान स्ट्रीट पर स्थित सोलिया होटल्स एंड अपार्टमेंट्स समकालीन होटल कमरे और विशाल अपार्टमेंट-शैली सुइट्स प्रदान करता है। शांत आधुनिक इंटीरियर के साथ यहाँ से अमाल्फ़ी स्ट्रीट, क्लॉक टॉवर प्लाज़ा और तटीय आकर्षणों तक आसान पहुँच मिलती है।', public_name = 'SOLÉA Hotels & Apartments Sunset Town', tags = ARRAY['residence', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'solea-hotels-apartments-sunset-town';
