UPDATE public.businesses SET category = 'hotels', subcategory = 'boutique_hotel', address = '37 Đ. Amalfi, Phú Quốc, An Giang, Vietnam', description_ko = '선셋타운 지중해풍 부티크 호텔.', description_en = 'Trung nguyên E coffee - JENBEN HOTEL is a boutique hotel located in Sunset Town, Phu Quoc.', description_vi = 'Trung nguyên E coffee - JENBEN HOTEL là khách sạn boutique nằm tại Thị trấn Hoàng Hôn, Phú Quốc.', description_zh = 'Trung nguyên E coffee - JENBEN HOTEL是一家位于富国岛日落小镇的地中海风格精品酒店。', description_ja = 'Trung nguyên E coffee - JENBEN HOTELはフーコックのサンセットタウンにある地中海風のブティックホテルです。', description_ru = 'Trung nguyên E coffee - JENBEN HOTEL — это бутик-отель в средиземноморском стиле в Сансет-Тауне на Фукуоке.', description_hi = 'Trung nguyên E coffee - JENBEN HOTEL फु क्वॉक के सनसेट टाउन में स्थित भूमध्यसागरीय शैली का एक बुटीक होटल है।', public_name = 'Trung nguyên E coffee - JENBEN HOTEL', tags = ARRAY['boutique_hotel', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'trung-nguyen-e-coffee-jenben-hotel';
UPDATE public.businesses SET category = 'hotels', subcategory = 'boutique_hotel', address = '22J4+M7W, Positano, Pos26 Địa, Phú Quốc, An Giang, Vietnam', description_ko = '선셋타운 지중해풍 부티크 호텔.', description_en = 'SUNSET BAY RETREAT PHÚ QUỐC is a boutique hotel located in Sunset Town, Phu Quoc.', description_vi = 'SUNSET BAY RETREAT PHÚ QUỐC là khách sạn boutique nằm tại Thị trấn Hoàng Hôn, Phú Quốc.', description_zh = 'SUNSET BAY RETREAT PHÚ QUỐC是一家位于富国岛日落小镇的地中海风格精品酒店。', description_ja = 'SUNSET BAY RETREAT PHÚ QUỐCはフーコックのサンセットタウンにある地中海風のブティックホテルです。', description_ru = 'SUNSET BAY RETREAT PHÚ QUỐC — это бутик-отель в средиземноморском стиле в Сансет-Тауне на Фукуоке.', description_hi = 'SUNSET BAY RETREAT PHÚ QUỐC फु क्वॉक के सनसेट टाउन में स्थित भूमध्यसागरीय शैली का एक बुटीक होटल है।', public_name = 'SUNSET BAY RETREAT PHÚ QUỐC', tags = ARRAY['boutique_hotel', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'sunset-bay-retreat-phu-quoc';
UPDATE public.businesses SET category = 'hotels', subcategory = 'boutique_hotel', address = 'Sunset Town, Địa Trung Hải, Phú Quốc, An Giang 922280, Vietnam', description_ko = '푸꾸옥 서해안의 보랏빛 노을에서 이름을 딴 지중해 감성 소규모 부티크 호텔입니다. 소렌토·해안 인접 거리의 차분한 분위기 속에서 정갈한 객실과 루프탑 선셋 뷰포인트를 제공하여 합리적인 비용으로 여유로운 휴식을 누리기에 알맞습니다.', description_en = 'Named after Phu Quoc’s violet twilight skies, Hoàng Hôn Tím Boutique Hotel is an intimate Mediterranean-style guesthouse in Sunset Town. It offers clean, restful rooms and charming sunset viewpoints within easy walking distance of coastal cafes and evening show venues.', description_vi = 'Lấy cảm hứng từ sắc chiều tím lãng mạn của đảo Ngọc, Hoàng Hôn Tím Boutique Hotel là điểm lưu trú nhỏ xinh mang phong cách Địa Trung Hải tại Thị trấn Hoàng Hôn. Phòng nghỉ sạch sẽ, yên tĩnh cùng khoảng nhìn hoàng hôn thoáng đãng rất hợp cho kỳ nghỉ nhẹ nhàng.', description_zh = 'Hoàng Hôn Tím 精品酒店得名于富国岛迷人的紫色晚霞，是日落小镇一家温馨雅致的地中海风小型精品旅馆。酒店客房整洁安静，设有赏景露台，步行前往海滨咖啡馆与夜间演艺场地均十分方便。', description_ja = 'フーコック島の紫色の夕焼けにちなんで名付けられた、地中海風のこぢんまりとしたブティックホテルです。落ち着いた清潔な客室と夕陽を望むビュースポットを備え、海辺のカフェや夜のショー会場へも徒歩で気軽にアクセスできます。', description_ru = 'Камерный бутик-отель Hoàng Hôn Tím, названный в честь лиловых закатов Фукуока, предлагает тихий отдых в средиземноморском антураже Сансет-Тауна. Чистые уютные номера и близость к прибрежным кафе и вечерним шоу делают его приятным бюджетным выбором.', description_hi = 'फ़ू क्वोक की बैंगनी गोधूलि बेला के नाम पर बना होआंग होन तिम बुटीक होटल सनसेट टाउन का एक शांत भूमध्यसागरीय ठहराव है। यहाँ स्वच्छ आरामदायक कमरे और सुंदर सूर्यास्त दृश्य मिलते हैं, तथा तटीय कैफ़े व रात्रि शो वेन्यू पैदल दूरी पर हैं।', public_name = 'Hoàng Hôn Tím Boutique Hotel', tags = ARRAY['boutique_hotel', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'hoa-ng-hon-ti-m-boutique-hotel';
UPDATE public.businesses SET category = 'hotels', subcategory = 'boutique_hotel', address = 'Hillside sunset town, Phú Quốc, An Giang 92509, Vietnam', description_ko = '선셋타운 지중해풍 부티크 호텔.', description_en = 'Sunset Royal is a boutique hotel located in Sunset Town, Phu Quoc.', description_vi = 'Sunset Royal là khách sạn boutique nằm tại Thị trấn Hoàng Hôn, Phú Quốc.', description_zh = 'Sunset Royal是一家位于富国岛日落小镇的地中海风格精品酒店。', description_ja = 'Sunset Royalはフーコックのサンセットタウンにある地中海風のブティックホテルです。', description_ru = 'Sunset Royal — это бутик-отель в средиземноморском стиле в Сансет-Тауне на Фукуоке.', description_hi = 'Sunset Royal फु क्वॉक के सनसेट टाउन में स्थित भूमध्यसागरीय शैली का एक बुटीक होटल है।', public_name = 'Sunset Royal', tags = ARRAY['boutique_hotel', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'sunset-royal';
UPDATE public.businesses SET category = 'hotels', subcategory = 'residence', address = 'Sun Grand City Hillside Residence, Đường TAORMINA, Phường, Phú Quốc, An Giang, Vietnam', description_ko = 'Sun Grand City Hillside 고층 아파트먼트, 오션/불꽃놀이 뷰.', description_en = 'Homestay Hillside An Thöi (The Hill) H2 is a residence apartment located in Sunset Town, Phu Quoc.', description_vi = 'Homestay Hillside An Thöi (The Hill) H2 là căn hộ lưu trú nằm tại Thị trấn Hoàng Hôn, Phú Quốc.', description_zh = 'The Hill 是位于富国岛日落小镇 Sun Grand City Hillside 的高层公寓式住宿，可欣赏海景和烟花表演。', description_ja = 'The Hillは、フーコック島のサンセットタウンにあるSun Grand City Hillsideの高層アパートメントで、海や花火を眺められます。', description_ru = 'The Hill — апартаменты в высотном здании комплекса Sun Grand City Hillside в Сансет-Тауне на Фукуоке с видом на море и фейерверки.', description_hi = 'The Hill फू क्वोक के सनसेट टाउन में Sun Grand City Hillside की ऊँची इमारत में स्थित अपार्टमेंट आवास है, जहाँ से समुद्र और आतिशबाज़ी का नज़ारा देखा जा सकता है।', public_name = 'Homestay Hillside An Thöi (The Hill) H2', tags = ARRAY['residence', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'homestay-hillside-an-th-i-the-hill-h2';
UPDATE public.businesses SET category = 'hotels', subcategory = 'boutique_hotel', address = '19 Positano Tổ 10, Khu phố 6, Phú Quốc, An Giang 92513, Vietnam', description_ko = '포지타노 거리 19번지에 위치한 가성비 뛰어난 3성급 부티크 호텔입니다. 깔끔한 침구와 발코니 객실을 갖추고 있으며 포지타노·아말피 거리의 베트남 로컬 식당, 한식당, 미니 마트, 환전소까지 걸어서 2~5분이면 닿아 동선이 매우 편리합니다.', description_en = 'Situated at 19 Positano Street, Golden Sunset Hotel is a smart-value 3-star boutique hotel right in Sunset Town’s walkable dining neighborhood. Clean air-conditioned rooms sit just 2 to 5 minutes on foot from Vietnamese and Korean restaurants, minimarts, currency exchange, and the waterfront.', description_vi = 'Nằm tại số 19 đường Positano, Golden Sunset Hotel là khách sạn boutique 3 sao giàu tính kinh tế ngay khu phố ẩm thực sầm uất. Từ đây chỉ mất 2–5 phút đi bộ để tới các nhà hàng Việt – Hàn, siêu thị mini, quầy đổi ngoại tệ và bờ biển Hoàng Hôn.', description_zh = 'Golden Sunset Hotel 位于波西塔诺街 19 号餐饮住宿核心街区，是一家性价比出众的三星级精品酒店。客房整洁凉爽，步行 2 至 5 分钟即可抵达周边越南菜馆、韩式餐厅、便利店、换汇处及海滨长廊。', description_ja = 'ポジターノ通り19番地に位置する、コストパフォーマンスの高い3つ星ブティックホテルです。清潔な客室を備え、ベトナム料理店や韓国料理店、ミニマート、両替所、海辺のプロムナードまで徒歩2〜5分で回れる便利な立地が魅力です。', description_ru = 'Практичный 3-звёздочный отель Golden Sunset Hotel на улице Позитано, 19, расположен в самом удобном для пеших прогулок квартале Сансет-Тауна. До вьетнамских и корейских кафе, минимаркетов, обменников и набережной можно дойти всего за 2–5 минут.', description_hi = '19 पॉज़िटानो स्ट्रीट पर स्थित गोल्डन सनसेट होटल पैदल घूमने योग्य डाइनिंग क्षेत्र के बीचों-बीच एक किफ़ायती 3-स्टार बुटीक होटल है। इसके स्वच्छ वातानुकूलित कमरों से स्थानीय रेस्तरां, मिनीमार्ट, करेंसी एक्सचेंज और समुद्र तट केवल 2–5 मिनट दूर हैं।', public_name = 'Golden Sunset Hotel', tags = ARRAY['boutique_hotel', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'golden-sunset-hotel';
UPDATE public.businesses SET category = 'hotels', subcategory = 'boutique_hotel', address = 'Primavera, Pos 41,43 Sun Premier Village, Phú Quốc, An Giang 92500, Vietnam', description_ko = '포지타노 거리(Pos 41-43)에 자리해 부티크 객실과 전용 스파 케어를 함께 제공하는 선셋타운 호텔입니다. 낮 동안 호핑투어나 케이블카 일정을 마친 뒤 숙소 내 스파에서 전신·발 마사지를 받고 곧장 객실에서 편히 쉴 수 있어 여행 동선이 여유롭습니다.', description_en = 'Occupying shophouses Pos 41–43 on Positano Street, ROVA Hotel & Spa combines comfortable Mediterranean boutique rooms with relaxing in-house spa therapies. After island-hopping or riding the cable car, guests can enjoy body or foot massages downstairs before retiring directly to their rooms.', description_vi = 'Tọa lạc tại căn Pos 41–43 đường Positano, ROVA Hotel & Spa kết hợp phòng nghỉ boutique ấm cúng cùng dịch vụ massage trị liệu ngay trong tòa nhà. Sau ngày dài đi tour đảo hoặc cáp treo, du khách có thể thư giãn spa ở tầng dưới rồi lên phòng nghỉ ngơi vô cùng tiện lợi.', description_zh = 'ROVA Hotel & Spa 位于波西塔诺街 Pos 41–43 号，将舒适的地中海风精品客房与馆内水疗按摩服务结合在一起。结束跳岛游或跨海缆车行程后，住客可在楼下享受全身或足部放松护理，随后直接回房休息。', description_ja = 'ポジターノ通り（Pos 41-43）に位置し、地中海調のブティック客室と館内スパを併設したホテルです。アイランドホッピングやケーブルカー観光の後、館内でボディやフットマッサージを受けてそのまま客室でゆっくり休めます。', description_ru = 'Отель ROVA Hotel & Spa занимает здания Pos 41–43 на улице Позитано, сочетая уютные номера с собственным массажным спа-салоном. После морских экскурсий или поездки на канатной дороге гости могут расслабиться на массаже прямо в здании отеля.', description_hi = 'पॉज़िटानो स्ट्रीट के शॉपहाउस Pos 41–43 में स्थित रोवा होटल एंड स्पा आरामदायक बुटीक कमरों के साथ इन-हाउस स्पा थेरेपी की सुविधा देता है। द्वीप भ्रमण या केबल कार की सैर के बाद मेहमान नीचे मसाज लेकर सीधे अपने कमरों में विश्राम कर सकते हैं।', public_name = 'ROVA HOTEL & SPA PHU QUOC', tags = ARRAY['boutique_hotel', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'rova-hotel-spa-phu-quoc';
