UPDATE public.businesses SET category = 'hotels', subcategory = 'boutique_hotel', address = '32 Đ.Positano, Sunset Town, Phú Quốc, An Giang, Vietnam', description_ko = '선셋타운 지중해풍 부티크 호텔.', description_en = 'TK HOUSE PHU QUOC is a boutique hotel located in Sunset Town, Phu Quoc.', description_vi = 'TK HOUSE PHU QUOC là khách sạn boutique nằm tại Thị trấn Hoàng Hôn, Phú Quốc.', description_zh = 'TK HOUSE PHU QUOC是位于富国岛日落小镇的地中海风格住宿。', description_ja = 'TK HOUSE PHU QUOCはフーコックのサンセットタウンにある地中海風の宿泊施設です。', description_ru = 'TK HOUSE PHU QUOC — это объект размещения в средиземноморском стиле в Сансет-Тауне на Фукуоке.', description_hi = 'TK HOUSE PHU QUOC फु क्वॉक के सनसेट टाउन में स्थित भूमध्यसागरीय शैली का आवास है।', public_name = 'TK HOUSE PHU QUOC', tags = ARRAY['boutique_hotel', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'tk-house-phu-quoc';
UPDATE public.businesses SET category = 'hotels', subcategory = 'boutique_hotel', address = 'Sunset Town, A104 Đ. Amalfi, An Thoi Quarter, Phú Quốc, An Giang 92500, Vietnam', description_ko = '아말피 해안 거리(A104 Amalfi)에 자리한 지중해 해변 별장 무드의 부티크 호텔입니다. 따뜻한 테라코타·화이트 색감의 아늑한 객실을 갖추었으며, 저녁 노을이 물드는 아말피 바닷가 산책로와 다이닝 펍·카페 거리까지 걸어서 바로 연결됩니다.', description_en = 'Set at A104 Amalfi Street in the An Thoi coastal quarter, CASA DEL MAR Boutique Hotel evokes a warm Mediterranean seaside villa atmosphere. Cozy, sunlit guestrooms place travelers steps from Amalfi’s sunset promenade, open-air dining pubs, and specialty coffee shops.', description_vi = 'Nằm tại căn A104 đường Amalfi, CASA DEL MAR Boutique Hotel gợi lên không gian biệt thự biển Địa Trung Hải ấm áp và gần gũi. Từ những căn phòng ngập nắng, du khách chỉ bước vài chân là tới đường dạo biển ngắm hoàng hôn, các quán pub ngoài trời và tiệm cà phê.', description_zh = 'CASA DEL MAR 精品酒店位于阿马尔菲海岸街 A104 号，营造出温暖惬意的地中海海滨别墅氛围。客房采光充足、布置温馨，出门几步即可抵达阿马尔菲日落海滨步道、露天餐吧与精品咖啡馆。', description_ja = 'アマルフィ通り（A104）に位置する、地中海の海辺のヴィラを思わせる温かみあるブティックホテルです。日当たりの良い居心地のよい客室から、夕陽が美しい海岸遊歩道やオープンエアのダイニングパブ、カフェ街へ歩いてすぐ出られます。', description_ru = 'Бутик-отель CASA DEL MAR на улице Амальфи (A104) передаёт тёплую атмосферу средиземноморской прибрежной виллы. Светлые уютные номера расположены всего в нескольких шагах от закатной набережной, открытых гастропабов и кофеен.', description_hi = 'A104 अमाल्फ़ी स्ट्रीट के तटीय क्षेत्र में स्थित कासा डेल मार बुटीक होटल भूमध्यसागरीय समुद्र तटीय विला जैसा गर्मजोशी भरा माहौल देता है। इसके उजले कमरों से अमाल्फ़ी का सनसेट प्रोमेनाड, ओपन-एयर रेस्तरां और कैफ़े चंद कदम दूर हैं।', public_name = 'CASA DEL MAR BOUTIQUE HOTEL', tags = ARRAY['boutique_hotel', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'casa-del-mar-boutique-hotel';
