UPDATE public.businesses SET category = 'hotels', subcategory = 'boutique_hotel', address = '167 Đường MILAN, Sunset Town, Phú Quốc, An Giang, Vietnam', description_ko = '밀란 거리 167번지에 자리한 밝고 조용한 분위기의 3성급 부티크 호텔입니다. 심야 시간대 해안가 공연·펍 소음에서 한발 비켜선 쾌적한 숙면 환경을 제공하면서도 드래곤 계단과 중심 광장, 해변까지는 도보로 부담 없이 오갈 수 있습니다.', description_en = 'Located at 167 Milan Street, MERCI HOTEL Sunset Town Phu Quoc offers bright, contemporary 3-star rooms in a calm residential pocket above the coast. Guests enjoy restful nights away from late-evening bar noise while staying a pleasant walk from Dragon Stairs and the town plazas.', description_vi = 'Tọa lạc tại số 167 đường Milan, MERCI HOTEL Sunset Town Phu Quoc mang đến không gian phòng nghỉ 3 sao sáng sủa và yên tĩnh, tách biệt khỏi tiếng ồn về khuya nơi bờ biển. Du khách vẫn dễ dàng đi bộ qua Thang Rồng để xuống quảng trường trung tâm và bãi biển.', description_zh = 'MERCI HOTEL 坐落于日落小镇米兰街 167 号，提供明亮整洁的现代三星级客房。酒店地处静谧街区，避开了海滨夜生活的喧嚣以保障安稳睡眠，同时步行即可经由龙梯轻松前往中心广场与海边。', description_ja = 'サンセットタウンのミラン通り167番地に位置する、明るく落ち着いた雰囲気の3つ星ブティックホテルです。夜遅くまで賑わう海沿いの喧騒から離れた静かな環境で快眠でき、ドラゴン階段や中央広場へも徒歩で無理なく移動できます。', description_ru = 'Светлый 3-звёздочный отель MERCI HOTEL на улице Милан, 167, расположен в спокойном квартале чуть выше прибрежной зоны. Здесь легко выспаться вдали от ночного шума баров и при этом быстро дойти пешком до Драконьей лестницы и морских площадей.', description_hi = '167 मिलान स्ट्रीट पर स्थित मर्सी होटल सनसेट टाउन शांत वातावरण में उजले और आधुनिक 3-स्टार कमरे उपलब्ध कराता है। देर रात के शोर-शराबे से दूर सुकून भरी नींद के साथ यहाँ से ड्रैगन स्टेयर्स और मुख्य प्लाज़ा तक पैदल पहुँचना आसान है।', public_name = 'MERCI HOTEL SUNSET TOWN PHU QUOC', tags = ARRAY['boutique_hotel', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'merci-hotel-sunset-town-phu-quoc';
UPDATE public.businesses SET category = 'hotels', subcategory = 'boutique_hotel', address = '51 Đ. Amalfi, Phú Quốc, An Giang 92500, Vietnam', description_ko = '아말피 거리 51번지에 자리한 싱그러운 보타니컬 감성의 3성급 부티크 호텔입니다. 내추럴 그린 포인트를 살린 정갈한 객실과 친절한 응대를 갖추었으며, 해변 일몰 포인트와 부이페스트 야시장, 케이블카 역까지 도보 접근성이 뛰어납니다.', description_en = 'Situated at 51 Amalfi Street, The Fern Phu Quoc Hotel brings calming botanical accents and crisp 3-star comfort to central Sunset Town. Its prime Amalfi address allows guests to walk effortlessly to sunset beach viewpoints, VuiFest Night Market, and the Hon Thom Cable Car.', description_vi = 'Nằm tại số 51 đường Amalfi trung tâm, The Fern Phu Quoc Hotel gây thiện cảm với điểm nhấn cây xanh dịu mắt và phòng nghỉ 3 sao tinh tươm. Từ khách sạn, du khách đi bộ rất gần tới bãi biển ngắm hoàng hôn, chợ đêm VuiFest cũng như ga cáp treo Hòn Thơm.', description_zh = 'The Fern Phu Quoc 酒店位于日落小镇阿马尔菲街 51 号，以清新自然的绿植设计元素装点整洁的三星级客房。优越的中心地段让住客步行即可轻松前往海滩日落观景点、VuiFest 夜市与香岛缆车站。', description_ja = 'アマルフィ通り51番地に佇む、ナチュラルなグリーンを取り入れたボタニカル調の3つ星ブティックホテルです。清潔感ある客室と丁寧な接客が好評で、夕陽スポットのビーチやVuiFestナイトマーケット、ケーブルカー駅へ徒歩すぐです。', description_ru = 'Уютный 3-звёздочный отель The Fern Phu Quoc на улице Амальфи, 51, оформлен со свежими ботаническими акцентами в самом центре Сансет-Тауна. До смотровых точек на пляже, ночного рынка VuiFest и канатной дороги можно легко дойти пешком.', description_hi = '51 अमाल्फ़ी स्ट्रीट पर स्थित द फ़र्न फ़ू क्वोक होटल शांत बॉटैनिकल सज्जा और आरामदायक 3-स्टार कमरों की पेशकश करता है। इस केंद्रीय लोकेशन से सनसेट बीच व्यूपॉइंट, वुईफ़ेस्ट नाइट मार्केट और होन थोम केबल कार तक पैदल जाना बेहद सुगम है।', public_name = 'The Fern Phu Quoc Hotel Sunset Town', tags = ARRAY['boutique_hotel', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'the-fern-phu-quoc-hotel-sunset-town';
