UPDATE public.businesses SET category = 'hotels', subcategory = 'residence', address = 'Toà S3, Sun Grand City Hillside Residence, An Thới, Phú Quốc Phu Quoc, Phú Quốc, An Giang 92513, Vietnam', description_ko = 'Sun Grand City Hillside 고층 아파트먼트, 오션/불꽃놀이 뷰.', description_en = 'Sunset Town Service Apartment Phu Quoc is a residence apartment located in Sunset Town, Phu Quoc.', description_vi = 'Sunset Town Service Apartment Phu Quoc là căn hộ lưu trú nằm tại Thị trấn Hoàng Hôn, Phú Quốc.', description_zh = 'Sunset Town Service Apartment Phu Quoc 是位于富国岛日落小镇 Sun Grand City Hillside 的高层公寓式住宿，可欣赏海景和烟花。', description_ja = 'Sunset Town Service Apartment Phu Quocは、フーコックのサンセットタウンにあるSun Grand City Hillsideの高層レジデンスアパートメントで、オーシャンビューと花火の景色を楽しめます。', description_ru = 'Sunset Town Service Apartment Phu Quoc — это высотные апартаменты в комплексе Sun Grand City Hillside в Sunset Town на Фукуоке с видом на океан и фейерверки.', description_hi = 'Sunset Town Service Apartment Phu Quoc फु कुओक के Sunset Town में Sun Grand City Hillside में स्थित एक ऊंची इमारत वाला रेज़िडेंस अपार्टमेंट है, जहाँ से समुद्र और आतिशबाजी का नज़ारा दिखता है।', public_name = 'Sunset Town Service Apartment Phu Quoc', tags = ARRAY['residence', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'sunset-town-service-apartment-phu-quoc';
UPDATE public.businesses SET category = 'hotels', subcategory = 'residence', address = 'Hillside Residence, Khu pho 6 An Thoi (TH1, Sungrand City, Phú Quốc, An Giang 92513, Vietnam', description_ko = '선 그랜드 시티 힐사이드(TH1) 고층에 자리해 선셋타운 지중해 지붕들과 키스 브릿지, 야간 해상 불꽃놀이를 파노라마로 조망하는 레지던스입니다. 깔끔한 거실·주방 설비와 단지 내 수영장·피트니스 부대시설을 함께 이용할 수 있어 만족도가 높습니다.', description_en = 'Elevated in tower TH1 of Sun Grand City Hillside Residence, Crystal Apartment commands bird’s-eye views over Sunset Town’s terracotta rooftops, Kiss Bridge, and nightly fireworks. Modern living spaces with kitchenettes and resident pool access suit couples and small families alike.', description_vi = 'Nằm trên tầng cao tòa TH1 khu Sun Grand City Hillside, Crystal Apartment thu trọn vào tầm mắt những mái ngói Địa Trung Hải, Cầu Hôn và pháo hoa rực rỡ mỗi tối. Không gian căn hộ hiện đại có bếp nhỏ cùng hồ bơi và phòng gym nội khu rất tiện nghi.', description_zh = 'Crystal Apartment 位于 Sun Grand City Hillside 住宅区（TH1 栋）高层，可俯瞰日落小镇红瓦屋顶、亲吻桥与每晚海上烟花全景。公寓配有现代起居空间、简易厨房及住客专属泳池与健身设施，深受情侣及小家庭欢迎。', description_ja = 'サン・グランド・シティ・ヒルサイド（TH1棟）高層階に位置し、テラコッタ屋根の街並みとキスブリッジ、夜の花火を眼下に望むレジデンスです。簡易キッチン付きの快適な居住空間に加え、館内のプールやジムも利用できます。', description_ru = 'Апартаменты Crystal Apartment в высотном корпусе TH1 комплекса Sun Grand City Hillside открывают вид с высоты птичьего полёта на терракотовые крыши Сансет-Тауна, Мост Поцелуев и салют. Гостям доступны мини-кухня, бассейн и фитнес-зона резиденции.', description_hi = 'सन ग्रैंड सिटी हिलसाइड रेज़िडेंस के TH1 टॉवर में स्थित क्रिस्टल अपार्टमेंट से सनसेट टाउन की छतों, किस ब्रिज और रात्रि आतिशबाज़ी का विहंगम दृश्य दिखता है। किचनेट और पूल सुविधा से युक्त ये आधुनिक अपार्टमेंट कपल्स व छोटे परिवारों के लिए उत्तम हैं।', public_name = 'Crystal Apartment Hillside Phu Quoc - Sunset Town & Firework', tags = ARRAY['residence', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'crystal-apartment-hillside-phu-quoc-sunset-town-firework';
UPDATE public.businesses SET category = 'hotels', subcategory = 'residence', address = 'Milan, Phú Quốc, An Giang 91000, Vietnam', description_ko = '밀란·힐사이드 고층 단지에 위치한 감각적인 인테리어의 오션뷰 레지던스 아파트먼트입니다. 여유로운 거실과 간이 주방, 세탁기, 루프탑 인피니티 풀 이용 권한을 갖추고 있어 푸꾸옥 남부에서 내 집처럼 편안하게 머물기 좋습니다.', description_en = 'Set within the Milan–Hillside high-rise enclave of Sunset Town, Dido Carthage Apartment offers thoughtfully styled self-contained residences with sea and town views. Guests enjoy living rooms, kitchenettes, in-unit laundry, and access to scenic rooftop infinity pool decks.', description_vi = 'Tọa lạc tại cụm căn hộ cao tầng khu Milan – Hillside, Dido Carthage Apartment gây ấn tượng với thiết kế nội thất tinh tế cùng tầm nhìn hướng biển và phố thị. Căn hộ có phòng khách, bếp, máy giặt riêng và quyền sử dụng hồ bơi vô cực trên tầng thượng.', description_zh = 'Dido Carthage 公寓位于日落小镇米兰与山坡高层住宅区，提供设计考究、视野开阔的海景与街景服务式公寓。房内配有独立客厅、简易厨房及洗衣机，住客还可前往顶楼无边泳池露台欣赏海天一色。', description_ja = 'ミラン〜ヒルサイド高層エリアに位置する、洗練されたインテリアのオーシャンビュー・レジデンスアパートメントです。リビングや簡易キッチン、洗濯機を完備し、見晴らしの良い屋上インフィニティプールも利用できる快適な滞在拠点です。', description_ru = 'Апартаменты Dido Carthage в высотном квартале Милан — Hillside предлагают стильные квартиры с видом на море и город. В распоряжении гостей гостиная зона, мини-кухня, стиральная машина и доступ к видовому панорамному бассейну на крыше.', description_hi = 'सनसेट टाउन के मिलान–हिलसाइड हाई-राइज़ क्षेत्र में स्थित डीडो कार्थेज अपार्टमेंट समुद्र और शहर के दृश्यों वाले सुसज्जित रेज़िडेंस प्रदान करता है। लिविंग रूम, किचनेट, वॉशिंग मशीन और रूफ़टॉप इन्फिनिटी पूल की सुविधा इसे बेहद आरामदायक बनाती है।', public_name = 'Dido Carthage Apartment Sunset Town, Phu Quoc Island', tags = ARRAY['residence', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'dido-carthage-apartment-sunset-town-phu-quoc-island';
UPDATE public.businesses SET category = 'hotels', subcategory = 'boutique_hotel', address = '39 Đ. Amalfi, Phú Quốc, An Giang, Vietnam', description_ko = '아말피 거리 중심부(39 Amalfi)에 자리해 해변과 주요 맛집·편의시설을 모두 걸어서 누릴 수 있는 깔끔한 3성급 호텔입니다. 정돈된 객실 컨디션과 세심한 프런트 응대로 자유여행객들의 가성비 선셋타운 숙소로 호평받고 있습니다.', description_en = 'Positioned at 39 Amalfi Street in central Sunset Town, JS Hotel Phu Quoc provides spotless 3-star guestrooms and responsive front-desk service at great value. Dining spots, currency exchange, minimarts, and coastal sunset viewpoints sit right outside along the Amalfi promenade.', description_vi = 'Nằm tại số 39 đường Amalfi ngay trung tâm Thị trấn Hoàng Hôn, JS Hotel Phu Quoc được du khách tự túc đánh giá cao nhờ phòng nghỉ 3 sao sạch sẽ và lễ tân chu đáo. Bước chân ra cửa là chuỗi nhà hàng, quầy đổi tiền, siêu thị mini và lối ra biển ngắm hoàng hôn.', description_zh = 'JS Hotel Phu Quoc 坐落于日落小镇中心阿马尔菲街 39 号，以干净整洁的三星级客房与细致周到的前台服务赢得自由行旅客好评。出门沿阿马尔菲大道步行即可到达人气餐厅、换汇点、便利店及海滨日落观景处。', description_ja = 'サンセットタウン中心部のアマルフィ通り39番地に位置する、清潔で使い勝手の良い3つ星ホテルです。整った客室と丁寧なフロント対応で個人旅行者からの評価が高く、周辺の飲食店や両替所、海辺の夕陽スポットへすぐ歩いて行けます。', description_ru = 'Аккуратный 3-звёздочный отель JS Hotel Phu Quoc расположен в центре улицы Амальфи, 39, и славится чистотой номеров и внимательным персоналом. Прямо рядом с отелем находятся популярные кафе, обменники, минимаркеты и выход к закатной набережной.', description_hi = '39 अमाल्फ़ी स्ट्रीट के केंद्रीय हिस्से में स्थित जेएस होटल फ़ू क्वोक किफ़ायती दरों पर स्वच्छ 3-स्टार कमरे और तत्पर फ्रंट-डेस्क सेवा प्रदान करता है। बाहर निकलते ही अमाल्फ़ी प्रोमेनाड पर रेस्तरां, मनी एक्सचेंज, मिनीमार्ट और सनसेट व्यूपॉइंट मिल जाते हैं।', public_name = 'JS Hotel Phu Quoc Sunset Town', tags = ARRAY['boutique_hotel', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'js-hotel-phu-quoc-sunset-town';
UPDATE public.businesses SET category = 'hotels', subcategory = 'boutique_hotel', address = '18 Positano, Sunset Town, Phú Quốc, An Giang 91000, Vietnam', description_ko = '선셋타운 지중해풍 부티크 호텔.', description_en = 'Haibot 12 Homestay Sunset Town Phu Quoc is a boutique hotel located in Sunset Town, Phu Quoc.', description_vi = 'Haibot 12 Homestay Sunset Town Phu Quoc là khách sạn boutique nằm tại Thị trấn Hoàng Hôn, Phú Quốc.', description_zh = 'Haibot 12 Homestay Sunset Town Phu Quoc 是位于富国岛日落小镇的地中海风格民宿。', description_ja = 'Haibot 12 Homestay Sunset Town Phu Quocは、フーコックのサンセットタウンにある地中海風のホームステイ宿泊施設です。', description_ru = 'Haibot 12 Homestay Sunset Town Phu Quoc — это объект размещения в стиле хоумстей в средиземноморском стиле, расположенный в Sunset Town на Фукуоке.', description_hi = 'Haibot 12 Homestay Sunset Town Phu Quoc फु कुओक के Sunset Town में स्थित एक भूमध्यसागरीय शैली का होमस्टे आवास है।', public_name = 'Haibot 12 Homestay Sunset Town Phu Quoc', tags = ARRAY['boutique_hotel', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'haibot-12-homestay-sunset-town-phu-quoc';
