UPDATE public.businesses SET category = 'hotels', subcategory = 'residence', address = 'Phu Quoc, An Giang, Vietnam', description_ko = 'Sun Grand City Hillside 고층 아파트먼트, 오션/불꽃놀이 뷰.', description_en = 'Casa Del Mar Hotel & Apartment - Sunset Town is a residence apartment located in Sunset Town, Phu Quoc.', description_vi = 'Casa Del Mar Hotel & Apartment - Sunset Town là căn hộ lưu trú nằm tại Thị trấn Hoàng Hôn, Phú Quốc.', description_zh = 'Casa Del Mar Hotel & Apartment - Sunset Town 是位于富国岛日落小镇 Sun Grand City Hillside 的高层公寓式住宿，可欣赏海景和烟花。', description_ja = 'Casa Del Mar Hotel & Apartment - Sunset Townは、フーコックのサンセットタウンにあるSun Grand City Hillsideの高層アパートメントで、オーシャンビューと花火の景観を楽しめます。', description_ru = 'Casa Del Mar Hotel & Apartment - Sunset Town — это высотные апартаменты в Sun Grand City Hillside в Sunset Town на Фукуоке с видом на море и фейерверки.', description_hi = 'Casa Del Mar Hotel & Apartment - Sunset Town फु कुओक के Sunset Town में Sun Grand City Hillside में स्थित एक ऊंची इमारत वाला अपार्टमेंट है, जहाँ से समुद्र और आतिशबाजी का दृश्य दिखता है।', public_name = 'Casa Del Mar Hotel & Apartment - Sunset Town', tags = ARRAY['residence', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'casa-del-mar-hotel-apartment-sunset-town';
UPDATE public.businesses SET category = 'hotels', subcategory = 'residence', address = 'Phu Quoc, An Giang, Vietnam', description_ko = 'Sun Grand City Hillside 고층 아파트먼트, 오션/불꽃놀이 뷰.', description_en = 'Hillside Apartment Sunset Town Phu Quoc - Apartment with Sea View is a residence apartment located in Sunset Town, Phu Quoc.', description_vi = 'Hillside Apartment Sunset Town Phu Quoc - Apartment with Sea View là căn hộ lưu trú nằm tại Thị trấn Hoàng Hôn, Phú Quốc.', description_zh = 'Hillside Apartment Sunset Town Phu Quoc - Apartment with Sea View是位于富国岛日落小镇Sun Grand City Hillside的高层海景公寓，可欣赏大海与烟花秀。', description_ja = 'Hillside Apartment Sunset Town Phu Quoc - Apartment with Sea Viewは、フーコックのサンセットタウンにあるSun Grand City Hillsideの高層アパートメントで、海の景色と花火を望めます。', description_ru = 'Hillside Apartment Sunset Town Phu Quoc - Apartment with Sea View — апартаменты в высотном здании Sun Grand City Hillside в Сансет-Тауне на Фукуоке с видом на море и фейерверки.', description_hi = 'Hillside Apartment Sunset Town Phu Quoc - Apartment with Sea View फु कुओक के Sunset Town में Sun Grand City Hillside में स्थित एक ऊंची इमारत वाला समुद्र दृश्य अपार्टमेंट है, जहाँ से आतिशबाजी भी देखी जा सकती है।', public_name = 'Hillside Apartment Sunset Town Phu Quoc - Apartment with Sea View', tags = ARRAY['residence', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'hillside-apartment-sunset-town-phu-quoc-apartment-with-sea-view';
UPDATE public.businesses SET category = 'dining', subcategory = 'western', address = 'New, Phú Quốc, An Giang 92000, Vietnam', description_ko = '그리스 전통 타베르나와 이탈리안 피제리아를 결합한 지중해 캐주얼 다이닝 레스토랑입니다. 참숯 향이 살아있는 그리스 수블라키·기로스·무사카부터 수제 화덕 피자, 생면 파스타, 양갈비 스테이크까지 선셋타운의 이국적인 거리 분위기와 잘 어우러집니다.', description_en = 'Combining a traditional Greek taverna with an artisan Italian pizzeria, MEDITERRAN brings authentic Mediterranean flavors to Sunset Town. Enjoy flame-grilled souvlaki skewers, gyros, creamy moussaka, wood-fired pizzas, and lamb chops in a warm, breezy setting.', description_vi = 'Kết hợp giữa quán rượu taverna Hy Lạp truyền thống và tiệm pizza thủ công nước Ý, MEDITERRAN mang hương vị Địa Trung Hải nguyên bản đến Thị trấn Hoàng Hôn. Thực khách có thể thưởng thức thịt xiên nướng souvlaki thơm lừng, bánh cuộn gyros, moussaka béo ngậy cùng pizza lò củi, mì Ý tươi và sườn cừu nướng.', description_zh = 'MEDITERRAN 将传统希腊小酒馆与手工意式披萨店巧妙结合，为日落小镇带来纯正的地中海风味。从炭香四溢的希腊烤肉串（Souvlaki）、旋转烤肉卷、经典茄子千层面（Moussaka），到窑烤手工披萨、鲜制意面与烤羊排，与小镇异域街景相得益彰。', description_ja = 'ギリシャの伝統的なタベルナとイタリアの職人ピッツェリアを融合させた地中海カジュアルダイニングです。炭火香るギリシャ風スブラキやギロス、濃厚なムサカから、薪窯ナポリピッツァ、生パスタ、ラムチョップまで、異国情緒あふれるサンセットタウンの街並みにぴったり調和します。', description_ru = 'Ресторан MEDITERRAN объединяет традиционную греческую таверну и ремесленную итальянскую пиццерию, привнося в Сансет-Таун подлинные вкусы Средиземноморья. В меню — обжаренные на огне шашлычки сувлаки, гирос, нежная мусака, пицца из дровяной печи, домашняя паста и каре ягнёнка.', description_hi = 'पारंपरिक ग्रीक तवेर्ना और आर्टिसन इतालवी पिज़्ज़ेरिया के संगम के रूप में मेडिटेरेन सनसेट टाउन में प्रामाणिक भूमध्यसागरीय स्वाद परोसता है। आरामदायक माहौल में फ्लेम-ग्रिल्ड सुवलाकी स्क्यूअर्स, जायरोस, क्रीमी मुसाका, वुड-फ़ायर्ड पिज़्ज़ा, पास्ता और लैम्ब चॉप्स का लुत्फ़ उठाएँ।', public_name = '메디테란 선셋타운 (MEDITERRAN Sunset Town (Greek & Italian Restaurant) pizza, pasta & souvlaki)', price_level = '$$$', tags = ARRAY['western', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'mediterran-sunset-town-greek-italian-restaurant-pizza-pasta-souvlaki';
UPDATE public.businesses SET category = 'dining', subcategory = 'western', address = 'Sunset Town Terza, Phú Quốc, An Giang 91000, Vietnam', description_ko = '라 페스타 푸꾸옥(힐튼) 내에 자리한 스페인 지중해식 캐주얼 파인 다이닝 레스토랑입니다. 사프란 향이 깊은 해산물 빠에야와 정통 스페인 타파스, 숙성 이베리코 하몽, 과일 향이 풍부한 상그리아를 해안 휴양지 무드 속에서 여유롭게 즐길 수 있습니다.', description_en = 'Located inside La Festa Phu Quoc, Curio Collection by Hilton, Finca celebrates coastal Spanish dining in a sunlit Mediterranean dining room. Share saffron-infused seafood paella, artisan Iberico ham, vibrant tapas plates, and house-made sangria overlooking the Sunset Town shoreline.', description_vi = 'Nằm trong khuôn viên La Festa Phu Quoc, Curio Collection by Hilton, Finca tôn vinh ẩm thực vùng biển Tây Ban Nha giữa không gian Địa Trung Hải ngập nắng. Thực đơn cuốn hút với cơm hải sản paella nghệ tây, đùi heo muối Iberico, các món tapas đầy sắc màu cùng rượu sangria pha chế thủ công.', description_zh = 'Finca 位于富国岛拉菲斯塔希尔顿酒店内，是一间主打西班牙海岸风味的明亮地中海餐厅。宾客可在此分享藏红花海鲜西班牙烩饭（Paella）、醇香伊比利亚火腿、缤纷塔帕斯小食与自制桑格利亚果酒，尽享悠闲的海滨度假食光。', description_ja = 'ラ・フェスタ・フーコック（ヒルトン）館内に位置する、スペイン・地中海料理のカジュアルファインダイニングです。サフラン香る魚介のパエリアや本格タパス、熟成イベリコ豚の生ハム、フルーティーなサングリアをリゾート感あふれる空間で堪能できます。', description_ru = 'Ресторан испанской прибрежной кухни Finca в отеле La Festa Phu Quoc, Curio Collection by Hilton встречает гостей светлым средиземноморским залом. Здесь подают ароматную паэлью с морепродуктами и шафраном, хамон иберико, разнообразные тапас и домашнюю сангрию.', description_hi = 'ला फ़ेस्टा फ़ू क्वोक, क्यूरियो कलेक्शन बाय हिल्टन के भीतर स्थित फ़िन्का धूप से सजे भूमध्यसागरीय परिवेश में तटीय स्पैनिश व्यंजन परोसता है। यहाँ केसर की खुशबू वाले सीफ़ूड पायेला, इबेरिको हैम, स्वादिष्ट तापास और ताज़ा संगरिया का आनंद लिया जा सकता है।', public_name = '핀카 (Finca)', price_level = '$$$$', tags = ARRAY['western', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'finca';
UPDATE public.businesses SET category = 'dining', subcategory = 'international', address = 'Sunset Town Terza, Phú Quốc, An Giang 91000, Vietnam', description_ko = '라 페스타 푸꾸옥(힐튼)에서 운영하는 모던 광동식 중식 & 수제 딤섬 파인 다이닝 레스토랑입니다. 정교하게 빚어낸 딤섬 셀렉션과 바삭한 광동식 로스트 덕, 푸꾸옥 제철 활해산물을 활용한 고급 중식 일품요리를 세련된 실내와 바다 전망 테라스에서 선보입니다.', description_en = 'Set within La Festa Phu Quoc, Curio Collection by Hilton, Seta presents contemporary Cantonese cuisine and handcrafted dim sum with coastal views. Diners savor delicate steamed dumplings, crispy Cantonese roast meats, and live Phu Quoc seafood wok specialties in an upscale setting.', description_vi = 'Tọa lạc tại La Festa Phu Quoc, Curio Collection by Hilton, Seta mang đến nghệ thuật ẩm thực Quảng Đông đương đại và dim sum thủ công tinh xảo hướng biển. Thực khách có thể thưởng thức há cảo hấp nóng hổi, vịt quay Quảng Đông da giòn cùng hải sản tươi sống Phú Quốc chế biến thượng hạng.', description_zh = 'Seta 现代粤菜及点心餐厅坐落于富国岛拉菲斯塔希尔顿酒店内，兼具雅致东方美学室内空间与海景露台。餐厅严选富国岛时令鲜活海产，匠心呈献手工现蒸港式点心、脆皮广式烧味及精致粤式小炒。', description_ja = 'ラ・フェスタ・フーコック（ヒルトン）内にある、モダン広東料理＆手作り点心のファインダイニングです。繊細な蒸し点心の数々や香ばしい広東式ローストダック、フーコック近海の新鮮な魚介を使った本格中華を洗練された空間と海景テラスで味わえます。', description_ru = 'Ресторан современной кантонской кухни Seta в отеле La Festa Phu Quoc, Curio Collection by Hilton сочетает изысканный интерьер с видом на море. Гостям подают димсамы ручной лепки, хрустящую утку и мясные деликатесы по-кантонски, а также блюда вок из живых морепродуктов Фукуока.', description_hi = 'ला फ़ेस्टा फ़ू क्वोक, क्यूरियो कलेक्शन बाय हिल्टन में स्थित सेता समुद्री नज़ारों के साथ आधुनिक कैंटोनीज़ व्यंजन और हस्तनिर्मित डिम सम प्रस्तुत करता है। यहाँ भाप में पके नाज़ुक डम्पलिंग्स, क्रिस्पी कैंटोनीज़ रोस्ट और ताज़ा फ़ू क्वोक सीफ़ूड वोक स्पेशलिटीज़ का स्वाद मिलता है।', public_name = '세타 (Seta)', price_level = '$$$$', tags = ARRAY['international', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'seta';
UPDATE public.businesses SET category = 'dining', subcategory = 'vietnamese', address = '81 Đ.Positano, Sunset Town, Phú Quốc, An Giang 92000, Vietnam', description_ko = '포지타노 거리 81번지에 자리한 남부 베트남 가정식 레스토랑입니다. 바삭한 반쎄오(베트남식 크레페)와 진한 육수의 쌀국수, 분짜, 푸꾸옥 해산물 볶음 요리를 에어컨이 완비된 쾌적한 실내에서 합리적인 가격으로 정갈하게 맛볼 수 있습니다.', description_en = 'Situated at 81 Positano Street, NamBo Kitchen specializes in authentic Southern Vietnamese home-style cooking in a clean, air-conditioned dining room. Highlights include crispy banh xeo crepes, rich beef pho, grilled pork bun cha, and fresh Phu Quoc seafood stir-fries.', description_vi = 'Nằm tại số 81 đường Positano, NamBo Kitchen mang đến hương vị cơm nhà miền Nam Việt Nam chuẩn vị trong không gian máy lạnh sạch sẽ, thoáng mát với mức giá hợp lý. Thực đơn nổi bật gồm bánh xèo miền Tây giòn rụm, phở bò nước dùng đậm đà, bún chả nướng và các món hải sản Phú Quốc xào tươi ngon.', description_zh = 'NamBo Kitchen 位于波西塔诺街 81 号，是一家主打正宗越南南部家常风味的餐厅，室内干净整洁且配备凉爽空调。招牌菜包括酥脆的越式煎班戟（Bánh xèo）、浓郁牛肉河粉、炭烤猪肉米线（Bún chả）及富国岛鲜美海鲜小炒，价格亲民实惠。', description_ja = 'ポジターノ通り81番地に位置する、南部ベトナムの家庭料理を味わえるレストランです。エアコン完備の清潔で快適な店内にて、パリッと焼き上げたバインセオや濃厚スープの牛肉フォー、ブンチャー、フーコック産シーフードの炒め物を手頃な価格で楽しめます。', description_ru = 'Ресторан NamBo Kitchen на улице Позитано, 81, специализируется на домашней кухне Южного Вьетнама в чистом зале с кондиционером и доступными ценами. В меню выделяются хрустящие блинчики бань-сео, наваристый суп фо с говядиной, бун-ча на гриле и блюда из свежих морепродуктов Фукуока.', description_hi = '81 पॉज़िटानो स्ट्रीट पर स्थित नामबो किचन स्वच्छ और वातानुकूलित डाइनिंग रूम में प्रामाणिक दक्षिणी वियतनामी घरेलू व्यंजन परोसता है। इसके प्रमुख आकर्षणों में कुरकुरे बान सेओ क्रेप्स, गाढ़े शोरबे वाला बीफ़ फ़ो, ग्रिल्ड पोर्क बुन चा और ताज़ा फ़ू क्वोक सीफ़ूड स्टिर-फ़्राई शामिल हैं।', public_name = '남보 키친 (NamBo Kitchen)', tags = ARRAY['vietnamese', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'nambo-kitchen';
UPDATE public.businesses SET category = 'dining', subcategory = 'seafood', address = 'Chợ đêm Vuifest - Sunset town, Phú Quốc, An Giang 92500, Vietnam', description_ko = '부이페스트(VuiFest) 야시장 내에 위치한 직화 해산물 & 문어 요리 전문점으로, 숯불에 구워내는 통문어·오징어 구이와 갈릭 버터 타이거 새우, 조개 요리를 시원한 맥주와 함께 야외 테라스에서 즐길 수 있습니다.', description_en = 'Open-air seafood grill restaurant inside VuiFest Night Market specializing in charcoal-grilled whole octopus, squid, garlic butter tiger prawns, and clams paired with cold beer.', description_vi = 'Nhà hàng hải sản nướng ngoài trời trong chợ đêm VuiFest, chuyên bạch tuộc nguyên con, mực, tôm sú bơ tỏi và nghêu nướng than, dùng kèm bia lạnh.', description_zh = '位于日落小镇 VuiFest 夜市内的露天海鲜烧烤餐厅，主打炭烤整只章鱼、鱿鱼、蒜香黄油虎虾和蛤蜊，并供应冰镇啤酒。', description_ja = 'サンセットタウンのVuiFestナイトマーケット内にある屋外シーフードグリルレストラン。丸ごと炭火焼きにしたタコやイカ、ガーリックバター風味のタイガープラウン、アサリなどを冷たいビールとともに楽しめます。', description_ru = 'Ресторан морепродуктов на открытом воздухе на ночном рынке VuiFest в Сансет-Тауне. Здесь готовят на углях целых осьминогов, кальмаров, тигровых креветок с чесночным маслом и моллюсков, а также подают холодное пиво.', description_hi = 'सनसेट टाउन के VuiFest नाइट मार्केट में स्थित यह खुला सीफ़ूड ग्रिल रेस्तराँ कोयले पर ग्रिल किया हुआ साबुत ऑक्टोपस, स्क्विड, लहसुन-मक्खन वाले टाइगर प्रॉन और क्लैम परोसता है। साथ में ठंडी बीयर भी उपलब्ध है।', public_name = '옥토퍼스 아일랜드 레스토랑 (Octopus Island Restaurant - Night Market Sunset town)', tags = ARRAY['seafood', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'octopus-island-restaurant-night-market-sunset-town';
UPDATE public.businesses SET category = 'dining', subcategory = 'korean', address = 'A56 sunset town, Phú Quốc, An Giang 920000, Vietnam', description_ko = '선셋타운 중심가에 자리한 인기 한국 분식 전문점으로, 매콤달콤한 국물 떡볶이와 참치·소고기 김밥, 바삭한 모둠 튀김, 얼큰한 라면을 푸짐하게 선보입니다. 야간 쇼 관람 전후 빠르고 든든한 한식 식사나 야식 포장 코스로 여행자들에게 인기가 높습니다.', description_en = 'Located in central Sunset Town, Sunset Bunsik serves comforting Korean street food favorites including spicy tteokbokki rice cakes, freshly rolled gimbap, crispy tempura, and hot ramyeon noodles. Generous portions and quick service make it a go-to spot before or after the evening shows.', description_vi = 'Tọa lạc tại trung tâm Thị trấn Hoàng Hôn, Sunset Bunsik chuyên phục vụ các món ăn vặt Hàn Quốc quen thuộc như bánh gạo cay tteokbokki, kimbap cá ngừ và bò cuộn tươi, đồ chiên giòn cùng mì ramyeon nóng hổi. Khẩu phần đầy đặn và lên món nhanh rất tiện cho bữa ăn trước hoặc sau giờ xem show.', description_zh = 'Sunset Bunsik（日落韩式小吃店）位于日落小镇中心街区，主打甜辣过瘾的韩式炒年糕、现卷金枪鱼与牛肉紫菜包饭、酥脆什锦炸物以及热腾腾的韩式拉面。分量十足且出餐迅速，是观看夜间演出前后解决简餐或打包宵夜的热门之选。', description_ja = 'サンセットタウン中心部にある人気の韓国粉食（ブンシク）専門店で、甘辛いスープトッポッキや具だくさんのキンパ、サクサクの天ぷら盛り合わせ、熱々の韓国ラーメンを提供しています。ボリューム満点で提供も早く、夜のショー前後の食事や夜食のテイクアウトに重宝します。', description_ru = 'Популярное кафе корейского стритфуда Sunset Bunsik в центре Сансет-Тауна готовит острые рисовые клёцки ттокпокки, свежие роллы кимбап, хрустящую темпуру и горячий рамён. Большие порции и быстрая подача делают заведение отличным выбором для перекуса до или после вечерних шоу.', description_hi = 'मध्य सनसेट टाउन में स्थित सनसेट बुनसिक लोकप्रिय कोरियन स्ट्रीट फ़ूड परोसता है, जिसमें मसालेदार त्तेओकबोक्की राइस केक, ताज़ा गिमबाप रोल, कुरकुरे टेम्पुरा और गरमागरम रामयोन नूडल्स शामिल हैं। भरपूर मात्रा और त्वरित सेवा इसे शाम के शो से पहले या बाद में खाने के लिए बेहतरीन बनाती है।', public_name = '선셋분식 (Sunset Bunsik)', tags = ARRAY['korean', 'Sunset Town', '선셋분식', 'Sunset bunsik']::text[], updated_at = NOW() WHERE slug = 'sunset-bunsik';
UPDATE public.businesses SET category = 'dining', subcategory = 'western', address = 'Amafi 136, Sunset Town, Phú Quốc, An Giang, Vietnam', description_ko = '선셋타운 아말피(Amalfi) 해안 거리에 위치한 로맨틱 이탈리안 레스토랑으로, 수제 도우 화덕 피자와 신선한 해산물 파스타, 와인을 일몰 오션뷰와 함께 즐길 수 있습니다.', description_en = 'Romantic Italian restaurant on Amalfi Street in Sunset Town serving wood-fired pizzas, fresh seafood pasta, and wine with sunset ocean views.', description_vi = 'Nhà hàng Ý trên đường Amalfi tại Thị trấn Hoàng Hôn, phục vụ pizza lò củi, mì Ý hải sản tươi và rượu vang với tầm nhìn biển lúc hoàng hôn.', description_zh = '位于日落小镇 Amalfi 街的意大利餐厅，环境适合情侣用餐，供应柴火烤披萨、新鲜海鲜意面和葡萄酒，用餐时可欣赏日落海景。', description_ja = 'サンセットタウンのAmalfi通りにある、落ち着いた雰囲気のイタリアンレストラン。薪窯焼きピザ、新鮮な魚介を使ったパスタ、ワインを提供しており、海に沈む夕日を眺めながら食事を楽しめます。', description_ru = 'Итальянский ресторан с романтической атмосферой на улице Amalfi в Сансет-Тауне. В меню — пицца из дровяной печи, паста со свежими морепродуктами и вино. Из ресторана открывается вид на море и закат.', description_hi = 'सनसेट टाउन की Amalfi स्ट्रीट पर स्थित यह रोमांटिक माहौल वाला इतालवी रेस्तराँ लकड़ी के ओवन में बने पिज़्ज़ा, ताज़े समुद्री भोजन वाला पास्ता और वाइन परोसता है। यहाँ भोजन करते हुए समुद्र पर सूर्यास्त का नज़ारा देखा जा सकता है।', public_name = 'BLUE TABLE(Italian Restaurant)', tags = ARRAY['western', 'Sunset Town', '블루 테이블', 'Blue Table', 'Italian Restaurant']::text[], updated_at = NOW() WHERE slug = 'blue-table-italian-restaurant';
UPDATE public.businesses SET category = 'dining', subcategory = 'western', address = '15-17 Đường Venice, Sunset Town, Phú Quốc, An Giang 92500, Vietnam', description_ko = '지중해풍 테라스에서 이탈리안 화덕 피자, 파스타, 브런치 플레이트와 함께 스페셜티 커피 및 열대과일 에이드를 즐길 수 있는 선셋타운 레스토랑 & 카페입니다.', description_en = 'Mediterranean-style restaurant and cafe in Sunset Town serving Italian pizzas, pasta, brunch plates, specialty coffee, and fruit ades.', description_vi = 'Nhà hàng và quán cà phê phong cách Địa Trung Hải tại Thị trấn Hoàng Hôn, phục vụ pizza Ý, mì Ý, brunch, cà phê đặc sản và nước trái cây pha soda.', description_zh = '位于日落小镇的地中海风格餐厅兼咖啡馆，提供意大利披萨、意面、早午餐、精品咖啡和水果气泡饮。', description_ja = 'サンセットタウンにある地中海スタイルのレストラン＆カフェ。イタリアンピザ、パスタ、ブランチメニュー、スペシャルティコーヒー、フルーツエードなどを提供しています。', description_ru = 'Ресторан и кафе в средиземноморском стиле в Сансет-Тауне. В меню — итальянская пицца, паста, блюда для бранча, спешелти-кофе и фруктовые газированные напитки.', description_hi = 'सनसेट टाउन में स्थित यह भूमध्यसागरीय शैली का रेस्तराँ और कैफ़े इतालवी पिज़्ज़ा, पास्ता, ब्रंच के व्यंजन, स्पेशलिटी कॉफ़ी और फलों से बने ठंडे फ़िज़ी ड्रिंक्स परोसता है।', public_name = '베니스 카페 & 이터리 (Venice Cafe)', tags = ARRAY['cafe', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'venice-cafe';
UPDATE public.businesses SET category = 'dining', subcategory = 'vietnamese', address = 'P27 Chợ đêm Vuifest - Sunset Town, Phú Quốc, An Giang 91000, Vietnam', description_ko = '베트남 전통 소쿠리(Cái Mâm)에 정갈하게 담아내는 베트남 가정식 백반과 해산물 요리, 분짜·반쎄오 및 시원한 음료를 맛볼 수 있는 선셋타운 베트남 비스트로입니다.', description_en = 'Vietnamese bistro in Sunset Town serving traditional home-style platter meals, local seafood dishes, bun cha, banh xeo, and refreshing drinks.', description_vi = 'Quán bistro Việt tại Thị trấn Hoàng Hôn, phục vụ mâm cơm truyền thống, hải sản địa phương, bún chả, bánh xèo và đồ uống giải khát.', description_zh = '位于日落小镇的越南风味小餐馆，提供传统家常拼盘套餐、本地海鲜、越式烤肉米粉（Bún Chả）、越南煎饼（Bánh Xèo）及清爽饮品。', description_ja = 'サンセットタウンにあるベトナム料理のビストロ。伝統的な家庭料理の盛り合わせ、地元のシーフード料理、ブンチャー、バインセオ、さっぱりとしたドリンクなどを提供しています。', description_ru = 'Вьетнамское бистро в Сансет-Тауне. Здесь подают традиционные домашние блюда в наборах, местные морепродукты, бунча — рисовую лапшу с жареным мясом, вьетнамские блинчики баньсео и освежающие напитки.', description_hi = 'सनसेट टाउन का यह वियतनामी बिस्ट्रो पारंपरिक घरेलू भोजन की थालियाँ, स्थानीय समुद्री व्यंजन, बुन चा (Bún Chả), बान सेओ (Bánh Xèo) और ताज़गी देने वाले पेय परोसता है।', public_name = '까이 멈 비스트로 (CÁI MÂM BISTRO)', tags = ARRAY['cafe', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'cai-mam-bistro';
UPDATE public.businesses SET category = 'dining', subcategory = 'korean', address = 'An Giang, Phú Quốc, Khu 2, Đ. Amalfi, Vietnam', description_ko = '선셋타운 아말피(Amalfi) 거리에 위치한 정통 한식 구이 & 찌개 전문점입니다. 두툼한 삼겹살·목살 구이와 진한 국물의 김치찌개·된장찌개, 정갈한 한식 밑반찬을 넉넉한 양으로 내어주어 가족 단위 여행객의 한식 외식 코스로 제격입니다.', description_en = 'Located along Amalfi Street in Sunset Town, Ddungbojip is a hearty Korean BBQ and stew restaurant known for generous portions and authentic home-style side dishes. Popular orders include thick-cut grilled pork belly, bubbling kimchi stew, soybean paste stew, and cold noodles.', description_vi = 'Nằm trên trục đường Amalfi của Thị trấn Hoàng Hôn, Ddungbojip là nhà hàng thịt nướng và canh hầm Hàn Quốc chuẩn vị nổi tiếng nhờ khẩu phần hào phóng cùng quầy panchan chỉn chu. Thực khách gia đình rất chuộng ba chỉ heo cắt dày nướng than, canh kim chi, canh tương đậu và mì lạnh giải nhiệt.', description_zh = '胖子家韩式烤肉炖汤店（Ddungbojip）坐落于日落小镇阿马尔菲街，以分量扎实的正宗韩式烤肉、热锅炖汤与地道韩式小菜闻名。人气菜品包括厚切烤五花肉、猪颈肉、浓郁泡菜汤、大酱汤与爽口冷面，非常适合家庭旅客聚餐。', description_ja = 'サンセットタウンのアマルフィ通りにある本格韓国焼肉＆チゲ専門店です。厚切りのサムギョプサルやモクサル（豚肩ロース）、旨みたっぷりのキムチチゲ・テンジャンチゲを多彩な韓国おかずとともにボリューム満点で提供し、家族連れの食事にもぴったりです。', description_ru = 'Основательный корейский ресторан барбекю и рагу Ddungbojip на улице Амальфи в Сансет-Тауне славится большими порциями и домашними закусками панчхан. Гости особенно любят толстые ломтики жареной свиной грудинки самгёпсаль, кипящее кимчи-ччигэ, соевый суп твенджан-ччигэ и холодную лапшу.', description_hi = 'सनसेट टाउन की अमाल्फ़ी स्ट्रीट पर स्थित दुंगबोजिप भरपूर मात्रा और पारंपरिक साइड डिशेज़ के लिए प्रसिद्ध एक प्रामाणिक कोरियन बीबीक्यू और स्टू रेस्तरां है। इसके लोकप्रिय व्यंजनों में थिक-कट ग्रिल्ड पोर्क बेली, गरमागरम किमची स्टू, सोयाबीन पेस्ट स्टू और ठंडे नूडल्स शामिल हैं।', public_name = '푸꾸옥 뚱보집 선셋타운', tags = ARRAY['korean', 'Sunset Town', '뚱보집', 'Phu Quoc Ttungbojip']::text[], updated_at = NOW() WHERE slug = 'sunset-place';
UPDATE public.businesses SET category = 'dining', subcategory = 'korean', address = 'Amalfi Street (Near A103), Sunset Town, An Thới, Phú Quốc, Kiên Giang, Vietnam', description_ko = '선셋타운에서 참숯 화로에 구워내는 육즙 가득한 삼겹살·목살·소갈비 바비큐와 얼큰한 김치찌개, 냉면, 밑반찬을 푸짐하게 맛볼 수 있는 정통 한식 참숯구이 전문점입니다.', description_en = 'Authentic Korean charcoal BBQ restaurant in Sunset Town serving premium grilled pork belly, marinated beef ribs, kimchi stew, and traditional Korean side dishes.', description_vi = 'Nhà hàng BBQ Hàn Quốc nướng than tại Thị trấn Hoàng Hôn, phục vụ ba chỉ heo, sườn bò ướp, canh kimchi và các món ăn kèm Hàn Quốc.', description_zh = '位于日落小镇的韩式炭火烤肉餐厅，供应精选烤五花肉、腌制牛排骨、泡菜汤及传统韩式小菜。', description_ja = 'サンセットタウンにある韓国式炭火焼肉レストラン。上質なサムギョプサル、味付け牛カルビ、キムチチゲ、韓国の伝統的なおかずなどを提供しています。', description_ru = 'Ресторан корейского барбекю на углях в Сансет-Тауне. В меню — отборная свиная грудинка на гриле, маринованные говяжьи рёбрышки, суп с кимчи и традиционные корейские закуски.', description_hi = 'सनसेट टाउन में स्थित यह कोरियाई चारकोल BBQ रेस्तराँ प्रीमियम ग्रिल्ड पोर्क बेली, मैरिनेटेड बीफ़ रिब्स, किमची स्ट्यू और पारंपरिक कोरियाई साइड डिश परोसता है।', public_name = '한식당 화로구이 (Charcoal Korean BBQ)', tags = ARRAY['korean', 'Sunset Town', '화로구이', '한식당 화로구이']::text[], updated_at = NOW() WHERE slug = 'charcoal-korean-bbq';
UPDATE public.businesses SET category = 'dining', subcategory = 'western', address = 'Sunset Town Level 1, Phú Quốc, An Giang 91000, Vietnam', description_ko = '라 페스타 푸꾸옥(힐튼) 1층에 자리한 시그니처 이탈리안 트라토리아 & 오션뷰 다이닝 레스토랑입니다. 셰프가 직접 뽑는 수제 생면 파스타와 나폴리식 화덕 피자, 지중해식 그릴 해산물과 스테이크를 엄선된 이탈리안 와인 리스트와 함께 로맨틱하게 즐길 수 있습니다.', description_en = 'Situated on Level 1 of La Festa Phu Quoc, Mare is the resort’s signature Italian trattoria overlooking the Sunset Town coastline. Expect house-made artisanal pastas, wood-fired Neapolitan pizzas, Mediterranean grilled seafood, prime steaks, and a curated Italian wine cellar.', description_vi = 'Nằm tại tầng 1 của khu nghỉ dưỡng La Festa Phu Quoc, Mare là nhà hàng Ý chủ đạo sở hữu tầm nhìn lãng mạn ra bờ biển Thị trấn Hoàng Hôn. Thực đơn chinh phục thực khách bằng mì Ý tươi làm thủ công, pizza nướng củi, hải sản nướng Địa Trung Hải, bít tết cùng hầm rượu vang Ý tuyển chọn.', description_zh = 'Mare 位于富国岛拉菲斯塔希尔顿酒店 1 层，是酒店俯瞰日落小镇海岸线的招牌意大利餐厅。主厨每日新鲜制作手工意面与木柴窑烤披萨，搭配地中海炭烤海鲜、精选牛排及丰富的意大利酒庄藏酒，氛围浪漫优雅。', description_ja = 'ラ・フェスタ・フーコック（ヒルトン）1階に位置する、サンセットタウンの海岸線を望むシグネチャー・イタリアンレストランです。シェフ手打ちの生パスタや薪窯焼きピッツァ、地中海風シーフードグリル、ステーキを厳選イタリアワインとともにロマンチックに堪能できます。', description_ru = 'Фирменная итальянская траттория Mare на 1-м этаже курорта La Festa Phu Quoc выходит окнами и террасой на побережье Сансет-Тауна. В меню — домашняя паста ручной работы, неаполитанская пицца из печи, средиземноморские морепродукты на гриле, стейки и богатая карта итальянских вин.', description_hi = 'ला फ़ेस्टा फ़ू क्वोक के लेवल 1 पर स्थित मारे रिसॉर्ट का प्रमुख इतालवी रेस्तरां है, जहाँ से सनसेट टाउन तट का सुंदर दृश्य दिखता है। यहाँ ताज़ा हैंडमेड पास्ता, वुड-फ़ायर्ड पिज़्ज़ा, मेडिटेरेनियन ग्रिल्ड सीफ़ूड, प्राइम स्टेक और चुनिंदा इतालवी वाइन परोसी जाती हैं।', public_name = '마레 (Mare)', price_level = '$$$$', tags = ARRAY['western', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'mare';
UPDATE public.businesses SET category = 'dining', subcategory = 'vietnamese', address = '40 Đường Venice, khu phố 6, Phú Quốc, An Giang 92513, Vietnam', description_ko = '베니스 거리 40번지에 위치한 하노이 3대 명물 쌀국수 브랜드 포틴(Phở Thìn)의 푸꾸옥 직영 매장입니다. 마늘과 함께 센 불에 볶아 불향을 입힌 소고기와 파채를 듬뿍 얹어내는 시그니처 직화 쌀국수(포 따이란)와 깊은 육수의 베트남식 전골을 쾌적한 실내에서 맛볼 수 있습니다.', description_en = 'Located at 40 Venice Street, Phở Thìn Phú Quốc brings Hanoi’s legendary 1979 pho heritage to Sunset Town in an air-conditioned setting. Its signature Phở Tái Lăn tops rich bone broth with wok-seared garlic beef and mounds of green scallions, alongside hearty Vietnamese hot pot sets.', description_vi = 'Tọa lạc tại số 40 đường Venice, Phở Thìn Phú Quốc mang trọn tinh hoa thương hiệu phở Hà Nội trứ danh vào không gian máy lạnh khang trang giữa Thị trấn Hoàng Hôn. Món phở tái lăn đặc trưng gây thương nhớ với thịt bò xào tỏi lửa lớn dậy mùi thơm, ngập hành lá trên nền nước dùng ninh xương đậm đà cùng các set lẩu hấp dẫn.', description_zh = '河内名店 Phở Thìn 富国岛分店位于威尼斯街 40 号，在舒适的空调堂食环境中传承自 1979 年的河内三大河粉风味。必点招牌蒜香猛火快炒牛肉河粉（Phở tái lăn）汤头醇厚、葱香浓郁，店内同时供应丰盛的越式火锅套餐。', description_ja = 'ヴェニス通り40番地に位置する、ハノイ三大フォーの名店「フォー・ティン（Phở Thìn）」のフーコック店です。ニンニクとともに強火で香ばしく炒めた牛肉とたっぷりの青ネギをのせた看板メニュー「フォー・タイラン」や本格ベトナム鍋を、涼しい店内で味わえます。', description_ru = 'Ресторан Phở Thìn Phú Quốc на улице Венеция, 40, представляет в Сансет-Тауне легендарную ханойскую школу супа фо в прохладном зале с кондиционером. Фирменное блюдо Phở Tái Lăn готовится с обжаренной на сильном огне чесночной говядиной, горой зелёного лука и насыщенным бульоном, а для компаний подают вьетнамский хот-пот.', description_hi = '40 वेनिस स्ट्रीट पर स्थित फ़ो थिन फ़ू क्वोक वातानुकूलित वातावरण में हनोई की प्रसिद्ध फ़ो नूडल परंपरा को सनसेट टाउन में प्रस्तुत करता है। इसके सिग्नेचर फ़ो ताई लान में गाढ़े शोरबे के ऊपर लहसुन के साथ तेज़ आँच पर भुना बीफ़ और भरपूर हरा प्याज़ परोसा जाता है, साथ ही वियतनामी हॉट पॉट भी उपलब्ध है।', public_name = '포틴 푸꾸옥 (Phở Thìn Phú Quốc - Top 3 Pho & Hot Pot)', price_level = '$$$', tags = ARRAY['vietnamese', 'Sunset Town', '포틴', '포틴 푸꾸옥']::text[], updated_at = NOW() WHERE slug = 'pho-thin-phu-quoc-top-3-pho-hot-pot';
UPDATE public.businesses SET category = 'dining', subcategory = 'seafood', address = '22J4+X3J, 65 Đ. Amalfi, Phú Quốc, An Giang 92500, Vietnam', description_ko = '아말피 해안도로(65 Amalfi) 바닷가에 펼쳐진 호치민 유명 다이닝 펍 체인의 선셋타운 지점입니다. 석양과 밤바다 불꽃놀이가 보이는 탁 트인 야외 비치사이드 테이블에서 직화 숯불 BBQ와 해산물 플래터, 시원한 수제 맥주·타워 비어를 활기차게 즐길 수 있습니다.', description_en = 'Occupying a prime beachfront stretch at 65 Amalfi Street, The Gangs Sunset brings Ho Chi Minh City''s famed open-air dining pub energy to Sunset Town. Feast on charcoal-grilled BBQ meats, fresh seafood platters, and craft beer towers with front-row sunset and fireworks views.', description_vi = 'Trải dài trên mặt biển đắt giá tại số 65 đường Amalfi, The Gangs Sunset mang trọn không khí sôi động của chuỗi dining pub nổi tiếng Sài Gòn đến Thị trấn Hoàng Hôn. Giữa bàn tiệc ngoài trời sát biển ngắm trọn hoàng hôn và pháo hoa, thực khách thỏa sức thưởng thức BBQ nướng than, khay hải sản tươi và tháp bia thủ công mát lạnh.', description_zh = 'The Gangs Sunset 占据阿马尔菲街 65 号黄金临海地段，将胡志明市超人气露天餐吧的热烈氛围带到日落小镇。食客可在第一排海滩露天餐桌前直击夕阳与夜间烟花秀，尽情享用炭火直烤 BBQ 肉排、鲜美海鲜拼盘以及精酿啤酒塔。', description_ja = 'アマルフィ海岸通り65番地のビーチフロントに広がる、ホーチミン発の人気ダイニングパブのサンセットタウン店です。夕陽と夜の花火を最前列で望む開放的な海辺の屋外席にて、炭火焼きBBQミートやシーフードプラッター、クラフトビールやタワービールを賑やかに楽しめます。', description_ru = 'Знаменитый сайгонский гастропаб The Gangs Sunset занимает лучший пляжный участок на улице Амальфи, 65, наполняя Сансет-Таун живой курортной энергией. За открытыми столиками у самой воды с видом на закат и фейерверк подают мясо на углях, плато морепродуктов и башни крафтового пива.', description_hi = '65 अमाल्फ़ी स्ट्रीट के प्रमुख समुद्र तट पर फैला द गैंग्स सनसेट हो ची मिन्ह सिटी के प्रसिद्ध ओपन-एयर डाइनिंग पब की जीवंत ऊर्जा को सनसेट टाउन में लाता है। सूर्यास्त और आतिशबाज़ी के फ्रंट-रो नज़ारों के साथ चारकोल-ग्रिल्ड बीबीक्यू, सीफ़ूड प्लैटर और क्राफ़्ट बीयर टावर्स का आनंद लें।', public_name = '더 갱스 선셋 (The Gangs Sunset)', price_level = '$$$', tags = ARRAY['seafood', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'the-gangs-sunset';
UPDATE public.businesses SET category = 'dining', subcategory = 'restaurant', address = '48 Positano Sunset Town, Phú Quốc, An Giang 92000, Vietnam', description_ko = '포지타노 거리 48번지에 자리한 정통 아메리칸 로우앤슬로우 훈제 바비큐 & 수제 맥주 전문점입니다. 장시간 참나무 연기로 훈연해 부드럽게 발라지는 스모크 폭립과 수제 버거, 수제 소시지를 다양한 로컬 크래프트 비어와 함께 캐주얼하게 즐기기 좋습니다.', description_en = 'Set at 48 Positano Street, Caveman Smoked Ribs & Craft Beer specializes in low-and-slow American-style smokehouse comfort food. Dig into fall-off-the-bone smoked pork ribs, artisanal sausages, and juicy gourmet burgers paired with cold Vietnamese craft beers on tap.', description_vi = 'Nằm tại số 48 đường Positano, Caveman Smoked Ribs & Craft Beer là điểm hẹn dành cho tín đồ thịt nướng xông khói kiểu Mỹ và bia thủ công. Sườn heo xông khói chậm mềm rục thấm vị, xúc xích làm tay và burger bò mọng nước kết hợp cực ăn ý cùng các dòng craft beer mát lạnh.', description_zh = 'Caveman 烟熏肋排与精酿啤酒屋坐落于波西塔诺街 48 号，主打正宗美式慢火烟熏烤肉料理。经过长时间熏烤的猪肋排软嫩脱骨、香气四溢，搭配手工香肠、多汁汉堡以及多款冰爽越南精酿生啤，氛围轻松畅快。', description_ja = 'ポジターノ通り48番地にある、本格アメリカンスタイルのスモークBBQ＆クラフトビール専門店です。じっくり低温燻製にして骨からほろりと外れるスモークポークリブや手作りソーセージ、ジューシーなバーガーを冷たいクラフトビールと気軽に楽しめます。', description_ru = 'Гастробар Caveman Smoked Ribs & Craft Beer на улице Позитано, 48, специализируется на американском копчёном барбекю томлёного приготовления. Нежнейшие свиные рёбрышки с дымком, домашние колбаски и сочные бургеры отлично сочетаются с холодным вьетнамским крафтовым пивом.', description_hi = '48 पॉज़िटानो स्ट्रीट पर स्थित केवमैन स्मोक्ड रिब्स एंड क्राफ़्ट बीयर धीमी आँच पर पके अमेरिकन स्मोकहाउस व्यंजनों के लिए जाना जाता है। यहाँ बेहद नरम स्मोक्ड पोर्क रिब्स, आर्टिसन सॉसेज और रसीले बर्गर के साथ ठंडी वियतनामी क्राफ़्ट बीयर का आनंद लें।', public_name = '케이브맨 스모크 립 & 크래프트 비어 (Caveman Smoked Ribs & Craft Beer)', price_level = '$$$', tags = ARRAY['restaurant', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'caveman-smoked-ribs-craft-beer';
UPDATE public.businesses SET category = 'dining', subcategory = 'restaurant', address = 'Sunset Town Level 1, Phú Quốc, An Giang 91000, Vietnam', description_ko = '라 페스타 푸꾸옥(힐튼) 1층에 위치한 메인 올데이 다이닝 레스토랑으로, 항구 도시 시장에서 영감을 얻은 활기찬 오픈 키친을 갖추고 있습니다. 아침에는 풍성한 인터내셔널·베트남 조식 뷔페를, 점심과 저녁에는 신선한 로컬 해산물과 웨스턴·아시안 단품 메뉴를 선보입니다.', description_en = 'Located on Level 1 of La Festa Phu Quoc, The Merchant is an airy all-day dining restaurant inspired by bustling European port markets and lively open kitchens. Guests gather for expansive international and Vietnamese breakfast buffets as well as coastal Asian and Western à la carte dishes.', description_vi = 'Nằm tại tầng 1 của La Festa Phu Quoc, The Merchant là nhà hàng ẩm thực cả ngày lấy cảm hứng từ những khu chợ cảng châu Âu nhộn nhịp với gian bếp mở sống động. Nhà hàng phục vụ buffet sáng quốc tế – Việt Nam phong phú cùng thực đơn gọi món Á – Âu và hải sản địa phương cho bữa trưa và tối.', description_zh = 'The Merchant 位于富国岛拉菲斯塔希尔顿酒店 1 层，是以热闹欧洲港口市集为灵感打造的全日制开放式厨房餐厅。早晨供应丰盛的国际与越式自助早餐，午晚餐时段则呈献新鲜本地海产及多元亚洲与西式单点佳肴。', description_ja = 'ラ・フェスタ・フーコック（ヒルトン）1階に位置する、活気ある港町のマルシェに着想を得たオープンキッチンのオールデイダイニングです。朝は種類豊富なインターナショナル＆ベトナム朝食ビュッフェ、昼夜は近海シーフードや洋食・アジアンアラカルトを提供します。', description_ru = 'Основной ресторан полного дня The Merchant на 1-м этаже отеля La Festa Phu Quoc оформлен в духе оживлённых европейских портовых рынков с открытой кухней. По утрам здесь сервируют богатый шведский стол с вьетнамскими и мировыми блюдами, а днём и вечером — меню à la carte из морепродуктов и классики Востока и Запада.', description_hi = 'ला फ़ेस्टा फ़ू क्वोक के लेवल 1 पर स्थित द मर्चेंट यूरोपीय बंदरगाह बाज़ारों और ओपन किचन से प्रेरित एक हवादार ऑल-डे डाइनिंग रेस्तरां है। यहाँ सुबह भव्य अंतरराष्ट्रीय व वियतनामी ब्रेकफ़ास्ट बुफ़े तथा दोपहर व रात में तटीय एशियाई और पश्चिमी व्यंजन परोसे जाते हैं।', public_name = '더 머천트 (The Merchant)', price_level = '$$$$', tags = ARRAY['restaurant', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'the-merchant';
UPDATE public.businesses SET category = 'dining', subcategory = 'seafood', address = 'AT-63 Đại Lộ New, Phường, Phú Quốc, An Giang, Vietnam', description_ko = '선셋타운 뉴 대로(AT-63)에 위치한 대형 수조 기반의 정찰제 해산물 & 그릴 레스토랑입니다. 살아있는 푸꾸옥산 크랩·랍스터·타이거 새우·가리비를 수족관에서 직접 골라 갈릭버터·타마린드 소스로 조리해 먹기 좋으며, 넓은 홀과 한국어 메뉴 안내를 지원합니다.', description_en = 'Located on New Boulevard (AT-63) in Sunset Town, Thuan Kieu 2 features transparent live seafood tanks and spacious dining halls ideal for families and groups. Guests can handpick live Phu Quoc crabs, lobsters, tiger prawns, and scallops prepared to order with garlic butter or tamarind glaze.', description_vi = 'Nằm trên Đại lộ New (AT-63) tại Thị trấn Hoàng Hôn, nhà hàng hải sản Thuận Kiều 2 sở hữu hệ thống bể hải sản tươi sống niêm yết giá rõ ràng cùng sảnh ăn rộng rãi cho gia đình và đoàn đông. Thực khách có thể tự tay chọn ghẹ Phú Quốc, tôm hùm, tôm sú, sò điệp bơi sống để chế biến sốt bơ tỏi hoặc rang me.', description_zh = '顺桥 2 号海鲜烧烤餐厅（Thuận Kiều 2）位于日落小镇新大道（AT-63），拥有明码标价的大型活海鲜池与宽敞舒适的聚餐大厅。食客可亲自挑选鲜活富国岛螃蟹、龙虾、黑虎虾与扇贝，现点现做蒜蓉黄油或罗望子风味佳肴，并备有多语种菜单指引。', description_ja = 'サンセットタウンのニュー大通り（AT-63）に位置する、大型生け簀を備えた明朗会計のシーフード＆グリルレストランです。活きの良いフーコック産のカニやロブスター、タイガープロウン、ホタテを生け簀から直接選んでガーリックバターやタマリンドソースで調理してもらえ、広いホールで団体や家族連れにも最適です。', description_ru = 'Большой ресторан морепродуктов и гриля Thuan Kieu 2 на бульваре Нью (AT-63) в Сансет-Тауне оснащён аквариумами с прозрачными ценами и просторным залом для семей и компаний. Гости сами выбирают живых фукуокских крабов, лобстеров, тигровых креветок и гребешков, которых готовят со сливочно-чесночным или тамариндовым соусом.', description_hi = 'सनसेट टाउन के न्यू बुलेवार्ड (AT-63) पर स्थित थुआन किउ 2 में पारदर्शी लाइव सीफ़ूड टैंक और परिवारों व समूहों के लिए विशाल डाइनिंग हॉल हैं। मेहमान ताज़ा फ़ू क्वोक केकड़े, लॉबस्टर, टाइगर प्रॉन और स्कैलप्स स्वयं चुन सकते हैं, जिन्हें गार्लिक बटर या इमली सॉस में तुरंत पकाया जाता है।', public_name = '투안 끼에우 2 해산물 식당 (Nhà hàng hải sản Thuận Kiều 2 | Seafood & Grill)', tags = ARRAY['seafood', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'nha-hang-hai-san-thuan-kieu-2-seafood-grill';
UPDATE public.businesses SET category = 'dining', subcategory = 'seafood', address = 'Ven45-sunset town, Phú Quốc, An Giang 92513, Vietnam', description_ko = '혼똔섬 해상 케이블카 탑승장 인근 베니스 거리(Ven45)에 자리한 로컬 해산물 전문점입니다. 갈릭버터와 매콤한 칠리 소스로 볶아낸 신선한 타이거 새우, 꽃게, 맛조개, 오징어 구이를 합리적인 가격에 즐길 수 있어 케이블카 탑승 전후 식사 코스로 편리합니다.', description_en = 'Just steps from the Hon Thom Cable Car station at Ven45 Venice Street, Hai San Cang serves fresh local seafood at approachable prices. Signature dishes include garlic butter tiger prawns, chili crab, grilled squid, and stir-fried razor clams paired with chilled local beer.', description_vi = 'Chỉ cách nhà ga cáp treo Hòn Thơm vài bước chân tại căn Ven45 đường Venice, Hải Sản Cảng phục vụ hải sản địa phương tươi ngon với mức giá dễ chịu. Thực đơn được yêu thích gồm tôm sú sốt bơ tỏi, ghẹ rang ớt, mực nướng mọi và ốc móng tay xào ăn kèm bia mát lạnh trước hoặc sau chuyến cáp treo.', description_zh = '海港海鲜餐厅（Hải Sản Cảng）位于威尼斯街 Ven45 号，毗邻香岛跨海缆车站，以亲民价格供应新鲜地道的富国岛海鲜。招牌菜式涵盖蒜蓉黄油黑虎虾、香辣炒蟹、炭烤鱿鱼与爆炒竹蛏，搭配冰镇本地啤酒，非常适合缆车行程前后就餐。', description_ja = 'ホントム島ケーブルカー駅近くのヴェニス通り（Ven45）に位置する、手頃な価格が魅力のローカルシーフードレストランです。ガーリックバターやピリ辛チリソースで仕上げた新鮮なタイガープロウン、ワタリガニ、マテ貝の炒め物、イカの炭火焼きを冷たいビールとともにケーブルカー乗車前後に気軽に楽しめます。', description_ru = 'Демократичный рыбный ресторан Hai San Cang расположен на улице Венеция (Ven45) в паре шагов от станции канатной дороги Хон-Тхом. Здесь подают свежие местные морепродукты — тигровых креветок в чесночном масле, чили-краба, кальмаров на гриле и морских черенков с холодным пивом.', description_hi = 'होन थोम केबल कार स्टेशन से चंद कदम दूर Ven45 वेनिस स्ट्रीट पर स्थित हाई सान कांग किफ़ायती दामों पर ताज़ा स्थानीय सीफ़ूड परोसता है। इसके खास व्यंजनों में गार्लिक बटर टाइगर प्रॉन, चिली क्रैब, ग्रिल्ड स्क्विड और स्टिर-फ़्राइड रेज़र क्लैम्स शामिल हैं।', public_name = '하이산캉', tags = ARRAY['seafood', 'Sunset Town', '하이산캉', 'Hải Sản Cảng', 'Hai San Cang']::text[], updated_at = NOW() WHERE slug = 'sunset-place-1';
UPDATE public.businesses SET category = 'dining', subcategory = 'international', address = 'Sunset, Town, P, Phú Quốc, An Giang 92500, Vietnam', description_ko = '선셋타운 중심 거리에서 셰프의 역동적인 즉석 수타면 제면 퍼포먼스를 볼 수 있는 중화 수타면 & 딤섬 전문점입니다. 쫄깃한 면발과 진한 육수가 어우러진 쿵푸 우육면, 해산물 볶음면, 육즙 가득한 만두를 부담 없는 가격에 든든하게 맛볼 수 있습니다.', description_en = 'Kungfu Noodle Phú Quốc entertains Sunset Town diners with live hand-pulled noodle stretching performances right at the storefront kitchen. Order chewy braised beef noodle soup, wok-tossed seafood noodles, and juicy steamed dumplings at casual, wallet-friendly prices.', description_vi = 'Kungfu Noodle Phú Quốc thu hút du khách trên phố Thị trấn Hoàng Hôn bằng màn trình diễn múa mì kéo tay điêu luyện ngay gian bếp mặt tiền. Sợi mì tươi dai mềm kết hợp hoàn hảo trong tô mì bò hầm đậm đà, mì xào hải sản và há cảo nóng hổi với mức giá rất phải chăng.', description_zh = '功夫面馆（Kungfu Noodle Phú Quốc）位于日落小镇中心街区，食客可在明档厨房前近距离观赏师傅现场手工拉面表演。店内手工拉面筋道爽滑，招牌红烧牛肉面、海鲜炒面与多汁手工水饺点心价格亲民、分量实在。', description_ja = 'サンセットタウンの中心通りで、職人による迫力ある手延べ麺パフォーマンスを間近に見られる中華麺＆点心レストランです。コシのある打ちたて麺を使った濃厚な牛肉麺（ニューローメン）や海鮮焼きそば、ジューシーな餃子を手頃な価格で楽しめます。', description_ru = 'Кафе Kungfu Noodle Phú Quốc в Сансет-Тауне привлекает гостей зрелищным шоу вытягивания лапши вручную прямо на открытой кухне у входа. Здесь готовят сытный суп с тушёной говядиной и упругой домашней лапшой, жареную лапшу с морепродуктами и сочные пельмени по доступным ценам.', description_hi = 'कुंगफ़ू नूडल फ़ू क्वोक सनसेट टाउन में अपने किचन के सामने लाइव हैंड-पुल्ड नूडल बनाने की कला से मेहमानों का मनोरंजन करता है। किफ़ायती दामों पर यहाँ स्वादिष्ट ब्रेज़्ड बीफ़ नूडल सूप, सीफ़ूड चाउमीन और रसीले स्टीम्ड डम्पलिंग्स का आनंद लें।', public_name = '쿵푸 누들 푸꾸옥 (Kungfu Noodle Phú Quốc)', price_level = '$$', tags = ARRAY['international', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'kungfu-noodle-phu-quoc';
UPDATE public.businesses SET category = 'dining', subcategory = 'cafe', address = 'Hexagonal House, Beachfront Promenade, Sunset Town, An Thới, Phú Quốc, Kiên Giang, Vietnam', description_ko = '키스 오브 더 씨 공연장 옆 상징적인 육각형 해변 건축물(Hexagonal House)에 자리한 베트남 하이엔드 카페 & 올데이 다이닝 공간입니다. 진한 베트남 에그커피·핀 드립커피·애프터눈 티부터 정갈한 베트남 요리·파스타까지 즐기며 서해안 석양과 야간 불꽃놀이를 감상할 수 있습니다.', description_en = 'Housed in the striking beachfront Hexagonal House right beside the Kiss of the Sea stage, RuNam Sunset Town is an upscale Vietnamese cafe and all-day bistro. Savor signature phin drip and egg coffees, afternoon tea sets, refined Vietnamese dishes, and pasta with front-row ocean and fireworks views.', description_vi = 'Tọa lạc trong tòa nhà Lục Giác (Hexagonal House) độc đáo sát biển ngay cạnh sân khấu Nụ Hôn Của Biển Cả, RuNam Sunset Town là không gian cà phê và ẩm thực cao cấp hàng đầu. Thực khách có thể thưởng thức cà phê phin, cà phê trứng, trà chiều cùng các món Việt – Âu tinh tế giữa tầm nhìn thẳng ra hoàng hôn và pháo hoa.', description_zh = 'RuNam 日落小镇店坐落于海之吻剧场旁极具辨识度的六角形海滨建筑（Hexagonal House）内，是越南知名高端咖啡与全日制餐饮品牌。宾客可在此品尝招牌越式滴滤咖啡、鸡蛋咖啡、精致下午茶及越西融合料理，同时近距离欣赏海上落日与烟花盛宴。', description_ja = 'キス・オブ・ザ・シー会場隣の象徴的な六角形の海辺建築（Hexagonal House）に入る、ベトナム屈指のハイエンドカフェ＆ビストロ「ルナム」です。濃厚なエッグコーヒーや伝統フィンドリップ、アフタヌーンティー、洗練されたベトナム料理やパスタを海と花火の特等席で堪能できます。', description_ru = 'Премиальное кафе-бистро RuNam Sunset Town занимает эффектный шестиугольный павильон на самом берегу рядом со сценой шоу «Поцелуй моря». Здесь подают фирменный вьетнамский кофе в фине и яичный кофе, послеобеденный чай, изысканные блюда вьетнамской и европейской кухни с видом на закат и салют.', description_hi = 'किस ऑफ़ द सी मंच के ठीक बगल समुद्र तटीय षट्कोणीय भवन (हेक्सागोनल हाउस) में स्थित रुनाम सनसेट टाउन एक प्रीमियम वियतनामी कैफ़े और ऑल-डे बिस्त्रो है। समुद्र और आतिशबाज़ी के शानदार दृश्यों के साथ यहाँ सिग्नेचर एग कॉफ़ी, फ़िन ड्रिप कॉफ़ी, आफ़्टरनून टी और स्वादिष्ट व्यंजनों का आनंद लें।', public_name = '카페 루남 선셋타운 (RuNam Sunset Town)', price_level = '$$', tags = ARRAY['cafe', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'sunset-place-2';
UPDATE public.businesses SET category = 'beaches', subcategory = 'vietnamese', address = 'Căn FB2, 05 Đường Venice, Khu đô thị Sun Địa Trung Hải, Phú Quốc, An Giang, Vietnam', description_ko = '베니스 거리 해안가(FB2-05)에 위치한 비치사이드 바비큐 & 베트남 로컬 레스토랑입니다. 숯불에 구워내는 신선한 해산물·육류 BBQ와 모닝글로리 볶음, 해산물 볶음밥, 시원한 생맥주를 여유로운 바다 전망과 함께 즐길 수 있습니다.', description_en = 'Located along the Venice Street waterfront (FB2-05), Lagoon BBQ & Vietnamese Cuisine offers relaxed seaside dining with charcoal-grilled seafood, meats, stir-fried morning glory, seafood fried rice, and cold draft beer.', description_vi = 'Nằm dọc bờ biển đường Venice (căn FB2-05), Lagoon BBQ & Vietnamese Cuisine mang đến không gian ẩm thực ven biển thư thái. Thực khách có thể thưởng thức hải sản và thịt nướng than hoa thơm phức, rau muống xào tỏi, cơm chiên hải sản cùng bia tươi mát lạnh giữa làn gió biển.', description_zh = 'Lagoon BBQ 越式海景烧烤餐厅坐落于威尼斯街海滨一线（FB2-05），提供轻松惬意的临海用餐体验。宾客可一边吹着海风眺望海景，一边享用炭火现烤海鲜与肉类、蒜蓉炒空心菜、海鲜炒饭以及冰爽生啤。', description_ja = 'ヴェニス通りの海沿い（FB2-05）に位置する、開放的なビーチサイドBBQ＆ベトナム料理レストランです。炭火で香ばしく焼き上げる新鮮な魚介や肉のバーベキューをはじめ、空芯菜のガーリック炒め、海鮮チャーハン、冷たい生ビールを海を眺めながらゆったり味わえます。', description_ru = 'Прибрежный ресторан Lagoon BBQ & Vietnamese Cuisine на набережной улицы Венеция (FB2-05) приглашает на неспешный ужин у самого моря. В меню — морепродукты и мясо на углях, обжаренная утренняя слава с чесноком, жареный рис с дарами моря и холодное разливное пиво.', description_hi = 'वेनिस स्ट्रीट वाटरफ़्रंट (FB2-05) के किनारे स्थित लगून बीबीक्यू एंड वियतनामीज़ कुज़ीन समुद्र के नज़ारों के साथ सुकून भरा भोजन परोसता है। यहाँ चारकोल-ग्रिल्ड सीफ़ूड व मीट, स्टिर-फ़्राइड मॉर्निंग ग्लोरी, सीफ़ूड फ़्राइड राइस और ठंडी ड्राफ़्ट बीयर का आनंद लें।', public_name = '라군 BBQ & 베트남 퀴진 (LAGOON BBQ & VIETNAMESE CUISINE)', tags = ARRAY['vietnamese', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'lagoon-bbq-vietnamese-cuisine';
UPDATE public.businesses SET category = 'dining', subcategory = 'vietnamese', address = 'Ama 17 đường Amarine, khu phố 6, Phú Quốc, An Giang 673966, Vietnam', description_ko = '향신료 부담 없이 한국인 입맛에도 잘 맞는 정갈한 베트남 가정식 백반과 진한 소고기 쌀국수, 분짜, 바삭한 짜조(스프링롤), 모닝글로리 볶음을 합리적인 가격에 선보이는 선셋타운 베트남 식당입니다.', description_en = 'Approachable Vietnamese restaurant in Sunset Town serving mild, flavorful beef pho, bun cha, crispy spring rolls, and home-style Vietnamese dishes.', description_vi = 'Nhà hàng món Việt tại Thị trấn Hoàng Hôn, phục vụ phở bò vị thanh, bún chả, chả giò giòn và các món cơm nhà.', description_zh = '位于日落小镇的越南餐厅，提供口味温和、汤头鲜香的牛肉河粉、越式烤肉米粉（Bún Chả）、酥脆炸春卷及越南家常菜。', description_ja = 'サンセットタウンにある気軽に利用できるベトナム料理店。辛さを抑えた風味豊かな牛肉フォー、ブンチャー、揚げ春巻き、ベトナムの家庭料理などを提供しています。', description_ru = 'Непринуждённый вьетнамский ресторан в Сансет-Тауне. Здесь подают говяжий фо с мягким, насыщенным вкусом, бунча, хрустящие жареные спринг-роллы и домашние вьетнамские блюда.', description_hi = 'सनसेट टाउन में स्थित यह सहज माहौल वाला वियतनामी रेस्तराँ हल्के लेकिन स्वादिष्ट शोरबे वाला बीफ़ फो, बुन चा, कुरकुरे फ्राइड स्प्रिंग रोल और घरेलू शैली के वियतनामी व्यंजन परोसता है।', public_name = '껌자딘 선셋타운 (Cơm Gia Đình Sunset Town)', tags = ARRAY['vietnamese', 'Sunset Town', '껌자딘', '껌자딘 선셋타운']::text[], updated_at = NOW() WHERE slug = 'sunset-place-3';
UPDATE public.businesses SET category = 'beaches', subcategory = 'seafood', address = 'FB3-03, Địa Trung Hải, phường, Phú Quốc, An Giang 92500, Vietnam', description_ko = '뜨거운 뚝배기에 지어 구수한 누룽지 풍미가 살아있는 베트남 전통 돌솥밥(Cơm Niêu)과 생선 조림, 돼지고기 계란 장조림(Thịt Kho Tàu), 모닝글로리 볶음을 정갈하게 내어주는 베트남 가정식 백반 명소입니다.', description_en = 'Renowned Vietnamese claypot rice (Com Nieu) restaurant in Sunset Town serving crispy-bottomed claypot rice paired with braised fish, caramelized pork, and stir-fried morning glory.', description_vi = 'Nhà hàng cơm niêu tại Thị trấn Hoàng Hôn, phục vụ cơm niêu cháy giòn cùng cá kho, thịt kho và rau muống xào.', description_zh = '位于日落小镇的越南砂锅饭（Cơm Niêu）餐厅，主打锅底带有香脆锅巴的砂锅米饭，搭配红烧鱼、焦糖炖猪肉和清炒空心菜等传统菜肴。', description_ja = 'サンセットタウンにあるベトナム式土鍋ご飯（Cơm Niêu）のレストラン。鍋底に香ばしいおこげができる土鍋ご飯に、魚の煮付け、豚肉の甘辛煮、空心菜炒めなどを組み合わせて楽しめます。', description_ru = 'Ресторан вьетнамского риса в глиняном горшочке (Cơm Niêu) в Сансет-Тауне. Рис с хрустящей корочкой на дне подают с тушёной рыбой, свининой в карамельном соусе и жареным водяным шпинатом.', description_hi = 'सनसेट टाउन का यह वियतनामी मिट्टी के बर्तन में पके चावल (Cơm Niêu) का रेस्तराँ है। यहाँ नीचे से कुरकुरे चावल के साथ मसालेदार धीमी आँच पर पकी मछली, कैरामेलाइज़्ड पोर्क और स्टर-फ्राइड वॉटर स्पिनच परोसे जाते हैं।', public_name = '껌니우 비엣 선셋타운 (Nhà hàng Cơm Niêu Việt Địa Trung Hải)', tags = ARRAY['seafood', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'nha-hang-com-nieu-viet-di-a-trung-hai';
UPDATE public.businesses SET category = 'dining', subcategory = 'vietnamese', address = '166 Đ. Amalfi, Sunset Town, Phú Quốc, An Giang 92500, Vietnam', description_ko = '진한 육수의 베트남 쌀국수(Phở)와 바삭한 수제 반미(Bánh Mì), 볶음밥 등 든든한 베트남 현지 식사와 시원한 연유 커피를 아침부터 저녁까지 합리적인 가격에 제공하는 식당 겸 카페입니다.', description_en = 'Welcoming Vietnamese restaurant and cafe in Sunset Town serving hearty beef pho, crispy banh mi sandwiches, fried rice, and iced Vietnamese coffee all day.', description_vi = 'Nhà hàng và quán cà phê món Việt tại Thị trấn Hoàng Hôn, phục vụ phở bò, bánh mì giòn, cơm chiên và cà phê đá Việt Nam cả ngày.', description_zh = '位于日落小镇的越南餐厅兼咖啡馆，全天供应牛肉河粉、酥脆越南法棍三明治（Bánh Mì）、炒饭和冰镇越南咖啡。', description_ja = 'サンセットタウンにあるベトナム料理店兼カフェ。具だくさんの牛肉フォー、サクサクのバインミー、チャーハン、冷たいベトナムコーヒーなどを終日提供しています。', description_ru = 'Вьетнамский ресторан и кафе в Сансет-Тауне. В течение всего дня здесь подают сытный говяжий фо, хрустящие сэндвичи бань ми, жареный рис и вьетнамский кофе со льдом.', description_hi = 'सनसेट टाउन में स्थित यह वियतनामी रेस्तराँ और कैफ़े पूरे दिन भरपूर बीफ़ फो, कुरकुरे बान मी सैंडविच, फ्राइड राइस और बर्फ़ वाली वियतनामी कॉफ़ी परोसता है।', public_name = 'SUNNY COFFEE - PHO - BANH MI (Vietnamese cuisine)', tags = ARRAY['cafe', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'sunny-coffee-pho-banh-mi-vietnamese-cuisine';
UPDATE public.businesses SET category = 'dining', subcategory = 'western', address = '54 Amalfi, Sunset Town, Phú Quốc, An Giang, Vietnam', description_ko = '선셋타운 시계탑 광장 인근의 유러피안 다이닝 레스토랑으로, 프리미엄 스테이크 그릴 요리와 화덕 피자, 크림·해산물 파스타, 와인 및 크래프트 비어를 고급스러운 분위기에서 선보입니다.', description_en = 'Upscale Western dining restaurant near Sunset Town''s Clock Tower offering grilled steaks, artisan pizzas, seafood pasta, fine wines, and craft beers.', description_vi = 'Nhà hàng món Âu gần Tháp Đồng Hồ tại Thị trấn Hoàng Hôn, phục vụ bít tết nướng, pizza thủ công, mì Ý hải sản, rượu vang và bia thủ công.', description_zh = '位于日落小镇钟楼附近的西式餐厅，提供烤牛排、手工披萨、海鲜意面、精选葡萄酒和精酿啤酒。', description_ja = 'サンセットタウンの時計塔近くにある、落ち着いた雰囲気の洋食レストラン。グリルステーキ、手作りピザ、シーフードパスタ、ワイン、クラフトビールなどを提供しています。', description_ru = 'Ресторан западной кухни повышенного класса рядом с Часовой башней в Сансет-Тауне. В меню — стейки на гриле, пицца ручной работы, паста с морепродуктами, отборные вина и крафтовое пиво.', description_hi = 'सनसेट टाउन के क्लॉक टॉवर के पास स्थित यह पश्चिमी शैली का अपस्केल रेस्तराँ ग्रिल्ड स्टेक, हाथ से बने पिज़्ज़ा, सीफ़ूड पास्ता, चुनिंदा वाइन और क्राफ़्ट बीयर परोसता है।', public_name = 'Times Corner Luxe - Pizza, Pasta & Grill', tags = ARRAY['western', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'times-corner-luxe-pizza-pasta-grill';
UPDATE public.businesses SET category = 'dining', subcategory = 'vietnamese', address = '201 Sorrento An Thới, Phú Quốc, An Giang 92000, Vietnam', description_ko = '선셋타운 중심부에서 신선한 푸꾸옥 해산물 요리와 베트남 전통 쌀국수·분짜·볶음밥, 서양식 캐주얼 메뉴까지 폭넓게 갖추어 가족·단체 여행객이 함께 식사하기 좋은 올데이 레스토랑입니다.', description_en = 'Spacious all-day restaurant in central Sunset Town serving fresh Phu Quoc seafood, classic Vietnamese dishes, and casual Western favorites for families and groups.', description_vi = 'Nhà hàng rộng rãi ở trung tâm Thị trấn Hoàng Hôn, phục vụ cả ngày với hải sản Phú Quốc, món Việt và món Âu cho gia đình, nhóm khách.', description_zh = '位于日落小镇中心的宽敞全天营业餐厅，供应新鲜富国岛海鲜、经典越南菜和常见西式餐点，适合家庭及团体用餐。', description_ja = 'サンセットタウン中心部にある広々としたオールデイダイニングレストラン。フーコック島の新鮮なシーフード、定番のベトナム料理、気軽に楽しめる洋食を提供しており、家族やグループでの食事にも利用できます。', description_ru = 'Просторный ресторан в центре Сансет-Тауна, работающий в течение всего дня. Здесь подают свежие морепродукты Фукуока, классические вьетнамские блюда и популярные блюда западной кухни. Подходит для семей и компаний.', description_hi = 'सनसेट टाउन के मध्य में स्थित यह विशाल ऑल-डे डाइनिंग रेस्तराँ ताज़ा फू क्वोक सीफ़ूड, पारंपरिक वियतनामी व्यंजन और लोकप्रिय पश्चिमी भोजन परोसता है। परिवारों और समूहों के लिए भी उपयुक्त है।', public_name = 'Times Corner Restaurant', tags = ARRAY['vietnamese', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'times-corner-restaurant';
UPDATE public.businesses SET category = 'bars', subcategory = 'cafe', address = '11 Đ. Amalfi, KĐT Sun Grand City, Phú Quốc, An Giang 91000, Vietnam', description_ko = '베트남 산지 로스팅 원두와 전통 핀(Phin) 드립 커피를 전문으로 다루는 로스터리 카페로, 진한 연유 커피와 코코넛 커피를 맛보고 선물용 고급 원두를 시음·구매할 수 있습니다.', description_en = 'Specialty coffee roastery and cafe in Sunset Town where visitors can savor authentic Phin-brewed coffee, coconut coffee, and shop freshly roasted Vietnamese coffee beans.', description_vi = 'Quán rang xay cà phê đặc sản tại Thị trấn Hoàng Hôn, phục vụ cà phê phin, cà phê dừa và bán hạt cà phê Việt mới rang.', description_zh = '位于日落小镇的精品咖啡烘焙店兼咖啡馆，提供传统越南滴漏咖啡（Phin）、椰子咖啡，并销售新鲜烘焙的越南咖啡豆。', description_ja = 'サンセットタウンにある自家焙煎のスペシャルティコーヒー店。伝統的なベトナム式フィンで淹れたコーヒーやココナッツコーヒーを楽しめるほか、焙煎したてのベトナム産コーヒー豆も購入できます。', description_ru = 'Кофейня и обжарочная спешелти-кофе в Сансет-Тауне. Здесь можно попробовать традиционный вьетнамский кофе, приготовленный через фильтр фин, и кокосовый кофе, а также купить свежеобжаренные вьетнамские кофейные зёрна.', description_hi = 'सनसेट टाउन में स्थित यह स्पेशलिटी कॉफ़ी रोस्टरी और कैफ़े पारंपरिक वियतनामी फिन फ़िल्टर से बनी कॉफ़ी और नारियल कॉफ़ी परोसता है। यहाँ ताज़ा भुनी हुई वियतनामी कॉफ़ी बीन्स भी खरीदी जा सकती हैं।', public_name = 'Trần Coffee Shop No.2 Sunset Town', tags = ARRAY['cafe', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'tran-coffee-shop-no-2-sunset-town';
UPDATE public.businesses SET category = 'dining', subcategory = 'vietnamese', address = '54 Đường Venice, Phú Quốc, An Giang 31078, Vietnam', description_ko = '현지인 셰프가 신선한 해산물과 로컬 식재료로 정성껏 조리하는 베트남 가정식 볶음 요리, 해산물 핫팟, 쌀국수를 정겨운 분위기에서 합리적인 가격에 맛볼 수 있는 로컬 맛집입니다.', description_en = 'Welcoming local eatery in Sunset Town serving authentic home-cooked Vietnamese stir-fries, fresh seafood hotpot, and noodle soups at friendly local prices.', description_vi = 'Quán ăn địa phương tại Thị trấn Hoàng Hôn, phục vụ món xào kiểu cơm nhà, lẩu hải sản tươi và các món bún nước với mức giá địa phương.', description_zh = '位于日落小镇的本地风味小餐馆，提供越南家常炒菜、新鲜海鲜火锅和汤粉面食，价格贴近当地日常消费水平。', description_ja = 'サンセットタウンにある地元の食堂。ベトナムの家庭的な炒め物、新鮮なシーフード鍋、麺料理などを、地元向けの手頃な価格で提供しています。', description_ru = 'Местное кафе-ресторан в Сансет-Тауне. Здесь предлагают домашние вьетнамские блюда вок, хот-пот со свежими морепродуктами и супы с лапшой по доступным местным ценам.', description_hi = 'सनसेट टाउन का यह स्थानीय भोजनालय घर में बने वियतनामी स्टर-फ्राइड व्यंजन, ताज़े सीफ़ूड हॉटपॉट और नूडल सूप स्थानीय स्तर की किफ़ायती कीमतों पर परोसता है।', public_name = 'Hai Bột Eatery & Homestay Phu Quoc', tags = ARRAY['vietnamese', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'hai-bot-eatery-homestay-phu-quoc';
UPDATE public.businesses SET category = 'dining', subcategory = 'street_food', address = 'VuiFest Bazaar Thị Trấn Hoàng Hôn, Phú Quốc, An Giang, Vietnam', description_ko = '부이페스트(VuiFest) 야시장 내에 위치한 홍콩식 버블 에그와플 & 젤라또 디저트 전문점으로, 겉바속촉 즉석 에그와플에 시원한 아이스크림과 열대과일 음료를 곁들여 야시장 산책 간식으로 인기가 높습니다.', description_en = 'Popular dessert stall inside VuiFest Night Market serving freshly made Hong Kong bubble egg waffles topped with gelato ice cream alongside refreshing tropical fruit drinks.', description_vi = 'Quầy tráng miệng tại chợ đêm VuiFest, phục vụ bánh trứng bong bóng Hồng Kông với kem gelato và đồ uống trái cây nhiệt đới.', description_zh = '位于 VuiFest 夜市内的甜品摊位，主打现做的港式鸡蛋仔，搭配意式冰淇淋，并提供清爽的热带水果饮品。', description_ja = 'VuiFestナイトマーケット内にあるデザート屋台。焼きたての香港式エッグワッフルにジェラートを添えたスイーツや、トロピカルフルーツドリンクを提供しています。', description_ru = 'Десертный киоск на ночном рынке VuiFest. Здесь готовят свежие гонконгские яичные вафли с джелато и предлагают освежающие напитки из тропических фруктов.', description_hi = 'VuiFest नाइट मार्केट में स्थित यह डेज़र्ट स्टॉल ताज़ा बने हांगकांग शैली के बबल एग वॉफ़ल पर जेलाटो आइसक्रीम परोसता है। यहाँ ताज़गी देने वाले ट्रॉपिकल फ्रूट ड्रिंक्स भी मिलते हैं।', public_name = 'H Corner Chợ đêm Vuifest', tags = ARRAY['vietnamese', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'h-corner-cho-dem-vuifest';
UPDATE public.businesses SET category = 'dining', subcategory = 'vietnamese', address = 'Amafi, Phú Quốc, An Giang, Vietnam', description_ko = '부이페스트(VuiFest) 야시장 안에 자리한 베트남 로컬 미식 식당으로, 숯불 해산물·꼬치구이와 바삭한 반쎄오, 볶음면, 시원한 맥주를 야시장의 활기찬 분위기 속에서 즐길 수 있습니다.', description_en = 'Vibrant Vietnamese eatery inside VuiFest Night Market serving charcoal-grilled seafood skewers, crispy banh xeo pancakes, stir-fried noodles, and cold beer.', description_vi = 'Quán món Việt trong chợ đêm VuiFest, phục vụ xiên hải sản nướng than, bánh xèo giòn, mì xào và bia lạnh.', description_zh = '位于 VuiFest 夜市内的越南餐饮店，提供炭烤海鲜串、酥脆越南煎饼（Bánh Xèo）、炒面和冰镇啤酒。', description_ja = 'VuiFestナイトマーケット内にあるベトナム料理店。炭火焼きのシーフード串、パリッとしたバインセオ、焼きそば風の炒め麺、冷たいビールなどを提供しています。', description_ru = 'Вьетнамское кафе на ночном рынке VuiFest. В меню — шашлычки из морепродуктов на углях, хрустящие вьетнамские блинчики баньсео, жареная лапша и холодное пиво.', description_hi = 'VuiFest नाइट मार्केट में स्थित यह वियतनामी भोजनालय कोयले पर ग्रिल किए गए सीफ़ूड स्क्यूअर, कुरकुरे बान सेओ पैनकेक, स्टर-फ्राइड नूडल्स और ठंडी बीयर परोसता है।', public_name = 'Đảo Vị VuiFest Bazaar', tags = ARRAY['vietnamese', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'dao-vi-vuifest-bazaar';
UPDATE public.businesses SET category = 'dining', subcategory = 'vietnamese', address = '21 Amalfi - Sunset, Phú Quốc, An Giang 92500, Vietnam', description_ko = '깔끔하고 쾌적한 실내에서 베트남 북부·남부식 가정식 백반(Cơm Gia Đình)과 신선한 해산물 요리, 분짜, 모닝글로리 볶음을 합리적인 가격에 즐길 수 있는 가족 외식 레스토랑입니다.', description_en = 'Clean, family-friendly Vietnamese restaurant in Sunset Town specializing in traditional home-style family meal sets (Com Gia Dinh), fresh seafood, and classic local dishes.', description_vi = 'Nhà hàng món Việt dành cho gia đình tại Thị trấn Hoàng Hôn, chuyên mâm cơm gia đình truyền thống, hải sản tươi và món địa phương.', description_zh = '位于日落小镇的越南家庭餐厅，环境整洁，主打传统越南家常合餐（Cơm Gia Đình）、新鲜海鲜及经典本地菜肴，适合家庭用餐。', description_ja = 'サンセットタウンにある清潔感のある家族向けベトナム料理店。伝統的な家庭料理のセット（Cơm Gia Đình）、新鮮なシーフード、定番の地元料理などを提供しています。', description_ru = 'Чистый семейный ресторан вьетнамской кухни в Сансет-Тауне. Специализируется на традиционных наборах домашних блюд Cơm Gia Đình, свежих морепродуктах и классических местных блюдах.', description_hi = 'सनसेट टाउन में स्थित यह साफ़-सुथरा, परिवार के अनुकूल वियतनामी रेस्तराँ पारंपरिक घरेलू पारिवारिक भोजन सेट (Cơm Gia Đình), ताज़ा समुद्री भोजन और स्थानीय व्यंजन परोसता है।', public_name = 'Cơm Gia Đình Việt - Tây Hồ Restaurant', tags = ARRAY['vietnamese', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'com-gia-dinh-viet-tay-ho-restaurant';
UPDATE public.businesses SET category = 'dining', subcategory = 'seafood', address = 'Shophouse KĐT Sun Grand City New KĐT Sun Grand City New, Phú Quốc, An Giang, Vietnam', description_ko = '푸꾸옥 대표 어촌인 함닌(Hàm Ninh) 산지 직송 크랩(꽃게) 찜과 살아있는 랍스터, 타이거 새우, 성게·가리비 숯불구이를 수족관에서 직접 골라 합리적인 시세로 맛볼 수 있는 정통 해산물 레스토랑입니다.', description_en = 'Authentic Phu Quoc seafood restaurant offering live-tank Ham Ninh steamed flower crabs, lobster, tiger prawns, and charcoal-grilled scallops and sea urchin.', description_vi = 'Nhà hàng hải sản Phú Quốc, phục vụ ghẹ Hàm Ninh hấp từ bể hải sản sống, tôm hùm, tôm sú, sò điệp và nhum nướng than.', description_zh = '富国岛海鲜餐厅，提供水箱鲜活海鲜，包括咸宁（Hàm Ninh）清蒸花蟹、龙虾、虎虾，以及炭烤扇贝和海胆。', description_ja = 'フーコック島のシーフードレストラン。生け簀の新鮮な魚介を使用し、ハムニン（Hàm Ninh）産の蒸しワタリガニ、ロブスター、タイガープラウン、炭火焼きのホタテやウニなどを提供しています。', description_ru = 'Ресторан морепродуктов Фукуока, предлагающий живые морепродукты из аквариумов. Среди блюд — приготовленные на пару крабы из Хамниня (Hàm Ninh), лобстеры, тигровые креветки, а также морские гребешки и морские ежи на углях.', description_hi = 'यह फू क्वोक का सीफ़ूड रेस्तराँ है, जहाँ टैंकों में रखे जीवित समुद्री जीवों से व्यंजन तैयार किए जाते हैं। मेन्यू में Hàm Ninh के स्टीम्ड फ़्लावर क्रैब, लॉब्स्टर, टाइगर प्रॉन, चारकोल-ग्रिल्ड स्कैलप और सी अर्चिन शामिल हैं।', public_name = 'Hải Sản Hàm Ninh', tags = ARRAY['seafood', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'hai-san-ham-ninh';
UPDATE public.businesses SET category = 'dining', subcategory = 'western', address = 'M107-M109, Đường MILAN, Sunset Town, Phú Quốc, An Giang, Vietnam', description_ko = '선셋타운 중심부에서 유러피안 브라세리 다이닝(파스타·스테이크)과 프랑스풍 수제 페이스트리·케이크, 와인 및 칵테일을 우아한 분위기 속에서 즐길 수 있는 올데이 다이닝 & 베이커리 바입니다.', description_en = 'Refined European brasserie, pastry cafe, and bar in Sunset Town offering artisan French pastries, pasta, steaks, fine wines, and cocktails.', description_vi = 'Quán ăn phong cách châu Âu kết hợp tiệm bánh và bar tại Thị trấn Hoàng Hôn, phục vụ bánh Pháp thủ công, mì Ý, bít tết, rượu vang và cocktail.', description_zh = '位于日落小镇的欧式小酒馆、甜点咖啡馆兼酒吧，提供手工法式糕点、意面、牛排、精选葡萄酒和鸡尾酒。', description_ja = 'サンセットタウンにあるヨーロッパ風ブラッスリー、ペストリーカフェ兼バー。手作りのフランス菓子、パスタ、ステーキ、ワイン、カクテルなどを提供しています。', description_ru = 'Европейская брассери, кондитерская-кафе и бар в Сансет-Тауне. В меню — французская выпечка ручной работы, паста, стейки, отборные вина и коктейли.', description_hi = 'सनसेट टाउन में स्थित यह यूरोपीय शैली की ब्रैसरी, पेस्ट्री कैफ़े और बार हाथ से बनी फ़्रेंच पेस्ट्री, पास्ता, स्टेक, चुनिंदा वाइन और कॉकटेल परोसता है।', public_name = 'Hội Quán - European Brasserie • Bar • Pastry', tags = ARRAY['european_brasserie_bakery', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'hoi-quan-european-brasserie-bar-pastry';
UPDATE public.businesses SET category = 'dining', subcategory = 'seafood', address = 'AT60 đại lộ New, Phú Quốc, An Giang, Vietnam', description_ko = '신선한 푸꾸옥산 해산물(새우·오징어·조개류)과 육즙 가득한 소고기·돼지고기 꼬치 및 직화 바비큐 그릴 요리를 한자리에서 구워 먹으며 시원한 생맥주를 즐기기 좋은 그릴 전문 식당입니다.', description_en = 'Lively seafood and meat grill restaurant in Sunset Town serving charcoal-grilled local prawns, squid, shellfish, and marinated BBQ meat skewers with cold draft beer.', description_vi = 'Nhà hàng nướng hải sản và thịt tại Thị trấn Hoàng Hôn, phục vụ tôm, mực, nghêu sò địa phương nướng than, xiên thịt BBQ ướp gia vị và bia tươi lạnh.', description_zh = '位于日落小镇的海鲜与肉类烧烤餐厅，供应炭烤本地鲜虾、鱿鱼、贝类及腌制烧烤肉串，并提供冰镇生啤酒。', description_ja = 'サンセットタウンにあるシーフードと肉料理のグリルレストラン。地元産エビ、イカ、貝類の炭火焼きや、味付けしたBBQ肉串を冷たい生ビールとともに提供しています。', description_ru = 'Ресторан морепродуктов и мяса на гриле в Сансет-Тауне. Здесь готовят на углях местных креветок, кальмаров, моллюсков и маринованные мясные шашлычки, а также подают холодное разливное пиво.', description_hi = 'सनसेट टाउन का यह सीफ़ूड और मीट ग्रिल रेस्तराँ कोयले पर ग्रिल किए गए स्थानीय प्रॉन, स्क्विड, शेलफ़िश और मैरिनेटेड BBQ मीट स्क्यूअर परोसता है। साथ में ठंडी ड्राफ़्ट बीयर भी मिलती है।', public_name = 'Phố Nướng / seafood & meat grill', tags = ARRAY['seafood', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'pho-nuong-seafood-meat-grill';
UPDATE public.businesses SET category = 'dining', subcategory = 'vietnamese', address = 'AT 80-82, Đại Lộ New, Phú Quốc, An Giang 92000, Vietnam', description_ko = '무슬림 여행자도 안심하고 즐길 수 있는 할랄(Halal) 인증 해산물·치킨·비프 커리와 중동·베트남 퓨전 요리, 신선한 커피와 과일 주스를 제공하는 선셋타운 할랄 레스토랑 & 카페입니다.', description_en = 'Halal-certified restaurant and cafe in Sunset Town offering flavorful halal curries, grilled seafood, Middle Eastern and Vietnamese dishes, and specialty coffee.', description_vi = 'Nhà hàng và quán cà phê được giới thiệu là đạt chuẩn halal tại Thị trấn Hoàng Hôn, phục vụ cà ri halal, hải sản nướng, món Trung Đông, món Việt và cà phê đặc sản.', description_zh = '位于日落小镇的清真认证餐厅兼咖啡馆，提供清真咖喱、烤海鲜、中东及越南风味菜肴，以及精品咖啡。', description_ja = 'サンセットタウンにあるハラール認証取得のレストラン＆カフェ。ハラール対応のカレー、シーフードグリル、中東料理やベトナム料理、スペシャルティコーヒーなどを提供しています。', description_ru = 'Ресторан и кафе с халяльной сертификацией в Сансет-Тауне. В меню — халяльные карри, морепродукты на гриле, блюда ближневосточной и вьетнамской кухни, а также спешелти-кофе.', description_hi = 'सनसेट टाउन में स्थित यह हलाल-प्रमाणित रेस्तराँ और कैफ़े स्वादिष्ट हलाल करी, ग्रिल्ड सीफ़ूड, मध्य-पूर्वी और वियतनामी व्यंजन तथा स्पेशलिटी कॉफ़ी परोसता है।', public_name = 'Restaurant- Coffee Halal Sunset Town Phu Quoc', tags = ARRAY['cafe', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'restaurant-coffee-halal-sunset-town-phu-quoc';
UPDATE public.businesses SET category = 'dining', subcategory = 'japanese', address = 'Khu Đô Thị Sun Premier Village Primavera, Căn FB3-04B, Phú Quốc, An Giang, Vietnam', description_ko = '선셋타운 해변가에 자리한 정통 일식 레스토랑으로, 신선한 모둠 사시미와 초밥, 고등어·열빙어·연어 숯불구이 정식, 따뜻한 우동과 일본 사케·생맥주를 깔끔한 분위기에서 선보입니다.', description_en = 'Authentic Japanese restaurant by the Sunset Town waterfront specializing in fresh sashimi, sushi rolls, charbroiled fish sets, udon noodles, and Japanese sake.', description_vi = 'Nhà hàng Nhật ven biển tại Thị trấn Hoàng Hôn, chuyên sashimi, sushi cuộn, set cá nướng than, mì udon và rượu sake Nhật.', description_zh = '位于日落小镇海滨的日式餐厅，主打新鲜刺身、寿司卷、炭烤鱼定食、乌冬面和日本清酒。', description_ja = 'サンセットタウンの海沿いにある日本料理店。新鮮な刺身、巻き寿司、魚の炭火焼き定食、うどん、日本酒などを提供しています。', description_ru = 'Японский ресторан у набережной Сансет-Тауна. Специализируется на свежем сашими, суши-роллах, сетах с рыбой на углях, лапше удон и японском саке.', description_hi = 'सनसेट टाउन के समुद्र किनारे स्थित यह जापानी रेस्तराँ ताज़ा साशिमी, सुशी रोल, चारकोल-ग्रिल्ड मछली के सेट मील, उडोन नूडल्स और जापानी साके परोसता है।', public_name = 'Yushima Japanese Restaurant', tags = ARRAY['japanese', 'seafood', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'yushima-japanese-restaurant';
UPDATE public.businesses SET category = 'dining', subcategory = 'vietnamese', address = '22H5+Q4V, Phú Quốc, An Giang, Vietnam', description_ko = '선셋타운 해안가에서 붉게 물드는 석양과 불꽃쇼를 감상하며 신선한 푸꾸옥 씨푸드 플래터, 바비큐 그릴 요리, 시원한 생맥주와 칵테일을 즐길 수 있는 오션뷰 레스토랑입니다.', description_en = 'Oceanfront sunset dining restaurant in Sunset Town offering fresh Phu Quoc seafood platters, BBQ grill dishes, draft beer, and cocktails with views of the evening fireworks.', description_vi = 'Nhà hàng ven biển tại Thị trấn Hoàng Hôn, phục vụ đĩa hải sản Phú Quốc, BBQ, bia tươi và cocktail, nhìn ra pháo hoa buổi tối.', description_zh = '位于日落小镇海滨的日落景观餐厅，提供新鲜富国岛海鲜拼盘、烧烤料理、生啤酒和鸡尾酒，用餐时可欣赏夜间烟花表演。', description_ja = 'サンセットタウンの海沿いにある、夕日の景色を楽しめるレストラン。フーコック島の新鮮なシーフード盛り合わせ、BBQ料理、生ビール、カクテルを提供しており、夜には花火を眺めることもできます。', description_ru = 'Ресторан на берегу моря в Сансет-Тауне с видом на закат. В меню — ассорти из свежих морепродуктов Фукуока, блюда на гриле, разливное пиво и коктейли. Вечером отсюда можно наблюдать фейерверки.', description_hi = 'सनसेट टाउन के समुद्र किनारे स्थित इस रेस्तराँ में सूर्यास्त के दृश्य के साथ ताज़े फू क्वोक सीफ़ूड प्लेटर, BBQ ग्रिल व्यंजन, ड्राफ़्ट बीयर और कॉकटेल मिलते हैं। यहाँ से शाम की आतिशबाज़ी भी देखी जा सकती है।', public_name = 'Chill Sunset Restaurant', tags = ARRAY['vietnamese', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'chill-sunset-restaurant';
UPDATE public.businesses SET category = 'dining', subcategory = 'vietnamese', address = '22J4+MC3, Phú Quốc, An Giang, Vietnam', description_ko = '베트남 고향의 맛(Quê Tôi)을 살린 정통 베트남 로컬 요리와 푸꾸옥 해산물 찜·구이, 샤브샤브 전골(Lẩu)을 푸짐하고 정갈하게 선보이는 선셋타운 현지식 레스토랑입니다.', description_en = 'Authentic Vietnamese restaurant in Sunset Town celebrating hometown flavors with fresh Phu Quoc steamed and grilled seafood, savory hotpots, and traditional local dishes.', description_vi = 'Nhà hàng món Việt tại Thị trấn Hoàng Hôn, phục vụ hải sản Phú Quốc hấp hoặc nướng, các món lẩu và đặc sản địa phương.', description_zh = '位于日落小镇的越南餐厅，以传统家乡风味为特色，提供新鲜富国岛清蒸及烧烤海鲜、风味火锅和经典本地菜肴。', description_ja = 'サンセットタウンにある、ベトナムの郷土料理を楽しめるレストラン。フーコック島の新鮮な魚介を使った蒸し料理やグリル料理、味わい深い鍋料理、伝統的な地元料理などを提供しています。', description_ru = 'Вьетнамский ресторан в Сансет-Тауне, посвящённый традиционным домашним вкусам. Здесь подают свежие морепродукты Фукуока на пару и на гриле, ароматные хот-поты и классические местные блюда.', description_hi = 'सनसेट टाउन में स्थित यह वियतनामी रेस्तराँ पारंपरिक घरेलू स्वादों पर केंद्रित है। यहाँ फू क्वोक का ताज़ा स्टीम्ड और ग्रिल्ड सीफ़ूड, स्वादिष्ट हॉटपॉट और स्थानीय व्यंजन परोसे जाते हैं।', public_name = 'WOW QUÊ TÔI', tags = ARRAY['vietnamese', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'wow-que-toi';
UPDATE public.businesses SET category = 'dining', subcategory = 'western', address = 'Kioks K11 chợ đêm Sunset Bazzar, thị trấn Sunset Town, Phú Quốc, An Giang, Vietnam', description_ko = '부이페스트 야시장 인근에서 참나무 훈연 바비큐 폭립(BBQ Ribs)과 육즙 가득한 수제 버거, 그릴 스테이크, 시원한 수제 맥주를 즐길 수 있는 아메리칸 그릴 & 비어 펍입니다.', description_en = 'Lively grill house and pub near VuiFest Night Market famous for its tender smoked BBQ ribs, juicy handcrafted burgers, grilled steaks, and ice-cold craft beers.', description_vi = 'Nhà hàng nướng và pub gần chợ đêm VuiFest, phục vụ sườn BBQ hun khói, burger thủ công, bít tết và bia thủ công lạnh.', description_zh = '位于 VuiFest 夜市附近的烧烤餐厅兼酒吧，主打烟熏 BBQ 排骨、手工汉堡、烤牛排和冰镇精酿啤酒。', description_ja = 'VuiFestナイトマーケット近くにあるグリルレストラン兼パブ。柔らかく仕上げたスモークBBQリブ、手作りのジューシーなハンバーガー、グリルステーキ、冷たいクラフトビールなどを提供しています。', description_ru = 'Гриль-ресторан и паб рядом с ночным рынком VuiFest. В меню — нежные копчёные рёбрышки BBQ, сочные бургеры ручной работы, стейки на гриле и холодное крафтовое пиво.', description_hi = 'VuiFest नाइट मार्केट के पास स्थित यह ग्रिल हाउस और पब नरम स्मोक्ड BBQ रिब्स, हाथ से बने रसदार बर्गर, ग्रिल्ड स्टेक और ठंडी क्राफ़्ट बीयर परोसता है।', public_name = 'Tribal Grill - Ribs, Burger & Beer', tags = ARRAY['western', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'tribal-grill-ribs-burger-beer';
UPDATE public.businesses SET category = 'dining', subcategory = 'seafood', address = 'Chợ đêm Vuifest - Sunset Town Phố, Phú Quốc, An Giang 92500, Vietnam', description_ko = '선셋타운 해안가에서 보트 테마의 감각적인 인테리어와 오션뷰를 배경으로 신선한 씨푸드 플래터, 그릴 스테이크, 파스타 및 트로피컬 칵테일을 즐길 수 있는 해변 레스토랑 & 바입니다.', description_en = 'Nautical-themed waterfront restaurant and bar in Sunset Town offering fresh seafood platters, grilled steaks, pasta, and tropical sunset cocktails.', description_vi = 'Nhà hàng và bar ven biển phong cách hàng hải tại Thị trấn Hoàng Hôn, phục vụ hải sản tươi, bít tết, mì Ý và cocktail hoàng hôn.', description_zh = '位于日落小镇海滨的航海主题餐厅兼酒吧，提供新鲜海鲜拼盘、烤牛排、意面和适合欣赏热带日落时享用的鸡尾酒。', description_ja = 'サンセットタウンの海沿いにある、船や海をテーマにしたレストラン＆バー。新鮮なシーフードの盛り合わせ、グリルステーキ、パスタ、夕日を眺めながら楽しめるトロピカルカクテルなどを提供しています。', description_ru = 'Ресторан и бар в морском стиле на набережной Сансет-Тауна. В меню — ассорти из свежих морепродуктов, стейки на гриле, паста и тропические коктейли, которыми можно насладиться на закате.', description_hi = 'सनसेट टाउन के समुद्र किनारे स्थित यह समुद्री थीम वाला रेस्तराँ और बार ताज़े सीफ़ूड प्लेटर, ग्रिल्ड स्टेक, पास्ता और सूर्यास्त के समय आनंद लेने के लिए ट्रॉपिकल कॉकटेल परोसता है।', public_name = 'One Boat Restaurant & Bar', tags = ARRAY['seafood', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'one-boat-restaurant-bar';
UPDATE public.businesses SET category = 'beaches', subcategory = 'seafood', address = 'FB3-03, Địa Trung Hải, phường, Phú Quốc, An Giang, Vietnam', description_ko = '선셋타운 해변 상가 구역(FB3-03)에 위치한 오픈에어 씨푸드 뷔페 & 그릴 레스토랑입니다. 푸꾸옥 근해에서 잡은 새우·조개·오징어·생선 등 다양한 해산물 즉석 그릴과 핫푸드, 열대과일, 시원한 맥주를 바닷바람이 부는 넓은 좌석에서 자유롭게 즐길 수 있습니다.', description_en = 'Set in the seaside FB3-03 dining block of Sunset Town, Green Tree Buffet SeaFood offers casual open-air seafood buffet and live grill dining. Guests sample grilled Phu Quoc prawns, clams, squid, local hot dishes, and fresh tropical fruit alongside cold beers by the coast.', description_vi = 'Nằm tại phân khu ẩm thực ven biển FB3-03 của Thị trấn Hoàng Hôn, Green Tree Buffet SeaFood phục vụ tiệc buffet hải sản và quầy nướng tại chỗ thoáng mát. Thực khách thoải mái thưởng thức tôm, nghêu sò, mực nướng tươi ngon cùng các món nóng địa phương, trái cây nhiệt đới và bia lạnh.', description_zh = 'Green Tree 海鲜自助烧烤餐厅位于日落小镇临海餐饮街区（FB3-03），拥有通风开阔的半露天用餐空间。餐厅供应富国岛本地鲜虾、贝类、鱿鱼等现烤海鲜以及越式热菜、时令热带水果与冰镇啤酒，适合家庭与团体畅享海鲜大餐。', description_ja = 'サンセットタウンの海沿い飲食エリア（FB3-03）に位置する、開放的なシーフードビュッフェ＆グリルレストランです。フーコック近海のエビや貝類、イカなどの炭火グリルをはじめ、温かいローカル料理や南国フルーツ、冷たいビールを潮風を感じながら満喫できます。', description_ru = 'Просторный ресторан формата шведского стола Green Tree Buffet SeaFood расположен в прибрежном секторе FB3-03 в Сансет-Тауне. Гостям предлагают креветок, моллюсков, кальмаров и рыбу с открытого гриля, горячие вьетнамские блюда, тропические фрукты и холодное пиво у моря.', description_hi = 'सनसेट टाउन के तटीय डाइनिंग ब्लॉक (FB3-03) में स्थित ग्रीन ट्री बुफ़े सीफ़ूड खुली हवा में सीफ़ूड बुफ़े और लाइव ग्रिल का आनंद देता है। समुद्री हवा के बीच मेहमान ग्रिल्ड फ़ू क्वोक प्रॉन, क्लैम्स, स्क्विड, स्थानीय गर्म व्यंजन और ताज़ा फलों का स्वाद ले सकते हैं।', public_name = 'Green Tree Buffet SeaFood', tags = ARRAY['seafood', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'green-tree-buffet-seafood';
UPDATE public.businesses SET category = 'dining', subcategory = 'seafood', address = 'Sunset Bazaar Seafront Zone, Sunset Town, An Thới, Phú Quốc, Kiên Giang, Vietnam', description_ko = '지중해 이비자 감성의 해변 라운지 & 씨푸드 바로, 신선한 석화(생굴·치즈 구이 굴)와 해산물 타파스, 세비체, 샴페인 및 시그니처 칵테일을 석양과 함께 즐길 수 있는 선셋타운 핫플레이스입니다.', description_en = 'Ibiza-inspired coastal seafood bar in Sunset Town famous for its fresh raw and baked oysters, seafood tapas, ceviche, chilled wines, and sunset cocktails.', description_vi = 'Quán bar hải sản ven biển phong cách Ibiza tại Thị trấn Hoàng Hôn, phục vụ hàu sống, hàu nướng, tapas hải sản, ceviche, rượu vang và cocktail.', description_zh = '位于日落小镇的伊比萨风格海滨海鲜酒吧，主打新鲜生蚝、焗烤生蚝、海鲜塔帕斯、酸橘汁腌海鲜（Ceviche）、冰镇葡萄酒和日落鸡尾酒。', description_ja = 'サンセットタウンにある、イビサ島の雰囲気を取り入れた海辺のシーフードバー。新鮮な生牡蠣や焼き牡蠣、シーフードタパス、セビーチェ、冷えたワイン、サンセットカクテルなどを提供しています。', description_ru = 'Прибрежный бар морепродуктов в Сансет-Тауне, оформленный в стиле Ибицы. В меню — свежие сырые и запечённые устрицы, тапас из морепродуктов, севиче, охлаждённые вина и коктейли для заката.', description_hi = 'सनसेट टाउन में स्थित यह इबीज़ा-प्रेरित समुद्री बार ताज़े कच्चे और बेक्ड ऑयस्टर, सीफ़ूड टापस, सेविचे, ठंडी वाइन और सूर्यास्त के समय परोसे जाने वाले कॉकटेल के लिए जाना जाता है।', public_name = 'IBIZA - Oyster & Seafood Bar', tags = ARRAY['seafood', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'ibiza-oyster-seafood-bar';
UPDATE public.businesses SET category = 'bars', subcategory = 'cafe', address = '88 amafi, sunset town, Phú Quốc, An Giang, Vietnam', description_ko = '선셋타운 중심 거리에서 시원한 에어컨 좌석과 함께 베트남 연유 커피, 코코넛 스무디 커피, 생망고 스무디 및 반미 브런치를 합리적인 가격에 즐길 수 있는 인기 캐주얼 카페입니다.', description_en = 'Popular casual cafe in central Sunset Town offering air-conditioned seating, Vietnamese condensed milk coffee, coconut smoothie coffee, fresh mango smoothies, and crispy banh mi.', description_vi = 'Quán cà phê ở trung tâm Thị trấn Hoàng Hôn, có chỗ ngồi máy lạnh, cà phê sữa, cà phê dừa đá xay, sinh tố xoài và bánh mì.', description_zh = '位于日落小镇中心区域的休闲咖啡馆，设有空调座位，提供越南炼乳咖啡、椰子冰沙咖啡、新鲜芒果冰沙和酥脆越南法棍三明治（Bánh Mì）。', description_ja = 'サンセットタウン中心部にあるカジュアルなカフェ。冷房の効いた店内席があり、ベトナム式練乳コーヒー、ココナッツコーヒースムージー、フレッシュマンゴースムージー、サクサクのバインミーを提供しています。', description_ru = 'Непринуждённое кафе в центре Сансет-Тауна с кондиционируемым залом. В меню — вьетнамский кофе со сгущённым молоком, кокосовый кофейный смузи, смузи из свежего манго и хрустящие сэндвичи бань ми.', description_hi = 'सनसेट टाउन के मध्य में स्थित इस कैफ़े में एयर-कंडीशंड बैठने की जगह है। यहाँ वियतनामी कंडेंस्ड मिल्क कॉफ़ी, नारियल और कॉफ़ी की स्मूदी, ताज़े आम की स्मूदी और कुरकुरे वियतनामी बान मी सैंडविच मिलते हैं।', public_name = '카페 그린 선셋타운 (CAFE GREEN SUNSET TOWN)', tags = ARRAY['cafe', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'cafe-green-sunset-town';
UPDATE public.businesses SET category = 'bars', subcategory = 'cafe', address = 'Ga đi Ánh Dương), TT, Cáp Treo, Phú Quốc, An Giang 91000, Vietnam', description_ko = '혼똔섬 해상 케이블카 탑승장(안터이 역) 바로 앞에 위치한 베트남 대표 커피 체인으로, 케이블카 탑승 전후 시원한 핀스다(연유 커피)와 골든 로투스 티, 바게트 반미를 빠르게 즐기기 좋습니다.', description_en = 'Vietnam''s leading coffee chain located right at the Hon Thom Cable Car station, ideal for grabbing signature Phin Sua Da coffee, Golden Lotus tea, and banh mi before or after boarding.', description_vi = 'Chi nhánh Highlands Coffee tại ga cáp treo Hòn Thơm, thuận tiện mua cà phê phin sữa đá, trà sen vàng và bánh mì trước hoặc sau khi đi cáp treo.', description_zh = '位于香岛（Hon Thom）缆车站旁的越南连锁咖啡店 Highlands Coffee，提供招牌冰炼乳滴漏咖啡（Phin Sữa Đá）、金莲花茶（Golden Lotus Tea）和越南法棍三明治（Bánh Mì），适合乘坐缆车前后短暂休息。', description_ja = 'ホントム（Hon Thom）ケーブルカー駅にあるベトナムの大手コーヒーチェーン、Highlands Coffee。定番の練乳入りアイスフィンコーヒー（Phin Sữa Đá）、ゴールデンロータスティー、バインミーなどを提供しており、乗車前後の休憩にも利用できます。', description_ru = 'Кофейня крупной вьетнамской сети Highlands Coffee прямо у станции канатной дороги Хонтхом (Hon Thom). Здесь можно заказать фирменный холодный кофе со сгущённым молоком Phin Sữa Đá, чай Golden Lotus и сэндвичи бань ми до или после поездки на канатной дороге.', description_hi = 'Hon Thom केबल कार स्टेशन पर स्थित Highlands Coffee वियतनाम की प्रमुख कॉफ़ी चेन में से एक है। यहाँ केबल कार की सवारी से पहले या बाद में सिग्नेचर Phin Sữa Đá आइस्ड कंडेंस्ड मिल्क कॉफ़ी, Golden Lotus चाय और बान मी सैंडविच लिए जा सकते हैं।', public_name = '하이랜드 커피 안터이 케이블카역 (Highlands Coffee Cable Car An Thới PQ)', tags = ARRAY['cafe', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'highlands-coffee-cable-car-an-thoi-pq';
UPDATE public.businesses SET category = 'bars', subcategory = 'cafe', address = 'Sunset Town, 222 Amalfi, Phú Quốc, An Giang 100000, Vietnam', description_ko = '베트남 전통 핀(Phin) 추출 방식과 원두 이야기를 배우며 에그 커피·코코넛 커피·솔트 커피를 직접 만들어 시음해 볼 수 있는 선셋타운의 이색 커피 워크숍 & 스페셜티 카페입니다.', description_en = 'Interactive Vietnamese coffee workshop and specialty cafe in Sunset Town where guests learn traditional Phin brewing and craft their own egg, coconut, and salted cream coffees.', description_vi = 'Không gian trải nghiệm pha cà phê Việt tại Thị trấn Hoàng Hôn, nơi khách học pha cà phê phin và tự làm cà phê trứng, cà phê dừa, cà phê kem muối.', description_zh = '位于日落小镇的互动式越南咖啡体验工坊兼精品咖啡馆。游客可以学习传统越南滴漏壶（Phin）冲泡方法，并亲手制作鸡蛋咖啡、椰子咖啡和咸奶盖咖啡。', description_ja = 'サンセットタウンにある体験型のベトナムコーヒーワークショップ兼スペシャルティカフェ。伝統的なフィンを使った抽出方法を学び、エッグコーヒー、ココナッツコーヒー、塩クリームコーヒーを自分で作ることができます。', description_ru = 'Интерактивная мастерская вьетнамского кофе и спешелти-кофейня в Сансет-Тауне. Участники знакомятся с традиционным завариванием через фильтр фин и самостоятельно готовят яичный, кокосовый кофе и кофе с солёными сливками.', description_hi = 'सनसेट टाउन में स्थित यह इंटरैक्टिव वियतनामी कॉफ़ी वर्कशॉप और स्पेशलिटी कैफ़े है। यहाँ मेहमान पारंपरिक फिन फ़िल्टर से कॉफ़ी बनाना सीखते हैं और अपनी एग कॉफ़ी, कोकोनट कॉफ़ी तथा सॉल्टेड क्रीम कॉफ़ी तैयार कर सकते हैं।', public_name = 'Phu Quoc Sunset Town Coffee Workshop - Brew & Design the Art of Vietnamese Coffee', tags = ARRAY['cafe', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'phu-quoc-sunset-town-coffee-workshop-brew-design-the-art-of-vietnamese-coffee';
UPDATE public.businesses SET category = 'bars', subcategory = 'cafe', address = 'Milan, Sunset Town, 64 Tổ 10 KP6, Phú Quốc, An Giang 92516, Vietnam', description_ko = '선셋타운 밀란(64 Milan) 거리에 위치한 베트남 로컬 프랜차이즈 카페로, 부담 없는 현지 가격대에 진한 아이스 연유 커피와 솔트 커피, 과일 아이스티를 테이크아웃하거나 쉬어가기 좋습니다.', description_en = 'Local Vietnamese coffee chain at 64 Milan Street, Sunset Town, serving strong iced condensed milk coffee, salted coffee, and fruit teas at budget-friendly local prices.', description_vi = 'Chi nhánh Milano Coffee tại 64 đường Milan, Thị trấn Hoàng Hôn, phục vụ cà phê sữa đá đậm vị, cà phê muối và trà trái cây giá bình dân.', description_zh = '位于日落小镇 Milan 街64号的越南本地连锁咖啡店，提供浓郁的冰炼乳咖啡、盐咖啡和水果茶，价格贴近当地日常消费水平。', description_ja = 'サンセットタウンのMilan通り64番地にあるベトナムのローカルコーヒーチェーン。濃いめの練乳入りアイスコーヒー、塩コーヒー、フルーツティーなどを地元向けの手頃な価格で提供しています。', description_ru = 'Кофейня местной вьетнамской сети по адресу: улица Milan, 64, Сансет-Таун. Здесь предлагают крепкий холодный кофе со сгущённым молоком, солёный кофе и фруктовые чаи по доступным местным ценам.', description_hi = 'सनसेट टाउन की Milan स्ट्रीट पर नंबर 64 में स्थित यह स्थानीय वियतनामी कॉफ़ी चेन की दुकान है। यहाँ स्ट्रॉन्ग आइस्ड कंडेंस्ड मिल्क कॉफ़ी, सॉल्टेड कॉफ़ी और फ्रूट टी स्थानीय स्तर की किफ़ायती कीमतों पर मिलती हैं।', public_name = 'Milano Coffee - 64 Milan Sunset Town', tags = ARRAY['cafe', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'milano-coffee-64-milan-sunset-town';
UPDATE public.businesses SET category = 'bars', subcategory = 'cafe', address = 'cạnh, 165 Đường MILAN, khu phố 6, Phú Quốc, An Giang, Vietnam', description_ko = '1958년 하노이에서 시작된 베트남 국민 전통 아이스크림 브랜드 ''트랑띠엔(Kem Tràng Tiền)''의 선셋타운 매장으로, 코코넛·녹두·토란·찹쌀 아이스크림과 베트남 커피를 맛볼 수 있는 디저트 카페입니다.', description_en = 'Sunset Town branch of Hanoi''s iconic 1958 heritage ice cream brand Kem Trang Tien, serving classic coconut, mung bean, taro, and young rice ice creams alongside Vietnamese coffee.', description_vi = 'Chi nhánh Kem Tràng Tiền tại Thị trấn Hoàng Hôn, thương hiệu kem Hà Nội từ năm 1958, phục vụ kem dừa, đậu xanh, khoai môn, cốm và cà phê Việt.', description_zh = '河内经典冰淇淋品牌 Kem Trang Tien 在日落小镇的分店。该品牌创立于1958年，提供传统椰子、绿豆、芋头和嫩糯米口味冰淇淋，以及越南咖啡。', description_ja = '1958年創業のハノイの老舗アイスクリームブランド「Kem Trang Tien」のサンセットタウン店。ココナッツ、緑豆、タロイモ、若いもち米などの伝統的なフレーバーのアイスクリームとベトナムコーヒーを提供しています。', description_ru = 'Филиал известной ханойской марки мороженого Kem Trang Tien в Сансет-Тауне. Бренд существует с 1958 года. Здесь подают мороженое с традиционными вкусами кокоса, маша, таро и молодого клейкого риса, а также вьетнамский кофе.', description_hi = 'यह सनसेट टाउन में हनोई के प्रसिद्ध आइसक्रीम ब्रांड Kem Trang Tien की शाखा है, जिसकी शुरुआत 1958 में हुई थी। यहाँ नारियल, मूंग, अरबी और कच्चे चिपचिपे चावल के पारंपरिक स्वादों वाली आइसक्रीम के साथ वियतनामी कॉफ़ी भी मिलती है।', public_name = 'Kem Tràng Tiền - Milan, Thị Trấn Hoàng hôn', tags = ARRAY['cafe', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'kem-trang-tien-sunset-town-phu-quoc';
UPDATE public.businesses SET category = 'bars', subcategory = 'cafe', address = '11 Đ.Positano, Khu phố 6, Phú Quốc, An Giang, Vietnam', description_ko = '상큼한 지중해 레몬 테마 인테리어가 돋보이는 부티크 호텔 겸 카페로, 차센으로 직접 격불한 프리미엄 우지 말차 라떼(Matcha Bar)와 스페셜티 에스프레소, 수제 레몬 에이드를 선보입니다.', description_en = 'Mediterranean lemon-themed boutique cafe and matcha bar specializing in hand-whisked ceremonial matcha lattes, specialty espresso drinks, and fresh homemade lemonade.', description_vi = 'Quán cà phê boutique phong cách Địa Trung Hải chủ đề chanh, chuyên matcha latte đánh tay, espresso đặc sản và nước chanh tươi tự làm.', description_zh = '以地中海柠檬元素为主题的精品咖啡馆兼抹茶吧，主打手工茶筅搅打的仪式级抹茶拿铁、精品浓缩咖啡饮品和新鲜自制柠檬水。', description_ja = '地中海のレモンをテーマにしたブティックカフェ兼抹茶バー。茶筅で一杯ずつ点てる上質な抹茶ラテ、スペシャルティエスプレッソドリンク、手作りのフレッシュレモネードなどを提供しています。', description_ru = 'Небольшое кафе и матча-бар в средиземноморском стиле с лимонной тематикой. Специализируется на матча-латте из церемониального чая, взбитого вручную венчиком, спешелти-напитках на основе эспрессо и свежем домашнем лимонаде.', description_hi = 'यह भूमध्यसागरीय नींबू-थीम वाला बुटीक कैफ़े और माचा बार है। यहाँ हाथ से फेंटे गए सेरेमोनियल-ग्रेड माचा लाटे, स्पेशलिटी एस्प्रेसो ड्रिंक्स और ताज़ा घर का बना लेमोनेड परोसा जाता है।', public_name = 'Casa Limone Hotel & Café - Specialty Coffee & Matcha', tags = ARRAY['cafe', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'casa-limone-phu-quoc-hotel-cafe-specialty-coffee-matcha-bar';
UPDATE public.businesses SET category = 'bars', subcategory = 'cafe', address = '22P3+78G, Ấp 7, Phú Quốc, An Giang, Vietnam', description_ko = '선셋타운 산책 중 당 충전에 제격인 버블티 & 생과일 티 전문점으로, 쫀득한 흑당 타이거 버블 밀크티와 복숭아·리치·패션후르츠 생과일 아이스티, 치즈폼 우롱티가 인기입니다.', description_en = 'Bubble tea and fruit tea shop in Sunset Town famous for its brown sugar tiger boba milk tea, fresh tropical fruit iced teas, and cheese foam oolong tea.', description_vi = 'Quán trà sữa và trà trái cây tại Thị trấn Hoàng Hôn, phục vụ trà sữa trân châu đường đen, trà trái cây nhiệt đới và ô long kem phô mai.', description_zh = '位于日落小镇的珍珠奶茶与水果茶店，主打黑糖虎纹珍珠奶茶、新鲜热带水果冰茶和芝士奶盖乌龙茶。', description_ja = 'サンセットタウンにあるタピオカミルクティーとフルーツティーの専門店。黒糖タイガータピオカミルクティー、トロピカルフルーツのアイスティー、チーズフォームをのせたウーロン茶などを提供しています。', description_ru = 'Магазин чая с тапиокой и фруктовых чаёв в Сансет-Тауне. Здесь предлагают молочный чай с шариками тапиоки и коричневым сахаром в стиле Tiger, холодные чаи со свежими тропическими фруктами и улун с сырной пенкой.', description_hi = 'सनसेट टाउन में स्थित यह बबल टी और फ्रूट टी शॉप ब्राउन शुगर टाइगर बोबा मिल्क टी, ताज़े ट्रॉपिकल फलों की आइस्ड टी और चीज़ फ़ोम वाली ऊलॉन्ग चाय परोसती है।', public_name = 'Sunset Tiger Tea', tags = ARRAY['cafe', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'sunset-tiger-tea';
UPDATE public.businesses SET category = 'bars', subcategory = 'cafe', address = 'VEN 46, Venice Street, Sunset Town, An Thới, Phú Quốc, Kiên Giang, Vietnam', description_ko = '감각적인 라운지 인테리어와 쾌적한 실내 좌석을 갖춘 선셋타운 카페로, 베트남 전통 커피부터 스페셜티 아메리카노, 열대과일 스무디와 가벼운 디저트를 여유롭게 즐길 수 있습니다.', description_en = 'Stylish coffee lounge in Sunset Town with comfortable indoor seating, serving traditional Vietnamese coffee, specialty espresso, tropical smoothies, and light desserts.', description_vi = 'Coffee lounge tại Thị trấn Hoàng Hôn, có chỗ ngồi trong nhà, phục vụ cà phê Việt, espresso, sinh tố nhiệt đới và món tráng miệng nhẹ.', description_zh = '位于日落小镇的咖啡休闲空间，设有舒适的室内座位，提供传统越南咖啡、精品浓缩咖啡饮品、热带水果冰沙和简餐甜点。', description_ja = 'サンセットタウンにあるスタイリッシュなコーヒーラウンジ。快適な屋内席を備え、伝統的なベトナムコーヒー、スペシャルティエスプレッソ、トロピカルフルーツスムージー、軽めのデザートなどを提供しています。', description_ru = 'Стильный кофейный лаунж в Сансет-Тауне с удобными местами в помещении. В меню — традиционный вьетнамский кофе, спешелти-напитки на основе эспрессо, смузи из тропических фруктов и лёгкие десерты.', description_hi = 'सनसेट टाउन में स्थित यह स्टाइलिश कॉफ़ी लाउंज आरामदायक इनडोर बैठने की सुविधा देता है। यहाँ पारंपरिक वियतनामी कॉफ़ी, स्पेशलिटी एस्प्रेसो ड्रिंक्स, ट्रॉपिकल फ्रूट स्मूदी और हल्की मिठाइयाँ परोसी जाती हैं।', public_name = 'Senthy Coffee Lounge', tags = ARRAY['cafe', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'senthy-coffee-lounge';
UPDATE public.businesses SET category = 'bars', subcategory = 'cafe', address = 'S1-09 New An Thới, Phú Quốc, An Giang 97000, Vietnam', description_ko = '일본 교토산 프리미엄 말차를 차센으로 직접 격불해 내어주는 선셋타운의 정통 일본 말차 전문 카페(Matcha Bar)로, 진한 우지 말차 라떼와 호지차 라떼, 말차 디저트가 인기입니다.', description_en = 'Authentic Japanese matcha specialty cafe in Sunset Town serving hand-whisked Kyoto Uji matcha lattes, houjicha lattes, and rich matcha desserts.', description_vi = 'Quán chuyên matcha Nhật tại Thị trấn Hoàng Hôn, phục vụ matcha latte Uji Kyoto đánh tay, houjicha latte và món tráng miệng matcha.', description_zh = '位于日落小镇的日式抹茶专门咖啡馆，提供手工茶筅搅打的日本京都宇治抹茶拿铁、焙茶拿铁及浓郁的抹茶甜品。', description_ja = 'サンセットタウンにある日本式の抹茶専門カフェ。京都・宇治産の抹茶を茶筅で点てた抹茶ラテ、ほうじ茶ラテ、濃厚な抹茶スイーツなどを提供しています。', description_ru = 'Кафе японского чая матча в Сансет-Тауне. Здесь подают матча-латте из чая Удзи, привезённого из Киото и взбитого вручную венчиком, латте с обжаренным зелёным чаем ходзича и десерты с насыщенным вкусом матча.', description_hi = 'सनसेट टाउन में स्थित यह जापानी माचा स्पेशलिटी कैफ़े क्योटो के उजी क्षेत्र की माचा चाय से हाथ से फेंटकर तैयार किया गया माचा लाटे, होजिचा लाटे और गाढ़े माचा स्वाद वाली मिठाइयाँ परोसता है।', public_name = 'Tsunagari Phu Quoc - Japanese matcha in the island', tags = ARRAY['cafe', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'tsunagari-phu-quoc-japanese-matcha-in-the-island';
UPDATE public.businesses SET category = 'bars', subcategory = 'cafe', address = 'Venice 07 Sunset town, Phú Quốc, An Giang, Vietnam', description_ko = '매일 굽는 프랑스식 버터 크루아상·수제 조각 케이크와 함께 부드러운 에그 커피, 코코넛 커피, 스페셜티 에스프레소를 즐길 수 있는 선셋타운의 유러피안 베이커리 & 에스프레소 바입니다.', description_en = 'European-style espresso bar and pastry cafe in Sunset Town serving freshly baked butter croissants, artisan cakes, creamy egg coffee, and coconut coffee.', description_vi = 'Quán espresso và bánh ngọt phong cách Âu tại Thị trấn Hoàng Hôn, phục vụ croissant bơ mới nướng, bánh thủ công, cà phê trứng và cà phê dừa.', description_zh = '位于日落小镇的欧式浓缩咖啡吧兼糕点咖啡馆，提供新鲜烘焙的黄油可颂、手工蛋糕、香浓越南鸡蛋咖啡和椰子咖啡。', description_ja = 'サンセットタウンにあるヨーロッパスタイルのエスプレッソバー兼ペストリーカフェ。焼きたてのバタークロワッサン、手作りケーキ、濃厚なエッグコーヒー、ココナッツコーヒーなどを提供しています。', description_ru = 'Кофейня и кондитерская в европейском стиле в Сансет-Тауне. Здесь подают эспрессо, свежеиспечённые масляные круассаны, торты ручной работы, нежный вьетнамский яичный кофе и кокосовый кофе.', description_hi = 'सनसेट टाउन में स्थित यह यूरोपीय शैली का एस्प्रेसो बार और पेस्ट्री कैफ़े ताज़ा बेक किए गए बटर क्रोइसाँ, हाथ से बने केक, क्रीमी वियतनामी एग कॉफ़ी और कोकोनट कॉफ़ी परोसता है।', public_name = 'Cafe Juliet & Pastries', tags = ARRAY['cafe', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'cafe-juliet-pastries';
UPDATE public.businesses SET category = 'bars', subcategory = 'cafe', address = '71 Amalfi, Sunset Town, Phú Quốc, An Giang 92513, Vietnam', description_ko = '선셋타운 아말피 해안도로(AMA71)에 자리한 오션뷰 디저트 카페로, 수제 티라미수·바스크 치즈케이크와 달콤한 코코넛 커피를 즐기며 일몰과 바다 전망을 감상하기 좋은 명소입니다.', description_en = 'Oceanfront dessert and coffee cafe along Amalfi Street (AMA71) in Sunset Town, popular for its house-made tiramisu, Basque cheesecake, coconut coffee, and sunset sea views.', description_vi = 'Quán cà phê và tráng miệng ven biển trên đường Amalfi (AMA71), Thị trấn Hoàng Hôn, phục vụ tiramisu tự làm, cheesecake Basque, cà phê dừa và tầm nhìn hoàng hôn.', description_zh = '位于日落小镇 Amalfi 街（AMA71）的海滨甜品咖啡馆，提供店内自制提拉米苏、巴斯克芝士蛋糕和椰子咖啡，并可欣赏日落海景。', description_ja = 'サンセットタウンのAmalfi通り（AMA71）にある海沿いのデザートカフェ。自家製ティラミス、バスクチーズケーキ、ココナッツコーヒーなどを提供しており、海に沈む夕日を眺められます。', description_ru = 'Десертное кафе у моря на улице Amalfi (AMA71) в Сансет-Тауне. Здесь предлагают домашний тирамису, баскский чизкейк и кокосовый кофе. Из кафе открывается вид на море и закат.', description_hi = 'सनसेट टाउन की Amalfi स्ट्रीट (AMA71) पर समुद्र किनारे स्थित यह डेज़र्ट कैफ़े घर में बना तिरामिसू, बास्क चीज़केक और कोकोनट कॉफ़ी परोसता है। यहाँ से समुद्र और सूर्यास्त का नज़ारा भी देखा जा सकता है।', public_name = 'The Juliet Coffee & Dessert - AMA71', tags = ARRAY['cafe', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'the-juliet-coffee-dessert-ama71';
UPDATE public.businesses SET category = 'bars', subcategory = 'cafe', address = '59 Đ.Positano, Phú Quốc, An Giang, Vietnam', description_ko = '푸꾸옥 현지 아티스트들의 핸드메이드 조개 공예·라탄 소품·엽서 편집숍과 아늑한 카페가 어우러진 공간으로, 시그니처 코코넛·솔트 커피를 마시며 특별한 여행 기념품을 고를 수 있습니다.', description_en = 'Charming concept cafe and artisan gift shop in Sunset Town combining specialty Vietnamese coffee with locally handcrafted shell crafts, rattan bags, and illustrated postcards.', description_vi = 'Quán cà phê kết hợp cửa hàng quà thủ công tại Thị trấn Hoàng Hôn, bán cà phê Việt, đồ thủ công từ vỏ sò, túi mây và bưu thiếp minh họa.', description_zh = '位于日落小镇的特色咖啡馆兼手工礼品店，将越南精品咖啡与当地手工制作的贝壳工艺品、藤编包和插画明信片结合在一起。', description_ja = 'サンセットタウンにあるコンセプトカフェ兼ハンドメイドギフトショップ。ベトナムのスペシャルティコーヒーを楽しみながら、地元で手作りされた貝殻の工芸品、ラタンバッグ、イラスト入りポストカードなどを購入できます。', description_ru = 'Концептуальное кафе и магазин подарков ручной работы в Сансет-Тауне. Здесь можно попробовать вьетнамский спешелти-кофе и приобрести местные изделия из ракушек, плетёные сумки из ротанга и открытки с иллюстрациями.', description_hi = 'सनसेट टाउन में स्थित यह कॉन्सेप्ट कैफ़े और हस्तनिर्मित उपहारों की दुकान वियतनामी स्पेशलिटी कॉफ़ी के साथ स्थानीय कारीगरों द्वारा बनाए गए सीपियों के हस्तशिल्प, रतन बैग और चित्रों वाले पोस्टकार्ड उपलब्ध कराती है।', public_name = 'Islander PhuQuoc Handmade Gifts & Coffee', tags = ARRAY['cafe', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'islander-phuquoc-handmade-gifts-coffee';
UPDATE public.businesses SET category = 'bars', subcategory = 'cafe', address = 'Đ. Amalfi, Sunset Town, Phú Quốc, An Giang 91000, Vietnam', description_ko = '선셋타운 해안가에서 탁 트인 오션뷰와 세련된 라운지 음악을 즐기며 시그니처 베트남 커피, 트로피컬 칵테일, 애프터눈 디저트를 맛볼 수 있는 감성 카페 & 라운지입니다.', description_en = 'Chic ocean-view cafe and lounge in Sunset Town offering specialty Vietnamese coffee, tropical cocktails, and desserts in a relaxing coastal setting.', description_vi = 'Quán cà phê và lounge nhìn ra biển tại Thị trấn Hoàng Hôn, phục vụ cà phê Việt đặc sản, cocktail nhiệt đới và món tráng miệng.', description_zh = '位于日落小镇的海景咖啡馆兼休闲酒廊，环境舒适，提供越南精品咖啡、热带鸡尾酒和甜品。', description_ja = 'サンセットタウンにある海の見えるカフェ＆ラウンジ。落ち着いた海辺の雰囲気の中で、ベトナムのスペシャルティコーヒー、トロピカルカクテル、デザートなどを楽しめます。', description_ru = 'Стильное кафе и лаунж с видом на море в Сансет-Тауне. В спокойной прибрежной обстановке здесь подают вьетнамский спешелти-кофе, тропические коктейли и десерты.', description_hi = 'सनसेट टाउन में समुद्र के दृश्य वाला यह स्टाइलिश कैफ़े और लाउंज आरामदायक तटीय माहौल में वियतनामी स्पेशलिटी कॉफ़ी, ट्रॉपिकल कॉकटेल और मिठाइयाँ परोसता है।', public_name = 'The Ivy Café & Lounge Phu Quoc', tags = ARRAY['cafe', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'the-ivy-cafe-lounge-phu-quoc';
UPDATE public.businesses SET category = 'bars', subcategory = 'cafe', address = '69 Đ.Positano, Sunset Town, Phú Quốc, An Giang 92000, Vietnam', description_ko = '베트남 전통 연꽃 감성을 담은 아늑한 홈 스타일 카페로, 향긋한 연꽃차와 베트남 핀 커피, 생망고·코코넛 스무디를 마시며 무더위를 식히기 좋은 휴식처입니다.', description_en = 'Cozy home-style cafe in Sunset Town offering fragrant Vietnamese lotus tea, traditional Phin coffee, and fresh mango and coconut smoothies in a relaxing setting.', description_vi = 'Quán cà phê phong cách gia đình tại Thị trấn Hoàng Hôn, phục vụ trà sen Việt, cà phê phin, sinh tố xoài và sinh tố dừa.', description_zh = '位于日落小镇的温馨家庭风格咖啡馆，环境轻松，提供清香的越南莲花茶、传统滴漏咖啡（Phin），以及新鲜芒果和椰子冰沙。', description_ja = 'サンセットタウンにある家庭的で落ち着いた雰囲気のカフェ。香り豊かなベトナムの蓮茶、伝統的なフィンコーヒー、フレッシュマンゴーやココナッツのスムージーなどを提供しています。', description_ru = 'Уютное кафе с домашней атмосферой в Сансет-Тауне. Здесь подают ароматный вьетнамский лотосовый чай, традиционный кофе через фильтр фин, а также смузи из свежего манго и кокоса.', description_hi = 'सनसेट टाउन में स्थित यह आरामदायक, घरेलू शैली का कैफ़े सुगंधित वियतनामी कमल की चाय, पारंपरिक फिन फ़िल्टर कॉफ़ी और ताज़े आम व नारियल की स्मूदी परोसता है।', public_name = 'Lotus Home & Cafe', tags = ARRAY['cafe', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'lotus-home-cafe';
UPDATE public.businesses SET category = 'bars', subcategory = 'cafe', address = '22M4+622, Phú Quốc, An Giang, Vietnam', description_ko = '푸르른 식물 인테리어와 탁 트인 바다 전망이 어우러진 오션뷰 카페로, 시원한 코코넛 커피 스무디와 열대과일 에이드를 마시며 선셋타운 해안 풍경을 감상하기 좋습니다.', description_en = 'Botanical ocean-view cafe in Sunset Town where guests can enjoy iced coconut coffee smoothies and tropical fruit ades overlooking the sea.', description_vi = 'Quán cà phê trang trí cây xanh nhìn ra biển tại Thị trấn Hoàng Hôn, phục vụ cà phê dừa đá xay và nước trái cây nhiệt đới có ga.', description_zh = '位于日落小镇的植物主题海景咖啡馆，游客可以一边欣赏海景，一边享用冰镇椰子咖啡冰沙和热带水果气泡饮。', description_ja = 'サンセットタウンにある植物を取り入れた海の見えるカフェ。海を眺めながら、冷たいココナッツコーヒースムージーやトロピカルフルーツエードを楽しめます。', description_ru = 'Кафе с растительным оформлением и видом на море в Сансет-Тауне. Здесь можно насладиться холодным кокосовым кофейным смузи и газированными напитками с тропическими фруктами, любуясь морским пейзажем.', description_hi = 'सनसेट टाउन में स्थित यह पौधों से सजा समुद्र-दृश्य वाला कैफ़े है, जहाँ समुद्र को निहारते हुए ठंडी कोकोनट कॉफ़ी स्मूदी और ट्रॉपिकल फ्रूट फ़िज़ी ड्रिंक्स का आनंद लिया जा सकता है।', public_name = 'The Fern Coffee Sea', tags = ARRAY['cafe', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'the-fern-coffee-sea';
UPDATE public.businesses SET category = 'bars', subcategory = 'cafe', address = '51 Đ.Positano, Phú Quốc, An Giang 31078, Vietnam', description_ko = '그리스 산토리니풍 화이트 & 블루 외관이 인상적인 포토제닉 카페로, 선셋타운 골목 산책 중 인생샷을 남기며 시원한 베트남 커피와 과일 스무디를 즐기기 좋습니다.', description_en = 'Santorini-inspired white-and-blue cafe in Sunset Town offering scenic photo spots alongside refreshing Vietnamese iced coffee and tropical fruit smoothies.', description_vi = 'Quán cà phê tông trắng xanh phong cách Santorini tại Thị trấn Hoàng Hôn, có góc chụp ảnh, cà phê đá Việt và sinh tố trái cây nhiệt đới.', description_zh = '位于日落小镇的圣托里尼风格咖啡馆，以蓝白色建筑装饰为特色，设有适合拍照的景观区域，并提供越南冰咖啡和热带水果冰沙。', description_ja = 'サンセットタウンにある、サントリーニ島をイメージした白と青のカフェ。写真撮影に適したスポットがあり、冷たいベトナムコーヒーやトロピカルフルーツスムージーを提供しています。', description_ru = 'Кафе в Сансет-Тауне, оформленное в бело-голубых тонах по мотивам Санторини. Здесь есть места для фотографий, а в меню — холодный вьетнамский кофе и смузи из тропических фруктов.', description_hi = 'सनसेट टाउन में स्थित यह सैंटोरिनी से प्रेरित सफ़ेद और नीले रंग का कैफ़े फ़ोटो खींचने के लिए आकर्षक स्थानों के साथ ठंडी वियतनामी कॉफ़ी और ट्रॉपिकल फ्रूट स्मूदी उपलब्ध कराता है।', public_name = 'SANTO CAFE', tags = ARRAY['cafe', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'santo-cafe';
UPDATE public.businesses SET category = 'bars', subcategory = 'cafe', address = '22J4+2P4, Phú Quốc, An Giang, Vietnam', description_ko = '세계적인 프랑스 아티장 베이커리 ''메종 카이저(Maison Kayser)''의 선셋타운 매장으로, 매일 아침 굽는 정통 버터 크루아상·뺑오쇼콜라·바게트 샌드위치와 고급 에스프레소 커피를 선보입니다.', description_en = 'Sunset Town branch of the world-renowned French artisan bakery Maison Kayser, serving freshly baked butter croissants, pain au chocolat, gourmet sandwiches, and specialty coffee.', description_vi = 'Chi nhánh Maison Kayser tại Thị trấn Hoàng Hôn, phục vụ croissant bơ mới nướng, pain au chocolat, sandwich và cà phê đặc sản.', description_zh = '法国手工烘焙品牌 Maison Kayser 位于日落小镇的分店，提供新鲜烘焙的黄油可颂、巧克力可颂、精选三明治和精品咖啡。', description_ja = 'フランス発のベーカリーブランド「Maison Kayser」のサンセットタウン店。焼きたてのバタークロワッサン、パン・オ・ショコラ、こだわりのサンドイッチ、スペシャルティコーヒーなどを提供しています。', description_ru = 'Филиал французской ремесленной пекарни Maison Kayser в Сансет-Тауне. Здесь предлагают свежеиспечённые масляные круассаны, пан-о-шоколя, сэндвичи и спешелти-кофе.', description_hi = 'सनसेट टाउन में स्थित यह फ़्रांसीसी आर्टिज़न बेकरी ब्रांड Maison Kayser की शाखा है। यहाँ ताज़ा बेक किए गए बटर क्रोइसाँ, पैन ओ शोकोला, विशेष सैंडविच और स्पेशलिटी कॉफ़ी मिलती है।', public_name = 'Maison Kayser Phu Quoc', tags = ARRAY['cafe', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'maison-kayser-phu-quoc';
UPDATE public.businesses SET category = 'bars', subcategory = 'cafe', address = '22H5+CHH, Phú Quốc, An Giang, Vietnam', description_ko = '깔끔하고 모던한 분위기에서 정성껏 내린 스페셜티 커피와 베트남 솔트 커피, 코코넛 커피 및 수제 티 베리에이션을 합리적인 가격에 제공하는 선셋타운 로컬 카페입니다.', description_en = 'Modern neighborhood cafe in Sunset Town serving specialty espresso, Vietnamese salted cream coffee, coconut coffee, and handcrafted fruit teas.', description_vi = 'Quán cà phê hiện đại tại Thị trấn Hoàng Hôn, phục vụ espresso đặc sản, cà phê kem muối, cà phê dừa và trà trái cây pha thủ công.', description_zh = '位于日落小镇的现代社区咖啡馆，提供精品浓缩咖啡、越南咸奶盖咖啡、椰子咖啡和手工调制的水果茶。', description_ja = 'サンセットタウンにあるモダンな街角カフェ。スペシャルティエスプレッソ、ベトナム式塩クリームコーヒー、ココナッツコーヒー、手作りのフルーツティーなどを提供しています。', description_ru = 'Современная кофейня в Сансет-Тауне. В меню — спешелти-эспрессо, вьетнамский кофе с солёными сливками, кокосовый кофе и фруктовые чаи ручного приготовления.', description_hi = 'सनसेट टाउन में स्थित यह आधुनिक स्थानीय कैफ़े स्पेशलिटी एस्प्रेसो, वियतनामी सॉल्टेड क्रीम कॉफ़ी, कोकोनट कॉफ़ी और हाथ से तैयार की गई फ्रूट टी परोसता है।', public_name = 'MAE Coffee', tags = ARRAY['cafe', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'mae-coffee';
UPDATE public.businesses SET category = 'bars', subcategory = 'cafe', address = 'Amalfi, Sunset Town, Phú Quốc, An Giang 92516, Vietnam', description_ko = '유럽풍 거리 풍경이 내려다보이는 테라스와 쾌적한 실내 좌석을 갖춘 선셋타운 카페로, 진한 코코넛 커피 스무디와 생과일 주스, 브런치 스낵을 여유롭게 즐기기 좋습니다.', description_en = 'Inviting cafe in Sunset Town with European-style street views, serving rich coconut coffee smoothies, fresh tropical fruit juices, and light brunch snacks.', description_vi = 'Quán cà phê tại Thị trấn Hoàng Hôn nhìn ra đường phố kiểu Âu, phục vụ cà phê dừa đá xay, nước ép trái cây nhiệt đới và brunch nhẹ.', description_zh = '位于日落小镇的休闲咖啡馆，可欣赏欧式风格街景，提供浓郁的椰子咖啡冰沙、新鲜热带果汁和简餐式早午餐小吃。', description_ja = 'サンセットタウンにある、ヨーロッパ風の街並みを眺められるカフェ。濃厚なココナッツコーヒースムージー、新鮮なトロピカルフルーツジュース、軽めのブランチメニューなどを提供しています。', description_ru = 'Уютное кафе в Сансет-Тауне с видом на улицы в европейском стиле. Здесь подают насыщенный кокосовый кофейный смузи, свежие соки из тропических фруктов и лёгкие блюда для бранча.', description_hi = 'सनसेट टाउन में स्थित इस कैफ़े से यूरोपीय शैली की सड़कों का नज़ारा दिखाई देता है। यहाँ गाढ़ी कोकोनट कॉफ़ी स्मूदी, ताज़े ट्रॉपिकल फलों के जूस और हल्के ब्रंच स्नैक्स परोसे जाते हैं।', public_name = 'Apollo Cafe Phu Quoc', tags = ARRAY['cafe', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'apollo-cafe-phu-quoc';
UPDATE public.businesses SET category = 'dining', subcategory = 'western', address = 'H3 0105 The Hill, sunset town, Đường MILAN, Phú Quốc, An Giang, Vietnam', description_ko = '화덕 스타일 수제 피자와 육즙 가득한 비프 버거, 파스타부터 베트남 연유 커피와 시원한 생맥주(해피아워 콤보)까지 올데이로 즐길 수 있는 캐주얼 비스트로 & 카페입니다.', description_en = 'Casual all-day bistro and cafe in Sunset Town serving handcrafted pizzas, gourmet beef burgers, pasta, Vietnamese coffee, and cold draft beer.', description_vi = 'Quán bistro kết hợp cà phê tại Thị trấn Hoàng Hôn, phục vụ cả ngày với pizza thủ công, burger bò, mì Ý, cà phê Việt và bia tươi lạnh.', description_zh = '位于日落小镇的休闲全天营业小酒馆兼咖啡馆，提供手工披萨、精选牛肉汉堡、意面、越南咖啡和冰镇生啤酒。', description_ja = 'サンセットタウンにあるカジュアルなオールデイビストロ＆カフェ。手作りピザ、こだわりのビーフバーガー、パスタ、ベトナムコーヒー、冷たい生ビールなどを提供しています。', description_ru = 'Непринуждённое бистро и кафе в Сансет-Тауне, работающее в течение всего дня. В меню — пицца ручной работы, бургеры с говядиной, паста, вьетнамский кофе и холодное разливное пиво.', description_hi = 'सनसेट टाउन में स्थित यह कैज़ुअल ऑल-डे बिस्ट्रो और कैफ़े हाथ से बने पिज़्ज़ा, विशेष बीफ़ बर्गर, पास्ता, वियतनामी कॉफ़ी और ठंडी ड्राफ़्ट बीयर परोसता है।', public_name = 'La isla Bistro & coffee', tags = ARRAY['cafe', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'la-isla-bistro-coffee';
UPDATE public.businesses SET category = 'bars', subcategory = 'bar', address = 'La Festa Phu Quoc (Terza Zone), Amalfi Coast Road, Sunset Town, An Thới, Phú Quốc, Vietnam', description_ko = '라 페스타 푸꾸옥(힐튼) 내부에 숨겨진 아늑한 라이브 재즈 & 스피크이지 칵테일 라운지입니다. 빈티지 이탈리안 무드 속에서 라이브 공연과 함께 바텐더의 시그니처 크래프트 칵테일, 싱글몰트 위스키, 바 스낵을 여유롭게 음미하기 좋습니다.', description_en = 'Tucked inside La Festa Phu Quoc, Curio Collection by Hilton, Luna Folk is an intimate speakeasy lounge blending vintage Italian charm with live jazz performances. Unwind after the evening shows over bespoke craft cocktails, single malt whiskies, and curated bar bites.', description_vi = 'Ẩn mình bên trong khách sạn La Festa Phu Quoc, Curio Collection by Hilton, Luna Folk là không gian speakeasy lounge ấm cúng kết hợp nét cổ điển nước Ý cùng những đêm nhạc jazz sống động. Đây là điểm dừng chân lý tưởng sau giờ xem show để thưởng thức cocktail pha chế riêng, whisky mạch nha đơn và món nhắm tinh tế.', description_zh = 'Luna Folk 隐匿于富国岛拉菲斯塔希尔顿酒店内部，是一间融合复古意式格调与现场爵士乐演出的私密地下风鸡尾酒廊。看完夜间演出后，非常适合来此细品调酒师定制的手工鸡尾酒、单一麦芽威士忌与精选佐酒小食。', description_ja = 'ラ・フェスタ・フーコック（ヒルトン）館内に佇む、隠れ家のようなライブジャズ＆スピークイージー・カクテルラウンジです。ヴィンテージ・イタリアンの落ち着いた空間で生演奏に耳を傾けながら、特製クラフトカクテルやシングルモルトウイスキー、バースナックをゆっくり味わえます。', description_ru = 'Уютный спикизи-лаундж Luna Folk внутри отеля La Festa Phu Quoc, Curio Collection by Hilton сочетает винтажный итальянский шарм с живыми джазовыми выступлениями. Идеальное место, чтобы расслабиться после вечерних шоу за авторскими коктейлями, односолодовым виски и изысканными закусками.', description_hi = 'ला फ़ेस्टा फ़ू क्वोक, क्यूरियो कलेक्शन बाय हिल्टन के भीतर छिपा लूना फ़ोक एक अंतरंग स्पीकईज़ी लाउंज है, जहाँ विंटेज इतालवी आकर्षण और लाइव जैज़ संगीत का संगम मिलता है। शाम के शो के बाद बेस्पोक क्राफ़्ट कॉकटेल, सिंगल माल्ट व्हिस्की और बार स्नैक्स के साथ सुकून भरे पल बिताएँ।', public_name = '루나 포크 (Luna Folk)', price_level = '$$$', tags = ARRAY['bar', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'luna-folk';
UPDATE public.businesses SET category = 'bars', subcategory = 'bar', address = 'Sunset Town, La Festa, Phú Quốc, An Giang 91000, Vietnam', description_ko = '라 페스타 푸꾸옥(힐튼) 로비 층에 위치한 클래식 이탈리안 살롱 콘셉트의 애프터눈 티 라운지입니다. 바다 전망의 우아한 실내에서 매일 구워내는 아티산 페이스트리와 이탈리안 애프터눈 티 세트, 스페셜티 에스프레소를 선보입니다.', description_en = 'Located on the lobby level of La Festa Phu Quoc, iL Salone channels classic Italian salon elegance with sunlit ocean views. Guests can indulge in signature afternoon tea sets, freshly baked artisan pastries, specialty espresso drinks, and evening aperitifs.', description_vi = 'Nằm tại tầng sảnh của La Festa Phu Quoc, iL Salone tái hiện vẻ thanh lịch của những phòng trà salon Ý cổ điển ngập tràn ánh nắng và hướng thẳng ra biển. Thực khách có thể thưởng thức bộ trà chiều đặc trưng, bánh ngọt thủ công nướng mới mỗi ngày, cà phê espresso thượng hạng và rượu khai vị buổi tối.', description_zh = 'iL Salone 位于富国岛拉菲斯塔希尔顿酒店大堂层，以经典意大利沙龙美学结合明亮开阔的海景视野。宾客可在优雅的室内空间享用招牌意式下午茶套餐、每日现烤手工糕点、精品浓缩咖啡以及傍晚开胃酒。', description_ja = 'ラ・フェスタ・フーコック（ヒルトン）のロビー階に位置する、クラシックなイタリアンサロンを再現したアフタヌーンティーラウンジです。光が差し込むオーシャンビューの優雅な空間で、焼きたてのアーティザン・ペイストリーや特製アフタヌーンティーセット、本格エスプレッソを楽しめます。', description_ru = 'Лаундж iL Salone на уровне лобби отеля La Festa Phu Quoc воплощает элегантность классического итальянского салона с солнечным видом на океан. Гостям предлагают фирменные сеты послеобеденного чая, свежую ремесленную выпечку, спешелти-эспрессо и вечерние аперитивы.', description_hi = 'ला फ़ेस्टा फ़ू क्वोक के लॉबी लेवल पर स्थित इल सलोने धूप से सराबोर समुद्री दृश्यों के साथ क्लासिक इतालवी सैलून की भव्यता प्रस्तुत करता है। मेहमान यहाँ सिग्नेचर आफ़्टरनून टी सेट, ताज़ा बेक की गई आर्टिसन पेस्ट्री, स्पेशलिटी एस्प्रेसो और शाम के एपेरितिफ़ का आनंद ले सकते हैं।', public_name = '일 살로네 (iL Salone – Afternoon Tea Lounge & Bar)', price_level = '$$$', tags = ARRAY['bar', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'il-salone-afternoon-tea-lounge-bar';
UPDATE public.businesses SET category = 'bars', subcategory = 'bar', address = 'Sunset Town Level 6, Phú Quốc, An Giang 91000, Vietnam', description_ko = '라 페스타 푸꾸옥(힐튼) 6층 최상층에 자리한 아말피 해안 감성의 루프탑 바입니다. 키스 브릿지와 푸꾸옥 서해안 석양, 야간 불꽃놀이를 파노라마 뷰로 조망하며 지중해풍 시그니처 칵테일과 와인, 타파스 스낵을 즐길 수 있습니다.', description_en = 'Perched on Level 6 of La Festa Phu Quoc, Curio Collection by Hilton, this Amalfi-inspired rooftop bar commands panoramic views of Kiss Bridge and the sea. Sip Mediterranean craft cocktails, champagne, and tapas while watching golden sunsets and the nightly fireworks display.', description_vi = 'Tọa lạc trên tầng 6 cao nhất của La Festa Phu Quoc, Curio Collection by Hilton, quầy bar tầng thượng mang cảm hứng bờ biển Amalfi này sở hữu tầm nhìn toàn cảnh Cầu Hôn và đại dương. Thực khách có thể nhâm nhi cocktail thủ công Địa Trung Hải, rượu vang và tapas trong lúc ngắm hoàng hôn rực rỡ cùng pháo hoa hàng đêm.', description_zh = 'Cielo 屋顶酒吧坐落于富国岛拉菲斯塔希尔顿格芮精选酒店 6 层顶楼，洋溢着迷人的意大利阿马尔菲海岸风情。宾客可在此饱览亲吻桥与西海岸全景，一边品尝地中海特调鸡尾酒、香槟与精致塔帕斯小食，一边欣赏金色落日与每晚盛大的海上烟花秀。', description_ja = 'ラ・フェスタ・フーコック（ヒルトン）最上階の6階に位置する、アマルフィ海岸の情緒あふれるルーフトップバーです。キスブリッジと西海岸の夕陽、夜の花火ショーをパノラマビューで一望しながら、地中海風シグネチャーカクテルやシャンパン、タパスを堪能できます。', description_ru = 'Панорамный руфтоп-бар Cielo на 6-м этаже отеля La Festa Phu Quoc, Curio Collection by Hilton оформлен в духе итальянского побережья Амальфи. Отсюда открывается захватывающий вид на Мост Поцелуев, золотой закат и вечерний фейерверк под авторские средиземноморские коктейли, шампанское и тапас.', description_hi = 'ला फ़ेस्टा फ़ू क्वोक, क्यूरियो कलेक्शन बाय हिल्टन की छठी मंज़िल पर स्थित यह अमाल्फ़ी-प्रेरित रूफ़टॉप बार किस ब्रिज और समुद्र का विहंगम दृश्य प्रस्तुत करता है। सुनहरे सूर्यास्त और रात्रि आतिशबाज़ी का आनंद लेते हुए यहाँ मेडिटेरेनियन क्राफ़्ट कॉकटेल, शैम्पेन और तापास का स्वाद लें।', public_name = '씨엘로 루프탑 바 (Cielo)', price_level = '$$$', tags = ARRAY['bar', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'cielo';
UPDATE public.businesses SET category = 'dining', subcategory = 'western', address = 'Sunset Town, An Thới, Phú Quốc, An Giang, Sunset town, An Giang Province 922000, Vietnam', description_ko = '육즙 가득한 정통 터키식 도네르 케밥 랩·플레이트와 화덕 피데, 할랄 그릴 요리를 빠르게 즐길 수 있는 선셋타운 터키 케밥 전문 레스토랑입니다.', description_en = 'Authentic Turkish kebab restaurant in Sunset Town serving juicy doner kebab wraps, plates, Turkish pide, and halal grilled specialties.', description_vi = 'Nhà hàng kebab Thổ Nhĩ Kỳ tại Thị trấn Hoàng Hôn, phục vụ döner kebab cuốn, phần kebab đĩa, bánh pide và các món nướng halal.', description_zh = '位于日落小镇的土耳其烤肉餐厅，提供多汁的土耳其旋转烤肉卷（Döner Kebab）、烤肉拼盘、土耳其皮德饼（Pide）及清真烧烤特色菜。', description_ja = 'サンセットタウンにあるトルコ料理のケバブ専門店。ジューシーなドネルケバブのラップサンドやプレート料理、トルコ風ピザのピデ、ハラール対応のグリル料理などを提供しています。', description_ru = 'Ресторан турецких кебабов в Сансет-Тауне. Здесь подают сочные роллы с донер-кебабом, мясные тарелки, турецкие лепёшки пиде и халяльные блюда на гриле.', description_hi = 'सनसेट टाउन में स्थित यह तुर्की कबाब रेस्तराँ रसदार डोनर कबाब रैप, कबाब प्लेटर, तुर्की पीदे और हलाल ग्रिल्ड व्यंजन परोसता है।', public_name = '술탄 터키쉬 케밥 선셋타운 (Sultan Turkish Kebab – Sunset Town Phu Quoc)', tags = ARRAY['international', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'sultan-turkish-kebab-sunset-town-phu-quoc';
UPDATE public.businesses SET category = 'beaches', subcategory = 'bar', address = 'Venice, Phú Quốc, An Giang 920000, Vietnam', description_ko = '베니스 해변 중앙에 우뚝 선 대형 목조 돔 브루어리 가스트로펍으로, 심포니 오브 더 씨 해상 불꽃쇼를 코앞에서 직관하는 명소입니다. 매장에서 직접 양조하는 독일식 수제 맥주(Sun KraftBeer) 6종과 바삭한 슈바인스학센, 수제 소시지 플래터를 라이브 밴드·댄스 공연과 함께 즐길 수 있습니다.', description_en = 'Anchoring Sunset Town’s beachfront beneath a grand timber dome, Sun Bavaria GastroPub brews German-style Sun KraftBeer right on site with front-row views of the Symphony of the Sea show. Pair six house craft beers with crispy pork knuckle, artisan sausages, and high-energy live band sets.', description_vi = 'Tọa lạc dưới mái vòm gỗ khổng lồ ngay bãi biển trung tâm, Sun Bavaria GastroPub là nhà hàng bia thủ công sở hữu tầm nhìn trực diện ra show pháo hoa Symphony of the Sea. Thực khách được thưởng thức 6 dòng bia tươi Đức Sun KraftBeer ủ tại chỗ ăn kèm chân giò heo muối chiên giòn, xúc xích Đức và nhạc sống sôi động.', description_zh = 'Sun Bavaria 精酿啤酒餐吧坐落于威尼斯海滩核心区宏伟的木结构穹顶建筑内，是近距离直击《海洋交响曲》海上烟花秀的绝佳据点。店内自酿 6 款德式风味鲜啤（Sun KraftBeer），搭配脆皮德国烤猪肘、手工香肠拼盘及热力十足的现场乐队歌舞演出。', description_ja = 'ヴェニスビーチ中央にそびえる大型木造ドームのブルワリー・ガストロパブで、「シンフォニー・オブ・ザ・シー」海上花火ショーを目の前で鑑賞できる特等席です。店内醸造のドイツ式クラフトビール（Sun KraftBeer）6種とパリパリのシュヴァインスハクセ、自家製ソーセージを生演奏やダンスとともに楽しめます。', description_ru = 'Масштабный пивоваренный гастропаб Sun Bavaria GastroPub под высоким деревянным куполом на пляже Сансет-Тауна открывает вид с первого ряда на водное шоу Symphony of the Sea. Здесь варят шесть сортов немецкого пива Sun KraftBeer, подают хрустящую рульку, баварские колбаски и устраивают живые концерты.', description_hi = 'विशाल लकड़ी के गुंबद के नीचे समुद्र तट पर स्थित सन बवेरिया गैस्ट्रोपब सिम्फनी ऑफ़ द सी शो के फ्रंट-रो नज़ारों के साथ ऑन-साइट जर्मन-शैली की सन क्राफ़्टबीयर तैयार करता है। लाइव बैंड प्रस्तुतियों के बीच छह हाउस क्राफ़्ट बीयर के साथ क्रिस्पी पोर्क नकल और आर्टिसन सॉसेज का आनंद लें।', public_name = '선 바바리아 가스트로펍 (Sun Bavaria GastroPub)', price_level = '$$$$', tags = ARRAY['bar', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'sun-bavaria-gastropub';
UPDATE public.businesses SET category = 'bars', subcategory = 'bar', address = 'VuiFest Bazaar Thị Trấn Hoàng Hôn, Phú Quốc, An Giang 92500, Vietnam', description_ko = '부이페스트(VuiFest) 야시장 해안 산책로에 자리한 오션프론트 캐주얼 비어 & 칵테일 바입니다. 파도 소리가 들리는 야외 테라스에서 바삭한 오징어튀김·스프링롤·꼬치구이와 시원한 생맥주, 트로피컬 칵테일을 즐기며 일몰을 감상하기 좋습니다.', description_en = 'Set right along the VuiFest Bazaar seaside promenade, Giòn Bar offers breezy oceanfront terrace seating for sunset drinks and night market people-watching. Pair cold draft beers and tropical cocktails with crispy calamari, Vietnamese spring rolls, and grilled skewers.', description_vi = 'Nằm ngay lối dạo bộ sát biển của chợ đêm VuiFest Bazaar, Giòn Bar sở hữu khoảng sân thượng lộng gió nghe rõ tiếng sóng vỗ rất hợp để ngắm hoàng hôn. Thực khách có thể nhâm nhi bia tươi mát lạnh, cocktail nhiệt đới ăn kèm mực chiên giòn, chả giò và các món xiên nướng thơm lừng.', description_zh = 'Giòn Bar 紧邻 VuiFest 海滨夜市步道，拥有海风拂面的临海露天露台座位，是傍晚赏日落与感受夜市热闹氛围的好去处。推荐点上一杯冰爽生啤或热带鸡尾酒，搭配酥脆炸鱿鱼、越式春卷与炭烤肉串。', description_ja = 'VuiFestバザール（ナイトマーケット）の海沿いプロムナードに位置する、開放的なオーシャンフロント・ビア＆カクテルバーです。波音が心地よい屋外テラス席で夕陽を眺めながら、冷たい生ビールやトロピカルカクテルとともにイカフライや揚げ春巻き、串焼きを味わえます。', description_ru = 'Демократичный бар Giòn Bar расположен прямо на приморском променаде ночного рынка VuiFest и располагает продуваемой террасой у самой воды. Здесь приятно встретить закат за кружкой холодного разливного пива или тропическим коктейлем с хрустящими кальмарами, спринг-роллами и шашлычками.', description_hi = 'वुईफ़ेस्ट बाज़ार के समुद्री प्रोमेनाड पर स्थित ज़िओन बार सूर्यास्त के समय ड्रिंक्स और नाइट मार्केट की रौनक देखने के लिए हवादार ओशनफ़्रंट टेरेस प्रदान करता है। ठंडी ड्राफ़्ट बीयर और ट्रॉपिकल कॉकटेल के साथ कुरकुरे कैलामारी, वियतनामी स्प्रिंग रोल्स और ग्रिल्ड स्क्यूअर्स का मज़ा लें।', public_name = '지온 바 & 바이츠 키친 (Giòn Bar)', tags = ARRAY['bar', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'gion-bar';
UPDATE public.businesses SET category = 'bars', subcategory = 'bar', address = 'Town Thị trấn Hoàng Hôn, Sunset phường, Phú Quốc, An Giang 92500, Vietnam', description_ko = '센트럴 빌리지 해변 위치, 야간 클럽 라운지 (접근성: 휠체어 이용가능 화장실) • [대표 메뉴/가격] 시그니처 칵테일, 위스키/샴페인 바틀, 물담배(Shisha), 핑거푸드 | 칵테일·음료 200,000~350,000 VND (VIP 바틀 별도).', description_en = 'Teatro Club Phú Quốc is a sunset bar & lounge located in Sunset Town, Phu Quoc.', description_vi = 'Teatro Club Phú Quốc là quán bar và lounge ngắm hoàng hôn nằm tại Thị trấn Hoàng Hôn, Phú Quốc.', description_zh = 'Teatro Club Phú Quốc是位于Central Village海滨的夜间俱乐部酒廊，设有轮椅使用者可用的卫生间。', description_ja = 'Teatro Club Phú Quốcは、Central Villageの海辺にあるナイトクラブラウンジです。車椅子対応のトイレがあります。', description_ru = 'Teatro Club Phú Quốc — ночной клуб-лаундж на побережье Central Village. Есть туалет, доступный для посетителей на инвалидных колясках.', description_hi = 'Teatro Club Phú Quốc Central Village के समुद्र तट पर स्थित एक नाइट क्लब लाउंज है। यहाँ व्हीलचेयर से उपयोग करने योग्य शौचालय उपलब्ध है।', public_name = '테아트로 클럽 푸꾸옥 (Teatro Club Phú Quốc)', price_level = '$$', tags = ARRAY['bar', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'teatro-club-phu-quo-c';
UPDATE public.businesses SET category = 'bars', subcategory = 'dessert_fruit_cafe', address = '38 Đ. Amalfi, Sunset Town, Phú Quốc, An Giang, Vietnam', description_ko = '선셋타운 아말피(38 Amalfi) 거리에 위치한 100% 생사탕수수 착즙 주스(Nước Mía) 및 신선 통코코넛 워터 전문 카페로, 해안 산책 중 갈증을 시원하게 날려주는 로컬 인기 스폿입니다.', description_en = 'Freshly pressed sugarcane juice (Nuoc Mia) and chilled whole coconut water specialty cafe at 38 Amalfi Street, Sunset Town.', description_vi = 'Quán chuyên nước mía ép tươi và nước dừa nguyên trái ướp lạnh tại 38 đường Amalfi, Thị trấn Hoàng Hôn.', description_zh = '位于日落小镇 Amalfi 街38号的饮品店，主打现榨越南甘蔗汁（Nước Mía）和冰镇整颗椰子水。', description_ja = 'サンセットタウンのAmalfi通り38番地にあるドリンク専門店。搾りたてのサトウキビジュース（Nước Mía）と、冷やした丸ごとのココナッツを提供しています。', description_ru = 'Кафе напитков по адресу: улица Amalfi, 38, Сансет-Таун. Специализируется на свежевыжатом соке сахарного тростника (Nước Mía) и охлаждённых целых кокосах с кокосовой водой.', description_hi = 'सनसेट टाउन की Amalfi स्ट्रीट पर नंबर 38 में स्थित यह पेय कैफ़े ताज़ा निकाले गए गन्ने के रस (Nước Mía) और ठंडे साबुत नारियल के पानी में विशेषज्ञता रखता है।', public_name = 'Mía Phú Quốc', tags = ARRAY['dessert_fruit_cafe', 'cafe', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'mia-phu-quoc';
UPDATE public.businesses SET category = 'beaches', subcategory = 'bar', address = 'Sunset Town, FB209, Phú Quốc, An Giang 92500, Vietnam', description_ko = '선셋타운 해안가(FB2-09)에 자리해 야외 자쿠지 풀과 오션프론트 선베드를 갖춘 감각적인 비치 클럽 & 칵테일 바입니다. 노을이 물드는 서해안 수평선과 밤하늘을 수놓는 불꽃놀이를 바라보며 트로피컬 칵테일과 칠아웃 DJ 사운드, 핑거푸드를 여유롭게 즐길 수 있습니다.', description_en = 'Set right on the Sunset Town waterfront (FB2-09), Loop Jacuzzi Bar combines open-air jacuzzi lounges and oceanfront daybeds with chill DJ beats. Sip tropical cocktails, mocktails, and light tapas while soaking in fiery western sunsets and evening fireworks over the bay.', description_vi = 'Nằm ngay mặt biển Thị trấn Hoàng Hôn (căn FB2-09), Loop Jacuzzi Bar gây ấn tượng với hồ sục jacuzzi ngoài trời, ghế nằm sát biển cùng âm nhạc DJ phóng khoáng. Đây là tọa độ tuyệt vời để nhâm nhi cocktail nhiệt đới, đồ ăn nhẹ và chiêm ngưỡng trọn vẹn khoảnh khắc hoàng hôn lẫn pháo hoa đêm.', description_zh = 'Loop Jacuzzi Bar 位于日落小镇海滨一线（FB2-09），是一间融合户外按摩泡池与临海日光躺椅的时尚海滩俱乐部酒吧。宾客可伴随轻松的 DJ 音乐，啜饮热带特调鸡尾酒与无酒精果饮，惬意饱览西海岸落日余晖与夜间海湾烟花。', description_ja = 'サンセットタウンの海岸沿い（FB2-09）に位置する、屋外ジャグジーラウンジと海辺のデイベッドを備えたスタイリッシュなビーチバーです。心地よいDJミュージックが流れる中、トロピカルカクテルや軽食を片手に茜色のサンセットと夜の花火を満喫できます。', description_ru = 'Стильный пляжный лаундж Loop Jacuzzi Bar на первой линии Сансет-Тауна (FB2-09) объединяет открытые джакузи, шезлонги у воды и расслабленные диджей-сеты. Отличная локация для встречи заката и просмотра вечернего фейерверка с тропическими коктейлями и лёгкими закусками.', description_hi = 'सनसेट टाउन वाटरफ़्रंट (FB2-09) पर स्थित लूप जकूज़ी बार ओपन-एयर जकूज़ी लाउंज, ओशनफ़्रंट डे-बेड और मधुर डीजे संगीत का अनूठा संगम है। खाड़ी के ऊपर सुंदर सूर्यास्त और शाम की आतिशबाज़ी देखते हुए यहाँ ट्रॉपिकल कॉकटेल, मॉकटेल और हल्के स्नैक्स का आनंद लें।', public_name = 'Loop Jacuzzi Bar', tags = ARRAY['Bar', 'Rooftop Bar', 'Cocktail Bar', 'bar', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'loop-jacuzzi-bar';
UPDATE public.businesses SET category = 'beaches', subcategory = 'bar', address = 'Sunset Town, Street Level FB03-02 Sorrento 1, Phú Quốc, An Giang 92500, Vietnam', description_ko = '소렌토 1거리 해변 라인(FB03-02)에 자리한 어쿠스틱 무드의 오션뷰 베란다 카페 & 칵테일 라운지입니다. 바닷바람이 통하는 목조 테라스에 앉아 낮에는 베트남 연유 커피와 과일 차를, 저녁에는 선셋 칵테일과 생맥주를 마시며 일몰과 해상 불꽃놀이를 감상하기 좋습니다.', description_en = 'Tucked along the Sorrento 1 coastal walkway (FB03-02), Hiên Nhà Veranda offers a laid-back wooden veranda overlooking Sunset Town’s bay. Drop by in the afternoon for Vietnamese iced coffee and fruit teas, or linger into the evening with sunset cocktails and unobstructed fireworks views.', description_vi = 'Nằm dọc lối dạo biển đường Sorrento 1 (FB03-02), Hiên Nhà Veranda mang nét mộc mạc, bình yên với khoảng hiên gỗ đón gió biển lồng lộng. Quán phục vụ cà phê Việt, trà trái cây tươi vào buổi chiều và chuyển mình thành góc chill cocktail, bia lạnh ngắm hoàng hôn cùng pháo hoa về đêm.', description_zh = 'Hiên Nhà Veranda 坐落于索伦托一街海滨步道旁（FB03-02），拥有木质露台与温润文艺的海边小院氛围。午后适合来此品尝越式冰奶咖与清爽鲜果茶，傍晚则可小酌日落鸡尾酒与冰啤，静赏海湾晚霞与夜间烟花。', description_ja = 'ソレント1通りの海沿い遊歩道（FB03-02）に佇む、木の温もりあふれるベランダカフェ＆カクテルラウンジです。昼下がりはベトナム練乳コーヒーやフルーツティー、夕暮れからはサンセットカクテルやビールを片手に夕陽と海上花火をゆったり眺められます。', description_ru = 'Уютный лаундж-бар и кафе Hiên Nhà Veranda расположен на прибрежной аллее Сорренто-1 (FB03-02) и располагает открытой деревянной верандой у моря. Днём здесь пьют вьетнамский кофе со сгущёнкой и фруктовый чай, а вечером встречают закат и салют с коктейлями.', description_hi = 'सोरेंटो 1 तटीय रास्ते (FB03-02) पर स्थित हिएन न्हा वेरांडा खाड़ी की ओर खुलने वाला एक सुकून भरा लकड़ी का वेरांडा कैफ़े और बार है। दोपहर में वियतनामी आइस्ड कॉफ़ी व फ्रूट टी और शाम को सनसेट कॉकटेल के साथ सूर्यास्त व आतिशबाज़ी का सीधा नज़ारा लें।', public_name = 'Hiên Nhà Veranda Sunset Town Phú Quốc', tags = ARRAY['bar', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'hien-nha-veranda-sunset-town-phu-quoc';
UPDATE public.businesses SET category = 'bars', subcategory = 'dessert_fruit_cafe', address = 'Quảng trường ga, Phu Quoc, An Giang 920000, Vietnam', description_ko = '신선한 열대과일을 아낌없이 갈아 넣은 생망고·아보카도·용과 스무디(Sinh Tố)와 착즙 주스, 밀크티·말차 라떼 및 베트남 로컬 간식(Ăn Vặt)을 한자리에서 즐기는 디저트 카페입니다.', description_en = 'Vibrant tropical dessert cafe in Sunset Town specializing in fresh mango smoothies, cold-pressed fruit juices, boba milk teas, matcha lattes, and Vietnamese street snacks.', description_vi = 'Quán tráng miệng nhiệt đới tại Thị trấn Hoàng Hôn, chuyên sinh tố xoài, nước ép lạnh, trà sữa trân châu, matcha latte và đồ ăn vặt Việt.', description_zh = '位于日落小镇的热带水果甜品咖啡馆，提供新鲜芒果冰沙、冷压果汁、珍珠奶茶、抹茶拿铁及越南街头小吃。', description_ja = 'サンセットタウンにあるトロピカルフルーツのデザートカフェ。フレッシュマンゴースムージー、コールドプレスジュース、タピオカミルクティー、抹茶ラテ、ベトナムの屋台風スナックなどを提供しています。', description_ru = 'Кафе тропических десертов в Сансет-Тауне. В меню — смузи из свежего манго, фруктовые соки холодного отжима, молочный чай с тапиокой, матча-латте и вьетнамские уличные закуски.', description_hi = 'सनसेट टाउन में स्थित यह ट्रॉपिकल डेज़र्ट कैफ़े ताज़े आम की स्मूदी, कोल्ड-प्रेस्ड फलों के जूस, टैपिओका पर्ल वाली मिल्क टी, माचा लाटे और वियतनामी स्ट्रीट स्नैक्स परोसता है।', public_name = 'Mango Mango', tags = ARRAY['dessert_fruit_cafe', 'cafe', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'mango-mango';
UPDATE public.businesses SET category = 'dining', subcategory = 'restaurant', address = '60-62 Đ. Nguyễn Văn Cừ, St Ward 3, Phú Quốc, An Giang 920000, Vietnam', description_ko = '선셋타운 야경 및 일몰·불꽃놀이 감상 라운지/바.', description_en = 'PH Rooftop Bar & Lounge - Sea View Restaurant, An Thoi, Phu Quoc is a restaurant located in Sunset Town, Phu Quoc.', description_vi = 'PH Rooftop Bar & Lounge - Sea View Restaurant, An Thoi, Phu Quoc là nhà hàng nằm tại Thị trấn Hoàng Hôn, Phú Quốc.', description_zh = 'PH Rooftop Bar & Lounge - Sea View Restaurant, An Thoi, Phu Quoc是位于富国岛日落小镇的屋顶餐厅与酒吧，可欣赏日落、夜景和烟花。', description_ja = 'PH Rooftop Bar & Lounge - Sea View Restaurant, An Thoi, Phu Quocは、フーコック島のサンセットタウンにあるルーフトップレストラン＆バーで、夕日や夜景、花火を眺められます。', description_ru = 'PH Rooftop Bar & Lounge - Sea View Restaurant, An Thoi, Phu Quoc — ресторан и бар на крыше в Сансет-Тауне на Фукуоке, откуда можно наблюдать закат, ночные виды и фейерверки.', description_hi = 'PH Rooftop Bar & Lounge - Sea View Restaurant, An Thoi, Phu Quoc फू क्वोक के सनसेट टाउन में स्थित एक रूफटॉप रेस्तराँ और बार है, जहाँ से सूर्यास्त, रात का दृश्य और आतिशबाज़ी देखी जा सकती है।', public_name = 'PH Rooftop Bar & Lounge - Sea View Restaurant, An Thoi, Phu Quoc', tags = ARRAY['restaurant', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'ph-rooftop-bar-lounge-sea-view-restaurant-an-thoi-phu-quoc';
UPDATE public.businesses SET category = 'shopping', subcategory = 'convenience_store', address = '140 Đ. Amalfi, Phú Quốc, An Giang 92500, Vietnam', description_ko = '선셋타운 아말피 거리(140 Amalfi)에 위치한 24시간 운영 편의점으로, 야간 불꽃쇼 관람 후 늦은 시간에도 생수·맥주·컵라면·간식과 여행용 상비 생필품, 유심·결제 편의를 언제든 이용할 수 있습니다.', description_en = 'Open 24 hours at 140 Amalfi Street in central Sunset Town, Tony Mart CN3 stocks cold drinks, local beers, cup noodles, snacks, sun care essentials, and daily travel necessities—ideal for late-night runs after the fireworks show.', description_vi = 'Mở cửa 24/24 tại số 140 đường Amalfi ngay trung tâm Thị trấn Hoàng Hôn, Tony Mart CN3 cung cấp đầy đủ nước suối, bia lạnh, mì ly, đồ ăn vặt, kem chống nắng và nhu yếu phẩm du lịch bất kể đêm muộn sau giờ xem pháo hoa.', description_zh = 'Tony Mart CN3 是位于日落小镇中心阿马尔菲街 140 号的 24 小时便利店，全天候供应冰镇饮品、本地啤酒、杯面零食、防晒洗护及旅行日常用品，看完夜间烟花秀后深夜采购也十分方便。', description_ja = 'サンセットタウン中心部のアマルフィ通り140番地にある24時間営業のコンビニエンスストアです。花火ショー終了後の遅い時間帯でも、ミネラルウォーターやビール、カップ麺、お菓子、日焼け止めや旅行用の日用品をいつでも購入できます。', description_ru = 'Круглосуточный минимаркет Tony Mart CN3 на улице Амальфи, 140, в центре Сансет-Тауна предлагает прохладительные напитки, местное пиво, лапшу быстрого приготовления, снеки, солнцезащитные средства и товары первой необходимости даже поздно ночью после салюта.', description_hi = 'मध्य सनसेट टाउन में 140 अमाल्फ़ी स्ट्रीट पर 24 घंटे खुला टोनी मार्ट CN3 ठंडे पेय, स्थानीय बीयर, कप नूडल्स, स्नैक्स, सन केयर और यात्रा की दैनिक ज़रूरत का सामान रखता है—आतिशबाज़ी शो के बाद देर रात खरीदारी के लिए आदर्श।', public_name = '토니 마트 24시 선셋타운 (TONY MART CN3 - Siêu thị tiện ích 24h)', tags = ARRAY['convenience_store', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'tony-mart-cn3-sieu-thi-tien-ich-24h';
UPDATE public.businesses SET category = 'shopping', subcategory = 'convenience_store', address = 'VuiFest Bazaar Entrance, Amalfi Street, Sunset Town, An Thới, Phú Quốc, Kiên Giang, Vietnam', description_ko = '부이페스트 야시장 입구 옆 아말피 거리에 자리한 대형 정찰제 슈퍼마켓으로, 신선한 열대과일과 주류·생수, 한국 라면·간식부터 푸꾸옥 후추·커피·건어물·땅콩 기념품까지 카드 결제로 쾌적하게 쇼핑할 수 있습니다.', description_en = 'Located on Amalfi Street right beside the VuiFest Bazaar entrance, Vietnam Select is Sunset Town’s flagship fixed-price supermarket accepting credit cards. Shop fresh mangoes, chilled beers, Korean noodles, bottled water, and gift-ready Phu Quoc pepper, coffee, and roasted peanuts.', description_vi = 'Tọa lạc trên đường Amalfi ngay sát cổng chợ đêm VuiFest Bazaar, Vietnam Select là siêu thị quy mô lớn bán đúng giá niêm yết và hỗ trợ thanh toán thẻ tiện lợi. Du khách có thể mua sắm thoải mái trái cây nhiệt đới tươi, bia rượu, mì Hàn Quốc cùng đặc sản hồ tiêu, cà phê, đậu phộng Phú Quốc làm quà.', description_zh = 'Vietnam Select 坐落于阿马尔菲街 VuiFest 海滨夜市入口旁，是日落小镇规模宏大、支持刷卡支付的明码标价超市。店内汇聚新鲜芒果山竹等热带水果、啤酒饮用水、韩国泡面零食，以及富国岛胡椒、咖啡与烤花生等伴手礼。', description_ja = 'VuiFestナイトマーケット入口横のアマルフィ通りに位置する、クレジットカード決済対応の大型定価制スーパーマーケットです。新鮮なマンゴーなどの南国フルーツや酒類・飲料水、韓国ラーメンから、フーコック産胡椒・コーヒー・ピーナッツのお土産まで快適に買い物できます。', description_ru = 'Крупный супермаркет с фиксированными ценами Vietnam Select расположен на улице Амальфи прямо у входа на ночной рынок VuiFest и принимает банковские карты. В широком ассортименте представлены свежие манго, пиво, вода, корейская лапша и подарочные наборы фукуокского перца, кофе и орехов.', description_hi = 'वुईफ़ेस्ट बाज़ार प्रवेश द्वार के ठीक बगल अमाल्फ़ी स्ट्रीट पर स्थित वियतनाम सेलेक्ट सनसेट टाउन का प्रमुख फ़िक्स्ड-प्राइस सुपरमार्केट है जहाँ कार्ड भुगतान स्वीकार्य है। यहाँ ताज़ा आम, ठंडी बीयर, कोरियन नूडल्स, पेयजल और फ़ू क्वोक काली मिर्च व कॉफ़ी उपहार पैक मिलते हैं।', public_name = '베트남 셀렉트 슈퍼마켓 (Vietnam Select)', tags = ARRAY['convenience_store', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'vietnam-select';
UPDATE public.businesses SET category = 'bars', subcategory = 'cafe', address = 'P02 Night Market, VuiFest Bazaar, Sunset Town, Phú Quốc, An Giang 91000, Vietnam', description_ko = '부이페스트 야시장(P02) 해안 산책로에 자리한 수제 그릭요거트 & 비건 너트 밀크티 디저트 전문점입니다. 꾸덕하게 유청을 뺀 수제 그릭요거트에 신선한 열대과일·그래놀라·꿀을 얹은 요거트 볼과 고소한 아몬드·캐슈넛 비건 밀크티를 가볍고 건강한 간식으로 선보입니다.', description_en = 'Located at booth P02 in VuiFest Bazaar Night Market, Queen Of Islands crafts thick, creamy handmade Greek yogurt bowls and dairy-free nut milk teas. Top artisan yogurt parfaits with fresh tropical fruits, crunchy granola, and honey for a refreshing, wholesome night-market treat.', description_vi = 'Tọa lạc tại gian hàng P02 chợ đêm VuiFest Bazaar, Queen Of Islands chuyên phục vụ sữa chua Hy Lạp làm thủ công sánh đặc và trà sữa hạt thuần chay thanh nhẹ. Các phần Greek yogurt kết hợp trái cây nhiệt đới tươi, granola giòn và mật ong là món tráng miệng lành mạnh rất được yêu thích khi dạo chợ đêm.', description_zh = 'Queen Of Islands 位于 VuiFest 海滨夜市 P02 铺位，是一家主打纯手工厚切希腊酸奶与植物坚果奶茶的健康甜品店。浓稠绵密的手作希腊酸奶搭配当季新鲜热带水果、香脆麦片与蜂蜜，以及醇香纯素坚果奶茶，是逛夜市时清爽无负担的甜点选择。', description_ja = 'VuiFestナイトマーケット（P02）に位置する、自家製グリークヨーグルト＆ヴィーガン・ナッツミルクティー専門店です。濃厚でクリーミーな水切りギリシャヨーグルトに新鮮な南国フルーツやグラノーラ、蜂蜜を添えたボウルは、夜市の散策中にぴったりなヘルシースイーツです。', description_ru = 'Десертная лавка Queen Of Islands в павильоне P02 ночного рынка VuiFest готовит густой домашний греческий йогурт и веганский чай с ореховым молоком. Порции нежного йогурта с тропическими фруктами, хрустящей гранолой и мёдом станут лёгким и полезным десертом во время вечерней прогулки.', description_hi = 'वुईफ़ेस्ट बाज़ार नाइट मार्केट के बूथ P02 में स्थित क्वीन ऑफ़ आइलैंड्स गाढ़ा हैंडमेड ग्रीक योगर्ट और डेयरी-मुक्त नट मिल्क टी तैयार करता है। ताज़ा उष्णकटिबंधीय फलों, कुरकुरे ग्रेनोला और शहद से सजे इसके योगर्ट बाउल एक ताज़गी भरा व स्वास्थ्यवर्धक डेज़र्ट हैं।', public_name = 'Queen Of Islands - Greek Yogurt & More Store', tags = ARRAY['Cafe', 'Dessert Cafe', 'Greek Yogurt', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'queen-of-islands-greek-yogurt-more-store';
UPDATE public.businesses SET category = 'shopping', subcategory = 'convenience_store', address = 'Pos 54, Đ.Positano, Phú Quốc, An Giang 960000, Vietnam', description_ko = '포지타노 거리(Pos 54) 숙소 밀집 구역에 자리한 깔끔한 미니 마트로, 시원한 주류·음료와 열대과일, 한국 라면·스낵, 푸꾸옥 후추·땅콩 등 소포장 기념품을 정찰 가격으로 편리하게 구매할 수 있습니다.', description_en = 'Conveniently located along the Positano Street hotel strip (Pos 54), Muoi Mini Mart offers clearly priced chilled beverages, fresh tropical fruits, Korean instant noodles, beach toiletries, and packaged Phu Quoc pepper and peanut snacks.', description_vi = 'Nằm ngay dãy khách sạn sầm uất đường Positano (căn Pos 54), Muoi Mini Mart bày bán gọn gàng với giá niêm yết rõ ràng các loại đồ uống ướp lạnh, trái cây nhiệt đới tươi, mì gói Hàn Quốc, đồ dùng đi biển cùng tiêu và đậu phộng Phú Quốc đóng gói làm quà.', description_zh = 'Muoi Mini Mart 位于波西塔诺街酒店密集区（Pos 54），店内整洁有序且明码标价，方便住客选购冰镇酒水饮料、新鲜热带水果、韩国泡面零食、海滩洗漱用品以及小包装富国岛胡椒与花生伴手礼。', description_ja = 'ポジターノ通りのホテル街（Pos 54）に位置する清潔なミニマートです。明朗な定価表示で、冷たいビールや飲料、南国フルーツ、韓国ラーメン・スナック菓子、フーコック産胡椒やピーナッツなど小分けのお土産を手軽に買い揃えられます。', description_ru = 'Аккуратный минимаркет Muoi Mini Mart расположен в гостиничном квартале на улице Позитано (Pos 54) и работает по фиксированным ценам. Здесь удобно купить охлаждённые напитки, свежие тропические фрукты, корейский рамён, пляжные принадлежности и сувенирный фукуокский перец с арахисом.', description_hi = 'पॉज़िटानो स्ट्रीट की होटल पट्टी (Pos 54) पर सुविधाजनक रूप से स्थित मुओई मिनी मार्ट स्पष्ट कीमतों पर ठंडे पेय, ताज़ा उष्णकटिबंधीय फल, कोरियन इंस्टेंट नूडल्स, बीच टॉयलेटरीज़ और फ़ू क्वोक काली मिर्च व मूंगफली के पैकेट उपलब्ध कराता है।', public_name = 'Muoi Mini Mart - Sunset Town', tags = ARRAY['convenience_store', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'muoi-mini-mart-sunset-town';
UPDATE public.businesses SET category = 'shopping', subcategory = 'convenience_store', address = 'AT137 new, sun grand city, Phú Quốc, An Giang 92500, Vietnam', description_ko = '선 그랜드 시티 뉴 대로(AT137 New)에 위치한 24시간 편의점으로, 심야 시간에도 시원한 생수·맥주·탄산음료와 한국 컵라면·스낵, 아이스크림, 선크림·모기퇴치제 등 여행 필수 생필품을 편리하게 구매할 수 있습니다.', description_en = 'Operating 24 hours at AT137 New Boulevard in Sun Grand City, SSMART 24H serves travelers around the clock with ice-cold water, local beers, Korean cup noodles, ice cream, sunscreen, mosquito repellent, and everyday hotel-stay essentials.', description_vi = 'Hoạt động xuyên suốt 24/24 tại căn AT137 Đại lộ New thuộc khu Sun Grand City, SSMART 24H đáp ứng nhanh nhu cầu mua sắm bất kể ngày đêm. Cửa hàng có sẵn nước khoáng lạnh, bia, mì ly Hàn Quốc, kem, kem chống nắng, xịt chống muỗi và đồ dùng cá nhân thiết yếu.', description_zh = 'SSMART 24H 位于 Sun Grand City 新大道 AT137 号，是一家全天 24 小时营业的便利超市。无论白天还是深夜，旅客都能随时买到冰镇矿泉水、本地啤酒、韩国杯面零食、冰淇淋以及防晒霜、驱蚊液等旅行常备日用品。', description_ja = 'サン・グランド・シティのニュー大通り（AT137）で24時間営業している便利なミニマートです。深夜でも冷たいミネラルウォーターやローカルビール、韓国カップ麺、アイスクリーム、日焼け止めや虫除けスプレーなどの旅行必需品をいつでも調達できます。', description_ru = 'Круглосуточный магазин SSMART 24H на бульваре Нью (AT137) в квартале Sun Grand City выручает путешественников в любое время дня и ночи. В продаже всегда есть холодная вода, пиво, корейская лапша в стаканчиках, мороженое, крем от солнца и репелленты.', description_hi = 'सन ग्रैंड सिटी के AT137 न्यू बुलेवार्ड पर 24 घंटे संचालित SSMART 24H यात्रियों को दिन-रात सेवा देता है। यहाँ ठंडा पानी, स्थानीय बीयर, कोरियन कप नूडल्स, आइसक्रीम, सनस्क्रीन, मच्छर भगाने वाला स्प्रे और रोज़मर्रा की ज़रूरी चीज़ें आसानी से मिलती हैं।', public_name = 'SSMART 24H', tags = ARRAY['convenience_store', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'ssmart-24h';
UPDATE public.businesses SET category = 'shopping', subcategory = 'convenience_store', address = 'Sorrento 3 Street, Sun Premier Village Primavera, Sunset Town, An Thới, Phú Quốc, Vietnam', description_ko = '소렌토 3거리(Sorrento 3) 해안 부티크 호텔 구역에 자리한 여행자 친화 미니 마트로, 대용량 생수와 시원한 맥주·음료, 한국 라면·과자, 열대과일 및 푸꾸옥 땅콩·후추 간식류를 정찰 가격에 알차게 갖추고 있습니다.', description_en = 'Situated along Sorrento 3 Street in Sunset Town’s boutique hotel quarter, THALA MART stocks bottled water jugs, chilled beers and soft drinks, Korean instant noodles, fresh fruit, toiletries, and Phu Quoc roasted peanut souvenirs at clear prices.', description_vi = 'Nằm trên đường Sorrento 3 giữa khu khách sạn boutique ven biển, THALA MART là điểm mua sắm tiện lợi với giá bán rõ ràng. Quầy kệ đầy đủ nước suối bình lớn, bia nước ngọt ướp lạnh, mì gói và bánh kẹo Hàn Quốc, trái cây tươi cùng đậu phộng Phú Quốc.', description_zh = 'THALA MART 坐落于日落小镇索伦托三街精品酒店区，方便周边住客就近补给。店内明码标价供应大桶饮用水、冰镇啤酒汽水、韩国方便面与休闲零食、时令水果、洗漱日用品及富国岛花生胡椒特产。', description_ja = 'ソレント3通りのブティックホテル街に位置する、宿泊客に使い勝手の良いミニマートです。大容量の飲料水や冷えたビール・ソフトドリンク、韓国ラーメンやお菓子、フルーツ、洗面用品、フーコック産ピーナッツ土産を明朗価格で取り揃えています。', description_ru = 'Удобный минимаркет THALA MART на улице Сорренто-3 в окружении бутик-отелей предлагает всё необходимое для отдыха по понятным ценам: большие бутыли воды, холодное пиво, корейскую лапшу, фрукты, средства гигиены и фукуокский жареный арахис.', description_hi = 'सनसेट टाउन के बुटीक होटल क्षेत्र में सोरेंटो 3 स्ट्रीट पर स्थित थाला मार्ट स्पष्ट कीमतों पर पानी की बड़ी बोतलें, ठंडी बीयर व सॉफ्ट ड्रिंक्स, कोरियन नूडल्स, ताज़ा फल, टॉयलेटरीज़ और फ़ू क्वोक मूंगफली स्नैक्स उपलब्ध कराता है।', public_name = 'THALA MART', tags = ARRAY['convenience_store', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'thala-mart';
UPDATE public.businesses SET category = 'shopping', subcategory = 'Souvenirs', address = '72 Amalfi/70 Primavera, Ấp 6, Phú Quốc, An Giang 31078, Vietnam', description_ko = '선셋타운 여행 기념품부터 리조트 비치웨어·수영복, 라탄 가방, 선글라스, 모자, 푸꾸옥 진주 액세서리, 여행용 캐리어와 향수까지 폭넓게 갖춘 원스톱 패션 & 기프트 스토어입니다.', description_en = 'One-stop souvenir and resort fashion store in Sunset Town offering beachwear, swimsuits, handbags, sunglasses, hats, Phu Quoc pearl jewelry, luggage, and gifts.', description_vi = 'Cửa hàng lưu niệm và thời trang biển tại Thị trấn Hoàng Hôn, bán đồ bơi, trang phục biển, túi, kính mát, mũ, trang sức ngọc trai Phú Quốc, vali và quà tặng.', description_zh = '位于日落小镇的纪念品与度假服饰商店，销售沙滩装、泳衣、手提包、太阳镜、帽子、富国岛珍珠首饰、行李箱及各类礼品。', description_ja = 'サンセットタウンにあるお土産とリゾートファッションのショップ。ビーチウェア、水着、バッグ、サングラス、帽子、フーコック島の真珠アクセサリー、スーツケース、ギフト用品などを取り扱っています。', description_ru = 'Магазин сувениров и курортной одежды в Сансет-Тауне. Здесь продаются пляжная одежда, купальники, сумки, солнцезащитные очки, шляпы, украшения с жемчугом Фукуока, чемоданы и подарки.', description_hi = 'सनसेट टाउन में स्थित यह स्मृति-चिह्न और रिज़ॉर्ट फ़ैशन स्टोर बीचवियर, स्विमसूट, हैंडबैग, धूप के चश्मे, टोपियाँ, फू क्वोक के मोतियों के आभूषण, सूटकेस और उपहार बेचता है।', public_name = 'Sunset Souvenir & Fashion Store', tags = ARRAY['convenience_store', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'sunset-souvenir-fashion-store';
UPDATE public.businesses SET category = 'bars', subcategory = 'cafe', address = 'sunset bazaar, Phú Quốc, An Giang 92000, Vietnam', description_ko = '선셋 바자(Sunset Bazaar) 중심 거리에 위치한 상큼한 수제 그릭요거트 & 헬시 브런치 디저트 카페입니다. 망고·용과·블루베리·키위를 듬뿍 올린 수제 그릭요거트 볼과 아보카도 크루아상 토스트, 생레몬을 착즙한 시그니처 레몬에이드와 스무디를 산뜻하게 즐길 수 있습니다.', description_en = 'Set in the lively Sunset Bazaar precinct, Lemon Queen is a bright dessert and light-brunch cafe specializing in fresh fruit Greek yogurt bowls and zesty lemonades. Guests stop in for mango and dragonfruit yogurt parfaits, avocado croissants, and cold-pressed citrus smoothies.', description_vi = 'Nằm trong khu phố Sunset Bazaar nhộn nhịp, Lemon Queen là tiệm cà phê tráng miệng và brunch lành mạnh nổi bật với các thố sữa chua Hy Lạp trái cây tươi cùng nước chanh ép mát lạnh. Thực đơn hấp dẫn gồm yogurt xoài – thanh long – việt quất, bánh sừng bò bơ tươi và sinh tố giải nhiệt.', description_zh = 'Lemon Queen 坐落于热闹的日落集市（Sunset Bazaar）街区，是一间主打鲜果手工希腊酸奶碗与轻食早午餐的清爽甜品咖啡馆。店内提供铺满芒果、火龙果与蓝莓的希腊酸奶杯、牛油果可颂吐司，以及现榨柠檬特调饮品与鲜果冰沙。', description_ja = 'サンセット・バザール地区に位置する、爽やかな自家製グリークヨーグルト＆ヘルシーブランチカフェです。マンゴーやドラゴンフルーツ、ベリーを贅沢に盛り付けたヨーグルトボウルをはじめ、アボカドクロワッサンや搾りたての特製レモネード、スムージーを味わえます。', description_ru = 'Яркое кафе десертов и лёгких бранчей Lemon Queen в квартале Sunset Bazaar славится боулами с домашним греческим йогуртом и освежающими лимонадами. Здесь заказывают парфе с манго и питахайей, круассаны с авокадо и прохладные фруктово-цитрусовые смузи.', description_hi = 'जीवंत सनसेट बाज़ार क्षेत्र में स्थित लेमन क्वीन ताज़ा फलों वाले ग्रीक योगर्ट बाउल और ताज़गी भरे लेमनेड के लिए प्रसिद्ध एक उजला डेज़र्ट व ब्रंच कैफ़े है। मेहमान यहाँ आम और ड्रैगनफ्रूट योगर्ट पारफ़े, एवोकाडो क्रोसां तथा सिट्रस स्मूदी का स्वाद लेने आते हैं।', public_name = 'Lemon Queen (bazaar store)', tags = ARRAY['Cafe', 'Dessert Cafe', 'Greek Yogurt', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'lemon-queen-bazaar-store';
UPDATE public.businesses SET category = 'shopping', subcategory = 'Souvenirs', address = 'S40103, Đường MILAN, Phú Quốc, An Giang, Vietnam', description_ko = '화사한 휴양지 원피스와 비치 모자, 조개껍질 수공예 소품, 마그넷·키링 등 선셋타운의 감성을 담은 다채로운 여행 기념품과 바캉스 패션을 판매하는 기프트숍입니다.', description_en = 'Vibrant souvenir and resort wear shop in Sunset Town featuring tropical dresses, beach hats, shell handicrafts, magnets, and island gifts.', description_vi = 'Cửa hàng quà lưu niệm và trang phục nghỉ dưỡng tại Thị trấn Hoàng Hôn, bán váy nhiệt đới, mũ biển, đồ thủ công vỏ sò, nam châm và quà tặng.', description_zh = '位于日落小镇的纪念品与度假服饰店，提供热带风格连衣裙、沙滩帽、贝壳手工艺品、冰箱贴和海岛主题礼品。', description_ja = 'サンセットタウンにあるお土産とリゾートウェアのショップ。トロピカル柄のワンピース、ビーチハット、貝殻の工芸品、マグネット、島をテーマにしたギフトなどを販売しています。', description_ru = 'Магазин сувениров и курортной одежды в Сансет-Тауне. В ассортименте — платья с тропическими принтами, пляжные шляпы, поделки из ракушек, магниты и подарки с островной тематикой.', description_hi = 'सनसेट टाउन की यह स्मृति-चिह्न और रिज़ॉर्ट कपड़ों की दुकान ट्रॉपिकल डिज़ाइन वाली ड्रेसेज़, बीच हैट, सीपियों से बने हस्तशिल्प, फ़्रिज मैग्नेट और द्वीप-थीम वाले उपहार बेचती है।', public_name = 'SUNSET TOWN STORE', tags = ARRAY['convenience_store', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'sunset-town-store';
UPDATE public.businesses SET category = 'shopping', subcategory = 'convenience_store', address = 'Positano Street (Near Pos 77), Sunset Town, An Thới, Phú Quốc, Kiên Giang, Vietnam', description_ko = '포지타노 거리(Pos 77 인근) 중심 숙소 라인에 위치한 동네 편의점으로, 호텔 복귀 길에 시원한 맥주·음료수와 생수, 한국 컵라면·안주 스낵, 우비·슬리퍼·일회용 세면도구, 소포장 푸꾸옥 특산품을 간편하게 구입하기 좋습니다.', description_en = 'Tucked along Positano Street near Pos 77 in Sunset Town, B&B Mart is a handy neighborhood convenience stop on the walk back to nearby hotels. Pick up cold beers, bottled water, Korean cup ramyeon, rain ponchos, toiletries, and Phu Quoc snack gifts.', description_vi = 'Tọa lạc trên đường Positano (gần căn Pos 77), B&B Mart là cửa hàng tiện lợi quen thuộc ngay lối về của nhiều khách sạn trung tâm. Khách dễ dàng ghé mua bia lạnh, nước suối, mì ly Hàn Quốc, đồ nhắm, áo mưa, đồ vệ sinh cá nhân và quà vặt đặc sản Phú Quốc.', description_zh = 'B&B Mart 位于日落小镇波西塔诺街（近 Pos 77）住宿核心段，是回酒店途中顺路采购的便捷小超市。店内备齐冰啤酒、矿泉水、韩国杯面与下酒零食、雨衣拖鞋、一次性洗漱用品以及小包装富国岛特产。', description_ja = 'ポジターノ通り（Pos 77近く）のホテル街にある便利なコンビニエンスマートです。ホテルへ戻る途中に立ち寄りやすく、冷たいビールや飲料水、韓国カップ麺・おつまみ、レインコートや洗面用具、小分けのフーコック土産を手軽に購入できます。', description_ru = 'Небольшой магазин у дома B&B Mart на улице Позитано (рядом с Pos 77) удобно расположен по пути в окрестные отели Сансет-Тауна. Здесь продаются холодное пиво, питьевая вода, корейский рамён, дождевики, дорожные мелочи и вкусные сувениры Фукуока.', description_hi = 'पॉज़िटानो स्ट्रीट पर Pos 77 के पास स्थित बी एंड बी मार्ट नज़दीकी होटलों में लौटते समय रुकने के लिए एक सुविधाजनक स्टोर है। यहाँ ठंडी बीयर, बोतलबंद पानी, कोरियन कप रामयोन, रेन पोंचो, टॉयलेटरीज़ और फ़ू क्वोक के पैक्ड स्नैक्स मिलते हैं।', public_name = 'B&B Mart', tags = ARRAY['convenience_store', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'b-b-mart';
UPDATE public.businesses SET category = 'shopping', subcategory = 'Local Specialties', address = 'Đường ĐT 975, Khu phố 6, Phú Quốc, An Giang 92513, Vietnam', description_ko = '선셋타운에서 자외선 차단제(선크림·선스프레이), 알로에 수딩젤, 렌즈 세척액, 마스크팩 등 한국·글로벌 정품 스킨케어 화장품과 뷰티 소품, 기념품을 편리하게 구매할 수 있는 코스메틱 전문점입니다.', description_en = 'Authentic cosmetics and beauty store in Sunset Town stocking K-beauty skincare, sunscreens, after-sun aloe gel, contact lens solution, sheet masks, and accessories.', description_vi = 'Cửa hàng mỹ phẩm tại Thị trấn Hoàng Hôn, bán sản phẩm dưỡng da Hàn Quốc, kem chống nắng, gel lô hội sau nắng, dung dịch kính áp tròng, mặt nạ giấy và phụ kiện.', description_zh = '位于日落小镇的化妆品与美容用品店，销售韩系护肤品、防晒霜、晒后芦荟凝胶、隐形眼镜护理液、片状面膜及美容配件。', description_ja = 'サンセットタウンにある化粧品・美容用品店。韓国系スキンケア製品、日焼け止め、日焼け後用のアロエジェル、コンタクトレンズ洗浄・保存液、シートマスク、美容小物などを取り扱っています。', description_ru = 'Магазин косметики и товаров для ухода за собой в Сансет-Тауне. В ассортименте — корейская уходовая косметика, солнцезащитные средства, гель алоэ после загара, раствор для контактных линз, тканевые маски и аксессуары.', description_hi = 'सनसेट टाउन में स्थित यह कॉस्मेटिक्स और ब्यूटी स्टोर कोरियाई स्किनकेयर उत्पाद, सनस्क्रीन, धूप के बाद लगाने वाला एलोवेरा जेल, कॉन्टैक्ट लेंस सॉल्यूशन, शीट मास्क और ब्यूटी एक्सेसरीज़ बेचता है।', public_name = 'HƯỜNG NGUYỄN COSMETICS', tags = ARRAY['convenience_store', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'huong-nguyen-cosmetics';
UPDATE public.businesses SET category = 'shopping', subcategory = 'convenience_store', address = '334 Đ. Nguyễn Văn Cừ, Ấp 6, Phú Quốc, An Giang, Vietnam', description_ko = '안터이·선셋타운 진입 대로인 응우옌반꾸 거리(334 Nguyễn Văn Cừ)에 자리한 실속형 마트로, 생수·주류·음료 박스와 수입·한국 스낵, 신선 과일, 생활용품 및 푸꾸옥 후추·피시소스 특산품을 합리적인 로컬 가격에 판매합니다.', description_en = 'Located at 334 Nguyen Van Cu Road along the main gateway linking An Thoi and Sunset Town, HomeMart offers local-value grocery shopping. Travelers find cases of water, chilled beers, Korean and imported snacks, fresh produce, household goods, and Phu Quoc pepper.', description_vi = 'Nằm tại số 334 đường Nguyễn Văn Cừ trên trục chính nối An Thới và Thị trấn Hoàng Hôn, HomeMart mang đến mức giá tiêu dùng địa phương rất hợp lý. Cửa hàng cung cấp đầy đủ thùng nước suối, bia rượu, bánh kẹo Hàn Quốc và nhập khẩu, trái cây tươi cùng hồ tiêu Phú Quốc.', description_zh = 'HomeMart 坐落于连接安泰镇与日落小镇的主干道阮文渠街 334 号，以实在的本地超市价格著称。适合整箱采购饮用水与冰啤，同时供应韩国及进口零食、新鲜果蔬、家居日用品与富国岛胡椒特产。', description_ja = 'アントイ地区とサンセットタウンを結ぶ幹線・グエンヴァンクー通り334番地にある、ローカル価格が魅力の実利派マートです。飲料水やビールのまとめ買いをはじめ、韓国・輸入スナック、果物、日用雑貨、フーコック産胡椒を手頃に購入できます。', description_ru = 'Практичный продуктовый магазин HomeMart на главной дороге Нгуен Ван Кы, 334, между районом Ан-Тхой и Сансет-Тауном радует местными ценами. В ассортименте — упаковки воды, охлаждённое пиво, корейские и импортные снеки, свежие фрукты, бытовые товары и фукуокский перец.', description_hi = 'अन थोई और सनसेट टाउन को जोड़ने वाली मुख्य सड़क 334 गुयेन वान कू रोड पर स्थित होममार्ट किफ़ायती स्थानीय दामों पर किराना सामान उपलब्ध कराता है। यहाँ पानी की पेटियाँ, ठंडी बीयर, कोरियन व इम्पोर्टेड स्नैक्स, ताज़ा फल और फ़ू क्वोक काली मिर्च मिलती हैं।', public_name = 'HomeMart', tags = ARRAY['convenience_store', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'homemart';
UPDATE public.businesses SET category = 'shopping', subcategory = 'convenience_store', address = '2297+HFF, Khu 2, Phú Quốc, An Giang, Vietnam', description_ko = '남부 안터이 2구역(Khu 2) 중심 생활권에 위치한 깔끔한 로컬 슈퍼마켓으로, 시원한 생수·맥주·유제품과 한국 라면·과자, 열대과일, 비치용품 및 푸꾸옥 특산 땅콩·커피·건과일 간식을 정찰제로 부담 없이 구매할 수 있습니다.', description_en = 'Serving Quarter 2 of An Thoi near Sunset Town and Khem Beach, Cocomart An Thới is a clean neighborhood mini-supermarket with fixed local pricing. Stock up on chilled drinks, dairy, Korean instant noodles, fresh tropical fruit, beach gear, and Phu Quoc coffee and nut snacks.', description_vi = 'Phục vụ khu vực Khu 2 An Thới gần Thị trấn Hoàng Hôn và Bãi Khem, Cocomart An Thới là siêu thị mini sạch sẽ với giá bán niêm yết phải chăng. Khách du lịch có thể ghé mua nước giải khát, sữa, mì gói Hàn Quốc, trái cây tươi, đồ đi biển cùng cà phê và hạt sấy Phú Quốc.', description_zh = 'Cocomart An Thới 位于邻近日落小镇与凯姆海滩的安泰二区生活圈，是一家干净整洁、明码标价的社区超市。店内供应冰镇饮品、乳制品、韩国方便面与饼干、新鲜热带水果、海滩用品以及富国岛咖啡坚果零食。', description_ja = 'サンセットタウンやケムビーチに近いアントイ第2地区にある、定価販売の清潔なローカルミニスーパーです。冷たい飲料や乳製品、韓国インスタント麺、南国フルーツ、ビーチ用品、フーコック産コーヒーやナッツ菓子を気軽に買い出しできます。', description_ru = 'Чистый районный мини-супермаркет Cocomart An Thới во 2-м квартале Ан-Тхой недалеко от Сансет-Тауна и пляжа Кхем предлагает товары по фиксированным ценам. Здесь удобно запастись напитками, молочными продуктами, корейской лапшой, фруктами и местным кофе с орехами.', description_hi = 'सनसेट टाउन और खेम बीच के नज़दीक अन थोई के क्वार्टर 2 में स्थित कोकोमार्ट अन थोई निश्चित स्थानीय कीमतों वाला साफ़-सुथरा मिनी-सुपरमार्केट है। यहाँ ठंडे पेय, डेयरी उत्पाद, कोरियन नूडल्स, ताज़ा फल, बीच गियर और फ़ू क्वोक कॉफ़ी व नट्स आसानी से मिलते हैं।', public_name = 'Cocomart An Thới', tags = ARRAY['convenience_store', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'cocomart-an-thoi';
UPDATE public.businesses SET category = 'shopping', subcategory = 'convenience_store', address = '22P7+FXF, Tổ 4 khu phố 6, Phú Quốc, An Giang, Vietnam', description_ko = '선셋타운·켐비치 연결 구역(안터이 6구역)에 자리한 여행자 편의 마트로, 호텔·풀빌라 입실 전 생수·맥주·와인·안주류와 한국 컵라면, 아기 간식·기저귀, 상비 위생용품 및 푸꾸옥 기념품을 한 번에 장보기 편리합니다.', description_en = 'Positioned in Quarter 6 between Sunset Town and Khem Beach resorts, DUGONG MART is a convenient provisioning stop before checking into hotels or pool villas. Find bottled water, beer, wine, Korean ramyeon, family toiletries, baby supplies, and packaged Phu Quoc gifts.', description_vi = 'Nằm tại khu phố 6 trên tuyến đường nối Thị trấn Hoàng Hôn và các resort Bãi Khem, DUGONG MART rất tiện để mua sắm trọn gói trước khi nhận phòng khách sạn hay biệt thự. Cửa hàng có đầy đủ nước suối, bia rượu, mì Hàn Quốc, đồ ăn nhẹ, bỉm sữa trẻ em và đặc sản quà tặng Phú Quốc.', description_zh = 'DUGONG MART 位于连接日落小镇与凯姆海滩度假村的第 6 街区，非常适合入住酒店或泳池别墅前一站式采购。商品涵盖饮用水、啤酒红酒、韩国拉面与佐酒小食、母婴洗护日用品以及包装精美的富国岛伴手礼。', description_ja = 'サンセットタウンとケムビーチのリゾート群を結ぶ第6地区に位置し、ホテルやプールヴィラへのチェックイン前の買い出しに重宝するマートです。飲料水やビール・ワイン、韓国ラーメン、おつまみ、ベビー用品・日用品、フーコック土産まで一通り揃います。', description_ru = 'Удобный магазин DUGONG MART в 6-м квартале на пути между Сансет-Тауном и курортами пляжа Кхем отлично подходит для закупки перед заселением в отель или на виллу. В наличии питьевая вода, пиво и вино, корейский рамён, детские и гигиенические товары, а также сувениры Фукуока.', description_hi = 'सनसेट टाउन और खेम बीच रिसॉर्ट्स के बीच क्वार्टर 6 में स्थित ड्यूगोंग मार्ट होटल या पूल विला में चेक-इन से पहले खरीदारी के लिए उपयुक्त स्थान है। यहाँ पानी, बीयर, वाइन, कोरियन रामयोन, पारिवारिक टॉयलेटरीज़, बेबी सप्लाई और फ़ू क्वोक उपहार पैक मिलते हैं।', public_name = 'DUGONG MART', tags = ARRAY['convenience_store', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'dugong-mart';
UPDATE public.businesses SET category = 'essentials', subcategory = 'pharmacy', address = 'Căn Amalfi 67, Phú Quốc, An Giang, Vietnam', description_ko = '아말피 67 약국 — 선셋타운 아말피 거리 67번지.', description_en = 'Amalfi 67 Pharmacy — 67 Amalfi, Sunset Town, Phu Quoc.', description_vi = 'Amalfi 67 Nhà thuốc — 67 Amalfi, Thị trấn Hoàng Hôn, Phú Quốc.', description_zh = 'Pharmacy Amalfi 67是位于富国岛日落小镇阿马尔菲街67号的药房。', description_ja = 'Pharmacy Amalfi 67はフーコック島のサンセットタウン・アマルフィ通り67番地にある薬局です。', description_ru = 'Pharmacy Amalfi 67 — аптека, расположенная на улице Амальфи, 67 в Сансет-Тауне на Фукуоке.', description_hi = 'Pharmacy Amalfi 67 फु क्वॉक के सनसेट टाउन में 67 अमाल्फी स्ट्रीट पर स्थित एक फार्मेसी है।', public_name = '아말피 67 약국 (Pharmacy Amalfi 67 sunset town phường an thới đặc khu phú quốc)', tags = ARRAY['clinic', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'pharmacy-amalfi-67-sunset-town-phuong-an-thoi-dac-khu-phu-quoc';
UPDATE public.businesses SET category = 'essentials', subcategory = 'clinic', address = 'Khu Đô thị An Thới, khu phố 6, Phu Quoc, An Giang, Vietnam', description_ko = '선 세레니아 국제병원 (Sun Serenia) — 선셋타운 뉴 안터이.', description_en = 'Sun Serenia International Hospital — New An Thoi, Sunset Town.', description_vi = 'Sun Serenia International Hospital — New An Thới, Thị trấn Hoàng Hôn.', description_zh = 'Bệnh viện Quốc tế Mặt Trời - Sun Serenia Hospital是位于日落小镇新安泰区域的国际医院。', description_ja = 'Bệnh viện Quốc tế Mặt Trời - Sun Serenia Hospitalは、サンセットタウンのニューアントイ地区にある国際病院です。', description_ru = 'Bệnh viện Quốc tế Mặt Trời - Sun Serenia Hospital — международная больница в районе Нью-Антой в Сансет-Тауне.', description_hi = 'Bệnh viện Quốc tế Mặt Trời - Sun Serenia Hospital सनसेट टाउन के न्यू अन थोई क्षेत्र में स्थित एक अंतरराष्ट्रीय अस्पताल है।', public_name = '선 국제병원 푸꾸옥 (Bệnh viện Quốc tế Mặt Trời Phú Quốc)', tags = ARRAY['clinic', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'benh-vien-quoc-te-mat-troi-phu-quoc';
UPDATE public.businesses SET category = 'essentials', subcategory = 'clinic', address = 'Sun Grand City, S259-S354, KĐT, An Thới, Phú Quốc, An Giang, Vietnam', description_ko = 'DNG 국제 종합 클리닉 — 선셋타운 뉴 안터이.', description_en = 'DNG International Polyclinic — New An Thoi, Sunset Town.', description_vi = 'DNG International Polyclinic — New An Thới, Thị trấn Hoàng Hôn.', description_zh = 'Phòng Khám Đa Khoa Quốc Tế DNG是位于日落小镇新安泰区域的国际综合诊所。', description_ja = 'Phòng Khám Đa Khoa Quốc Tế DNGは、サンセットタウンのニューアントイ地区にある国際総合クリニックです。', description_ru = 'Phòng Khám Đa Khoa Quốc Tế DNG — международная многопрофильная клиника в районе Нью-Антой в Сансет-Тауне.', description_hi = 'Phòng Khám Đa Khoa Quốc Tế DNG सनसेट टाउन के न्यू अन थोई क्षेत्र में स्थित एक अंतरराष्ट्रीय पॉलीक्लिनिक है।', public_name = 'DNG 국제 종합 클리닉 안터이 (Phòng Khám Đa Khoa Quốc Tế DNG (Cơ Sở An Thới))', tags = ARRAY['clinic', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'phong-kham-da-khoa-quoc-te-dng-co-so-an-thoi';
