UPDATE public.businesses SET category = 'wellness', subcategory = 'spa', address = 'A58 Sunset Town, Phú Quốc, An Giang 920000, Vietnam', description_ko = '시원한 생통코코넛 웰컴 음료·카페 메뉴와 함께 코코넛 오일 전신 테라피, 핫스톤 마사지, 발 마사지를 한 공간에서 즐길 수 있는 선셋타운의 이색 스파 & 카페입니다.', description_en = 'Unique spa and cafe concept in Sunset Town where guests enjoy fresh whole coconut drinks alongside virgin coconut oil body massages, hot stone therapy, and foot reflexology.', description_vi = 'Spa kết hợp quán cà phê tại Thị trấn Hoàng Hôn; khách có thể uống nước dừa tươi và trải nghiệm massage với dầu dừa nguyên chất, đá nóng, bấm huyệt chân.', description_zh = '位于日落小镇的水疗与咖啡馆复合空间，游客可以享用新鲜整颗椰子饮品，并体验初榨椰子油身体按摩、热石护理和足部反射按摩。', description_ja = 'サンセットタウンにあるスパとカフェを組み合わせた施設。新鮮な丸ごとのココナッツドリンクを楽しめるほか、バージンココナッツオイルを使ったボディマッサージ、ホットストーン、足裏リフレクソロジーなどを利用できます。', description_ru = 'Спа и кафе в одном пространстве в Сансет-Тауне. Гостям предлагают напитки из свежих целых кокосов, массаж тела с нерафинированным кокосовым маслом первого отжима, процедуры с горячими камнями и рефлексологический массаж стоп.', description_hi = 'सनसेट टाउन में स्थित यह स्पा और कैफ़े का संयुक्त स्थान है, जहाँ मेहमान ताज़े साबुत नारियल का पानी पीने के साथ वर्जिन कोकोनट ऑयल बॉडी मसाज, हॉट स्टोन थेरेपी और फ़ुट रिफ़्लेक्सोलॉजी का अनुभव कर सकते हैं।', public_name = '코코넛 스파 & 카페 (Coconut Spa&Cafe)', tags = ARRAY['cafe', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'coconut-spa-cafe';
UPDATE public.businesses SET category = 'wellness', subcategory = 'spa', address = 'Sun Premier Village primavera Project, Shophouse ven, 62 Đường Venice, Phú Quốc, An Giang, Vietnam', description_ko = '선셋타운 베니스 거리(VEN62)에 위치한 모던 프리미엄 스파로, 세련된 블랙 & 우드 톤의 프라이빗 룸에서 아로마 딥티슈 전신 마사지, 핫스톤 테라피, 발 리플렉솔로지를 제공합니다.', description_en = 'Modern premium spa on Venice Street (VEN62) in Sunset Town offering aroma deep-tissue body massage, hot stone therapy, and foot reflexology in sleek private rooms.', description_vi = 'Spa hiện đại trên đường Venice (VEN62), Thị trấn Hoàng Hôn, cung cấp massage toàn thân tinh dầu tác động sâu, trị liệu đá nóng và bấm huyệt chân trong phòng riêng.', description_zh = '位于日落小镇 Venice 街（VEN62）的现代高端水疗馆，设有设计简洁的独立护理室，提供芳香精油深层肌肉按摩、热石护理和足部反射按摩。', description_ja = 'サンセットタウンのVenice通り（VEN62）にあるモダンなスパ。洗練された個室で、アロマオイルを使ったディープティシューボディマッサージ、ホットストーン、足裏リフレクソロジーなどを提供しています。', description_ru = 'Современный спа-салон премиум-класса на улице Venice (VEN62) в Сансет-Тауне. В стильных отдельных кабинетах предлагают глубокий массаж тела с ароматическими маслами, процедуры с горячими камнями и рефлексологический массаж стоп.', description_hi = 'सनसेट टाउन की Venice स्ट्रीट (VEN62) पर स्थित यह आधुनिक प्रीमियम स्पा सुसज्जित निजी कमरों में अरोमा डीप-टिश्यू बॉडी मसाज, हॉट स्टोन थेरेपी और फ़ुट रिफ़्लेक्सोलॉजी उपलब्ध कराता है।', public_name = '블랙스파 푸꾸옥 (Blackspa Phuquoc)', tags = ARRAY['spa', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'blackspa-phuquoc';
UPDATE public.businesses SET category = 'wellness', subcategory = 'spa', address = '72 Amalfi Street (Opposite La Festa), Sunset Town, An Thới, Phú Quốc, Kiên Giang, Vietnam', description_ko = '라 페스타 푸꾸옥(힐튼) 맞은편 아말피 거리 72번지에 자리한 한국인 여행자 친화 프리미엄 데이 스파입니다. 한국어 세밀 문진표를 통해 압 강도와 집중 케어 부위를 정확히 지정할 수 있으며, 아로마 오일 전신 테라피와 핫스톤·알로에 선번 진정 마사지, 쾌적한 샤워 시설을 제공합니다.', description_en = 'Located at 72 Amalfi Street directly opposite La Festa Phu Quoc, SPA THE - L is a traveler-favorite wellness spa offering detailed multilingual consultation forms to customize pressure and focus areas. Signature treatments include aroma oil body massage, hot stone therapy, soothing aloe after-sun care, and private shower rooms.', description_vi = 'Tọa lạc tại số 72 đường Amalfi ngay đối diện khách sạn La Festa Hilton, SPA THE - L được du khách yêu thích nhờ bảng khảo sát chi tiết giúp tùy chỉnh lực ấn và vùng trị liệu mong muốn. Các liệu trình nổi bật gồm massage tinh dầu toàn thân, đá nóng, chăm sóc dịu da cháy nắng bằng nha đam cùng phòng tắm tráng sạch sẽ.', description_zh = 'SPA THE - L 位于阿马尔菲街 72 号，正对拉菲斯塔希尔顿酒店，是一家备受旅客青睐的高品质日间水疗馆。店内提供细致的多语种问诊单以精准定制按压力度与重点部位，主打精油全身按摩、热石理疗及晒后芦荟舒缓护理，并配有整洁淋浴间。', description_ja = 'ラ・フェスタ（ヒルトン）向かいのアマルフィ通り72番地に位置する、細やかな多言語カウンセリングシートが好評のデイスパです。好みの力加減や重点部位を細かく指定でき、アロマオイル全身マッサージやホットストーン、日焼け後のアロエ鎮静ケア、清潔なシャワー設備を提供しています。', description_ru = 'Дневной спа-салон SPA THE - L расположен на улице Амальфи, 72, прямо напротив отеля La Festa Hilton и предлагает подробные анкеты для точного выбора силы нажатия и зон массажа. В меню — аромамассаж всего тела, стоун-терапия, успокаивающий уход с алоэ после солнца и удобные душевые.', description_hi = 'ला फ़ेस्टा फ़ू क्वोक के ठीक सामने 72 अमाल्फ़ी स्ट्रीट पर स्थित स्पा द - एल एक लोकप्रिय वेलनेस स्पा है, जहाँ दबाव और विशेष हिस्सों के चयन हेतु विस्तृत परामर्श फ़ॉर्म दिए जाते हैं। यहाँ अरोमा ऑयल मसाज, हॉट स्टोन थेरेपी, धूप के बाद एलोवेरा सूदिंग केयर और शॉवर रूम उपलब्ध हैं।', public_name = '스파 더 엘 (SPA THE - L)', tags = ARRAY['spa', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'spa-the-l';
UPDATE public.businesses SET category = 'hotels', subcategory = 'hotel', address = 'Terza Zone, Amalfi Coast Road, Sunset Town, An Thới, Phú Quốc, Kiên Giang, Vietnam', description_ko = '아말피 해안 마을을 모티브로 조성된 선셋타운의 랜드마크 5성급 럭셔리 리조트입니다. 키스 브릿지와 서해안 일몰을 마주하는 인피니티 풀, 프라이빗 비치, 에포레아 스파를 비롯해 더 머천트·마레·세타·핀카·씨엘로 루프탑 바 등 다채로운 파인 다이닝을 갖추고 있습니다.', description_en = 'Inspired by Italy’s sun-drenched Amalfi Coast, La Festa Phu Quoc, Curio Collection by Hilton is Sunset Town’s flagship 5-star beachfront resort overlooking Kiss Bridge. Guests enjoy a sunset infinity pool, Eforea Spa, and standout dining venues including The Merchant, Mare, Seta, Finca, iL Salone, and Cielo rooftop bar.', description_vi = 'Lấy cảm hứng từ bờ biển Amalfi nước Ý, La Festa Phu Quoc, Curio Collection by Hilton là khu nghỉ dưỡng 5 sao biểu tượng tại Thị trấn Hoàng Hôn với tầm nhìn thẳng ra Cầu Hôn. Khu nghỉ dưỡng quy tụ hồ bơi vô cực ngắm hoàng hôn, Eforea Spa cùng chuỗi ẩm thực đẳng cấp gồm The Merchant, Mare, Seta, Finca, iL Salone và Cielo.', description_zh = '富国岛拉菲斯塔希尔顿格芮精选酒店汲取意大利阿马尔菲海岸灵感，是日落小镇正对亲吻桥的地标性五星级海滨奢华度假村。酒店配备落日无边泳池、Eforea 水疗中心，并汇聚 The Merchant、Mare、Seta、Finca、iL Salone 及 Cielo 屋顶酒吧等多元餐饮空间。', description_ja = 'イタリア・アマルフィ海岸の街並みに着想を得た、サンセットタウンを代表するヒルトン系列の5つ星ラグジュアリーリゾートです。キスブリッジを望むインフィニティプールやエフォリア・スパに加え、Mare、Seta、Finca、ルーフトップバーCieloなど多彩なダイニングを擁しています。', description_ru = 'Флагманский пятизвёздочный курорт La Festa Phu Quoc, Curio Collection by Hilton вдохновлён итальянским побережьем Амальфи и выходит прямо на Мост Поцелуев. К услугам гостей панорамный бассейн на закат, спа-центр Eforea и коллекция ресторанов и баров — The Merchant, Mare, Seta, Finca, iL Salone и Cielo.', description_hi = 'इटली के अमाल्फ़ी तट से प्रेरित ला फ़ेस्टा फ़ू क्वोक, क्यूरियो कलेक्शन बाय हिल्टन किस ब्रिज के सामने सनसेट टाउन का प्रमुख 5-स्टार लग्ज़री रिसॉर्ट है। यहाँ सनसेट इन्फिनिटी पूल, एफ़ोरिया स्पा और द मर्चेंट, मारे, सेता, फ़िन्का व सिएलो रूफ़टॉप बार जैसे विशिष्ट रेस्तरां मौजूद हैं।', public_name = '라 페스타 푸꾸옥, 큐리오 컬렉션 바이 힐튼 (La Festa Phu Quoc, Curio Collection by Hilton)', tags = ARRAY['hotel', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'sunset-place-7';
UPDATE public.businesses SET category = 'wellness', subcategory = 'spa', address = '58 Đường Venice, Phú Quốc, An Giang, Vietnam', description_ko = '선셋타운 베니스 거리(58 Venice)에 자리한 친절한 스파 & 네일 살롱으로, 여행 피로를 녹여주는 아로마·핫스톤 전신 마사지와 발 마사지, 꼼꼼한 젤 네일·페디큐어 케어로 호평받고 있습니다.', description_en = 'Welcoming spa and nail salon at 58 Venice Street, Sunset Town, praised for its relaxing aroma and hot stone massages, foot reflexology, and detailed gel manicure and pedicure care.', description_vi = 'Spa và tiệm nail tại 58 đường Venice, Thị trấn Hoàng Hôn, cung cấp massage tinh dầu, đá nóng, bấm huyệt chân, làm móng gel và chăm sóc móng chân.', description_zh = '位于日落小镇 Venice 街58号的水疗与美甲店，提供芳香精油按摩、热石按摩、足部反射按摩，以及细致的凝胶美甲和足部美甲护理。', description_ja = 'サンセットタウンのVenice通り58番地にあるスパ＆ネイルサロン。アロママッサージ、ホットストーンマッサージ、足裏リフレクソロジーに加え、丁寧なジェルネイルやペディキュアを提供しています。', description_ru = 'Спа и маникюрный салон по адресу: улица Venice, 58, Сансет-Таун. Здесь предлагают расслабляющий аромамассаж, массаж горячими камнями, рефлексологический массаж стоп, а также гелевый маникюр и педикюр.', description_hi = 'सनसेट टाउन की Venice स्ट्रीट पर नंबर 58 में स्थित यह स्पा और नेल सैलून आरामदायक अरोमा मसाज, हॉट स्टोन मसाज, फ़ुट रिफ़्लेक्सोलॉजी तथा बारीकी से की जाने वाली जेल मैनीक्योर और पेडीक्योर सेवाएँ प्रदान करता है।', public_name = 'Chip’s Spa & Nail - 58 Venice (Sunset Town Phu Quoc)', tags = ARRAY['spa', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'chip-s-spa-nail-58-venice-sunset-town-phu-quoc';
UPDATE public.businesses SET category = 'wellness', subcategory = 'spa', address = 'Căn Pos, 39 Đ.Positano, Khu Sunset Town, Phú Quốc, An Giang 92500, Vietnam', description_ko = '선셋타운 중심가의 넓고 쾌적한 시설을 갖춘 킹 스파(King Spa)로, 숙련된 테라피스트의 전통 타이 스트레칭·아로마 오일 전신 마사지와 핫스톤, 허벌 두피 샴푸 코스를 합리적인 가격에 제공합니다.', description_en = 'Spacious wellness spa in central Sunset Town offering skilled Thai stretching, aroma oil full-body massage, hot stone therapy, and Vietnamese herbal head spa treatments.', description_vi = 'Spa rộng rãi ở trung tâm Thị trấn Hoàng Hôn, phục vụ kéo giãn kiểu Thái, massage toàn thân tinh dầu, đá nóng và gội đầu dưỡng sinh thảo mộc Việt.', description_zh = '位于日落小镇中心的宽敞养生水疗馆，提供泰式拉伸按摩、芳香精油全身按摩、热石护理和越南草本头部水疗护理。', description_ja = 'サンセットタウン中心部にある広々としたウェルネススパ。タイ式ストレッチマッサージ、アロマオイルを使った全身マッサージ、ホットストーン、ベトナム式ハーブヘッドスパなどを提供しています。', description_ru = 'Просторный оздоровительный спа-салон в центре Сансет-Тауна. Здесь предлагают тайский массаж с растяжкой, массаж всего тела с ароматическими маслами, процедуры с горячими камнями и вьетнамский травяной уход за кожей головы.', description_hi = 'सनसेट टाउन के मध्य में स्थित यह विशाल वेलनेस स्पा थाई स्ट्रेचिंग मसाज, अरोमा ऑयल फ़ुल-बॉडी मसाज, हॉट स्टोन थेरेपी और वियतनामी हर्बल हेड स्पा सेवाएँ प्रदान करता है।', public_name = '킹 스파 & 마사지 (KING Spa & Massage Sunset Town Phú Quốc)', tags = ARRAY['spa', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'king-spa-massage-sunset-town-phu-quoc-spa-phu-quoc';
UPDATE public.businesses SET category = 'wellness', subcategory = 'spa', address = '81 Venice, Sunset Town, KP6, Phú Quốc, An Giang 91400, Vietnam', description_ko = '은은한 플로럴 아로마 향기와 아늑한 베드룸이 돋보이는 선셋타운 부티크 스파로, 천연 에센셜 오일 전신 테라피와 선번 진정 알로에 케어, 발 지압 마사지를 세심하게 진행합니다.', description_en = 'Botanical boutique spa in Sunset Town specializing in natural essential oil body therapy, soothing aloe sunburn care, and restorative foot massage.', description_vi = 'Spa boutique chủ đề thảo mộc tại Thị trấn Hoàng Hôn, chuyên trị liệu cơ thể bằng tinh dầu thiên nhiên, chăm sóc da sau nắng bằng lô hội và massage chân.', description_zh = '位于日落小镇的植物主题精品水疗馆，主打天然精油身体护理、晒后芦荟舒缓护理和放松足部按摩。', description_ja = 'サンセットタウンにある植物をテーマにしたブティックスパ。天然エッセンシャルオイルを使ったボディケア、日焼け後の肌を落ち着かせるアロエケア、足の疲れを和らげるマッサージなどを提供しています。', description_ru = 'Небольшой спа-салон с растительной тематикой в Сансет-Тауне. Специализируется на уходе за телом с натуральными эфирными маслами, успокаивающих процедурах с алоэ после загара и расслабляющем массаже стоп.', description_hi = 'सनसेट टाउन में स्थित यह वनस्पति-थीम वाला बुटीक स्पा प्राकृतिक एसेंशियल ऑयल बॉडी थेरेपी, धूप से प्रभावित त्वचा के लिए एलोवेरा सूदिंग केयर और आरामदायक फ़ुट मसाज में विशेषज्ञता रखता है।', public_name = 'SUNSET BLOOM SPA', tags = ARRAY['spa', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'sunset-bloom-spa';
UPDATE public.businesses SET category = 'wellness', subcategory = 'spa', address = 'A44-A46 Đ. Amalfi, Sunset Town, Phú Quốc, An Giang 92500, Vietnam', description_ko = '일본식 오모테나시(세심한 환대) 감성과 베트남 전통 테라피를 결합한 스파로, 깔끔한 시설에서 정교한 전신 지압·아로마 마사지와 다리 부기를 빼주는 집중 발 마사지를 받을 수 있습니다.', description_en = 'Japanese-inspired wellness spa in Sunset Town combining attentive hospitality with skilled full-body aroma massage, acupressure, and targeted foot reflexology.', description_vi = 'Spa phong cách Nhật tại Thị trấn Hoàng Hôn, cung cấp massage toàn thân tinh dầu, bấm huyệt và massage phản xạ vùng chân.', description_zh = '位于日落小镇的日式风格养生水疗馆，注重细致服务，提供芳香精油全身按摩、穴位按压按摩和针对性的足部反射按摩。', description_ja = 'サンセットタウンにある日本風のウェルネススパ。丁寧な接客を大切にし、アロマオイルを使った全身マッサージ、指圧、足裏のリフレクソロジーなどを提供しています。', description_ru = 'Оздоровительный спа-салон в японском стиле в Сансет-Тауне, уделяющий внимание обслуживанию гостей. Здесь предлагают аромамассаж всего тела, точечный массаж и рефлексологический массаж стоп.', description_hi = 'सनसेट टाउन में स्थित यह जापानी शैली का वेलनेस स्पा ध्यानपूर्वक सेवा के साथ फ़ुल-बॉडी अरोमा मसाज, एक्यूप्रेशर और विशेष फ़ुट रिफ़्लेक्सोलॉजी प्रदान करता है।', public_name = '사쿠라쿄 스파 푸꾸옥 (Sakurakyo Spa Phu Quoc)', tags = ARRAY['spa', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'sakurakyo-spa-phu-quoc-massage-body-massage-foot';
UPDATE public.businesses SET category = 'wellness', subcategory = 'spa', address = '30 Amalfi, Sunset Town, Phú Quốc, An Giang 92513, Vietnam', description_ko = '선셋타운 중심부에 위치한 평점 4.9점의 인기 데이 스파 & 네일숍으로, 천연 아로마 전신 테라피, 따뜻한 핫스톤 마사지, 두피 피로를 풀어주는 베트남식 허벌 샴푸 및 네일 케어로 유명합니다.', description_en = 'Top-rated 4.9-star day spa and nail lounge in Sunset Town renowned for its aroma full-body therapy, hot stone massage, Vietnamese herbal hair wash, and gel nail care.', description_vi = 'Spa và tiệm nail tại Thị trấn Hoàng Hôn được giới thiệu có đánh giá 4.9 sao, cung cấp massage tinh dầu toàn thân, đá nóng, gội đầu thảo mộc và làm móng gel.', description_zh = '位于日落小镇的日间水疗与美甲店，评分为4.9星，提供芳香精油全身按摩、热石按摩、越南草本洗头护理和凝胶美甲服务。', description_ja = 'サンセットタウンにある評価4.9のデイスパ＆ネイルサロン。アロマオイルを使った全身マッサージ、ホットストーンマッサージ、ベトナム式ハーブシャンプー、ジェルネイルなどを提供しています。', description_ru = 'Дневной спа-салон и нейл-студия в Сансет-Тауне с рейтингом 4,9 звезды. Здесь предлагают аромамассаж всего тела, массаж горячими камнями, вьетнамское травяное мытьё головы и гелевый маникюр.', description_hi = 'सनसेट टाउन में स्थित यह 4.9-स्टार रेटिंग वाला डे स्पा और नेल लाउंज अरोमा फ़ुल-बॉडी मसाज, हॉट स्टोन मसाज, वियतनामी हर्बल हेयर वॉश और जेल नेल केयर प्रदान करता है।', public_name = '오아시스 스파 (OASIS Spa Massage & Nail (Sunset Town Phu Quoc))', tags = ARRAY['spa', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'oasis-spa-massage-nail-sunset-town-phu-quoc';
UPDATE public.businesses SET category = 'wellness', subcategory = 'spa', address = '21 Đ.Positano, Sunset Town, Phú Quốc, An Giang 92500, Vietnam', description_ko = '세련된 인테리어와 숙련된 테라피스트를 갖춘 선셋타운 베라 스파(Vera Spa)로, 아로마·핫스톤 전신 마사지와 정교한 커스텀 젤 네일·페디큐어 아트, 편리한 그랩/픽업 지원으로 인기가 높습니다.', description_en = 'Stylish spa and nail salon in Sunset Town offering aroma and hot stone body massages, custom gel nail art, pedicures, and convenient local transport support.', description_vi = 'Spa và tiệm nail tại Thị trấn Hoàng Hôn, cung cấp massage tinh dầu, đá nóng, vẽ móng gel, chăm sóc móng chân và hỗ trợ di chuyển tại địa phương.', description_zh = '位于日落小镇的水疗与美甲店，提供芳香精油及热石身体按摩、定制凝胶美甲、足部美甲护理，并可协助安排当地交通。', description_ja = 'サンセットタウンにあるスパ＆ネイルサロン。アロマオイルやホットストーンを使ったボディマッサージ、オーダーメイドのジェルネイルアート、ペディキュアを提供し、近隣の移動手段についてもサポートしています。', description_ru = 'Стильный спа-салон и нейл-студия в Сансет-Тауне. Здесь предлагают аромамассаж и массаж горячими камнями, индивидуальный дизайн гелевых ногтей, педикюр, а также помощь с организацией местного транспорта.', description_hi = 'सनसेट टाउन में स्थित यह स्टाइलिश स्पा और नेल सैलून अरोमा तथा हॉट स्टोन बॉडी मसाज, पसंद के अनुसार जेल नेल आर्ट, पेडीक्योर और स्थानीय परिवहन की व्यवस्था में सहायता प्रदान करता है।', public_name = 'Véra Spa & Nail (Phú Quốc Sunset Town)', tags = ARRAY['spa', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'vera-spa-nail-phu-quoc-sunset-town';
UPDATE public.businesses SET category = 'wellness', subcategory = 'spa', address = '38 Amalfi, SunSet Town, Phú Quốc, An Giang, Vietnam', description_ko = '선셋타운 도보 관광과 야시장 산책 후 뭉친 종아리·발 피로를 집중적으로 풀어주는 발 리플렉솔로지 및 아로마 전신·어깨 마사지 전문 힐링 스파입니다.', description_en = 'Relaxing massage parlor in Sunset Town specializing in revitalizing foot reflexology and neck-and-shoulder aroma massage after evening walking tours.', description_vi = 'Cơ sở massage tại Thị trấn Hoàng Hôn, chuyên bấm huyệt chân và massage cổ vai gáy với tinh dầu sau khi khách đi dạo buổi tối.', description_zh = '位于日落小镇的按摩店，主打足部反射按摩及颈肩芳香精油按摩，适合傍晚步行游览后放松休息。', description_ja = 'サンセットタウンにあるリラクゼーションマッサージ店。足裏リフレクソロジーや首・肩のアロママッサージを中心に提供しており、夕方の散策後の休憩にも利用できます。', description_ru = 'Массажный салон в Сансет-Тауне, специализирующийся на рефлексологическом массаже стоп и аромамассаже шеи и плеч. Подходит для отдыха после вечерних прогулок.', description_hi = 'सनसेट टाउन में स्थित यह मसाज सेंटर विशेष रूप से फ़ुट रिफ़्लेक्सोलॉजी और गर्दन व कंधों की अरोमा मसाज प्रदान करता है। शाम की पैदल सैर के बाद आराम करने के लिए यह एक विकल्प है।', public_name = 'LUMI SPA - MASSAGE 2 (Foot Massage Sunset Town)', tags = ARRAY['spa', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'lumi-spa-massage-2-foot-massage-sunset-town';
UPDATE public.businesses SET category = 'wellness', subcategory = 'spa', address = '58 Địa Trung Hải, Phú Quốc, An Giang, Vietnam', description_ko = '따뜻한 캔들 조명과 아로마 향기 속에서 깊은 휴식을 취할 수 있는 감성 스파로, 따뜻한 캔들 오일·핫스톤 전신 마사지와 림프 순환 케어로 커플 여행객에게 특히 인기가 많습니다.', description_en = 'Intimate candlelit spa in Sunset Town popular among couples for its warm aromatherapy oil massage, hot stone treatments, and lymphatic relaxation care.', description_vi = 'Spa ánh nến tại Thị trấn Hoàng Hôn dành cho các cặp đôi, cung cấp massage tinh dầu ấm, đá nóng và chăm sóc thư giãn hệ bạch huyết.', description_zh = '位于日落小镇的烛光氛围水疗馆，适合情侣体验，提供温热芳香精油按摩、热石护理和以放松为目的的淋巴按摩。', description_ja = 'サンセットタウンにあるキャンドルの灯りが特徴の落ち着いたスパ。カップルにも利用されており、温かいアロマオイルを使ったマッサージ、ホットストーン、リンパの流れを意識したリラクゼーションケアなどを提供しています。', description_ru = 'Небольшой спа-салон с атмосферой свечного освещения в Сансет-Тауне, популярный среди пар. Здесь предлагают массаж тёплыми ароматическими маслами, процедуры с горячими камнями и расслабляющий лимфодренажный массаж.', description_hi = 'सनसेट टाउन में स्थित यह मोमबत्ती की रोशनी वाला शांत स्पा जोड़ों के बीच लोकप्रिय है। यहाँ गर्म अरोमाथेरेपी ऑयल मसाज, हॉट स्टोन ट्रीटमेंट और आराम के लिए लिंफ़ैटिक मसाज केयर प्रदान की जाती है।', public_name = 'Candle Spa', tags = ARRAY['spa', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'candle-spa';
UPDATE public.businesses SET category = 'wellness', subcategory = 'spa', address = '56 Venice, Sunset Town, P, Phú Quốc, An Giang 91000, Vietnam', description_ko = '선셋타운 베니스 거리(56 Venice)에 위치한 한즈 선셋 스파 2호점으로, 쾌적한 다인실·커플룸에서 전신 아로마 테라피, 타이 마사지, 발 각질 케어 및 네일 서비스를 제공합니다.', description_en = 'Second branch of Hanz Sunset Spa at 56 Venice Street, featuring clean couple and group rooms for aroma body therapy, Thai massage, foot care, and nail services.', description_vi = 'Chi nhánh thứ hai Hanz Sunset Spa tại 56 đường Venice, có phòng cho cặp đôi và nhóm, phục vụ massage tinh dầu, massage Thái, chăm sóc chân và làm nail.', description_zh = 'Hanz Sunset Spa 位于日落小镇 Venice 街56号的第二家分店，设有整洁的双人及团体护理室，提供芳香精油身体按摩、泰式按摩、足部护理和美甲服务。', description_ja = 'サンセットタウンのVenice通り56番地にあるHanz Sunset Spaの2号店。清潔なカップル向け・グループ向けの施術室を備え、アロマボディマッサージ、タイ式マッサージ、フットケア、ネイルサービスなどを提供しています。', description_ru = 'Второй филиал Hanz Sunset Spa по адресу: улица Venice, 56, Сансет-Таун. Здесь есть чистые кабинеты для пар и групп, а среди услуг — аромамассаж тела, тайский массаж, уход за стопами и ногтевые процедуры.', description_hi = 'सनसेट टाउन की Venice स्ट्रीट पर नंबर 56 में स्थित यह Hanz Sunset Spa की दूसरी शाखा है। यहाँ जोड़ों और समूहों के लिए साफ़-सुथरे कमरे हैं तथा अरोमा बॉडी मसाज, थाई मसाज, फ़ुट केयर और नेल सेवाएँ उपलब्ध हैं।', public_name = 'HANZ SUNSET SPA 2 - 56 VENICE (Sunset Town)', tags = ARRAY['spa', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'hanz-sunset-spa-2-56-venice-sunset-town';
UPDATE public.businesses SET category = 'wellness', subcategory = 'spa', address = '43 Amalfi, Sunset Town, Phú Quốc, An Giang, Vietnam', description_ko = '야시장과 불꽃쇼 관람 후 늦은 저녁에도 방문하기 좋은 루나 스파 & 네일(Luna Spa & Nail)로, 피로 회복 아로마 전신·발 마사지와 트렌디한 젤 네일·페디큐어를 한곳에서 즐길 수 있습니다.', description_en = 'Evening-friendly spa and nail studio in Sunset Town ideal for post-fireworks aroma body and foot massages alongside trendy gel manicure and pedicure art.', description_vi = 'Spa và tiệm nail tại Thị trấn Hoàng Hôn phục vụ buổi tối, có massage toàn thân, massage chân tinh dầu và làm móng gel sau giờ xem pháo hoa.', description_zh = '位于日落小镇、适合晚间到访的水疗与美甲工作室，提供芳香精油全身及足部按摩，以及时尚凝胶手部和足部美甲，适合观看烟花后放松。', description_ja = 'サンセットタウンにある夜の利用にも便利なスパ＆ネイルスタジオ。花火鑑賞後のリラックスにも利用でき、アロマボディマッサージやフットマッサージ、トレンドを取り入れたジェルネイルやペディキュアアートを提供しています。', description_ru = 'Спа и нейл-студия в Сансет-Тауне, удобная для вечернего посещения. После просмотра фейерверков здесь можно заказать аромамассаж тела и стоп, а также современный гелевый маникюр и педикюр с дизайном.', description_hi = 'सनसेट टाउन में स्थित यह स्पा और नेल स्टूडियो शाम के समय भी सुविधाजनक है। आतिशबाज़ी देखने के बाद यहाँ अरोमा बॉडी और फ़ुट मसाज के साथ आधुनिक जेल मैनीक्योर और पेडीक्योर नेल आर्ट का आनंद लिया जा सकता है।', public_name = 'Luna Spa & Nail Phú Quốc (Sunset Town)', tags = ARRAY['spa', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'luna-spa-nail-phu-quoc-sunset-town';
UPDATE public.businesses SET category = 'wellness', subcategory = 'spa', address = '04, Venice, Sunset Town, Phú Quốc, An Giang 91000, Vietnam', description_ko = '체계적인 마사지 교육과 깔끔한 위생 관리를 자랑하는 한즈 선셋 스파 본점으로, 강도 선택이 가능한 딥티슈·아로마 전신 코스와 핫스톤, 선번 알로에 진정 마사지를 선보입니다.', description_en = 'Flagship Hanz Sunset Spa in Sunset Town offering customizable deep-tissue and aroma full-body massages, hot stone therapy, and after-sun aloe soothing treatments.', description_vi = 'Chi nhánh chính của Hanz Sunset Spa tại Thị trấn Hoàng Hôn, cung cấp massage toàn thân tác động sâu hoặc tinh dầu theo yêu cầu, đá nóng và chăm sóc da sau nắng bằng lô hội.', description_zh = '位于日落小镇的 Hanz Sunset Spa 主店，提供可根据个人需求调整的深层肌肉按摩、芳香精油全身按摩、热石护理及晒后芦荟舒缓护理。', description_ja = 'サンセットタウンにあるHanz Sunset Spaの本店。好みに合わせて調整できるディープティシューマッサージやアロマオイル全身マッサージ、ホットストーン、日焼け後のアロエを使った肌のケアなどを提供しています。', description_ru = 'Главный салон Hanz Sunset Spa в Сансет-Тауне. Здесь предлагают глубокий массаж мышц и аромамассаж всего тела с возможностью индивидуальной настройки, процедуры с горячими камнями и успокаивающий уход с алоэ после загара.', description_hi = 'सनसेट टाउन में स्थित यह Hanz Sunset Spa की मुख्य शाखा है। यहाँ व्यक्तिगत पसंद के अनुसार डीप-टिश्यू और अरोमा फ़ुल-बॉडी मसाज, हॉट स्टोन थेरेपी तथा धूप के बाद एलोवेरा से त्वचा को आराम देने वाली देखभाल उपलब्ध है।', public_name = 'Hanz Sunset Spa - Phu Quoc Massage', tags = ARRAY['spa', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'hanz-sunset-spa-phu-quoc-massage';
UPDATE public.businesses SET category = 'wellness', subcategory = 'spa', address = 'Sunset town , Địa Trung Hải, A103 Amafi, Phú Quốc, An Giang 92513, Vietnam', description_ko = '선셋타운 아말피 해안 거리(A103 Amalfi)에 자리해 높은 여행자 평점을 기록 중인 부티크 웰니스 스파입니다. 한낮 야외 관광 후 열기를 식혀주는 페퍼민트 쿨링 아로마 마사지와 선번 애프터케어, 따뜻한 현무암 핫스톤 테라피를 정숙한 프라이빗 베드룸에서 제공합니다.', description_en = 'Located along the coastal stretch at A103 Amalfi Street, SOLANA Spa is a top-rated Sunset Town wellness retreat known for attentive therapists and serene treatment rooms. Signature rituals include peppermint cooling aroma massage, soothing after-sun skin recovery, and warm basalt hot stone therapy.', description_vi = 'Tọa lạc tại căn A103 đường Amalfi ven biển, SOLANA Spa là điểm chăm sóc sức khỏe được du khách đánh giá rất cao nhờ không gian trị liệu yên tĩnh và kỹ thuật viên tận tâm. Các liệu trình đặc trưng gồm massage tinh dầu bạc hà làm mát cơ thể, phục hồi da cháy nắng và trị liệu đá nóng bazan.', description_zh = 'SOLANA Spa 坐落于日落小镇阿马尔菲海滨街（A103），凭借专业细致的理疗师与静谧私密的护理空间收获极高口碑。招牌项目涵盖薄荷清凉芳香精油按摩、晒后肌肤舒缓修护以及温热玄武岩热石理疗。', description_ja = 'サンセットタウンのアマルフィ海岸通り（A103）に佇む、旅行者から高評価を得ているブティック・ウェルネススパです。日中の観光後のほてりを鎮めるペパーミント・クーリングアロママッサージや日焼け後ケア、玄武岩ホットストーンセラピーを静かな個室空間で堪能できます。', description_ru = 'Высоко оценённый путешественниками спа-салон SOLANA Spa расположен на прибрежной улице Амальфи (A103) в Сансет-Тауне и славится тихими кабинетами и чуткими мастерами. Фирменные процедуры включают охлаждающий аромамассаж с перечной мятой, восстановление кожи после солнца и массаж горячими базальтовыми камнями.', description_hi = 'A103 अमाल्फ़ी स्ट्रीट की तटीय पट्टी पर स्थित सोलाना स्पा अपने शांत ट्रीटमेंट रूम और कुशल थेरेपिस्ट के लिए सनसेट टाउन में उच्च रेटिंग प्राप्त वेलनेस केंद्र है। इसके प्रमुख उपचारों में पिपरमिंट कूलिंग अरोमा मसाज, धूप के बाद त्वचा की देखभाल और गर्म बेसाल्ट हॉट स्टोन थेरेपी शामिल हैं।', public_name = '솔라나 스파 선셋타운 (SOLANA Spa Sunset Town Phú Quốc)', tags = ARRAY['spa', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'solana-spa-sunset-town-phu-quoc';
UPDATE public.businesses SET category = 'wellness', subcategory = 'spa', address = 'Ven02 Sunset Town, Phú Quốc, An Giang 92513, Vietnam', description_ko = '선셋타운 해안 전망대 인근에 자리한 킹 스파 선셋뷰 지점으로, 일몰 감상 전후 시원한 에어컨 룸에서 발 마사지, 아로마 전신 테라피, 두피 마사지를 받으며 재충전하기 좋습니다.', description_en = 'Sunset-view branch of King Spa in Sunset Town, offering refreshing foot reflexology, full-body aroma therapy, and head massages right by the coastal promenade.', description_vi = 'Chi nhánh King Spa nhìn ra hoàng hôn tại Thị trấn Hoàng Hôn, phục vụ bấm huyệt chân, massage toàn thân tinh dầu và massage đầu bên đường dạo ven biển.', description_zh = '位于日落小镇海滨步道旁的 King Spa 日落景观分店，提供足部反射按摩、芳香精油全身护理和头部按摩。', description_ja = 'サンセットタウンの海沿いの遊歩道に面したKing Spaのサンセットビュー店。足裏リフレクソロジー、アロマオイルを使った全身マッサージ、ヘッドマッサージなどを提供しています。', description_ru = 'Филиал King Spa с видом на закат рядом с прибрежной прогулочной зоной Сансет-Тауна. Здесь предлагают рефлексологический массаж стоп, аромамассаж всего тела и массаж головы.', description_hi = 'सनसेट टाउन के समुद्र किनारे बने पैदल मार्ग के पास स्थित यह King Spa की सनसेट-व्यू शाखा है। यहाँ फ़ुट रिफ़्लेक्सोलॉजी, फ़ुल-बॉडी अरोमा थेरेपी और हेड मसाज उपलब्ध हैं।', public_name = 'King Spa & Massage Sunset View', tags = ARRAY['spa', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'king-spa-massage-sunset-view';
UPDATE public.businesses SET category = 'wellness', subcategory = 'spa', address = 'Căn 09 Positano Sunset Tower, Địa Trung Hải, Phú Quốc, An Giang 92500, Vietnam', description_ko = '정겨운 환대와 꼼꼼한 손길로 높은 평점(4.9점)을 받는 선셋타운 스파로, 합리적인 가격대의 베트남 전통 전신 지압·아로마 오일 마사지와 개운한 허벌 샴푸 코스를 운영합니다.', description_en = 'Highly rated 4.9-star boutique spa in Sunset Town known for warm hospitality, thorough Vietnamese acupressure and aroma oil massages, and herbal hair wash courses.', description_vi = 'Spa boutique tại Thị trấn Hoàng Hôn được giới thiệu có đánh giá 4.9 sao, cung cấp bấm huyệt Việt, massage tinh dầu và liệu trình gội đầu thảo mộc.', description_zh = '位于日落小镇的精品水疗馆，评分为4.9星，以亲切服务为特色，提供细致的越南传统穴位按摩、芳香精油按摩和草本洗头护理。', description_ja = 'サンセットタウンにある評価4.9のブティックスパ。温かい接客が特徴で、ベトナム式の丁寧な指圧マッサージ、アロマオイルマッサージ、ハーブを使ったヘアウォッシュコースなどを提供しています。', description_ru = 'Небольшой спа-салон в Сансет-Тауне с рейтингом 4,9 звезды, известный гостеприимным обслуживанием. Здесь предлагают тщательный вьетнамский точечный массаж, массаж с ароматическими маслами и курсы травяного мытья головы.', description_hi = 'सनसेट टाउन में स्थित यह 4.9-स्टार रेटिंग वाला बुटीक स्पा अपने गर्मजोशी भरे आतिथ्य के लिए जाना जाता है। यहाँ विस्तार से की जाने वाली वियतनामी एक्यूप्रेशर मसाज, अरोमा ऑयल मसाज और हर्बल हेयर वॉश कोर्स उपलब्ध हैं।', public_name = '미스 띠엔 스파 & 홈스테이 (Miss Tiên Spa & Homestay Phú Quốc Sunset Town)', tags = ARRAY['spa', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'miss-tien-spa-homestay-phu-quoc-sunset-town';
UPDATE public.businesses SET category = 'wellness', subcategory = 'spa', address = 'Sun Grand City New, S3.22 đường SETA-S3, Phú Quốc, An Giang 92513, Vietnam', description_ko = '아로마 전신·발 마사지와 함께 스마트폰·여행 피로를 덜어주는 온열 아이 케어, 웰컴 허브티와 다과 서비스를 세심하게 챙겨주는 선셋타운 중심가 스파입니다.', description_en = 'Attentive day spa in central Sunset Town offering aroma body and foot massages complemented by warm eye-care masks and complimentary herbal tea.', description_vi = 'Spa tại trung tâm Thị trấn Hoàng Hôn, phục vụ massage toàn thân và chân với tinh dầu, mặt nạ mắt ấm và trà thảo mộc miễn phí.', description_zh = '位于日落小镇中心的日间水疗馆，提供芳香精油身体按摩和足部按摩，并配有温热眼部护理眼罩及免费草本茶。', description_ja = 'サンセットタウン中心部にあるデイスパ。アロマオイルを使ったボディマッサージやフットマッサージに加え、温かいアイケアマスクや無料のハーブティーも用意されています。', description_ru = 'Дневной спа-салон в центре Сансет-Тауна с внимательным обслуживанием. Здесь предлагают аромамассаж тела и стоп, тёплые маски для области глаз и бесплатный травяной чай.', description_hi = 'सनसेट टाउन के मध्य में स्थित यह डे स्पा अरोमा बॉडी और फ़ुट मसाज के साथ गर्म आई-केयर मास्क और मुफ़्त हर्बल चाय प्रदान करता है।', public_name = 'Sunset Spa Phú Quốc', tags = ARRAY['spa', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'sunset-spa-phu-quoc';
UPDATE public.businesses SET category = 'wellness', subcategory = 'spa', address = 'M103, Đường MILAN, Sunset Town, Phú Quốc, An Giang, Vietnam', description_ko = '400건 이상의 구글 리뷰(평점 4.9)가 검증하는 선셋타운 대표 마사지 & 헤드스파 전문점으로, 목·어깨·등 집중 딥티슈 마사지와 풍성한 거품의 베트남 전통 두피·모발 허벌 샴푸(Hair Wash) 코스가 특히 유명합니다.', description_en = 'Highly acclaimed Sunset Town spa (4.9 stars, 400+ reviews) famous for its deep-tissue body and foot massages and signature Vietnamese herbal hair wash & head spa.', description_vi = 'Spa tại Thị trấn Hoàng Hôn được giới thiệu có đánh giá 4.9 sao với hơn 400 lượt nhận xét, chuyên massage toàn thân tác động sâu, massage chân và gội đầu dưỡng sinh thảo mộc.', description_zh = '位于日落小镇的水疗馆，评分为4.9星，拥有400多条评价，主打深层肌肉全身按摩、足部按摩，以及特色越南草本洗头和头部水疗护理。', description_ja = 'サンセットタウンにあるスパ。評価は4.9で、口コミは400件以上。ディープティシューボディマッサージ、フットマッサージ、ベトナム式のハーブシャンプーとヘッドスパを中心に提供しています。', description_ru = 'Спа-салон в Сансет-Тауне с рейтингом 4,9 звезды и более чем 400 отзывами. Специализируется на глубоком массаже тела и стоп, а также фирменном вьетнамском травяном мытье головы и спа-уходе за кожей головы.', description_hi = 'सनसेट टाउन में स्थित इस स्पा की रेटिंग 4.9 स्टार है और इसे 400 से अधिक समीक्षाएँ मिली हैं। यह डीप-टिश्यू बॉडी और फ़ुट मसाज तथा विशेष वियतनामी हर्बल हेयर वॉश और हेड स्पा सेवाओं के लिए जाना जाता है।', public_name = 'Em Spa Sunset Town - Hair Wash - Massage Body & Foot', tags = ARRAY['spa', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'em-spa-sunset-town-hair-wash-massage-body-foot';
UPDATE public.businesses SET category = 'activities', subcategory = 'attraction', address = '22H3+CXC, Phú Quốc, An Giang, Vietnam', description_ko = '매일 오후 일몰 무렵(17:00~17:30경) 키스 브릿지 앞바다에서 펼쳐지는 역동적인 익스트림 수상 스포츠 퍼포먼스 쇼입니다. 세계 정상급 선수들의 플라이보드 공중 회전과 제트스키 워터 아크로바틱이 석양을 배경으로 연출되며, 해안 산책로에서도 관람할 수 있고 다리 위 직관 시에는 키스 브릿지 입장권이 필요합니다.', description_en = 'Performed daily around sunset (17:00–17:30) in the bay beside Kiss Bridge, Awaken Sea is a high-adrenaline flyboard and jet-ski stunt spectacle. Watch championship riders carve synchronized wakes and aerial flips from the coastal promenade, or view up close from Kiss Bridge with bridge admission.', description_vi = 'Diễn ra hàng ngày vào khung giờ hoàng hôn (khoảng 17:00–17:30) trên mặt biển ngay cạnh Cầu Hôn, Awaken Sea là màn trình diễn thể thao mạo hiểm trên nước đầy phấn khích. Khán giả có thể chiêm ngưỡng những cú nhào lộn flyboard và mô tô nước điêu luyện từ đường dạo biển hoặc mua vé lên Cầu Hôn để xem cận cảnh.', description_zh = '《唤醒大海》（Awaken Sea）是每日傍晚日落时分（约 17:00–17:30）在亲吻桥海域上演的水上极限运动特技秀。世界级选手伴随夕阳余晖展现水上飞板空翻与摩托艇编队花式特技，游客可在海滨步道驻足观赏，若登桥近距离观看则需购买亲吻桥门票。', description_ja = '毎日夕暮れ時（17:00〜17:30頃）にキスブリッジ前の海上で繰り広げられる、大迫力のエクストリーム水上スポーツショーです。夕陽を背にフライボードの空中回転やジェットスキーのアクロバットが披露され、海沿いの遊歩道から鑑賞できるほか、橋の上からの観覧にはキスブリッジ入場券が必要です。', description_ru = 'Динамичное водное экстрим-шоу Awaken Sea проходит ежедневно на закате (около 17:00–17:30) в акватории у Моста Поцелуев. Чемпионы мира по флайборду и гидроциклам выполняют синхронные виражи и сальто над водой; смотреть шоу можно с набережной или с самого моста по входному билету.', description_hi = 'प्रतिदिन सूर्यास्त के समय (लगभग 17:00–17:30) किस ब्रिज के पास समुद्र में आयोजित अवेकन सी एक रोमांचक फ़्लाईबोर्ड और जेट-स्की स्टंट शो है। तटीय प्रोमेनाड से खिलाड़ियों के हवाई करतब देखे जा सकते हैं, जबकि पुल के ऊपर से देखने के लिए किस ब्रिज प्रवेश टिकट आवश्यक है।', public_name = '어웨이큰 씨 쇼 (Awaken Sea)', tags = ARRAY['attraction', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'awaken-sea';
UPDATE public.businesses SET category = 'activities', subcategory = 'attraction', address = '22J4+3RF, Phú Quốc, An Giang, Vietnam', description_ko = '이탈리아 베네치아의 산마르코 종탑에서 영감을 받아 세워진 높이 75m의 붉은 벽돌 시계탑으로, 선셋타운 센트럴 빌리지의 상징적인 랜드마크입니다. 야외 광장은 24시간 상시 개방되어 낮에는 지중해풍 건축미를 배경으로 기념사진을 남기고, 저녁에는 조명과 노을이 어우러진 전경을 감상할 수 있습니다.', description_en = 'Rising 75 meters above Central Village, the red-brick Clock Tower (Tháp Đồng Hồ) is Sunset Town’s architectural centerpiece inspired by Venice’s St. Mark’s Campanile. Its surrounding open-air plaza is accessible 24 hours a day for daytime Mediterranean photo walks and illuminated sunset views.', description_vi = 'Vươn cao 75m giữa phân khu Central Village, Tháp Đồng Hồ gạch đỏ lấy cảm hứng từ tháp chuông St. Mark tại Venice là biểu tượng kiến trúc nổi bật nhất của Thị trấn Hoàng Hôn. Quảng trường ngoài trời dưới chân tháp mở cửa tự do 24/24 để du khách chụp ảnh phong cách Địa Trung Hải và ngắm cảnh biển chiều.', description_zh = '高达 75 米的红砖钟楼（Tháp Đồng Hồ）汲取意大利威尼斯圣马可钟楼的设计灵感，是日落小镇中央村落最具标志性的建筑地标。钟楼周边的露天广场全天 24 小时免费开放，白天适合拍摄地中海风情大片，傍晚则可欣赏夕阳与灯光交相辉映的海湾盛景。', description_ja = 'イタリア・ヴェネツィアのサン・マルコ鐘楼をモチーフに建てられた高さ75mの赤レンガ造りの時計塔で、サンセットタウン中心部の象徴的なランドマークです。周囲の屋外広場は24時間開放されており、日中の記念撮影から夕暮れ時のライトアップ散策まで自由に楽しめます。', description_ru = 'Семидесятипятиметровая Часовая башня из красного кирпича (Tháp Đồng Hồ), вдохновлённая кампанилой собора Святого Марка в Венеции, служит главной архитектурной доминантой Сансет-Тауна. Открытая площадь вокруг башни доступна круглосуточно для фотопрогулок и любования вечерней подсветкой.', description_hi = 'सेंट्रल विलेज में 75 मीटर ऊँचा लाल ईंटों वाला क्लॉक टॉवर (थाप दोंग हो) वेनिस के सेंट मार्क्स कैम्पानिल से प्रेरित सनसेट टाउन का प्रमुख स्थापत्य स्मारक है। इसके चारों ओर खुला प्लाज़ा दिन-रात खुला रहता है, जहाँ दिन में फ़ोटोग्राफ़ी और शाम को रोशनी से जगमगाते सूर्यास्त का आनंद मिलता है।', public_name = '선셋타운 시계탑 (Tháp Đồng Hồ)', tags = ARRAY['attraction', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'thap-dong-ho';
UPDATE public.businesses SET category = 'activities', subcategory = 'attraction', address = '22G5+V5C, Phú Quốc, An Giang, Vietnam', description_ko = '포지타노 해안 절벽 위에 고대 로마 도시 폼페이의 석조 기둥과 아치 유적을 정교하게 재현한 야외 포토존 명소입니다. 24시간 개방되는 해안 전망대로, 석조 열주 사이로 푸른 바다와 혼똔섬 해상 케이블카 캐빈이 지나가는 이국적인 프레임을 사진에 담을 수 있습니다.', description_en = 'Perched along the Positano coastal bluff, the Ancient Pompeii Columns recreate weathered Roman stone pillars and terracotta ruins against the turquoise sea. Open 24 hours along the public walkway, it frames iconic photographs of Hon Thom cable cars gliding across the horizon.', description_vi = 'Nằm bên bờ vực biển khu Positano, cụm Cột Đá Cổ Pompeii tái hiện sống động những hàng cột đá và cổng vòm La Mã cổ đại nhuốm màu thời gian trước biển xanh. Điểm check-in ngoài trời mở cửa 24/24 này đặc biệt nổi tiếng với góc chụp xuyên qua hàng cột bắt trọn tuyến cáp treo Hòn Thơm trên nền trời.', description_zh = '古庞贝石柱遗址（Ancient Pompeii）矗立于波西塔诺海滨悬崖之上，逼真复刻了古罗马庞贝城的斑驳石柱与拱门遗迹。该海景打卡点全天 24 小时开放，透过石柱取景可将蔚蓝大海与空中缓缓驶过的香岛跨海缆车同框定格。', description_ja = 'ポジターノ地区の海辺の崖上に、古代ローマ都市ポンペイの石柱やアーチ遺跡を精巧に再現した屋外フォトスポットです。24時間開放されており、石柱越しに青い海と空を行き交うホントム島ケーブルカーを収めた異国情緒あふれる一枚を撮影できます。', description_ru = 'Античные колонны Помпеи на прибрежном утёсе улицы Позитано живописно воссоздают каменные портики и арки древнеримского города на фоне бирюзового моря. Смотровая площадка открыта круглосуточно и славится эффектными ракурсами с проплывающими в небе кабинками канатной дороги.', description_hi = 'पॉज़िटानो तटीय चट्टान पर बने प्राचीन पोम्पेई स्तंभ नीले समुद्र की पृष्ठभूमि में रोमन पत्थर के खंभों और मेहराबों की भव्य प्रतिकृति प्रस्तुत करते हैं। 24 घंटे खुले इस फ़ोटो स्पॉट से समुद्र के ऊपर गुज़रती होन थोम केबल कार की बेहद आकर्षक तस्वीरें ली जा सकती हैं।', public_name = '고대 폼페이 유적 기둥 (Cột Đá Cổ Pompeii - Ancient Pompeii)', tags = ARRAY['attraction', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'cot-da-co-pompeii-ancient-pompeii';
UPDATE public.businesses SET category = 'activities', subcategory = 'attraction', address = '22H3+7G4, Phú Quốc, An Giang, Vietnam', description_ko = '이탈리아 건축가 마르코 카사몬티가 설계한 선셋타운의 대표 해상 보도교로, 바다 위로 뻗은 두 다리 끝단이 약 30cm 간격을 두고 마주 보도록 조형되어 있습니다. 매일 07:00~23:00 운영하며 황금빛 태양이 두 다리 사이 수평선으로 내려앉는 일몰 시간대(16:00~19:00)가 하이라이트이고, 일부 쇼·케이블카 콤보권에는 입장 혜택이 포함됩니다.', description_en = 'Designed by Italian architect Marco Casamonti, Kiss Bridge (Cầu Hôn) is Sunset Town’s iconic overwater walkway whose two cantilevered spans meet just 30 centimeters apart above the sea. Open daily from 07:00 to 23:00, it peaks at golden hour when the setting sun aligns between the bridge tips.', description_vi = 'Được thiết kế bởi kiến trúc sư người Ý Marco Casamonti, Cầu Hôn là kiệt tác cầu đi bộ trên biển biểu tượng của Thị trấn Hoàng Hôn với hai nhánh cầu vươn ra đại dương cách nhau đúng 30cm. Mở cửa từ 07:00 đến 23:00 hàng ngày, khoảnh khắc mặt trời hoàng hôn buông xuống ngay giữa hai mũi cầu luôn làm say đắm mọi du khách.', description_zh = '亲吻桥（Kiss Bridge / Cầu Hôn）由意大利建筑大师马可·卡萨蒙蒂设计，两座延伸入海的桥身在海面上相距仅约 30 厘米遥遥相对，是日落小镇的浪漫灵魂地标。每日 07:00 至 23:00 开放，傍晚 16:00–19:00 夕阳恰好落入两桥间隙的时刻最为震撼，部分演艺或缆车套票亦包含登桥礼遇。', description_ja = 'イタリア人建築家マルコ・カサモンティが設計したサンセットタウン象徴の海上歩道橋で、海に張り出した2本の橋の先端が約30cmの隙間を残して向かい合う独創的な造りです。毎日07:00〜23:00に開放され、夕陽が橋の間へと沈むサンセット時間帯が最大の見どころとなっています。', description_ru = 'Знаменитый пешеходный Мост Поцелуев (Kiss Bridge) по проекту итальянского архитектора Марко Казамонти состоит из двух консольных половин, замирающих в 30 сантиметрах друг от друга над морем. Мост открыт ежедневно с 07:00 до 23:00 и особенно впечатляет на закате, когда солнце садится ровно между его пролётами.', description_hi = 'इतालवी वास्तुकार मार्को कासामोंटी द्वारा डिज़ाइन किया गया किस ब्रिज सनसेट टाउन का प्रतिष्ठित समुद्री पैदल पुल है, जिसके दो सिरे समुद्र के ऊपर मात्र 30 सेंटीमीटर की दूरी पर आमने-सामने मिलते हैं। प्रतिदिन 07:00 से 23:00 बजे तक खुला यह पुल सूर्यास्त के समय अद्भुत दृश्य प्रस्तुत करता है।', public_name = '키스 브릿지 (Kiss Bridge)', price_level = '$', tags = ARRAY['attraction', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'kiss-bridge';
UPDATE public.businesses SET category = 'activities', subcategory = 'attraction', address = '22J5+23, Phú Quốc, An Giang, Vietnam', description_ko = '언덕 위 밀란 거리와 해안가 아말피 거리를 지그재그 화단 계단으로 잇는 선셋타운의 대표적인 보행 산책길이자 포토 스팟입니다. 샌프란시스코 롬바드 스트리트에서 모티브를 얻은 꽃길 계단 위에서 다채로운 색감의 지중해풍 건물들과 푸른 바다를 한눈에 내려다볼 수 있습니다.', description_en = 'Winding down the hillside between Milan Street and coastal Amalfi Street, Dragon Stairs (Thang Rồng) is a flower-lined serpentine staircase inspired by San Francisco’s Lombard Street. Open 24 hours, its terraced landings offer postcard views over pastel facades and the sea.', description_vi = 'Uốn lượn mềm mại nối liền phố đồi Milan xuống trục biển Amalfi, Thang Rồng là lối bậc thang ngập tràn hoa cỏ lấy cảm hứng từ đường hoa Lombard nổi tiếng tại San Francisco. Mở cửa tự do cả ngày đêm, từng chiếu nghỉ tại đây đều mở ra góc chụp toàn cảnh mái nhà đa sắc và đại dương xanh ngắt.', description_zh = '龙梯（Thang Rồng）是连接山坡米兰街与海滨阿马尔菲街的蜿蜒花坛阶梯步道，设计灵感源自旧金山著名的九曲花街。步道全天 24 小时开放，站在层层鲜花簇拥的台阶高处，可俯瞰五彩斑斓的地中海建筑群与蔚蓝海面。', description_ja = '高台のミラン通りと海沿いのアマルフィ通りをジグザグの花壇階段で結ぶ、サンフランシスコのロンバード・ストリートに着想を得た人気フォトスポットです。24時間通行でき、色とりどりの草花に彩られた階段の上からカラフルな街並みと海を一望できます。', description_ru = 'Живописная Драконья лестница (Thang Rồng) зигзагом спускается среди цветочных клумб от улицы Милан к прибрежной улице Амальфи, напоминая знаменитую Ломбард-стрит в Сан-Франциско. Лестница открыта круглосуточно и дарит открыточные виды на цветные фасады и море.', description_hi = 'पहाड़ी मिलान स्ट्रीट और तटीय अमाल्फ़ी स्ट्रीट को जोड़ने वाली ड्रैगन स्टेयर्स (थांग रोंग) सैन फ्रांसिस्को की लोम्बार्ड स्ट्रीट से प्रेरित फूलों से सजी घुमावदार सीढ़ियाँ हैं। 24 घंटे खुली इन सीढ़ियों से रंगीन इमारतों और समुद्र का बेहद सुंदर दृश्य दिखाई देता है।', public_name = '드래곤 계단 (Thang Rồng)', tags = ARRAY['attraction', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'thang-rong';
UPDATE public.businesses SET category = 'activities', subcategory = 'attraction', address = '22P3+78G, Ấp 7, Phú Quốc, An Giang, Vietnam', description_ko = '매일 오후 4시부터 자정까지 약 400m 해안 산책로를 따라 열리는 베트남 최초의 오션프론트 크리에이티브 야시장입니다. 50여 개 로컬 길거리 음식·해산물·수공예 부스와 함께 주방 기구 타악 퍼포먼스 로앙소앙 쇼, 거리 마술 등 활기찬 야간 거리 공연을 무료 입장으로 즐길 수 있습니다.', description_en = 'Stretching 400 meters along the Sunset Town seafront daily from 16:00 to midnight, VuiFest Bazaar is Vietnam’s first creative oceanfront night market. Browse over 50 street-food, seafood, craft, and souvenir stalls alongside lively Loảng Xoảng street theater and waterfront views.', description_vi = 'Hoạt động hàng ngày từ 16:00 đến 24:00 dọc 400m bờ biển Thị trấn Hoàng Hôn, Vui-Fest Bazaar là chợ đêm bên biển sáng tạo đầu tiên tại Việt Nam. Hơn 50 gian hàng ẩm thực đường phố, hải sản, thủ công mỹ nghệ kết hợp cùng các suất diễn đường phố Loảng Xoảng sôi động tạo nên không khí lễ hội ngập tràn.', description_zh = 'VuiFest 海滨夜市每日 16:00 至 24:00 沿日落小镇约 400 米长的海岸步道热闹开市，是越南首座临海创意主题夜市。现场汇聚 50 余家地道街头美食、现烤海鲜与手工艺品摊位，并穿插《Loảng Xoảng》趣味打击乐街头秀等精彩免费演出。', description_ja = '毎日16時から深夜24時まで、約400mの海岸遊歩道沿いに開かれるベトナム初のオーシャンフロント・クリエイティブナイトマーケットです。50以上の屋台グルメやシーフード、雑貨ブースが並び、「ロアンソアン・ショー」などの愉快なストリートパフォーマンスも楽しめます。', description_ru = 'Первый во Вьетнаме креативный приморский ночной рынок VuiFest Bazaar ежедневно с 16:00 до полуночи растягивается на 400 метров вдоль набережной Сансет-Тауна. Гостей ждут более 50 павильонов с уличной едой, морепродуктами и сувенирами, а также уличные представления шоу Loảng Xoảng.', description_hi = 'प्रतिदिन शाम 4 बजे से मध्यरात्रि तक सनसेट टाउन के 400 मीटर लंबे समुद्र तट पर लगने वाला वुईफ़ेस्ट बाज़ार वियतनाम का पहला ओशनफ़्रंट क्रिएटिव नाइट मार्केट है। यहाँ 50 से अधिक स्ट्रीट-फ़ूड, सीफ़ूड और हस्तशिल्प स्टॉल्स के साथ जीवंत लोआंग सोआंग स्ट्रीट शो का आनंद मिलता है।', public_name = '부이페스트 바자 야시장 (Chợ Đêm Vui-Fest Bazaar Sunset Town)', tags = ARRAY['attraction', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'cho-dem-vui-fest-bazaar-sunset-town';
UPDATE public.businesses SET category = 'activities', subcategory = 'attraction', address = 'Sunset Town, Bãi Đất Đỏ, phường, Phú Quốc, An Giang, Vietnam', description_ko = '매일 저녁 21:00~21:30(화요일 정기 휴연 가능) 거대한 해상 멀티미디어 무대에서 펼쳐지는 선셋타운의 하이라이트 야간 공연입니다. 불·물·레이저·3D 프로젝션 매핑과 60여 명의 다국적 아티스트 퍼포먼스에 이어 약 21:25경 밤하늘을 수놓는 대규모 고고도 해상 불꽃놀이로 대미를 장식합니다.', description_en = 'Staged nightly from 21:00 to 21:30 (except scheduled Tuesday maintenance) on a massive overwater theater, Kiss of the Sea blends fire, water screens, laser mapping, and 60 international performers. Every show culminates around 21:25 with Sunset Town’s signature high-altitude sea fireworks.', description_vi = 'Diễn ra hàng đêm từ 21:00 đến 21:30 (trừ lịch nghỉ bảo trì thứ Ba) trên sân khấu mặt biển khổng lồ, Nụ Hôn Của Biển Cả (Kiss of the Sea) kết hợp mãn nhãn giữa lửa, màn nước, laser 3D và 60 nghệ sĩ quốc tế. Đêm diễn khép lại vào khoảng 21:25 bằng màn pháo hoa nghệ thuật tầm cao rực sáng bầu trời đảo Ngọc.', description_zh = '《海之吻》（Kiss of the Sea）每晚 21:00 至 21:30（周二例行休演除外）在宏伟的海上多媒体剧场震撼上演，是日落小镇的压轴夜间巨制。演出融合水幕、烈焰、激光 3D 投影与 60 余位国际演员的现场表演，并于约 21:25 以盛大的高空海上烟花秀推向高潮。', description_ja = '毎晩21:00〜21:30（火曜休演の場合あり）に巨大な海上ステージで上演される、サンセットタウン最大のマルチメディア・ナイトショーです。炎やウォータースクリーン、レーザー投影と約60名の国際パフォーマーが共演し、21:25頃の壮大な海上打ち上げ花火でフィナーレを迎えます。', description_ru = 'Грандиозное мультимедийное шоу «Поцелуй моря» (Kiss of the Sea) проходит каждый вечер с 21:00 до 21:30 (кроме плановых выходных по вторникам) на огромной морской сцене. Огонь, водные экраны, лазерная 3D-проекция и выступление 60 артистов завершаются в 21:25 масштабным высотным салютом над морем.', description_hi = 'प्रतिदिन रात 21:00 से 21:30 बजे तक (मंगलवार अवकाश को छोड़कर) विशाल समुद्री मंच पर आयोजित किस ऑफ़ द सी में आग, वाटर स्क्रीन, लेज़र मैपिंग और 60 अंतरराष्ट्रीय कलाकारों की प्रस्तुति होती है। शो का समापन रात लगभग 21:25 बजे भव्य समुद्री आतिशबाज़ी के साथ होता है।', public_name = '키스 오브 더 씨 쇼 (Kiss of the Sea Show - Nụ hôn của Biển Cả)', price_level = '$$$$', tags = ARRAY['attraction', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'sunset-place-10';
UPDATE public.businesses SET category = 'activities', subcategory = 'attraction', address = 'Bãi Đất Đỏ, Phú Quốc, An Giang, Vietnam', description_ko = '고대 로마 콜로세움을 모티브로 한 안터이 역에서 출발해 바다 위 섬들을 넘어 혼똔섬 네이처 파크까지 이어지는 총길이 7,899.9m의 세계 최장 3선식 해상 케이블카입니다. 에메랄드빛 남부 다도해와 어선 군락을 하늘에서 조망하며 아쿠아토피아 워터파크·엑조티카 빌리지를 함께 즐길 수 있고, 낮 정기 점검 시간대(11:30~13:30경)를 피해 탑승 일정을 잡는 것이 좋습니다.', description_en = 'Departing from Sunset Town’s Colosseum-inspired An Thoi Station, the 7,899.9-meter Hon Thom Cable Car holds the Guinness record as the world’s longest three-wire sea-crossing gondola. Soar above turquoise islands and fishing fleets to Aquatopia Water Park, noting the midday maintenance pause around 11:30–13:30.', description_vi = 'Khởi hành từ nhà ga An Thới mang kiến trúc Đấu trường La Mã, tuyến cáp treo 3 dây vượt biển Hòn Thơm dài 7.899,9m giữ kỷ lục Guinness dài nhất thế giới. Du khách được thu trọn vẻ đẹp biển trời Nam đảo từ trên cao trước khi vui chơi tại công viên nước Aquatopia; lưu ý khung giờ nghỉ trưa bảo trì khoảng 11:30–13:30.', description_zh = '香岛跨海缆车自日落小镇古罗马斗兽场风格的安泰站出发，全长 7,899.9 米，创下世界最长三索跨海缆车吉尼斯纪录。乘坐在高空轿厢内可俯瞰翡翠色群岛与壮观渔船队，直达香岛水世界乐园；出行请注意避开中午约 11:30–13:30 的例行停运检修时段。', description_ja = '古代ローマのコロッセオを模したアントイ駅から出発し、海を越えてホントム島ネイチャーパークへ続く全長7,899.9mの世界最長3線式海上ケーブルカーです。エメラルド色の海と島々を眼下にアクアトピア・ウォーターパークへ直行でき、昼の定期点検時間（11:30〜13:30頃）を避けた乗車計画がおすすめです。', description_ru = 'Канатная дорога Хон-Тхом длиной 7899,9 м отправляется со станции Ан-Тхой в стиле римского Колизея и внесена в Книгу рекордов Гиннесса как самая длинная трёхканатная морская дорога в мире. Кабинки парят над бирюзовыми островами по пути в аквапарк Aquatopia; учитывайте дневной технический перерыв около 11:30–13:30.', description_hi = 'रोमन कोलोसियम शैली के अन थोई स्टेशन से चलने वाली 7,899.9 मीटर लंबी होन थोम केबल कार दुनिया की सबसे लंबी तीन-तार वाली समुद्री केबल कार है। फ़िरोज़ा द्वीपों के ऊपर से उड़ान भरते हुए यह एक्वाटोपिया वाटर पार्क पहुँचती है; कृपया दोपहर 11:30–13:30 के रखरखाव विराम का ध्यान रखें।', public_name = '선월드 혼똔섬 케이블카 탑승장 (Sunworld Hòn Thơm - Hon Thom Cable Car Phu Quoc)', price_level = '$$$$', tags = ARRAY['attraction', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'sunworld-hon-thom-hon-thom-cable-car-phu-quoc';
UPDATE public.businesses SET category = 'activities', subcategory = 'attraction', address = '22G5+Q53 Sunset Town, Bãi Đất Đỏ phường Phú Quốc, An Giang, Vietnam', description_ko = '매일 저녁 19:30~20:00경 선셋타운 해변 만에서 펼쳐지는 야간 수상 익스트림 & 불꽃 뮤지컬 쇼입니다. LED 라이트 수트를 입은 제트스키·플라이보드 아티스트들의 야간 수상 군무와 음악 분수, 해상 불꽃 퍼포먼스가 어우러지며 전용 관람석 티켓 또는 선 바바리아 디너 패키지로 직관할 수 있습니다.', description_en = 'Lighting up Sunset Town Bay nightly around 19:30–20:00, Symphony of the Sea pairs LED-suited jet-ski and flyboard athletes with choreographed music and overwater pyrotechnics. Watch from dedicated bayside grandstands or combine the show with craft beer and dinner at Sun Bavaria GastroPub.', description_vi = 'Thắp sáng vịnh biển Thị trấn Hoàng Hôn mỗi tối từ 19:30 đến 20:00, Symphony of the Sea là bản giao hưởng nghệ thuật kết hợp trình diễn mô tô nước, flyboard mặc giáp LED phát sáng và pháo hoa trên mặt nước. Du khách có thể mua vé khán đài riêng hoặc chọn gói ăn tối kèm bia thủ công tại Sun Bavaria GastroPub.', description_zh = '《海洋交响曲》（Symphony of the Sea）每晚约 19:30–20:00 在日落小镇海湾璀璨上演，是一场结合水上极限特技与烟花音乐的夜间大秀。身着 LED 发光战衣的摩托艇与水上飞板选手在海面编队起舞并绽放绚丽水上烟火，可购买看台门票或预订 Sun Bavaria 精酿晚宴套票观赏。', description_ja = '毎晩19:30〜20:00頃にサンセットタウンの入り江で開催される、水上エクストリーム＆花火ミュージカルショーです。LEDスーツを纏ったジェットスキーやフライボード選手による幻想的な夜間演舞と水上花火が融合し、専用観覧席チケットやサン・バヴァリアのディナーパッケージで鑑賞できます。', description_ru = 'Вечернее шоу на воде Symphony of the Sea проходит ежедневно около 19:30–20:00 в бухте Сансет-Тауна, соединяя музыку, пиротехнику и трюки райдеров в светящихся LED-костюмах на гидроциклах и флайбордах. Смотреть представление можно с трибун у воды или за ужином с крафтовым пивом в Sun Bavaria GastroPub.', description_hi = 'प्रतिदिन शाम लगभग 19:30–20:00 बजे सनसेट टाउन की खाड़ी में आयोजित सिम्फनी ऑफ़ द सी में एलईडी सूट पहने जेट-स्की व फ़्लाईबोर्ड कलाकार संगीत और समुद्री आतिशबाज़ी के साथ अद्भुत प्रदर्शन करते हैं। इसे समर्पित स्टैंड से या सन बवेरिया गैस्ट्रोपब के डिनर पैकेज के साथ देखा जा सकता है।', public_name = '심포니 오브 더 씨 쇼 (Symphony of the sea show)', price_level = '$$$$', tags = ARRAY['attraction', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'symphony-of-the-sea-show';
UPDATE public.businesses SET category = 'activities', subcategory = 'attraction', address = 'Thị Trấn Địa Trung Hải, Phu Quoc, An Giang, Vietnam', description_ko = '세계적인 리조트 건축 거장 빌 벤슬리(Bill Bensley)가 미드센추리 모던 예술 양식으로 설계한 선셋타운의 독창적인 건축·전시 컨벤션 랜드마크입니다. 대담한 기하학 패턴과 색채가 돋보이는 외관 광장은 여행자들의 단골 건축 포토존으로 사랑받으며, 내부 대형 볼룸과 전시는 특별 행사 기간에 개방됩니다.', description_en = 'Designed by acclaimed architect Bill Bensley, Sun Signature Gallery is a bold Mid-Century Modern architectural landmark and event center in Sunset Town. Visitors admire and photograph its colorful geometric facade year-round, while its grand museum-like interiors open during exhibitions and conventions.', description_vi = 'Được chắp bút bởi kiến trúc sư lừng danh Bill Bensley, Sun Signature Gallery là tuyệt tác kiến trúc và trung tâm sự kiện mang phong cách nghệ thuật Mid-Century Modern độc bản tại Thị trấn Hoàng Hôn. Mặt tiền hình khối rực rỡ là tọa độ chụp ảnh yêu thích của du khách, còn không gian nội thất mở cửa theo các kỳ triển lãm và hội nghị.', description_zh = '太阳标志画廊（Sun Signature Gallery）由享誉国际的建筑大师比尔·本斯利（Bill Bensley）操刀设计，是一座极具中世纪现代主义艺术气息的建筑与会展地标。色彩大胆、几何感十足的建筑外立面常年吸引游客拍照打卡，恢弘的艺术内厅则在特定展览与活动期间开放。', description_ja = '世界的建築家ビル・ベンスリーがミッドセンチュリー・モダン様式で設計した、サンセットタウン屈指のアート建築＆コンベンション施設です。大胆な色彩と幾何学模様が際立つ外観広場は人気の建築フォトスポットとなっており、内部ホールは展示会やイベント開催時に公開されます。', description_ru = 'Яркий архитектурный и выставочный центр Sun Signature Gallery спроектирован знаменитым архитектором Биллом Бенсли в эстетике модернизма середины XX века. Выразительный геометричный фасад круглый год служит эффектной фотолокацией, а музейные залы внутри открываются во время выставок и мероприятий.', description_hi = 'प्रसिद्ध वास्तुकार बिल बेंसली द्वारा मिड-सेंचुरी मॉडर्न शैली में डिज़ाइन की गई सन सिग्नेचर गैलरी सनसेट टाउन की एक विशिष्ट कला और कन्वेंशन इमारत है। इसका रंगीन ज्यामितीय बाहरी स्वरूप फ़ोटोग्राफ़ी के लिए हमेशा खुला रहता है, जबकि भव्य आंतरिक कक्ष प्रदर्शनियों व आयोजनों के दौरान खुलते हैं।', public_name = '선 시그니처 갤러리 (Sun Signature Gallery)', tags = ARRAY['attraction', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'sun-signature-gallery';
UPDATE public.businesses SET category = 'banking', subcategory = 'currency_exchange', address = 'Amalfi & Positano Junction (Near 19 Positano), Sunset Town, An Thới, Phú Quốc, Vietnam', description_ko = '선셋타운 아말피 중심 거리(42 Amalfi 인근)에 위치한 사설 환전 창구로, 해변 산책로와 식당가를 오가며 미화 달러(USD)나 주요 외화를 베트남 동(VND) 현금으로 간편하게 환전할 수 있습니다. 방문 전 여권을 지참하고 현장 고시 환율과 권종별 우대 조건을 확인한 뒤 거래하는 것이 좋습니다.', description_en = 'Centrally located near 42 Amalfi Street in Sunset Town, Money Exchange Sunset Town provides convenient walk-up foreign currency exchange into Vietnamese Dong (VND). Bring your passport and confirm the posted counter rates—especially for crisp $100 USD bills—before exchanging.', description_vi = 'Nằm ngay khu trung tâm gần số 42 đường Amalfi, quầy Money Exchange Sunset Town hỗ trợ du khách quy đổi nhanh USD và các ngoại tệ phổ biến sang tiền mặt Việt Nam Đồng (VND). Bạn nên mang theo hộ chiếu và kiểm tra trực tiếp bảng tỷ giá niêm yết tại quầy trước khi giao dịch.', description_zh = 'Money Exchange Sunset Town 位于日落小镇中心阿马尔菲街（近 42 号），方便游客在逛街就餐途中将美元等主要外币兑换为越南盾现金。前往办理时建议随身携带护照，并在交易前现场核对当日挂牌汇率及大面额纸币优惠标准。', description_ja = 'サンセットタウン中心部のアマルフィ通り（42番地付近）にある両替カウンターで、散策や食事の合間に米ドルなどの主要外貨をベトナムドン（VND）現金へ手軽に両替できます。パスポートを持参のうえ、店頭の掲示レートや高額紙幣の条件を確認してからの利用がおすすめです。', description_ru = 'Пункт обмена валюты Money Exchange Sunset Town удобно расположен в центре улицы Амальфи (рядом с домом 42) для быстрого обмена долларов США и другой валюты на вьетнамские донги. Рекомендуется иметь при себе паспорт и заранее уточнять текущий курс на стойке.', description_hi = 'सनसेट टाउन में 42 अमाल्फ़ी स्ट्रीट के पास स्थित मनी एक्सचेंज सनसेट टाउन अमेरिकी डॉलर और प्रमुख विदेशी मुद्राओं को वियतनामी डोंग (VND) में बदलने की सुविधा देता है। कृपया पासपोर्ट साथ रखें और लेनदेन से पहले काउंटर पर प्रदर्शित विनिमय दर की पुष्टि कर लें।', public_name = 'Money Exchange Sunset Town', tags = ARRAY['attraction', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'money-exchange-sunset-town';
UPDATE public.businesses SET category = 'essentials', subcategory = 'laundry', address = '22J4+47P, Ấp 6, Phú Quốc, An Giang 92513, Vietnam', description_ko = '푸꾸옥 세탁소 — 선셋타운.', description_en = 'Phu Quoc Laundry — Sunset Town, Phu Quoc.', description_vi = 'Phú Quốc Giặt ủi — Thị trấn Hoàng Hôn, Phú Quốc.', description_zh = 'Phu Quoc Laundry 位于富国岛日落小镇，提供衣物洗涤与烘干服务。', description_ja = 'Phu Quoc Laundryはフーコック島サンセットタウンに位置し、洗濯および乾燥サービスを提供しています。', description_ru = 'Phu Quoc Laundry — прачечная в Сансет-Тауне на Фукуоке, предоставляющая услуги стирки и сушки одежды.', description_hi = 'Phu Quoc Laundry फू क्वोक के सनसेट टाउन में स्थित है, जो कपड़े धोने और सुखाने की सेवा प्रदान करती है।', public_name = 'Phú Quốc Laundry (Giặt sấy)', tags = ARRAY['attraction', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'phu-quoc-laundry-giat-say';
UPDATE public.businesses SET category = 'activities', subcategory = 'attraction', address = 'Sky Building, SunGrand, An Thoi, Phú Quốc, An Giang 925000, Vietnam', description_ko = '자유 관람 및 이용 가능 • [이용 안내] 선셋타운 관광 편의시설 및 명소.', description_en = 'Phú Quốc Go is an attraction & landmark located in Sunset Town, Phu Quoc.', description_vi = 'Phú Quốc Go là địa điểm tham quan nằm tại Thị trấn Hoàng Hôn, Phú Quốc.', description_zh = 'Phú Quốc Go 是位于富国岛日落小镇的旅游便民设施与景点，可自由参观与使用。', description_ja = 'Phú Quốc Goはフーコック島サンセットタウンに位置する観光利便施設・見どころで、自由に立ち寄り利用できます。', description_ru = 'Phú Quốc Go — это туристический объект и удобство для путешественников в Сансет-Тауне на Фукуоке, открытый для свободного посещения.', description_hi = 'Phú Quốc Go फू क्वोक के सनसेट टाउन में स्थित एक पर्यटन सुविधा और दर्शनीय स्थल है, जहाँ स्वतंत्र रूप से घूमा और उपयोग किया जा सकता है।', public_name = 'Phú Quốc Go', tags = ARRAY['attraction', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'phu-quoc-go';
UPDATE public.businesses SET category = 'activities', subcategory = 'attraction', address = '22J4+3RF, Phú Quốc, An Giang, Vietnam', description_ko = '키스 브릿지와 선 바바리아 가스트로펍 앞쪽으로 초승달처럼 완만하게 펼쳐진 선셋타운의 중심 해변 산책 구역입니다. 낮에는 야자수 그늘과 백사장을 따라 여유롭게 거닐고, 해 질 녘에는 황금빛 서해안 일몰과 해상 쇼, 밤바다 불꽃놀이를 가장 가까이에서 감상할 수 있습니다.', description_en = 'Curving gracefully beside Kiss Bridge and Sun Bavaria GastroPub, Sunset Town Beach (Bãi biển Thị trấn Hoàng Hôn) is the district’s scenic palm-lined bayfront. Stroll the white-sand shoreline by day and gather along the promenade at dusk for golden sunsets, water shows, and fireworks.', description_vi = 'Uốn cong mềm mại hình cánh cung ngay trước Cầu Hôn và Sun Bavaria GastroPub, Bãi biển Thị trấn Hoàng Hôn là khoảng bờ biển rợp bóng dừa thơ mộng giữa khu phố Địa Trung Hải. Ban ngày du khách có thể dạo bước trên cát trắng mịn, còn chiều tối là thời điểm lý tưởng nhất để đón hoàng hôn và xem pháo hoa trên vịnh.', description_zh = '日落小镇海滩（Bãi biển Thị trấn Hoàng Hôn）呈优美的新月弧线环抱于亲吻桥与 Sun Bavaria 餐吧前方，是小镇核心的滨海休闲海岸。白天可沿椰林白沙滩悠闲漫步，傍晚时分则是欣赏西海岸金色落日、水上特技秀与璀璨烟花的前排观景地。', description_ja = 'キスブリッジやサン・バヴァリア前の入り江に沿って緩やかな弧を描く、サンセットタウン中心部のパームツリーが並ぶビーチエリアです。昼間は白い砂浜と海辺の遊歩道を心地よく散策でき、夕暮れから夜にかけては夕陽や水上ショー、打ち上げ花火を間近に楽しめます。', description_ru = 'Живописный пляж Сансет-Тауна (Bãi biển Thị trấn Hoàng Hôn) полумесяцем огибает бухту рядом с Мостом Поцелуев и гастропабом Sun Bavaria. Днём здесь приятно гулять вдоль пальм и белого песка, а вечером берег превращается в лучший партер для наблюдения за закатом, водными шоу и салютом.', description_hi = 'किस ब्रिज और सन बवेरिया गैस्ट्रोपब के सामने अर्धचंद्राकार रूप में फैला सनसेट टाउन बीच ताड़ के पेड़ों से सजा मनोरम समुद्र तट है। दिन में सफ़ेद रेत के किनारे टहलें और शाम को सुनहरे सूर्यास्त, वाटर शो तथा आतिशबाज़ी का नज़दीक से आनंद लें।', public_name = 'Bãi biển Thị trấn Hoàng Hôn', tags = ARRAY['attraction', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'bai-bien-thi-tran-hoang-hon';
UPDATE public.businesses SET category = 'banking', subcategory = 'currency_exchange', address = 'Đại Lộ New Số AT 96, Khu Đô Thị New, Phú Quốc, An Giang 92513, Vietnam', description_ko = '선셋타운 뉴 안터이 대로(AT 96, Đại Lộ New)에 자리한 솔 코지(Sol Cosy) 외화 환전소입니다. 뉴 대로변 호텔·미니마트·해산물 식당 라인과 인접해 있어 야시장이나 로컬 식당 방문 전 소액 경비와 베트남 동 현금을 준비하기 편리합니다.', description_en = 'Situated at AT 96 New Boulevard (Đại Lộ New) in the New An Thoi quarter, Sol Cosy Money Exchange offers accessible currency exchange near neighborhood hotels and seafood restaurants. Stop by with valid ID to convert major foreign banknotes into Vietnamese Dong before night-market outings.', description_vi = 'Tọa lạc tại căn AT 96 Đại lộ New thuộc khu đô thị New An Thới, quầy đổi tiền Sol Cosy nằm ngay trục đường tập trung nhiều khách sạn và nhà hàng hải sản. Đây là điểm ghé thuận tiện để du khách đổi ngoại tệ sang tiền mặt VND trước khi đi ăn tối hay dạo chợ đêm.', description_zh = 'Sol Cosy 换汇点坐落于日落小镇新安泰街区新大道 AT 96 号（Đại Lộ New），毗邻沿街精品酒店、便利店与海鲜餐厅。非常适合在前往夜市或本地餐馆消费前，携有效证件顺路将外币现钞兑换为越南盾零钱。', description_ja = 'サンセットタウンのニュー大通り（AT 96, Đại Lộ New）に位置する「ソル・コージー」外貨両替所です。大通り沿いのホテルやミニマート、シーフードレストランに近く、ナイトマーケットや食事へ出かける前にベトナムドン現金を用意するのに便利です。', description_ru = 'Обменный пункт Sol Cosy на бульваре Нью (AT 96, Đại Lộ New) в квартале Нью-Ан-Тхой расположен рядом с отелями и рыбными ресторанами. Удобное место, чтобы обменять наличную иностранную валюту на вьетнамские донги перед походом на ночной рынок.', description_hi = 'न्यू अन थोई क्षेत्र के AT 96 न्यू बुलेवार्ड पर स्थित सोल कोज़ी मनी एक्सचेंज पास के होटलों और सीफ़ूड रेस्तरां के करीब सुगम मुद्रा विनिमय सेवा देता है। नाइट मार्केट जाने से पहले विदेशी करेंसी को वियतनामी डोंग में बदलने के लिए यहाँ रुका जा सकता है।', public_name = 'Exchange Money - Sol Cosy Phu Quoc', tags = ARRAY['attraction', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'exchange-money-sol-cosy-phu-quoc';
UPDATE public.businesses SET category = 'banking', subcategory = 'currency_exchange', address = '22H5+C89, Phú Quốc, An Giang, Vietnam', description_ko = '선셋타운 포지타노·아말피 연결 구역에 위치한 G&G 머니 익스체인지 환전 창구입니다. 주변 부티크 호텔 투숙객들이 마사지 숍이나 야시장 현금 결제용 베트남 동(VND)이 필요할 때 도보로 빠르게 방문해 환율 확인 후 환전할 수 있습니다.', description_en = 'Located along the walkable Positano–Amalfi connector in Sunset Town, G&G Money Exchange serves travelers staying at nearby boutique hotels. Drop in on foot to check live counter exchange rates and pick up Vietnamese Dong cash for spas, taxis, and night-market stalls.', description_vi = 'Nằm tại khu vực kết nối phố Positano và Amalfi của Thị trấn Hoàng Hôn, G&G Money Exchange phục vụ nhanh chóng nhu cầu đổi ngoại tệ của khách lưu trú quanh các khách sạn boutique. Du khách chỉ cần đi bộ vài phút để xem tỷ giá trực tiếp và đổi tiền mặt VND chi tiêu hàng ngày.', description_zh = 'G&G 换汇窗口位于日落小镇波西塔诺与阿马尔菲街连接地带，周边环绕多家精品酒店。住客若需准备水疗按摩、打车或夜市小吃所需的越南盾现金，步行数分钟即可抵达并现场核对汇率办理兑换。', description_ja = 'サンセットタウンのポジターノ通りとアマルフィ通りを結ぶエリアにある「G&Gマネーエクスチェンジ」両替窓口です。周辺のブティックホテル滞在中にスパやタクシー、屋台用のベトナムドン現金が必要になった際、徒歩ですぐ立ち寄ってレート確認・両替ができます。', description_ru = 'Пункт обмена валюты G&G Money Exchange расположен в пешеходной зоне между улицами Позитано и Амальфи рядом с бутик-отелями Сансет-Тауна. Сюда удобно зайти пешком, чтобы узнать актуальный курс и обменять наличные на донги для оплаты спа и уличной еды.', description_hi = 'सनसेट टाउन के पॉज़िटानो–अमाल्फ़ी संपर्क मार्ग पर स्थित जी एंड जी मनी एक्सचेंज आस-पास के बुटीक होटलों में ठहरे यात्रियों के लिए बेहद उपयोगी है। स्पा, टैक्सी और नाइट मार्केट के नकद खर्चों हेतु वियतनामी डोंग लेने के लिए यहाँ पैदल पहुँचा जा सकता है।', public_name = 'G&G Money Exchange Sunset Town', tags = ARRAY['attraction', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'g-g-money-exchange-sunset-town';
UPDATE public.businesses SET category = 'activities', subcategory = 'attraction', address = '22H4+QVJ, Phú Quốc, An Giang, Vietnam', description_ko = '베니스·아말피 해변 거리와 시계탑 광장을 연결하는 유럽풍 보행자 상점가 구역인 선셋 바자(Sunset Bazaar)입니다. 파스텔 톤 지중해 건축물 1층마다 아티산 베이커리, 카페, 레스토랑, 디저트 숍이 들어서 있어 해안 풍경을 바라보며 미식 산책과 거리 사진 촬영을 즐기기 좋습니다.', description_en = 'Linking the Clock Tower plaza with the Venice and Amalfi waterfront, Sunset Bazaar is a lively European-inspired pedestrian commercial quarter. Pastel Mediterranean storefronts house artisan bakeries, cafes, bistros, and dessert bars with open-air seating facing the sea.', description_vi = 'Kết nối quảng trường Tháp Đồng Hồ với dãy phố biển Venice và Amalfi, Sunset Bazaar là khu phố thương mại đi bộ mang đậm hơi thở châu Âu phóng khoáng. Dọc những dãy nhà màu pastel rực rỡ là chuỗi tiệm bánh thủ công, quán cà phê, nhà hàng và tiệm tráng miệng hướng biển cực kỳ nhộn nhịp.', description_zh = '日落集市商业街区（Sunset Bazaar）串联起钟楼广场与威尼斯、阿马尔菲海滨大道，是一片充满欧式风情的步行美食商业街。色彩柔和的地中海建筑底层汇集了手工烘焙坊、海景咖啡馆、西式餐酒馆与甜品店，非常适合边走边逛、拍照与品尝美食。', description_ja = '時計塔広場からヴェニス・アマルフィの海岸通りへと続く、ヨーロッパの街角を再現した歩行者中心の商業ゾーン「サンセット・バザール」です。パステルカラーの地中海建築が並ぶ通りにベーカリーやカフェ、ビストロ、デザート店が集まり、海風を感じながら街歩きとグルメを満喫できます。', description_ru = 'Торгово-пешеходный квартал Sunset Bazaar связывает площадь Часовой башни с набережными улиц Венеция и Амальфи в европейском курортном стиле. За пастельными средиземноморскими фасадами работают ремесленные пекарни, кофейни, бистро и десертные лавки с террасами у моря.', description_hi = 'क्लॉक टॉवर प्लाज़ा को वेनिस और अमाल्फ़ी समुद्र तट से जोड़ने वाला सनसेट बाज़ार यूरोपीय शैली का एक जीवंत पैदल बाज़ार क्षेत्र है। पेस्टल भूमध्यसागरीय इमारतों में आर्टिसन बेकरी, कैफ़े, बिस्त्रो और डेज़र्ट शॉप्स हैं, जहाँ समुद्र के नज़ारों के साथ घूमने और खाने का मज़ा मिलता है।', public_name = 'Sunset Bazaar Phú Quốc', tags = ARRAY['attraction', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'sunset-bazaar-phu-quoc';
UPDATE public.businesses SET category = 'banking', subcategory = 'currency_exchange', address = 'khu Sunset Town, 25 Đ. Amalfi, khu phố 6, Phú Quốc, An Giang 950000, Vietnam', description_ko = '선셋타운 아말피 거리 25번지(25 Amalfi) 중심 상권에 자리한 전문 환전소 EXMoney입니다. 케이블카 광장과 아말피 해안 식당가에서 가까워 미화 달러·유로·원화 등 주요 통화의 당일 환율을 현장에서 비교·확인하며 깔끔하게 환전할 수 있습니다.', description_en = 'Positioned at 25 Amalfi Street near the cable car plaza and coastal dining row, EXMoney Sunset Town is a dedicated currency exchange counter. Travelers can easily check posted daily rates for USD, EUR, KRW, and other major currencies in a clean storefront setting.', description_vi = 'Tọa lạc tại số 25 đường Amalfi gần quảng trường ga cáp treo và dãy nhà hàng ven biển, EXMoney Sunset Town là quầy thu đổi ngoại tệ khang trang, dễ tìm. Khách du lịch có thể kiểm tra minh bạch tỷ giá trong ngày cho USD, EUR, KRW cùng nhiều đồng tiền phổ biến khác.', description_zh = 'EXMoney 专业外币兑换处位于日落小镇核心地段阿马尔菲街 25 号，邻近跨海缆车广场与海滨餐饮街。门店环境整洁，支持美元、欧元、韩元等多种主流货币现金兑换，交易前可清晰查看当日现场牌价。', description_ja = 'ケーブルカー広場や海沿いの飲食店街に近いアマルフィ通り25番地に構える外貨両替所「EXMoney」です。清潔感のある窓口で米ドルやユーロ、韓国ウォンなど主要通貨の当日レートを確認しながらスムーズにベトナムドンへ両替できます。', description_ru = 'Специализированный пункт обмена валюты EXMoney на улице Амальфи, 25, находится в паре минут ходьбы от площади канатной дороги и прибрежных ресторанов. В аккуратном офисе можно проверить дневные курсы для долларов, евро и других мировых валют.', description_hi = 'केबल कार प्लाज़ा और तटीय रेस्तरां के पास 25 अमाल्फ़ी स्ट्रीट पर स्थित एक्समनी सनसेट टाउन एक समर्पित करेंसी एक्सचेंज काउंटर है। यात्री यहाँ साफ़-सुथरे स्टोरफ़्रंट में अमेरिकी डॉलर, यूरो और अन्य प्रमुख मुद्राओं की दैनिक दरें देखकर विनिमय कर सकते हैं।', public_name = '익스머니 환전소 (EXMoney Sunset Town | Currency Exchange)', tags = ARRAY['attraction', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'exmoney-sunset-town-currency-exchange';
UPDATE public.businesses SET category = 'activities', subcategory = 'attraction', address = 'M107-M109 Milan Street, Sunset Town, Phú Quốc, An Giang, Vietnam', description_ko = '자유 관람 및 이용 가능 • [이용 안내] 선셋타운 관광 편의시설 및 명소.', description_en = 'Sunset Town Motorbike & Scooter Rental is an attraction & landmark located in Sunset Town, Phu Quoc.', description_vi = 'Sunset Town Motorbike & Scooter Rental là địa điểm tham quan nằm tại Thị trấn Hoàng Hôn, Phú Quốc.', description_zh = 'Sunset Town Motorbike & Scooter Rental是位于富国岛日落小镇的摩托车与踏板车租赁服务点。', description_ja = 'Sunset Town Motorbike & Scooter Rentalは、フーコック島サンセットタウンにあるバイク・スクーターレンタルサービスです。', description_ru = 'Sunset Town Motorbike & Scooter Rental — пункт проката мотоциклов и скутеров в Сансет-Тауне на Фукуоке.', description_hi = 'Sunset Town Motorbike & Scooter Rental फू क्वोक के सनसेट टाउन में स्थित मोटरबाइक और स्कूटर किराये की सेवा है।', public_name = 'Sunset Town Motorbike & Scooter Rental', tags = ARRAY['attraction', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'sunset-town-motorbike-scooter-rental';
UPDATE public.businesses SET category = 'essentials', subcategory = 'laundry', address = 'Sunset Town, The Sky Building, Sun Grand City Hillside Residence, Khu Phố 6, Phú Quốc, An Giang, Vietnam', description_ko = 'GL90s 세탁소 (S4점) — 선셋타운 소렌토 S4.', description_en = 'GL90s Laundry (Branch S4) — Sorrento S4, Sunset Town, Phu Quoc.', description_vi = 'GL90s Giặt ủi (Chi nhánh S4) — Sorrento S4, Thị trấn Hoàng Hôn, Phú Quốc.', description_zh = 'GL90s Laundry (分店 S4) 位于富国岛日落小镇索伦托区 S4，提供便捷的洗衣与衣物护理服务。', description_ja = 'GL90s Laundry（S4店）は、フーコック島サンセットタウンのソレントS4に位置する洗濯サービス店です。', description_ru = 'GL90s Laundry (филиал S4) — прачечная, расположенная в районе Sorrento S4 в Сансет-Тауне на Фукуоке.', description_hi = 'GL90s Laundry (शाखा S4) फू क्वोक के सनसेट टाउन में सोरेंटो S4 में स्थित एक लॉन्ड्री सेवा केंद्र है।', public_name = 'GL90S Laundry ( CS S4)', tags = ARRAY['attraction', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'gl90s-laundry-cs-s4';
UPDATE public.businesses SET category = 'banking', subcategory = 'currency_exchange', address = 'A mafi 58. Sunsettown, Phú Quốc, An Giang 920000, Vietnam', description_ko = '아말피 해안도로 58번지(58 Amalfi)에 위치한 선셋타운 익스체인지 환전 창구입니다. 해변 펍과 한식당·스파가 밀집한 아말피 중심 블록에 자리해 저녁 식사나 마사지 방문 전후로 부족한 베트남 동 현금을 빠르게 환전하기 편리합니다.', description_en = 'Located at 58 Amalfi Street right along Sunset Town’s lively dining and spa block, Sunset Town Exchange offers convenient walk-in currency conversion. It is a practical stop before dinner or evening shows when topping up Vietnamese Dong cash on hand.', description_vi = 'Nằm tại số 58 đường Amalfi ngay dãy phố tập trung đông đúc nhà hàng, quán pub và spa, Sunset Town Exchange mang lại sự tiện lợi tối đa khi cần đổi ngoại tệ. Du khách có thể ghé đổi nhanh tiền mặt VND ngay trước giờ dùng bữa tối hoặc đi thư giãn cuối ngày.', description_zh = 'Sunset Town Exchange 坐落于阿马尔菲街 58 号餐饮与水疗馆密集的黄金街区，提供便捷的现场外币兑换服务。在享用晚餐、预约按摩或观看夜间演出前后，若需补充越南盾现金可就近快速办理。', description_ja = 'レストランやスパが立ち並ぶアマルフィ通り58番地に位置する両替窓口「サンセットタウン・エクスチェンジ」です。夕食やマッサージ、夜のショー鑑賞の前後に手持ちのベトナムドン現金を素早く補充したい時に重宝します。', description_ru = 'Обменный пункт Sunset Town Exchange на улице Амальфи, 58, расположен прямо в оживлённом квартале ресторанов и спа-салонов. Практичное место, чтобы быстро пополнить запас наличных вьетнамских донгов перед ужином или вечерней прогулкой.', description_hi = 'सनसेट टाउन के जीवंत डाइनिंग और स्पा ब्लॉक में 58 अमाल्फ़ी स्ट्रीट पर स्थित सनसेट टाउन एक्सचेंज सुगम वॉक-इन करेंसी एक्सचेंज प्रदान करता है। रात के खाने या शाम के शो से पहले वियतनामी डोंग नकद लेने के लिए यह एक व्यावहारिक स्थान है।', public_name = '선셋타운 환전소 (Sunset Town Exchange)', tags = ARRAY['attraction', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'sunsettown-exchange';
UPDATE public.businesses SET category = 'activities', subcategory = 'attraction', address = 'Bãi biển thị trấn hoàng hôn, Phú Quốc, An Giang 920000, Vietnam', description_ko = '선셋타운 해변 산책로 인근에 자리한 수제 맥주 양조장(Sun KraftBeer) 테마 건축 명소입니다. 거대한 구리 당화조 설비와 파스텔 핑크빛 유러피안 외관이 어우러져 독특한 포토존을 이루며, 이곳에서 갓 양조된 신선한 독일식 수제 맥주는 해변의 선 바바리아 가스트로펍 등에서 맛볼 수 있습니다.', description_en = 'Standing beside the Sunset Town beachfront, Phu Quoc Brew House showcases traditional German brewing craft inside a striking pastel-pink European landmark. Visitors love photographing its distinctive facade, while its freshly brewed Sun KraftBeer pours right next door at Sun Bavaria GastroPub.', description_vi = 'Nằm ngay cạnh lối dạo biển Thị trấn Hoàng Hôn, Phu Quoc Brew House gây ấn tượng mạnh với kiến trúc châu Âu sắc hồng pastel độc đáo nơi ủ dòng bia thủ công Sun KraftBeer chuẩn Đức. Công trình vừa là điểm chụp ảnh nổi bật vừa cung cấp nguồn bia tươi mát lạnh cho nhà hàng Sun Bavaria kế bên.', description_zh = '富国岛精酿啤酒工坊（Phu Quoc Brew House）坐落于日落小镇海滨步道旁，将传统德国酿酒工艺融入醒目的粉彩欧式地标建筑之中。极具辨识度的外观是热门街拍背景，工坊鲜酿的 Sun KraftBeer 德式精酿啤酒则在紧邻的 Sun Bavaria 海景餐吧新鲜供应。', description_ja = 'サンセットタウンの海辺プロムナードそばに佇む、パステルピンクの欧風外観が印象的なクラフトビール醸造所（Sun KraftBeer）のランドマークです。写真映えする建物外観の撮影スポットとして人気が高く、ここで醸造された新鮮なドイツ式ビールは隣接するサン・バヴァリア等で味わえます。', description_ru = 'Здание пивоварни Phu Quoc Brew House у пляжного променада Сансет-Тауна сочетает немецкие пивоваренные традиции с эффектным пастельно-розовым европейским фасадом. Это популярная фотолокация, а свежесваренное здесь крафтовое пиво Sun KraftBeer разливают по соседству в Sun Bavaria GastroPub.', description_hi = 'सनसेट टाउन समुद्र तट के पास स्थित फ़ू क्वोक ब्रू हाउस एक आकर्षक पेस्टल-गुलाबी यूरोपीय इमारत में पारंपरिक जर्मन ब्रूइंग शिल्प को प्रदर्शित करता है। इसका अनूठा बाहरी स्वरूप फ़ोटो के लिए बेहद लोकप्रिय है, और यहाँ बनी ताज़ा सन क्राफ़्टबीयर बगल के सन बवेरिया गैस्ट्रोपब में परोसी जाती है।', public_name = 'Phu Quoc Brew House', tags = ARRAY['attraction', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'phu-quoc-brew-house';
UPDATE public.businesses SET category = 'essentials', subcategory = 'laundry', address = 'S1-09 l, KDC New An Thới, Đặc Khu Phú Quốc, An Giang, Phú Quốc, An Giang, Vietnam', description_ko = '아오메이 세탁소 & 슈즈스파 — 선셋타운.', description_en = 'Ao May Laundry & Shoe Spa — Sunset Town, Phu Quoc.', description_vi = 'Ao May Giặt ủi & Shoe Spa — Thị trấn Hoàng Hôn, Phú Quốc.', description_zh = 'Áo Mây Laundry & Shoe Spa 位于富国岛日落小镇，提供快捷洗烘、干洗及洗鞋护理服务。', description_ja = 'Áo Mây Laundry & Shoe Spaはフーコック島サンセットタウンに位置し、スピード洗濯・乾燥、ドライクリーニング、靴のクリーニングを提供しています。', description_ru = 'Áo Mây Laundry & Shoe Spa — прачечная и салон по уходу за обувью в Сансет-Тауне на Фукуоке, предлагающие экспресс-стирку, сушку, химчистку и чистку обуви.', description_hi = 'Áo Mây Laundry & Shoe Spa फू क्वोक के सनसेट टाउन में स्थित है, जहाँ त्वरित धुलाई, ड्राई क्लीनिंग और जूतों की सफाई की सेवाएँ उपलब्ध हैं।', public_name = 'Áo Mây Phú Quốc Laundry, Shoesspa - Giặt Sấy Nhanh, Giặt Hấp, Vệ Sinh Giày', tags = ARRAY['attraction', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'ao-may-phu-quoc-laundry-shoesspa-giat-say-nhanh-giat-hap-ve-sinh-giay';
UPDATE public.businesses SET category = 'banking', subcategory = 'atm', address = 'Đường New, Thị trấn, Phú Quốc, An Giang, Vietnam', description_ko = '선셋타운 뉴 거리(Đường New) 중심부에 설치된 베트남 군대상업은행(MB Bank) 공식 현금자동입출금기(ATM)입니다. 해외 겸용 체크·신용카드(Visa, Mastercard 등)를 이용한 베트남 동(VND) 현금 인출을 지원하며, 기기 화면에서 출금 한도와 해외 인출 수수료 안내를 즉시 확인할 수 있습니다.', description_en = 'Installed along New Street (Đường New) in Sunset Town, this official MB Bank (Military Commercial Joint Stock Bank) ATM supports Vietnamese Dong cash withdrawals via international Visa and Mastercard cards. On-screen prompts display per-transaction withdrawal limits and any applicable ATM fees.', description_vi = 'Đặt trên trục Đường New tại Thị trấn Hoàng Hôn, cây ATM chính thức của Ngân hàng Quân đội (MB Bank) hỗ trợ rút và nộp tiền mặt VND cùng thẻ quốc tế Visa, Mastercard. Màn hình máy hiển thị rõ hạn mức giao dịch và biểu phí trước khi xác nhận rút tiền.', description_zh = '这台越南军队商业银行（MB Bank）官方自动取款机位于日落小镇新街（Đường New）沿线，支持使用带有 Visa、Mastercard 等标识的国际银行卡提取越南盾现金。操作界面支持多语种提示，并会在取款前清晰显示单笔限额与手续费信息。', description_ja = 'サンセットタウンのニュー通り（Đường New）に設置されているベトナム軍隊商業銀行（MBバンク）公式のATMです。VisaやMastercardなどの国際ブランド付きカードでベトナムドン現金を引き出せ、画面上で1回あたりの限度額や手数料案内を確認できます。', description_ru = 'Официальный банкомат вьетнамского банка MB Bank на улице Нью (Đường New) в Сансет-Тауне обслуживает международные карты Visa и Mastercard для снятия наличных донгов. На экране отображаются лимиты одной операции и размер комиссии перед подтверждением выдачи.', description_hi = 'सनसेट टाउन की न्यू स्ट्रीट (Đường New) पर लगी यह आधिकारिक एमबी बैंक एटीएम मशीन अंतरराष्ट्रीय वीज़ा और मास्टरकार्ड से वियतनामी डोंग नकद निकासी की सुविधा देती है। स्क्रीन पर प्रति लेनदेन की सीमा और लागू शुल्क स्पष्ट रूप से दिखाए जाते हैं।', public_name = 'MB ATM (Nộp/rút tiền)', tags = ARRAY['attraction', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'mb-atm-nop-rut-tien';
UPDATE public.businesses SET category = 'banking', subcategory = 'atm', address = '22G5+V5C, Phú Quốc, An Giang, Vietnam', description_ko = '선셋타운 해안 중심 구역(폼페이 기둥·포지타노 인근)에 위치한 베트남 국영 상업은행 BIDV 공식 ATM 기기입니다. 해외 트래블카드 및 국제 브랜드 카드(Visa, Mastercard, UnionPay 등)로 24시간 베트남 동 현금 인출이 가능해 관광 도중 급히 현금이 필요할 때 유용합니다.', description_en = 'Located near the Positano coastal plaza in Sunset Town, this official state-backed BIDV Bank ATM provides 24-hour Vietnamese Dong cash withdrawals. It accepts major international travel debit and credit cards including Visa, Mastercard, JCB, and UnionPay.', description_vi = 'Nằm gần khu vực quảng trường biển Positano của Thị trấn Hoàng Hôn, máy ATM chính thức của Ngân hàng BIDV phục vụ rút tiền mặt VND 24/7. Máy chấp nhận hầu hết các dòng thẻ thanh toán quốc tế phổ biến như Visa, Mastercard, JCB và UnionPay.', description_zh = '这台越南投资发展银行（BIDV）国有商业银行官方 ATM 位于日落小镇波西塔诺海滨广场附近，提供 24 小时越南盾自助取现服务。机器兼容 Visa、Mastercard、JCB 与银联等主流国际旅行借记卡及信用卡，方便游览途中应急取款。', description_ja = 'サンセットタウンのポジターノ海辺エリア近くに設置された、ベトナム大手国営系商業銀行BIDVの公式ATMです。Visa、Mastercard、JCBなどの海外トラベルデビットカードやクレジットカードに対応しており、観光中に現金が必要になった際24時間利用できます。', description_ru = 'Круглосуточный официальный банкомат крупного государственного банка Вьетнама BIDV расположен рядом с прибрежной зоной Позитано в Сансет-Тауне. Устройство принимает международные карты Visa, Mastercard, JCB и UnionPay для выдачи наличных вьетнамских донгов.', description_hi = 'सनसेट टाउन में पॉज़िटानो तटीय क्षेत्र के पास स्थित यह प्रमुख सरकारी बैंक बीआईडीवी (BIDV) का आधिकारिक 24-घंटे चालू एटीएम है। इसमें वीज़ा, मास्टरकार्ड, जेसीबी और यूनियनपे जैसे अंतरराष्ट्रीय ट्रैवल व क्रेडिट कार्ड से वियतनामी डोंग निकाले जा सकते हैं।', public_name = 'BIDV ATM machine', tags = ARRAY['attraction', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'bidv-atm-machine';
UPDATE public.businesses SET category = 'banking', subcategory = 'atm', address = '22P3+78G, Ấp 7, Phú Quốc, An Giang, Vietnam', description_ko = '부이페스트 바자 야시장 인근(7구역)에 설치된 베트남 주요 국영상업은행 비엣띤뱅크(VietinBank) 공식 ATM입니다. 야시장 먹거리 부스나 기념품 쇼핑 중 현금이 부족할 때 국제 브랜드 체크·신용카드로 손쉽게 베트남 동을 인출할 수 있습니다.', description_en = 'Positioned in Quarter 7 right near VuiFest Bazaar Night Market, this official VietinBank ATM offers reliable Vietnamese Dong withdrawals from a major Vietnamese state-owned bank. Ideal for topping up cash with Visa, Mastercard, or UnionPay cards before browsing night-market food stalls.', description_vi = 'Đặt tại khu vực Ấp 7 ngay gần chợ đêm VuiFest Bazaar, cây ATM chính thức của ngân hàng lớn VietinBank giúp du khách rút tiền mặt VND an toàn và nhanh chóng. Rất thuận tiện để bổ sung tiền mặt từ thẻ quốc tế trước khi thưởng thức ẩm thực đường phố tại chợ đêm.', description_zh = '这台越南工商银行（VietinBank）大型国有银行官方 ATM 设于紧邻 VuiFest 海滨夜市的 7 区地段。游客在逛夜市品尝街头小吃或购买手工艺品时若现金不足，可使用 Visa、Mastercard 或银联卡就近便捷提取越南盾。', description_ja = 'VuiFestナイトマーケット近く（第7地区）に設置されている、ベトナム大手国営系銀行ヴィエティンバンク（VietinBank）の公式ATMです。夜市の屋台グルメや雑貨ショッピングの前に、国際ブランド対応カードでベトナムドン現金を引き出すのに便利です。', description_ru = 'Официальный банкомат одного из крупнейших государственных банков Вьетнама VietinBank установлен в 7-м квартале рядом с ночным рынком VuiFest Bazaar. Удобная точка для снятия наличных донгов с карт Visa, Mastercard или UnionPay перед покупками на рынке.', description_hi = 'वुईफ़ेस्ट बाज़ार नाइट मार्केट के बिल्कुल पास क्वार्टर 7 में स्थित यह प्रमुख सरकारी बैंक विएतिनबैंक (VietinBank) का आधिकारिक एटीएम है। नाइट मार्केट के फ़ूड स्टॉल्स पर जाने से पहले वीज़ा, मास्टरकार्ड या यूनियनपे कार्ड से नकद निकालने के लिए यह बेहद सुविधाजनक है।', public_name = 'VietinBank ATM', tags = ARRAY['attraction', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'vietinbank-atm';
