UPDATE public.businesses SET category = 'banking', subcategory = 'atm', address = '22PF+8V6 Jw Marriott, Phú Quốc, An Giang, Vietnam', description_ko = '켐비치 JW 메리어트 푸꾸옥 에메랄드 베이 리조트 정문 인근에 나란히 설치된 비엣콤뱅크(Vietcombank) 및 BIDV 공동 ATM 부스입니다. 켐비치 해변 레스토랑·스파·상가 구역을 이용하는 여행자들이 선셋타운까지 나가지 않고도 대표 국영은행 기기에서 안전하게 베트남 동을 인출할 수 있습니다.', description_en = 'Located beside the main entrance of JW Marriott Phu Quoc Emerald Bay in Khem Beach, this dual ATM booth houses machines from two leading Vietnamese banks—Vietcombank and BIDV. Resort and beach visitors can withdraw Vietnamese Dong cash locally using international debit or credit cards.', description_vi = 'Nằm ngay cổng chính khu nghỉ dưỡng JW Marriott Phu Quoc Emerald Bay tại Bãi Khem, cụm buồng ATM đôi quy tụ máy rút tiền của hai ngân hàng hàng đầu là Vietcombank và BIDV. Du khách lưu trú và vui chơi quanh Bãi Khem có thể rút tiền mặt VND bằng thẻ quốc tế cực kỳ thuận tiện.', description_zh = '这座联合银行自助取款亭位于凯姆海滩富国岛翡翠湾 JW 万豪度假酒店正门旁，同时配备越南外贸银行（Vietcombank）与越南投资发展银行（BIDV）两家主流大行的 ATM 机。住在凯姆海滩片区的游客无需远赴小镇，即可使用国际银行卡安全提取越南盾现金。', description_ja = 'ケムビーチのJWマリオット・フーコック・エメラルドベイ正門そばに並設された、ベトナム最大手銀行ベトコムバンク（Vietcombank）とBIDVのATMブースです。ケムビーチ周辺のレストランやスパを利用する際、国際カードで安全に現地通貨を引き出せます。', description_ru = 'Двойной павильон банкоматов у главного входа в курорт JW Marriott Phu Quoc Emerald Bay на пляже Кхем объединяет терминалы ведущих банков Вьетнама — Vietcombank и BIDV. Отдыхающие на Бãi Кхем могут круглосуточно снять наличные донги с международных карт без поездки в центр.', description_hi = 'खेम बीच में जेडब्ल्यू मैरियट फ़ू क्वोक एमराल्ड बे के मुख्य द्वार के पास स्थित इस बूथ में वियतनाम के दो प्रमुख बैंकों—वियतकॉमबैंक और बीआईडीवी—के एटीएम एक साथ लगे हैं। रिसॉर्ट और समुद्र तट के यात्री अंतरराष्ट्रीय कार्ड से यहीं सुरक्षित रूप से वियतनामी डोंग निकाल सकते हैं।', public_name = 'ATM Vietcombank, BIDV ATM', tags = ARRAY['Khem Beach', 'atm']::text[], updated_at = NOW() WHERE slug = 'atm-vietcombank-bidv-atm';
UPDATE public.businesses SET category = 'banking', subcategory = 'atm', address = '2276+VMH, Khu Phố 1, Phú Quốc, An Giang, Vietnam', description_ko = 'Vietcombank ATM — 안터이 1구역 (2276+VMH).', description_en = 'Vietcombank ATM — Khu Pho 1, An Thoi, Phu Quoc (2276+VMH).', description_vi = 'Vietcombank ATM — Khu Pho 1, An Thới, Phú Quốc (2276+VMH).', description_zh = 'Vietcombank ATM 位于富国岛安泰第1街区（Khu Phố 1），提供现金取款等金融服务。', description_ja = 'Vietcombank ATMは、フーコック島アントイの第1街区（Khu Phố 1）に位置するATMです。', description_ru = 'Банкомат Vietcombank ATM расположен в районе Khu Phố 1 городка Антой на Фукуоке.', description_hi = 'Vietcombank ATM फू क्वोक के अन थोई में खू फो 1 (Khu Phố 1) में स्थित एक एटीएम है।', public_name = 'ATM Vietcombank', tags = ARRAY['attraction', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'atm-vietcombank';
UPDATE public.businesses SET category = 'banking', subcategory = 'atm', address = '346 Đ. Nguyễn Văn Cừ, Khu phố 6, Phú Quốc, An Giang, Vietnam', description_ko = 'Sacombank ATM — 안터이 응우옌반끄 346번지.', description_en = 'Sacombank ATM — 346 Nguyen Van Cu, An Thoi, Phu Quoc.', description_vi = 'Sacombank ATM — 346 Nguyễn Văn Cừ, An Thới, Phú Quốc.', description_zh = 'Sacombank ATM 位于富国岛安泰阮文渠街346号（346 Nguyễn Văn Cừ），提供现金取款等自动金融服务。', description_ja = 'Sacombank ATMは、フーコック島アントイのグエン・ヴァン・クー通り346番地に位置するATMです。', description_ru = 'Банкомат Sacombank ATM расположен по адресу 346 Nguyễn Văn Cừ в городке Антой на Фукуоке.', description_hi = 'Sacombank ATM फू क्वोक के अन थोई में 346 गुयेन वान कू पर स्थित एक एटीएम है।', public_name = 'ATM SACOMBANK', tags = ARRAY['attraction', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'atm-sacombank';
UPDATE public.businesses SET category = 'banking', subcategory = 'atm', address = '109 Đ. Nguyễn Văn Cừ, Khu Phố 3, Phú Quốc, An Giang 922283, Vietnam', description_ko = 'KienlongBank ATM — 안터이 응우옌반끄 109번지.', description_en = 'KienlongBank ATM — 109 Nguyen Van Cu, An Thoi, Phu Quoc.', description_vi = 'KienlongBank ATM — 109 Nguyễn Văn Cừ, An Thới, Phú Quốc.', description_zh = 'KienlongBank ATM 位于富国岛安泰阮文渠街109号（109 Nguyễn Văn Cừ），提供便捷的现金取款服务。', description_ja = 'KienlongBank ATMは、フーコック島アントイのグエン・ヴァン・クー通り109番地に位置するATMです。', description_ru = 'Банкомат KienlongBank ATM расположен по адресу 109 Nguyễn Văn Cừ в Антое на Фукуоке.', description_hi = 'KienlongBank ATM फू क्वोक के अन थोई में 109 गुयेन वान कू पर स्थित एक एटीएम है।', public_name = 'ATM - KienlongBank An Thới', tags = ARRAY['attraction', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'atm-kienlongbank-an-thoi';
UPDATE public.businesses SET category = 'hotels', subcategory = 'boutique_hotel', address = '65 Đường Venice, An Thới, Phú Quốc, Kiên Giang, Vietnam', description_ko = '선셋타운 베니스 거리 중심부에 자리해 스타벅스 비치 하우스와 키스 브릿지, 부이페스트 야시장까지 모두 도보 5~6분 내에 닿는 감성 부티크 호텔입니다. 오션뷰 객실 전용 발코니에서 푸꾸옥 서해안 일몰과 야간 불꽃놀이를 프라이빗하게 감상할 수 있으며, 포근한 침구와 세심한 호스피탈리티로 커플 및 자유여행객 만족도가 높습니다.', description_en = 'Perfectly positioned on Venice Street within a 5-minute walk of Starbucks Beach House, Kiss Bridge, and VuiFest Night Market, The Room Hotel offers an intimate boutique stay in the heart of Sunset Town. All ocean-view rooms feature private balconies with unobstructed sunset and nightly fireworks views, paired with plush bedding and attentive local hospitality.', description_vi = 'Tọa lạc ngay trung tâm đường Venice của Thị trấn Hoàng Hôn, chỉ cách Starbucks Beach House, Cầu Hôn và chợ đêm VuiFest khoảng 5–6 phút đi bộ, The Room Hotel mang đến không gian lưu trú boutique ấm cúng. Các hạng phòng hướng biển đều có ban công riêng tầm nhìn thoáng đãng để thưởng thức hoàng hôn và pháo hoa hàng đêm cùng dịch vụ chu đáo.', description_zh = 'The Room Hotel 坐落于日落小镇威尼斯街中心地带，步行 5 至 6 分钟即可抵达星巴克海滨店、亲吻桥与 VuiFest 海滨夜市。海景客房均配有私人观景阳台，足不出户即可私享富国岛西海岸的金色落日与每晚盛大的海上烟花秀，舒适床品与贴心礼遇深受情侣及自由行旅客喜爱。', description_ja = 'サンセットタウンのヴェニス通り中心部に位置し、スターバックス・ビーチハウスやキスブリッジ、VuiFestナイトマーケットまで徒歩5〜6分の好立地を誇るブティックホテルです。オーシャンビュー客室の専用バルコニーからは西海岸の夕陽と夜の花火ショーをプライベートに鑑賞でき、心地よい寝具と丁寧な接客でカップルや個人旅行者に高く評価されています。', description_ru = 'Уютный бутик-отель The Room Hotel расположен в самом сердце улицы Венеция в Сансет-Тауне, всего в 5–6 минутах ходьбы от пляжного Starbucks, Моста Поцелуев и ночного рынка VuiFest. Номера с видом на океан оснащены собственными балконами для уединённого просмотра закатов и вечерних фейерверков, а мягкие постели и внимательный сервис нравятся парам и самостоятельным гостям.', description_hi = 'सनसेट टाउन की वेनिस स्ट्रीट के केंद्र में स्थित द रूम होटल से स्टारबक्स बीच हाउस, किस ब्रिज और वुईफ़ेस्ट नाइट मार्केट पैदल केवल 5–6 मिनट की दूरी पर हैं। सभी ओशन-व्यू कमरों की निजी बालकनी से फ़ू क्वोक का सूर्यास्त और रात्रि आतिशबाज़ी साफ़ दिखाई देती है, तथा आरामदायक बिस्तर व आत्मीय सेवा इसे कपल्स की पसंदीदा जगह बनाते हैं।', public_name = '더 룸 호텔 - 스타벅스 앤 파이어웍스 (The Room Hotel - Starbucks & FIREWORKS)', tags = ARRAY['boutique_hotel', 'Sunset Town', 'featured', 'ocean_view']::text[], updated_at = NOW() WHERE slug = 'the-room-hotel';
UPDATE public.businesses SET category = 'hotels', subcategory = 'residence', address = 'thị trấn Hoàng Hôn, Phú Quốc, An Giang, Vietnam', description_ko = 'Sun Grand City Hillside 고층 아파트먼트, 오션/불꽃놀이 뷰.', description_en = 'Triland Hillside is a residence apartment located in Sunset Town, Phu Quoc.', description_vi = 'Triland Hillside là căn hộ lưu trú nằm tại Thị trấn Hoàng Hôn, Phú Quốc.', description_zh = 'Triland Hillside是位于Sun Grand City Hillside的高层公寓式住宿，享有海景与烟花表演景观。', description_ja = 'Triland HillsideはSun Grand City Hillsideの高層レジデンスアパートメントで、オーシャンビューと花火の眺望が楽しめます。', description_ru = 'Triland Hillside — это высотные апартаменты в комплексе Sun Grand City Hillside с видом на море и фейерверки.', description_hi = 'Triland Hillside फू क्वोक के सनसेट टाउन में Sun Grand City Hillside की ऊँची इमारत में स्थित अपार्टमेंट आवास है, जहाँ से समुद्र और आतिशबाज़ी का नज़ारा देखा जा सकता है।', public_name = '트라이랜드 힐사이드 (Triland Hillside)', tags = ARRAY['residence', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'triland-hillside';
UPDATE public.businesses SET category = 'hotels', subcategory = 'boutique_hotel', address = '17 Positano, An Thới, Phú Quốc, Kiên Giang, Vietnam', description_ko = '선셋타운 포지타노 거리에 위치한 감성 부티크 호텔. 청결한 시설과 평점 9.5의 높은 만족도.', description_en = 'Boutique hotel in Sunset Town along Positano Street with high cleanliness and a 9.5 rating.', description_vi = 'Khách sạn boutique trên đường Positano tại Thị trấn Hoàng Hôn, được giới thiệu có độ sạch sẽ cao và điểm đánh giá 9.5.', description_zh = '位于日落小镇 Positano 街的精品酒店，以整洁的客房和周到的服务为特色。', description_ja = 'サンセットタウンのPositano通りにあるブティックホテル。清潔な客室と丁寧なサービスが特徴です。', description_ru = 'Бутик-отель на улице Positano в Сансет-Тауне, известный чистыми номерами и внимательным обслуживанием.', description_hi = 'सनसेट टाउन की Positano स्ट्रीट पर स्थित यह बुटीक होटल साफ़-सुथरे कमरों और ध्यानपूर्वक दी जाने वाली सेवा के लिए जाना जाता है।', public_name = '코스탈 리빙 호텔 푸꾸옥 (Coastal Living Hotel Phu Quoc)', tags = ARRAY['boutique_hotel', 'Sunset Town', 'Ocean View']::text[], updated_at = NOW() WHERE slug = 'coastal-living-hotel-phu-quoc';
UPDATE public.businesses SET category = 'dining', subcategory = 'restaurant_and_lounge', address = '302 - 304 đường Sorrento, Sunset Town, An Thới, Phú Quốc', description_ko = '선셋타운 소렌토 거리에 위치한 카세피아 호텔의 감성 다이닝 & 라운지. Kiss of the Sea 공연장 및 해변과 인접하여 로맨틱한 식사와 칵테일을 즐길 수 있습니다.', description_en = 'Atmospheric dining & lounge at CASEPiA Hotel in Sunset Town. Located right in front of the Kiss of the Sea theater and beachfront.', description_vi = 'Không gian nhà hàng và lounge tại khách sạn CASEPiA ở Thị trấn Hoàng Hôn, ngay trước sân khấu Kiss of the Sea và bãi biển.', description_zh = '位于日落小镇 Sorrento 街 CASEPiA Hotel 内的餐厅与休闲酒廊，邻近 Kiss of the Sea 剧场及海滨区域。', description_ja = 'サンセットタウンのSorrento通りにあるCASEPiA Hotel内のレストラン＆ラウンジ。Kiss of the Seaシアターや海辺のエリアの近くに位置しています。', description_ru = 'Ресторан и лаунж в отеле CASEPiA Hotel на улице Sorrento в Сансет-Тауне, недалеко от театра Kiss of the Sea и набережной.', description_hi = 'सनसेट टाउन की Sorrento स्ट्रीट पर स्थित CASEPiA Hotel का यह रेस्तराँ और लाउंज Kiss of the Sea थिएटर और समुद्र तट के पास स्थित है।', public_name = '카세피아 키친 & 라운지 (CASEPiA Kitchen & Lounge)', tags = ARRAY['dining', 'lounge', 'Sunset Town', 'Kiss of the Sea', 'Ocean View']::text[], updated_at = NOW() WHERE slug = 'casepia-kitchen-and-lounge';
UPDATE public.businesses SET category = 'banking', subcategory = 'currency_exchange', address = 'Kem Beach, 59 Diamond 1, Phú Quốc, Vietnam', description_ko = NULL, description_en = NULL, description_vi = NULL, description_zh = NULL, description_ja = NULL, description_ru = NULL, description_hi = NULL, public_name = 'King Kong Money Exchange - Khem Beach', tags = ARRAY['Khem Beach', 'currency_exchange']::text[], updated_at = NOW() WHERE slug = 'king-kong-money-exchange-khem-beach';
UPDATE public.businesses SET category = 'dining', subcategory = 'indian', address = 'A172 Đường Amalfi, Sunset Town, An Thới, Phú Quốc, Kiên Giang, Vietnam', description_ko = '선셋타운 아말피 거리(A172)에 위치한 순수 채식(Pure Veg) 및 자이나교(Jain) 맞춤 조리가 가능한 인도 전문 레스토랑입니다. 파니르 커리와 달 타드카, 갓 구운 탄두리 난 등 정통 인도 채식 요리를 제공합니다.', description_en = 'Pure vegetarian and Jain-friendly Indian restaurant at A172 Amalfi Street in Sunset Town serving North and South Indian curries, paneer specialties, dal tadka, and freshly baked tandoori naan.', description_vi = 'Nhà hàng Ấn Độ thuần chay (có phục vụ món Jain) tại A172 đường Amalfi, Thị trấn Hoàng Hôn, chuyên các món cà ri phô mai paneer, đậu lăng dal và bánh naan nướng lò đất.', description_zh = '位于日落小镇阿马尔菲街（A172）的纯素食及耆那教友好印度餐厅，供应北印与南印咖喱、印度奶酪（Paneer）、扁豆咖喱及现烤馕饼。', description_ja = 'サンセットタウンのアマルフィ通り（A172）にあるピュアベジタリアン＆ジャイナ教対応のインド料理店。パニールカレーやダル、焼きたてタンドリーナンを提供しています。', description_ru = 'Вегетарианский индийский ресторан (включая меню джайн) на улице Amalfi, A172 в Сансет-Тауне: карри с паниром, дал тадка и свежие лепёшки наан из тандыра.', description_hi = 'सनसेट टाउन के अमाल्फ़ी स्ट्रीट (A172) पर स्थित शुद्ध शाकाहारी (Pure Veg) और जैन भोजन उपलब्ध कराने वाला भारतीय रेस्तरां, जहाँ पनीर करी, दाल तड़का और ताज़ा तंदूरी नान परोसे जाते हैं।', public_name = '마 인디안 레스토랑 (Maa Indian Restaurant)', tags = ARRAY['Indian', 'Vegetarian', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'maa-indian-sunset-town';
UPDATE public.businesses SET category = 'dining', subcategory = 'indian', address = '55 Đường Amalfi, Sunset Town, An Thới, Phú Quốc, Kiên Giang, Vietnam', description_ko = '선셋타운 아말피 거리 55번지에 자리한 인도 레스토랑으로, 버터 치킨·탄두리 치킨·비리야니 등 육류 메뉴와 전통 인도 채식 커리를 모두 폭넓게 갖추고 있습니다.', description_en = 'Indian restaurant at 55 Amalfi Street in Sunset Town offering a full menu of both non-vegetarian classics (butter chicken, tandoori chicken, lamb curry, biryani) and traditional vegetarian Indian dishes.', description_vi = 'Nhà hàng Ấn Độ tại số 55 đường Amalfi, Thị trấn Hoàng Hôn phục vụ đầy đủ cả thực đơn mặn (gà bơ, gà nướng tandoori, cơm biryani) lẫn các món chay Ấn Độ truyền thống.', description_zh = '位于日落小镇阿马尔菲街55号的印度餐厅，同时提供黄油鸡、坦都里烤鸡、印度香饭等荤食经典菜品以及丰富的传统素食印度料理。', description_ja = 'サンセットタウンのアマルフィ通り55番地にあるインドレストラン。バターチキンやタンドリーチキン、ビリヤニなどの肉料理と伝統的なベジタリアン料理の両方を揃え、幅広い好みに応えます。', description_ru = 'Индийский ресторан на улице Amalfi, 55 в Сансет-Тауне: в меню представлены как мясные блюда (баттер-чикен, цыплёнок тандури, бирьяни), так и вегетарианская классика.', description_hi = 'सनसेट टाउन में 55 अमाल्फ़ी स्ट्रीट पर स्थित भारतीय रेस्तरां, जहाँ नॉन-वेज (बटर चिकन, तंदूरी चिकन, बिरयानी) और शाकाहारी दोनों तरह के प्रामाणिक भारतीय व्यंजन मिलते हैं।', public_name = '스와드 키친 (Swad Kitchen)', tags = ARRAY['Indian', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'swad-kitchen-sunset-town';
UPDATE public.businesses SET category = 'dining', subcategory = 'indian', address = '148 Đường Amalfi, Sunset Town, An Thới, Phú Quốc, Kiên Giang, Vietnam', description_ko = '선셋타운 키스브릿지 인근 아말피 거리(148번지)에 위치한 캐주얼 인디안 다바(Dhaba) 비스트로로, 향신료 풍미의 비리야니와 갈릭 난, 탄두리 플래터, 마살라 차이를 부담 없이 즐길 수 있습니다.', description_en = 'Casual Indian dhaba-style bistro on Amalfi Street (No. 148) within walking distance of Kiss Bridge in Sunset Town, serving spiced biryanis, garlic naan, tandoori platters, and masala chai.', description_vi = 'Quán bistro Ấn Độ phong cách dhaba bình dân tại 148 đường Amalfi gần Cầu Hôn (Sunset Town), phục vụ cơm biryani, bánh naan bơ tỏi, đồ nướng tandoori và trà sữa masala.', description_zh = '位于日落小镇阿马尔菲街（148号）、邻近接吻桥的休闲印度小馆（Dhaba 风格），供应印度香饭、蒜香烤馕、坦都里拼盘与玛萨拉奶茶。', description_ja = 'サンセットタウンのキスブリッジ近く、アマルフィ通り（148番）にあるカジュアルなインディアン・ダバ（大衆食堂）風ビストロ。ビリヤニやナン、タンドリー料理を気軽に楽しめます。', description_ru = 'Демократичное индийское бистро в стиле дхаба на улице Amalfi (д. 148) недалеко от Моста Поцелуев в Сансет-Тауне: бирьяни, чесночный наан, блюда из тандыра и масала-чай.', description_hi = 'सनसेट टाउन में किस ब्रिज के पास अमाल्फ़ी स्ट्रीट (148) पर स्थित कैज़ुअल इंडियन ढाबा बिस्ट्रो, जहाँ बिरयानी, गार्लिक नान, तंदूरी प्लैटर और मसाला चाय परोसी जाती है।', public_name = '압나 인디안 다바 비스트로 (Apnaa Indian Dhaba Bistro)', tags = ARRAY['Indian', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'apnaa-indian-dhaba-sunset-town';
UPDATE public.businesses SET category = 'dining', subcategory = 'indian', address = 'VEN57 Đường Venice, Sunset Town, An Thới, Phú Quốc, Kiên Giang, Vietnam', description_ko = '선셋타운 베니스 거리(VEN57, 키스브릿지 승하차 광장 옆)에 자리한 100% 순수 채식(Pure Veg) 및 자이나교 인도 레스토랑으로, 탈리 세트와 파니르 커리, 도사 등을 늦은 저녁까지 제공합니다.', description_en = '100% pure vegetarian and Jain Indian restaurant at VEN57 Venice Street right beside the Kiss Bridge drop-off plaza in Sunset Town, serving thalis, paneer curries, dosa, and chaat until late evening.', description_vi = 'Nhà hàng Ấn Độ 100% thuần chay và phục vụ thực đơn Jain tại căn VEN57 đường Venice (cạnh điểm đón trả khách Cầu Hôn, Sunset Town), mở cửa đến tối muộn.', description_zh = '位于日落小镇威尼斯街（VEN57，紧邻接吻桥上下车广场）的100%纯素及耆那教正宗印度餐厅，供应印式拼盘（Thali）、奶酪咖喱与南印薄饼至深夜。', description_ja = 'サンセットタウンのヴェニス通り（VEN57、キスブリッジ乗降場横）にある100%ピュアベジタリアン＆ジャイナ教対応の本格インド料理店。ターリーやパニールカレーを夜遅くまで提供しています。', description_ru = 'На 100% вегетарианский и джайнский индийский ресторан на улице Venice (VEN57, рядом с площадкой у Моста Поцелуев): тхали, карри с паниром и закуски чаат допоздна.', description_hi = 'सनसेट टाउन के वेनिस स्ट्रीट (VEN57, किस ब्रिज ड्रॉप-ऑफ़ के पास) पर स्थित 100% शुद्ध शाकाहारी और जैन भारतीय रेस्तरां, जहाँ थाली, पनीर व्यंजन, डोसा और चाट देर शाम तक मिलते हैं।', public_name = '마하라자 라운지 선셋타운 (Maharaja Lounge Sunset Town)', tags = ARRAY['Indian', 'Vegetarian', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'maharaja-lounge-sunset-town';
UPDATE public.businesses SET category = 'dining', subcategory = 'chinese', address = '69 Đường Positano & Kiosk P24 VuiFest Bazaar, Sunset Town, An Thới, Phú Quốc, Kiên Giang, Vietnam', description_ko = '선셋타운 포지타노 거리(69번지)와 부이페스트 야시장(P24 부스)에서 만날 수 있는 수제 바오번·딤섬 전문점으로, 갓 쪄낸 폭신한 바오즈와 하가우·샤오마이 등 간편한 중식 딤섬을 선보입니다.', description_en = 'Handcrafted bao bun and dim sum eatery operating at 69 Positano Street and Kiosk P24 inside VuiFest Bazaar in Sunset Town, serving steamed baozi, har gow, siu mai, and quick Chinese-style bites.', description_vi = 'Quán bánh bao thủ công và dimsum tại số 69 đường Positano cùng gian hàng P24 chợ đêm VuiFest (Sunset Town), phục vụ bánh bao nóng, há cảo và xíu mại hấp tại chỗ.', description_zh = '位于日落小镇波西塔诺街69号及 VuiFest 夜市 P24 摊位的手工刈包与广式点心专门店，现蒸包点、虾饺、烧卖等中式小吃堂食外带皆宜。', description_ja = 'サンセットタウンのポジターノ通り69番地およびVuiFestナイトマーケット（P24）で営業する手作りパオ（中華まん）・点心専門店。蒸したてのバオや海老餃子・焼売を気軽に味わえます。', description_ru = 'Закусочная ручных паровых булочек бао и димсамов на улице Positano, 69 и в павильоне P24 ночного рынка VuiFest в Сансет-Тауне.', description_hi = 'सनसेट टाउन में 69 पोसिटानो स्ट्रीट और VuiFest बाज़ार (P24) पर स्थित हैंडक्राफ़्टेड बाओ बन और डिम सम रेस्तरां, जहाँ ताज़ा स्टीम्ड बाओज़ी और चाइनीज़ स्नैक्स मिलते हैं।', public_name = '로드 오브 더 바오 (Lord of the Bao)', tags = ARRAY['Chinese', 'Street Food', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'lord-of-the-bao-sunset-town';
UPDATE public.businesses SET category = 'dining', subcategory = 'chinese', address = '1 Đường Lê Quý Đôn, Khu phố 2, An Thới, Phú Quốc, Kiên Giang, Vietnam', description_ko = '선셋타운에서 택시로 약 5~8분 거리인 안터이 시내(1 Lê Quý Đôn)에 위치한 정통 사천식 훠궈 식당으로, 얼얼한 마라 육수와 반반 훠궈에 신선한 해산물·육류·채소를 곁들여 저녁 식사로 즐기기 좋습니다.', description_en = 'Neighborhood Sichuan-style Chinese hotpot restaurant in An Thới town (1 Lê Quý Đôn, about 5–8 minutes by taxi from Sunset Town) serving spicy mala and dual-broth hotpots with sliced meats, local seafood, and vegetables.', description_vi = 'Quán lẩu Tứ Xuyên tại số 1 Lê Quý Đôn, Khu phố 2, An Thới (cách Sunset Town khoảng 5–8 phút đi taxi), phục vụ lẩu cay mala và lẩu uyên ương hai ngăn với thịt bò, hải sản tươi.', description_zh = '位于安泰镇（1 Lê Quý Đôn，距日落小镇乘车约5至8分钟）的川味中式火锅店，主打麻辣锅与鸳鸯锅底，搭配现切肉类、当地海鲜与时令蔬菜。', description_ja = 'サンセットタウンからタクシーで約5〜8分のアントイ市街（1 Lê Quý Đôn）にある四川風中華火鍋店。麻辣スープや二色鍋で肉・地元産魚介・野菜を堪能できます。', description_ru = 'Ресторан китайского сычуаньского хого в городке Ан Тхой (1 Lê Quý Đôn, 5–8 минут на такси от Сансет-Тауна): острый бульон мала и двойные котлы с мясом и морепродуктами.', description_hi = 'सनसेट टाउन से टैक्सी द्वारा लगभग 5–8 मिनट दूर अन थोई कस्बे (1 Lê Quý Đôn) में स्थित सिचुआन चाइनीज़ हॉटपॉट रेस्तरां, जहाँ मसालेदार माला और डबल-ब्रॉथ हॉटपॉट परोसा जाता है।', public_name = '러우 뜨 쑤옌 사천 훠궈 (Lẩu Tứ Xuyên Chinese Hotpot)', tags = ARRAY['Chinese', 'Nearby (An Thoi)']::text[], updated_at = NOW() WHERE slug = 'lau-tu-xuyen-an-thoi';
UPDATE public.businesses SET category = 'bars', subcategory = 'cafe', address = 'Central Square (Near Cable Car Station), Sunset Town, An Thới, Phú Quốc, Kiên Giang, Vietnam', description_ko = '선셋타운 혼똔 케이블카 탑승장 인근 중앙 광장에 자리한 프랑스 아티장 베이커리 카페입니다. 이른 아침부터 사워도우 바게트와 버터 크루아상, 타르트, 샌드위치 및 커피로 가벼운 조식을 해결하기 좋습니다.', description_en = 'French artisan bakery and breakfast cafe located near Hon Thom Cable Car Station in Sunset Town, serving sourdough breads, butter croissants, tarts, sandwiches, and espresso drinks from early morning.', description_vi = 'Tiệm bánh nghệ nhân Pháp và cà phê ăn sáng nằm gần Ga cáp treo Hòn Thơm tại Thị trấn Hoàng Hôn, phục vụ bánh sừng bò bơ Pháp, bánh mì sourdough, bánh ngọt và cà phê từ sáng sớm.', description_zh = '位于日落小镇跨海缆车站旁中央广场的法国手工烘焙咖啡馆，清晨起供应天然酵母法棍、黄油牛角包、法式挞点、三明治与意式咖啡，适合早餐小憩。', description_ja = 'サンセットタウンのケーブルカー駅近くに構えるフランスのアルティザン・ベーカリーカフェ。朝早くからクロワッサンやバゲットサンド、タルト、コーヒーを味わえます。', description_ru = 'Французская ремесленная пекарня и кафе для завтраков рядом со станцией канатной дороги в Сансет-Тауне: круассаны на сливочном масле, хлеб на закваске, сэндвичи и кофе с утра.', description_hi = 'सनसेट टाउन में केबल कार स्टेशन के पास स्थित फ़्रेंच आर्टिज़न बेकरी और ब्रेकफ़ास्ट कैफ़े, जहाँ सुबह से ही ताज़ा क्रोसां, ब्रेड, सैंडविच और कॉफ़ी उपलब्ध रहती है।', public_name = '메종 카이저 선셋타운 (Maison Kayser Sunset Town)', tags = ARRAY['Cafe', 'Dessert Cafe', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'maison-kayser-sunset-town';
UPDATE public.businesses SET category = 'shopping', subcategory = 'pearls', address = 'Đường Trần Hưng Đạo, Tổ 1, Ấp Dương Tơ, Dương Tơ, Phú Quốc, Kiên Giang, Vietnam', description_ko = '공항과 남부(선셋타운) 이동 경로인 즈엉떠(Dương Tơ) 쩐흥다오 대로변에 위치한 푸꾸옥 대표 진주 양식장 겸 대형 쇼룸입니다. 진주 양식 과정 관람이 가능하며 정품 보증서가 포함된 진주 주얼리를 정찰제로 판매합니다.', description_en = 'Established Phu Quoc cultured pearl farm and showroom on Trần Hưng Đạo Road in Dương Tơ (along the route between the airport and South Island), providing pearl-cultivation displays and certified jewelry with authenticity warranties.', description_vi = 'Cơ sở nuôi cấy và showroom trưng bày ngọc trai Ngọc Hiền trên đường Trần Hưng Đạo, Dương Tơ (trục đường sân bay đi Nam đảo), cung cấp trang sức ngọc trai kèm giấy chứng nhận và bảo hành chính hãng.', description_zh = '位于杨丝社（Dương Tơ，机场前往南岛日落小镇必经干道）的富国岛知名珍珠养殖场与展厅，可了解海水珍珠培育过程，并提供附正品鉴定证书的珍珠首饰。', description_ja = '空港と南部サンセットタウンを結ぶズオントー地区（Trần Hưng Đạo通り）にあるフーコック代表的な真珠養殖場＆ショールーム。養殖工程の見学ができ、品質保証書付きの真珠ジュエリーを購入できます。', description_ru = 'Известная жемчужная ферма и шоурум на улице Trần Hưng Đạo в районе Dương Tơ (по пути из аэропорта на юг острова): знакомство с выращиванием жемчуга и украшения с сертификатом подлинности.', description_hi = 'दुओंग तो (एयरपोर्ट और साउथ आइलैंड के मार्ग पर Trần Hưng Đạo रोड) में स्थित प्रमाणित फू क्वोक पर्ल फ़ार्म और शोरूम, जहाँ प्रामाणिकता वारंटी के साथ असली मोती के आभूषण मिलते हैं।', public_name = '응옥 히엔 진주 농장 & 쇼룸 (Ngọc Hiền Pearl Farm & Showroom)', tags = ARRAY['Pearls', 'Souvenirs', 'Nearby (An Thoi)']::text[], updated_at = NOW() WHERE slug = 'ngoc-hien-pearl-phu-quoc';
UPDATE public.businesses SET category = 'shopping', subcategory = 'local_specialties', address = '471 Đường Nguyễn Văn Cừ (Opposite Phú Quốc Prison), Khu phố 4, An Thới, Phú Quốc, Kiên Giang, Vietnam', description_ko = '안터이 코코넛 수용소(푸꾸옥 감옥) 바로 맞은편 응우옌반꾸 대로에 자리한 전통 목조 발효통 느억맘(멸치 액젓) 제조장 겸 특산품 매장입니다. 푸꾸옥 통후추, 심 와인, 건어물 기념품을 함께 구매할 수 있습니다(액젓 병은 항공 기내 반입 제한 유의).', description_en = 'Traditional wooden-barrel anchovy fish sauce house on Nguyễn Văn Cừ Road directly opposite Phú Quốc Coconut Prison in An Thới, selling Phu Quoc pepper, sim wine, dried seafood, and specialty gift sets (note airline carry-on restrictions on bottled fish sauce).', description_vi = 'Nhà thùng nước mắm truyền thống nằm đối diện Di tích Nhà tù Phú Quốc trên đường Nguyễn Văn Cừ (An Thới), trưng bày thùng gỗ ủ chượp cá cơm và bán hồ tiêu Phú Quốc, rượu sim, đặc sản đóng gói.', description_zh = '位于安泰镇阮文渠路（富国岛椰子监狱正对面）的传统木桶鱼露酿造坊兼特产店，可参观巨大木制发酵桶并选购富国胡椒、桃金娘酒与海味干货（注意瓶装鱼露不可随身登机）。', description_ja = 'アントイのココナッツ収容所（フーコック刑務所）向かいにある伝統的な木樽ヌクマム（魚醤）醸造所兼特産品店。フーコック胡椒やシムワインも揃います（魚醤ボトルの航空機持ち込み制限に注意）。', description_ru = 'Традиционная фабрика рыбного соуса в деревянных бочках на улице Nguyễn Văn Cừ напротив Кокосовой тюрьмы в Ан Тхое: фукуокский перец, миртовое вино и местные деликатесы (учитывайте правила авиаперевозки соуса).', description_hi = 'अन थोई में कोकोनट प्रिज़न के ठीक सामने स्थित पारंपरिक फ़िश सॉस बैरल हाउस और स्थानीय विशेषता दुकान, जहाँ फू क्वोक काली मिर्च और स्थानीय उपहार मिलते हैं।', public_name = '풍흥 느억맘 전통 발효장 (Nhà Thùng Nước Mắm Phụng Hưng)', tags = ARRAY['Local Specialties', 'Souvenirs', 'Nearby (An Thoi)']::text[], updated_at = NOW() WHERE slug = 'phung-hung-fish-sauce-an-thoi';
UPDATE public.businesses SET category = 'shopping', subcategory = 'souvenirs', address = 'VuiFest Bazaar, Sunset Town, An Thới, Phú Quốc, Kiên Giang, Vietnam', description_ko = '선셋타운 부이페스트 야시장(VuiFest Bazaar) 내에서 매일 오후 4시부터 자정까지 운영되는 공정무역 수공예 기프트숍으로, 베트남 소수민족 수직물 가방·파우치, 도자기, 친환경 바다 테마 소품을 판매합니다.', description_en = 'Fair-trade handicraft boutique inside VuiFest Bazaar in Sunset Town open daily from 16:00 to midnight, offering handwoven ethnic minority textiles, embroidered bags, ceramics, and eco-friendly coastal decor.', description_vi = 'Cửa hàng thủ công mỹ nghệ thương mại công bằng nằm trong chợ đêm VuiFest Bazaar (Sunset Town), mở cửa 16:00–24:00 với các sản phẩm thổ cẩm dân tộc, gốm sứ và quà lưu niệm thân thiện môi trường.', description_zh = '位于日落小镇 VuiFest 海滨夜市内的公平贸易手工艺礼品店（每日16:00至午夜营业），售卖越南少数民族手工织锦包袋、陶瓷器皿与海洋环保文创纪念品。', description_ja = 'サンセットタウンのVuiFestナイトマーケット内にあるフェアトレード手工芸ショップ（16:00〜24:00営業）。ベトナム少数民族の手織り布バッグや陶器、海モチーフのエコ雑貨が揃います。', description_ru = 'Магазин ремесленных сувениров честной торговли на ночном рынке VuiFest в Сансет-Тауне (16:00–24:00): домотканый текстиль малых народов Вьетнама, керамика и эко-декор.', description_hi = 'सनसेट टाउन के VuiFest नाइट मार्केट में स्थित फ़ेयर-ट्रेड हैंडीक्राफ़्ट दुकान (शाम 4 बजे से मध्यरात्रि तक खुली), जहाँ पारंपरिक हथकरघा बैग, सिरेमिक और स्मृति-चिह्न मिलते हैं।', public_name = '푸꾸옥 크래프트 링크 (Phu Quoc Craft Link)', tags = ARRAY['Souvenirs', 'Local Specialties', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'phu-quoc-craft-link-vuifest';
UPDATE public.businesses SET category = 'shopping', subcategory = 'fresh_market', address = 'Đường Nguyễn Văn Cừ (Near An Thới Port), Khu phố 1, An Thới, Phú Quốc, Kiên Giang, Vietnam', description_ko = '선셋타운에서 차량 약 5~10분 거리인 안터이 항구 인근 남부 최대 로컬 재래시장입니다. 오전 시간대에 방문하면 망고·망고스틴 등 제철 열대과일과 건오징어·건새우, 캐슈넛 등 현지 먹거리를 저렴하게 구입할 수 있습니다(소액 현금 지참 권장).', description_en = 'Bustling local daytime wet and fruit market near An Thới Port (about 5–10 minutes by taxi from Sunset Town), best visited in the morning for seasonal tropical fruits, dried squid and shrimp, cashews, and everyday local snacks.', description_vi = 'Chợ dân sinh truyền thống sầm uất nhất khu vực Nam đảo gần cảng An Thới (cách Sunset Town 5–10 phút đi xe), bày bán trái cây nhiệt đới theo mùa, hải sản tươi và khô mực, tôm khô.', description_zh = '靠近安泰港的南岛最大本地日间菜市场与水果市场（距日落小镇乘车约5至10分钟），适合上午前往选购当季热带水果、鱿鱼干、虾干与腰果（建议备好越南盾现金）。', description_ja = 'アントイ港近くにある南部最大のローカル市場（サンセットタウンから車で約5〜10分）。午前中の訪問がおすすめで、旬の南国フルーツやスルメ・干しエビ、カシューナッツを手頃に購入できます。', description_ru = 'Колоритный дневной местный рынок у порта Ан Тхой (5–10 минут на такси от Сансет-Тауна): свежие тропические фрукты, сушёные морепродукты и орехи кешью по местным ценам.', description_hi = 'अन थोई पोर्ट के पास स्थित स्थानीय ताज़ा फल और सीफ़ूड बाज़ार (सनसेट टाउन से टैक्सी द्वारा 5–10 मिनट), जहाँ मौसमी उष्णकटिबंधीय फल और सूखे समुद्री उत्पाद मिलते हैं।', public_name = '안터이 재래시장 (Chợ An Thới)', tags = ARRAY['Fresh Market', 'Local Specialties', 'Nearby (An Thoi)']::text[], updated_at = NOW() WHERE slug = 'cho-an-thoi-fresh-market';
UPDATE public.businesses SET category = 'shopping', subcategory = 'pharmacy', address = 'Căn Amalfi 67, Sunset Town, An Thới, Phú Quốc, Kiên Giang, Vietnam', description_ko = '선셋타운 중심부 아말피 67호에 위치해 도보로 바로 방문할 수 있는 약국입니다. 해열진통제, 소화제·지사제, 멀미약, 모기 기피제, 화상·상처 연고 등 여행자 상비약을 늦은 밤까지 구비하고 있습니다.', description_en = 'Walkable retail pharmacy right inside Sunset Town at unit Amalfi 67 stocking over-the-counter pain relievers, digestive and motion-sickness medicine, bandages, mosquito repellent, and sunburn ointment until late night.', description_vi = 'Nhà thuốc nằm ngay trung tâm Thị trấn Hoàng Hôn tại căn Amalfi 67, mở cửa đến khuya, cung cấp thuốc hạ sốt, giảm đau, tiêu hóa, chống say tàu xe, xịt muỗi và kem bôi dịu nắng.', description_zh = '位于日落小镇中心阿马尔菲街67号、步行即可到达的药房，营业至深夜，备有退烧止痛药、肠胃药、晕船晕车药、驱蚊液及晒伤烫伤药膏等旅行常备药品。', description_ja = 'サンセットタウン中心部のアマルフィ67番にあり徒歩で立ち寄れる薬局。解熱鎮痛剤や胃腸薬、酔い止め、虫除け、日焼け・傷薬などの旅行用常備薬を夜遅くまで取り扱っています。', description_ru = 'Аптека в самом центре Сансет-Тауна (Amalfi 67) в пешей доступности от отелей: безрецептурные обезболивающие, средства от расстройства желудка и укачивания, репелленты и мази от ожогов.', description_hi = 'सनसेट टाउन के भीतर अमाल्फ़ी 67 में पैदल दूरी पर स्थित फ़ार्मेसी, जहाँ देर रात तक दर्द निवारक, पाचन व मोशन-सिकनेस की दवाइयाँ, मच्छर रोधी स्प्रे और प्राथमिक उपचार सामग्री मिलती है।', public_name = '아말피 67 약국 (Pharmacy Amalfi 67)', tags = ARRAY['Pharmacy', 'Essentials', 'Sunset Town']::text[], updated_at = NOW() WHERE slug = 'pharmacy-amalfi-67-sunset-town';
UPDATE public.businesses SET category = 'shopping', subcategory = 'pharmacy', address = '46 Đường Nguyễn Văn Cừ, Khu phố 3, An Thới, Phú Quốc, Kiên Giang, Vietnam', description_ko = '안터이 중심 대로(46 Nguyễn Văn Cừ)에 위치한 베트남 최대 전국 프랜차이즈 약국 체인점입니다. 전 품목 바코드 정찰제로 투명하게 운영되며 전문 약사 상담과 해외 신용카드 결제가 가능합니다.', description_en = 'Branch of Vietnam''s largest nationwide pharmacy chain at 46 Nguyễn Văn Cừ in An Thới, offering transparent fixed barcode pricing, licensed pharmacists, international brand medications, and card payment.', description_vi = 'Chi nhánh hệ thống nhà thuốc lớn hàng đầu Việt Nam tại số 46 Nguyễn Văn Cừ, An Thới, bán đúng giá niêm yết toàn hệ thống, có dược sĩ tư vấn và hỗ trợ thanh toán thẻ.', description_zh = '位于安泰镇阮文渠路46号的越南最大全国连锁药房分店，全店商品实行透明条码明码标价，配有执业药师，备齐国际品牌常备药并支持国际信用卡支付。', description_ja = 'アントイ中心部のグエン・ヴァン・クー通り46番地にあるベトナム最大手薬局チェーン店。全品バーコードによる明朗な定価販売で、薬剤師が常駐し国際クレジットカード決済にも対応しています。', description_ru = 'Филиал крупнейшей всевьетнамской аптечной сети на улице Nguyễn Văn Cừ, 46 в Ан Тхое: фиксированные цены по штрихкоду, лицензированные фармацевты и оплата банковскими картами.', description_hi = 'अन थोई में 46 Nguyễn Văn Cừ पर स्थित वियतनाम की प्रमुख फ़ार्मेसी चेन की शाखा, जहाँ पारदर्शी तय कीमतों पर प्रमाणित दवाइयाँ मिलती हैं और कार्ड भुगतान स्वीकार किया जाता है।', public_name = 'FPT 롱쩌우 약국 안터이점 (Nhà Thuốc FPT Long Châu An Thới)', tags = ARRAY['Pharmacy', 'Essentials', 'Nearby (An Thoi)']::text[], updated_at = NOW() WHERE slug = 'fpt-long-chau-an-thoi';
UPDATE public.businesses SET category = 'shopping', subcategory = 'pharmacy', address = 'Đường Nguyễn Văn Cừ, Khu phố 3, An Thới, Phú Quốc, Kiên Giang, Vietnam', description_ko = '안터이 응우옌반꾸 거리(더저이이동 매장 옆)에 위치한 대기업 계열 정찰제 체인 약국으로, 정품 일반의약품·어린이 해열제·전해질 보충제·선케어 제품을 정가에 구매할 수 있으며 해외 카드 결제를 지원합니다.', description_en = 'Fixed-price Mobile World Group chain pharmacy on Nguyễn Văn Cừ Street in An Thới offering verified origin OTC medicines, pediatric fever reducers, rehydration salts, sunscreen, and international card payments.', description_vi = 'Nhà thuốc chuỗi chính hãng thuộc tập đoàn Thế Giới Di Động trên đường Nguyễn Văn Cừ, An Thới, cam kết thuốc rõ nguồn gốc, giá niêm yết minh bạch và chấp nhận thanh toán thẻ quốc tế.', description_zh = '位于安泰镇阮文渠路（紧邻 Thế Giới Di Động 门店）的大型集团直营明码标价连锁药房，供应正品非处方药、儿童退烧药、口服补液盐及防晒护肤品，支持国际银行卡付款。', description_ja = 'アントイのグエン・ヴァン・クー通りにある大手グループ運営の定価制チェーン薬局。市販薬や子ども用解熱剤、経口補水塩、日焼け止めを明朗価格で販売し、海外カード決済に対応しています。', description_ru = 'Сетевая аптека с фиксированными ценами на улице Nguyễn Văn Cừ в Ан Тхое: сертифицированные препараты, детские жаропонижающие, электролиты, солнцезащитные средства и оплата международными картами.', description_hi = 'अन थोई में Nguyễn Văn Cừ रोड पर स्थित तय कीमतों वाली प्रतिष्ठित चेन फ़ार्मेसी, जहाँ प्रमाणित ओटीसी दवाइयाँ और प्राथमिक उपचार उत्पाद अंतरराष्ट्रीय कार्ड भुगतान सुविधा के साथ उपलब्ध हैं।', public_name = '안캉 약국 안터이점 (Nhà Thuốc An Khang An Thới)', tags = ARRAY['Pharmacy', 'Essentials', 'Nearby (An Thoi)']::text[], updated_at = NOW() WHERE slug = 'nha-thuoc-an-khang-an-thoi';

COMMIT;
